	class Du {
		static parseItemStr(e, t = ":") {
			let i = e.split(t);
			let s = {};
			s.type = parseInt(i[0]);
			s.tid = parseInt(i[1]);
			if (i[2]) {
				s.num = parseInt(i[2])
			}
			return s
		}
		static splitToNumArr(e, t = "#") {
			let i = e.split(t);
			let s = [];
			for (let a = 0; a < i.length; a++) {
				s[a] = parseInt(i[a])
			}
			return s
		}
		static splitAttrStr2Arr(e, t = "#", i = ":") {
			if (e == "")
				return [];
			var s = e.split(t);
			var a = [];
			for (var r = 0; r < s.length; r++) {
				var l = s[r].split(i);
				a.push({
					type: parseInt(l[0]),
					value: parseFloat(l[1])
				})
			}
			return a
		}
	}
