	class cd {
		static regDot(e, t) {
			this._dotDic[e] = t;
			this.updateDot(e)
		}
		static unRegDot(e) {
			delete this._dotDic[e]
		}
		static setDot(e, t, i) {
			let s = this._callerDic[e];
			if (!s) {
				s = [];
				this._callerDic[e] = s
			}
			if (i) {
				if (s.indexOf(t) == -1) {
					s.push(t);
					this.updateDot(e)
				}
			} else {
				if (s.indexOf(t) != -1) {
					s.splice(s.indexOf(t), 1);
					this.updateDot(e)
				}
			}
		}
		static updateDot(e) {
			let t = this._dotDic[e];
			if (!t)
				return;
			let i = this._callerDic[e];
			if (!i || !i.length) {
				t.visible = false
			} else {
				t.visible = true
			}
		}
		static regCheckFun(e) {
			this._checkFunList.push(e)
		}
		static checkLoop() {
			for (let e = 0; e < this._checkFunList.length; e++) {
				this._checkFunList[e]()
			}
		}
		static startCheck() {
			Laya.timer.loop(1e3, this, this.checkLoop)
		}
		static addDot(e, t = null, i = null) {
			let s = this.getDot(e);
			if (!s) {
				s = new Laya.Image("img/baseUI/dian0.png");
				s.name = "dot"
			}
			e.addChild(s);
			if (t == null || i == null) {
				s.pos(e.width - 18, -12)
			} else {
				s.pos(t, i)
			}
		}
		static removeDot(e) {
			for (let t = 0; t < e.numChildren; t++) {
				let i = e.getChildAt(t);
				if (i instanceof Laya.Image && i.name == "dot") {
					e.removeChildAt(t);
					return
				}
			}
		}
		static getDot(e) {
			for (let t = 0; t < e.numChildren; t++) {
				let i = e.getChildAt(t);
				if (i instanceof Laya.Image && i.name == "dot") {
					return i
				}
			}
			return null
		}
	}
