	class gd {
		static DecBagRuneInit(e) {
			let t = {};
			t.list = [];
			for (let i = 0; i < e.data.list.length; i++) {
				t.list[i] = gd.RunePO(e.data.list[i])
			}
			t.capacity = e.data.capacity;
			t.expandTimes = e.data.expandTimes;
			return t
		}
		static RunePO(e) {
			let t = {};
			t._idHex = e._idHex;
			t.attrIds = e.attrIds;
			t.skillIds = e.skillIds;
			t.levelAttrIds = e.levelAttrIds;
			if (e.reCast) {
				t.temp = {};
				t.temp.attrIds = e.reCast.attrIds;
				t.temp.skillIds = e.reCast.skillIds;
				t.temp.levelAttrIds = e.reCast.levelAttrIds
			}
			t.exp = e.exp;
			t.tid = e.tid;
			t.num = e.num;
			t.type = c.RUNE;
			return t
		}
		static DecBagRuneNew(e) {
			let t = {};
			t.list = [];
			for (let i = 0; i < e.list.length; i++) {
				t.list[i] = gd.RunePO(e.list[i])
			}
			return t
		}
	}
