	class a_ {
		static playBGM(e = null) {
			if (e) {
				this.bgmDic[e] = true
			}
			this.refreshBGM()
		}
		static stopBGM(e) {
			this.bgmDic[e] = false
		}
		static refreshBGM() {
			if (!FM.spaceMan.musicOn)
				return;
			if (this.bgmDic["pvp"]) {
				this.playMusic("bgm_pvp.mp3")
			} else if (this.bgmDic["pve"]) {
				this.playMusic("bgm_pve.mp3")
			} else if (this.bgmDic["preface"]) {
				this.playMusic("bgm_begin.mp3")
			} else if (this.bgmDic["raceTower"]) {
				this.playMusic("se_ui_tower_open.wav")
			} else {
				this.playMusic("bgm_maincity.mp3")
			}
		}
		static playMusic(e) {
			if (this.curBgm == e)
				return;
			this.curBgm = e;
			Laya.SoundManager.playMusic("sound/" + e)
		}
		static stopMusic() {
			this.curBgm = null;
			Laya.SoundManager.stopMusic()
		}
		static playSound(e, t = null) {
			if (!FM.spaceMan.soundOn) {
				if (t) {
					t.recover()
				}
				return
			}
			Laya.SoundManager.playSound("sound/" + e, 1, t)
		}
		static stopSound(e) {
			Laya.SoundManager.stopSound("sound/" + e)
		}
		static playSoundWithOutBGM(e) {
			if (!FM.spaceMan.soundOn)
				return
		}
		static playBattleVoice(e) {
			if (!FM.spaceMan.voiceOn)
				return;
			if (this.playingBattleVoiceDic[e])
				return;
			this.playingBattleVoiceDic[e] = true;
			Laya.SoundManager.playSound("sound/" + e, 1, Laya.Handler.create(this, this.battleVoiceEnd, [e]))
		}
		static battleVoiceEnd(e) {
			delete this.playingBattleVoiceDic[e]
		}
		static playUIVoice(e) {
			if (!FM.spaceMan.voiceOn)
				return;
			if (this.playingUIVoice == e)
				return;
			if (this.playingUIVoice) {
				Laya.SoundManager.stopSound("sound/" + this.playingUIVoice)
			}
			this.playingUIVoice = e;
			Laya.SoundManager.playSound("sound/" + e, 1, Laya.Handler.create(this, this.UIVoiceEnd, [e]))
		}
		static UIVoiceEnd(e) {
			this.playingUIVoice = null
		}
	}
