	class l_ extends Laya.Sprite {
		constructor(e, t, i) {
			super();
			this._canOprate = true;
			this._scaleClick = true;
			this.initGrid(e, t, i);
			this.on(Laya.Event.DISPLAY, this, this.onDisplay);
			this.on(Laya.Event.UNDISPLAY, this, this.onUnDisplay)
		}
		onDisplay(e) {}
		onUnDisplay(e) {}
		initSize() {
			this.gridWidth = 120;
			this.gridHeight = 120;
			this.iconWidth = 108;
			this.iconHeight = 108
		}
		initGrid(e, t, i) {
			this._info = e;
			this.initSize();
			if (!t)
				t = this.gridWidth;
			if (!i)
				i = this.gridHeight;
			this.ctn = new Laya.Sprite;
			this.addChild(this.ctn);
			this.width = t;
			this.height = i;
			this.ctn.width = this.gridWidth;
			this.ctn.height = this.gridHeight;
			this.scale(t / this.gridWidth, i / this.gridHeight);
			this.ctn.pivot(t / 2, i / 2);
			this.ctn.pos(t / 2, i / 2);
			this.updateInfo();
			this.ctn.on(Laya.Event.MOUSE_DOWN, this, this.scaleIn);
			this.ctn.on(Laya.Event.MOUSE_UP, this, this.scaleOut);
			this.ctn.on(Laya.Event.MOUSE_OUT, this, this.scaleOut);
			this.on(Laya.Event.CLICK, this, this.onClick)
		}
		onClick(e) {
			a_.playSound("se_icon_click.wav")
		}
		set canOprate(e) {
			if (this._canOprate == e)
				return;
			this._canOprate = e;
			if (e) {
				this.on(Laya.Event.CLICK, this, this.onClick)
			} else {
				this.off(Laya.Event.CLICK, this, this.onClick)
			}
		}
		get canOprate() {
			return this._canOprate
		}
		set scaleClick(e) {
			if (this._scaleClick == e)
				return;
			this._scaleClick = e;
			if (e) {
				this.ctn.on(Laya.Event.MOUSE_DOWN, this, this.scaleIn);
				this.ctn.on(Laya.Event.MOUSE_UP, this, this.scaleOut);
				this.ctn.on(Laya.Event.MOUSE_OUT, this, this.scaleOut)
			} else {
				this.ctn.off(Laya.Event.MOUSE_DOWN, this, this.scaleIn);
				this.ctn.off(Laya.Event.MOUSE_UP, this, this.scaleOut);
				this.ctn.off(Laya.Event.MOUSE_OUT, this, this.scaleOut)
			}
		}
		scaleIn() {
			Laya.Tween.to(this.ctn, {
				scaleX: 1.1,
				scaleY: 1.1
			}, 100, undefined, undefined, 0, true)
		}
		scaleOut() {
			Laya.Tween.to(this.ctn, {
				scaleX: 1,
				scaleY: 1
			}, 100, undefined, undefined, 0, true)
		}
		set info(e) {
			this._info = e;
			this.updateInfo()
		}
		get info() {
			return this._info
		}
		updateInfo() {
			if (!this.info.baseTpl) {
				console.error("Không tồn tại vật phẩm, type:" + this.info.type + "，tid:" + this.info.tid + "，num:" + this.info.num + "，idHex:" + (this.info.idHex ? this.info.idHex : this.info._idHex));
				i.reportError("normalError", "Không tồn tại vật phẩm, type:" + this.info.type + "，tid:" + this.info.tid + "，num:" + this.info.num + "，idHex:" + (this.info.idHex ? this.info.idHex : this.info._idHex));
				return
			}
			this.updateBg();
			this.updateIcon()
		}
		updateBg() {}
		updateIcon() {
			if (!this.icon) {
				this.icon = new r_;
				this.ctn.addChild(this.icon);
				this.icon.pos((this.gridWidth - this.iconWidth) / 2, (this.gridHeight - this.iconHeight) / 2)
			}
			this.icon.iconId = this._info.baseTpl.icon
		}
	}
