	class b_ {
		static getTimeStamp() {
			return uP.getIns().serverTime
		}
		static isSameToday(e) {
			this.tmpDate0.setTime(e);
			this.tmpDate1.setTime(this.getTimeStamp());
			return this.tmpDate0.getDate() == this.tmpDate1.getDate() && this.tmpDate0.getMonth() == this.tmpDate1.getMonth() && this.tmpDate0.getFullYear() == this.tmpDate1.getFullYear()
		}
		static getDayStartTimeStamp(e = null) {
			if (!e)
				e = this.getTimeStamp();
			this.tmpDate0.setTime(e);
			this.tmpDate0.setHours(0);
			this.tmpDate0.setMinutes(0);
			this.tmpDate0.setSeconds(0);
			this.tmpDate0.setMilliseconds(0);
			return this.tmpDate0.getTime()
		}
		static getDayEndTimeStamp(e = null) {
			return this.getDayStartTimeStamp(e) + this.ONEDAYMILLISECONDS
		}
		static getWeekStartTimeStamp(e = null) {
			if (!e)
				e = this.getTimeStamp();
			this.tmpDate0.setTime(e);
			this.tmpDate0.setHours(0);
			this.tmpDate0.setMinutes(0);
			this.tmpDate0.setSeconds(0);
			this.tmpDate0.setMilliseconds(0);
			let t = this.tmpDate0.getDay();
			if (t == 0) {
				t = 7
			}
			t = t - 1;
			return this.tmpDate0.getTime() - t * this.ONEDAYMILLISECONDS
		}
		static getWeekEndTimeStamp(e = null) {
			return this.getWeekStartTimeStamp(e) + 7 * this.ONEDAYMILLISECONDS
		}
		static getWeekDay(e = null) {
			if (!e)
				e = this.getTimeStamp();
			this.tmpDate0.setTime(e);
			let t = this.tmpDate0.getDay();
			if (t == 0) {
				t = 7
			}
			return t
		}
		static getMonthStartTimeStamp(e = null) {
			if (!e)
				e = this.getTimeStamp();
			this.tmpDate0.setTime(e);
			this.tmpDate0.setDate(1);
			this.tmpDate0.setHours(0);
			this.tmpDate0.setMinutes(0);
			this.tmpDate0.setSeconds(0);
			this.tmpDate0.setMilliseconds(0);
			return this.tmpDate0.getTime()
		}
		static getMonthEndTimeStamp(e = null) {
			if (!e)
				e = this.getTimeStamp();
			this.tmpDate0.setTime(e);
			this.tmpDate0.setDate(1);
			this.tmpDate0.setHours(0);
			this.tmpDate0.setMinutes(0);
			this.tmpDate0.setSeconds(0);
			this.tmpDate0.setMilliseconds(0);
			if (this.tmpDate0.getMonth() == 11) {
				this.tmpDate0.setFullYear(this.tmpDate0.getFullYear() + 1, 0)
			} else {
				this.tmpDate0.setMonth(this.tmpDate0.getMonth() + 1)
			}
			return this.tmpDate0.getTime()
		}
		static getRefreshTimeStamp(e, t = null) {
			if (!t)
				t = this.getTimeStamp();
			let i = e.split(":");
			let s = parseInt(i[0]);
			let a = parseInt(i[1]);
			let r;
			if (i.length == 3) {
				r = i[2].split(",")
			}
			let l = this.tmpDate0;
			if (!r) {
				switch (s) {
				case this.TIMETYPE_HOUR:
					return t + 3600 * 1e3 * a;
				case this.TIMETYPE_DAY:
					return t + 24 * 3600 * 1e3 * a;
				case this.TIMETYPE_WEEK:
					return t + 7 * 24 * 3600 * 1e3 * a;
				case this.TIMETYPE_MONTH:
					l.setTime(t);
					if (l.getMonth() + a > 11) {
						l.setFullYear(l.getFullYear() + 1, l.getMonth() + a - 12)
					} else {
						l.setMonth(l.getMonth() + a)
					}
					return l.getTime()
				}
			} else {
				let e = Number.MAX_VALUE;
				let i;
				for (let l = 0; l < r.length; l++) {
					i = this.getNextTimeByStartTime(t, s, a, parseInt(r[l]));
					if (i < e) {
						e = i
					}
				}
				return e
			}
		}
		static getNextTimeByStartTime(e, t, i, s) {
			let a = this.tmpDate0;
			a.setTime(e);
			switch (t) {
			case this.TIMETYPE_HOUR:
				if (a.getMinutes() >= s) {
					a.setTime(e + 3600 * 1e3 * i)
				} else {
					a.setTime(e + 3600 * 1e3 * (i - 1))
				}
				a.setMinutes(s);
				a.setSeconds(0);
				return a.getTime();
			case this.TIMETYPE_DAY:
				if (a.getHours() >= s) {
					a.setTime(e + 24 * 3600 * 1e3 * i)
				} else {
					a.setTime(e + 24 * 3600 * 1e3 * (i - 1))
				}
				a.setHours(s);
				a.setMinutes(0);
				a.setSeconds(0);
				return a.getTime();
			case this.TIMETYPE_WEEK:
				let r = a.getDay();
				if (r == 0) {
					r = 7
				}
				if (r >= s) {
					a.setTime(e + 7 * 24 * 3600 * 1e3 * i)
				} else {
					a.setTime(e + 7 * 24 * 3600 * 1e3 * (i - 1))
				}
				let l = s - r;
				a.setHours(0);
				a.setMinutes(0);
				a.setSeconds(0);
				return a.getTime() + l * 24 * 3600 * 1e3;
			case this.TIMETYPE_MONTH:
				let h = 0;
				if (a.getDate() >= s) {
					h = i
				} else {
					h = i - 1
				}
				if (a.getMonth() + h > 11) {
					a.setFullYear(a.getFullYear() + 1, a.getMonth() + h - 12)
				} else {
					a.setMonth(a.getMonth() + h)
				}
				a.setDate(1);
				a.setHours(0);
				a.setMinutes(0);
				a.setSeconds(0);
				return a.getTime()
			}
		}
		static getLitTimeStr(e) {
			var t = Math.ceil(e / 1e3);
			var i;
			if (t < 60) {
				i = WM.getLanCodeTip(20085, [t])
			} else if (t < 3600) {
				i = WM.getLanCodeTip(20086, [Math.floor(t / 60)])
			} else if (t < 86400) {
				i = WM.getLanCodeTip(20087, [Math.floor(t / 3600)])
			} else {
				i = WM.getLanCodeTip(20088, [Math.floor(t / 86400)])
			}
			return i
		}
		static getCdTimeStrByMs(e, t = "[hh]:[mm]:[ss]") {
			return this.getCdTimeStrBySec(Math.floor(e / 1e3), t)
		}
		static getCdTimeStrBySec(e, t = "[hh]:[mm]:[ss]") {
			if (t.indexOf("[YY]") != -1) {
				let i = Math.floor(e / (this.ONEDAYSECONDS * 365));
				t = t.replace("[YY]", "" + i);
				e = e % (this.ONEDAYSECONDS * 365)
			}
			if (t.indexOf("[MM]") != -1) {
				let i = Math.floor(e / (this.ONEDAYSECONDS * 30));
				t = t.replace("[MM]", "" + i);
				e = e % (this.ONEDAYSECONDS * 30)
			}
			if (t.indexOf("[DD]") != -1) {
				let i = Math.floor(e / this.ONEDAYSECONDS);
				t = t.replace("[DD]", "" + i);
				e = e % 86400
			}
			if (t.indexOf("[hh]") != -1) {
				let i = Math.floor(e / 3600);
				t = t.replace("[hh]", this.getTimeNumStr(i));
				e = e % 3600
			}
			if (t.indexOf("[mm]") != -1) {
				let i = Math.floor(e / 60);
				t = t.replace("[mm]", this.getTimeNumStr(i));
				e = e % 60
			}
			if (t.indexOf("[ss]") != -1) {
				t = t.replace("[ss]", this.getTimeNumStr(e))
			}
			return t
		}
		static getTimeStmapStr(e, t = "[YY]-[MM]-[DD] [hh]:[mm]:[ss]") {
			this.tmpDate0.setTime(e);
			if (t.indexOf("[YY]") != -1) {
				t = t.replace("[YY]", "" + this.tmpDate0.getFullYear())
			}
			if (t.indexOf("[MM]") != -1) {
				t = t.replace("[MM]", "" + (this.tmpDate0.getMonth() + 1))
			}
			if (t.indexOf("[DD]") != -1) {
				t = t.replace("[DD]", "" + this.tmpDate0.getDate())
			}
			if (t.indexOf("[hh]") != -1) {
				t = t.replace("[hh]", this.getTimeNumStr(this.tmpDate0.getHours()))
			}
			if (t.indexOf("[mm]") != -1) {
				t = t.replace("[mm]", this.getTimeNumStr(this.tmpDate0.getMinutes()))
			}
			if (t.indexOf("[ss]") != -1) {
				t = t.replace("[ss]", this.getTimeNumStr(this.tmpDate0.getSeconds()))
			}
			return t
		}
		static getTimeNumStr(e) {
			return e >= 10 ? "" + e : "0" + e
		}
		static getWeekDayStr(e) {
			let t = "";
			switch (e) {
			case 0:
				t = WM.getLanCodeTip(10197);
				break;
			case 1:
				t = WM.getLanCodeTip(10198);
				break;
			case 2:
				t = WM.getLanCodeTip(10199);
				break;
			case 3:
				t = WM.getLanCodeTip(10200);
				break;
			case 4:
				t = WM.getLanCodeTip(10201);
				break;
			case 5:
				t = WM.getLanCodeTip(10202);
				break;
			case 6:
				t = WM.getLanCodeTip(10203);
				break
			}
			return t
		}
		static getDayHourStr(e) {
			let t = Math.floor(e / 1e3);
			let i = Math.floor(t / 86400);
			let s = Math.floor(t % 86400 / 3600);
			return WM.getLanCodeTip(20089, [i, s])
		}
		static getActEndTime(e, t) {
			let i = t.split(":");
			let s = parseInt(i[0]);
			let a = parseInt(i[1]);
			let r = parseInt(i[2]);
			return ((e - 1) * 86400 + s * 3600 + a * 60 + r) * 1e3
		}
		static getActStartTime(e, t) {
			let i = t.split(":");
			let s = parseInt(i[0]);
			let a = parseInt(i[1]);
			let r = parseInt(i[2]);
			return ((e - 1) * 86400 + s * 3600 + a * 60 + r) * 1e3
		}
		static getActTimeByStr(e) {
			let t = new Date;
			let i = e.split(" ");
			let s = i[0].split("-");
			let a = i[1].split(":");
			t.setFullYear(parseInt(s[0]), parseInt(s[1]) - 1, parseInt(s[2]));
			t.setHours(parseInt(a[0]), parseInt(a[1]), parseInt(a[2]));
			return t
		}
		static getTimeStrMs(e) {
			let t = e.split(":");
			let i = parseInt(t[0]);
			let s = parseInt(t[1]);
			let a = parseInt(t[2]);
			return (i * 3600 + s * 60 + a) * 1e3
		}
	}
	b_.tmpDate0 = new Date;
	b_.tmpDate1 = new Date;
	b_.ONEDAYMILLISECONDS = 24 * 3600 * 1e3;
