		delayRefreshPannelFun() {
			this.isLevelChange = false;
			this.refreshPannel0()
		}
		getCurLevelAddAttr(e, t = 0, i = 0) {
			let s = [];
			let a = 0;
			for (let r = 1; r <= t; r++) {
				let l = this.getCurBeastLevelTpl(e, r);
				a = i;
				if (t != r) {
					a = l.levelTimes
				}
				for (let e = 1; e <= a; e++) {
					n_.mergeArr2Arr(s, l.attr, true)
				}
				if (t >= r) {
					n_.mergeArr2Arr(s, l.levelAttr, true)
				}
			}
			return s
		}
		getCurLevelMaxAddAttr(e) {
			let t = [];
			let i = this.getCurBeastMaxLevelTpl(e);
			for (let s = 1; s <= i.level; s++) {
				let a = this.getCurBeastLevelTpl(e, s);
				let r = a.levelTimes;
				for (let e = 1; e <= r; e++) {
					n_.mergeArr2Arr(t, a.attr, true)
				}
				if (i.level >= s) {
					n_.mergeArr2Arr(t, a.levelAttr, true)
				}
			}
			return t
		}
