		static canMingGeOnOne(e, t) {
			if (e.baseTpl.star < t.heroStar)
				return false;
			let i = e.mingGeDic[t.id];
			let s = WM.splitToNumArr(t.protoIds);
			let a = [];
			let r = uP.getIns().bag.mingGe.list;
			for (let l = 0; l < r.length; l++) {
				if (t.type != r[l].baseTpl.type)
					continue;
				if (s.indexOf(r[l].baseTpl.protoId) != -1) {
					a.push(r[l])
				}
			}
			if (a.length) {
				if (!i)
					return true;
				a.sort(this.sortMGFun);
				if (a[0].baseTpl.quality > i.baseTpl.quality) {
					return true
				} else if (a[0].baseTpl.quality == i.baseTpl.quality) {
					if (a[0].level) {
						let e = a[0].level;
						if (a[0].shareLevel > 0) {
							e = a[0].shareLevel
						}
						let t = i.level;
						if (i.shareLevel > 0) {
							t = i.shareLevel
						}
						if (e == t && a[0].grade > i.grade) {
							return true
						}
						if (!t || e > t) {
							return true
						}
					}
				}
			}
			return false
		}
		static sortMGFun(e, t) {
			if (e.baseTpl.quality == t.baseTpl.quality) {
				if (e.level && !t.level) {
					return -100
				} else if (t.level && !e.level) {
					return 100
				} else {
					let i = e.level;
					if (e.shareLevel > 0) {
						i = e.shareLevel
					}
					let s = t.level;
					if (t.shareLevel > 0) {
						s = t.shareLevel
					}
					if (i != s) {
						return s - i
					}
					if (i == s) {
						if (e.grade != 0 || t.grade != 0) {
							return t.grade - e.grade
						}
						return e.baseTpl.id - t.baseTpl.id
					} else {
						return s - i
					}
				}
			} else {
				return t.baseTpl.quality - e.baseTpl.quality
			}
		}
