	class ig extends Laya.List {
		constructor() {
			super(...arguments);
			this._initWidth = null;
			this._initHeight = null;
			this.isShowEffect = true;
			this._delayTotalFrame = 15;
			this._delaySingleFrame = 1;
			this._totalFrame = 10
		}
		get array() {
			return super.array
		}
		set array(e) {
			super.array = e;
			if (this._initWidth == null) {
				this._initWidth = this.width
			}
			if (this._initHeight == null) {
				this._initHeight = this.height
			}
			this.centerX = 0;
			this.centerY = 0;
			var t = this.cells[0];
			if (!t) {
				t = this.createItem()
			}
			var i = t.width * e.length + this.spaceX * (e.length - 1);
			if (i > this._initWidth) {
				this.width = this._initWidth
			} else {
				this.width = i
			}
			if (this.scrollBar && this.scrollBar.isVertical) {
				var s = t.width + this.spaceX;
				var a = this.scrollBar.isVertical ? Math.round(this._initWidth / s) : Math.ceil(this._initWidth / s);
				var r = Math.ceil(e.length / a);
				var l = t.height * r + this.spaceY * (r - 1);
				if (l > this._initHeight) {
					this.height = this._initHeight
				} else {
					this.height = l
				}
			}
		}
		showEffect(e = null, t = null, i = 10, s = 15, a = 1, r = ig.SCALE) {
			this.isShowEffect = true;
			this._caller = e;
			this._completeFun = t;
			this._delayTotalFrame = s;
			this._delaySingleFrame = a;
			this._totalFrame = i;
			this._curState = r
		}
		hideEffect() {
			if (this.delayShowArr && this.delayShowArr.length > 0) {
				Laya.timer.clear(this, this.updateAnimFun);
				for (let e = 0; e < this.delayShowArr.length; e++) {
					let t = this.delayShowArr[e];
					if (this._curState == ig.ALPHA) {
						t.cell.alpha = 1
					} else if (this._curState == ig.SCALE) {
						t.cell.scaleX = t.cell.scaleY = 1
					}
				}
				this.delayShowArr = null
			}
		}
		renderItems(e, t) {
			super.renderItems(e, t);
			if (this.isShowEffect) {
				this.delayShowArr = [];
				for (let e = 0; e < this.cells.length; e++) {
					this.delayShowArr.push({
						cell: this.cells[e],
						totalTime: this._totalFrame,
						delayTime: this._delayTotalFrame + e * this._delaySingleFrame,
						curTime: 0,
						isComplete: false
					})
				}
				Laya.timer.once(500, this, this.effectStateChange)
			}
			if (this.delayShowArr && this.delayShowArr.length > 0) {
				for (let e = 0; e < this.delayShowArr.length; e++) {
					let t = this.delayShowArr[e];
					if (this._curState == ig.ALPHA) {
						t.cell.alpha = 0
					} else if (this._curState == ig.SCALE) {
						t.cell.scaleX = t.cell.scaleY = 0
					}
				}
				Laya.timer.frameLoop(1, this, this.updateAnimFun)
			}
		}
		effectStateChange() {
			this.isShowEffect = false
		}
		updateAnimFun() {
			let e = false;
			let t = 0;
			if (this.delayShowArr) {
				for (let e = 0; e < this.delayShowArr.length; e++) {
					let i = this.delayShowArr[e];
					if (i.isComplete == false) {
						i.curTime += 1;
						if (i.curTime <= i.delayTime)
							continue;
						if (i.curTime <= i.delayTime + i.totalTime) {
							i.curTime += 1;
							let e = (i.curTime - i.delayTime) / i.totalTime;
							if (this._curState == ig.ALPHA) {
								i.cell.alpha = (1 - 0) * e
							} else if (this._curState == ig.SCALE) {
								i.cell.scaleX = i.cell.scaleY = (1 - 0) * e + -2 * e * (e - 1)
							}
							continue
						}
						i.isComplete = true;
						t += 1
					} else {
						t += 1
					}
				}
				if (t >= this.delayShowArr.length) {
					e = true
				}
			}
			if (e == true) {
				Laya.timer.clear(this, this.updateAnimFun);
				if (this._completeFun) {
					this._completeFun.call(this._caller)
				}
				this.delayShowArr = null
			}
		}
	}
	ig.SCALE = "scale";
