	class hg extends g {
		constructor() {
			super("EquipRecast");
			this.tarCampX = 0;
			this.middleTarX = 0;
			this._loopX = 0;
			this._recasting = true
		}
		static getIns() {
			if (!this._ins) {
				this._ins = new hg
			}
			return this._ins
		}
		getMsgs() {
			return [jd.EQUIP_RECAST_REC]
		}
		exeMsg(e, t) {
			switch (t) {
			case jd.EQUIP_RECAST_REC:
				this.equipRecastRec(e);
				break
			}
		}
		getCmds() {
			return [d.HERO_EQUIP_RECAST, d.BAG_EQUIP_RECAST]
		}
		exeCmd(e, t) {
			switch (t) {
			case d.HERO_EQUIP_RECAST:
				this.heroEquipRecast(e);
				break;
			case d.BAG_EQUIP_RECAST:
				this.bagEquipRecast(e);
				break
			}
		}
		onClick(e) {
			switch (e.target) {
			case this._ui.btnClose:
				this.closeUI();
				break;
			case this._ui.btnRecast:
				this.recastClick();
				break;
			case this._ui.btnTip:
				D_.showById(177);
				break
			}
		}
		initUI() {
			this._ui = this.uiView;
			this.setLayer(1, 1, 1, 1);
			this._ui.listHero.mouseHandler = Laya.Handler.create(this, this.onHeroClick, null, false);
			this.campImgArr = [];
			for (let e = 0; e < 5; e++) {
				this.campImgArr.push(this._ui["imgCamp" + e])
			}
			this._ui.boxLoop.scrollRect = new Laya.Rectangle(0, 0, this._ui.boxLoop.width, this._ui.boxLoop.height);
			this.cellWidth = 15 + 87;
			this.loopWidth = this._ui.boxLoop.width + this.cellWidth
		}
		afterClose() {
			if (this.recasting) {
				if (this.equip) {
					sg.getIns().show([this.equip], 1)
				}
			}
			this.stopTimers()
		}
		set loopX(e) {
			this._loopX = e;
			for (let t = 0; t < this.campImgArr.length; t++) {
				let i = this.campImgArr[t];
				i.x = (this.cellWidth * t + e) % this.loopWidth - .5 * this.cellWidth
			}
		}
		get loopX() {
			return this._loopX
		}
		set recasting(e) {
			this._recasting = e;
			this._ui.btnRecast.disabled = e
		}
		get recasting() {
			return this._recasting
		}
		startNormalLoop() {
			this.stopTimers();
			Laya.timer.frameLoop(1, this, this.normalLoop)
		}
		stopTimers() {
			this.recasting = false;
			Laya.timer.clear(this, this.normalLoop);
			Laya.timer.clear(this, this.recastLoop)
		}
		normalLoop() {
			this.loopX += 1
		}
		startRecastLoop(e) {
			this.stopTimers();
			this.recasting = true;
			this.tarCampX = this.loopX + this.loopWidth * 5;
			this.tarCampX = this.tarCampX - this.tarCampX % this.loopWidth;
			for (let t = 0; t < this.campArr.length; t++) {
				if (this.campArr[t] == e) {
					this.tarCampX += this.loopWidth * .5 - this.cellWidth * t;
					break
				}
			}
			this.middleTarX = (this.tarCampX - this.loopX) / 2 + this.loopX;
			Laya.timer.frameLoop(1, this, this.recastLoop)
		}
		recastLoop() {
			let e = 1;
			let t = this.tarCampX - this.middleTarX;
			if (this.loopX <= this.middleTarX) {
				e = 4 + 180 * Math.pow((t - (this.middleTarX - this.loopX)) / t, 2)
			} else {
				e = 2 + 180 * Math.pow((t - (this.loopX - this.middleTarX)) / t, 2)
			}
			this.loopX += e;
			if (this.loopX > this.tarCampX) {
				this.loopX = this.tarCampX;
				Laya.timer.clear(this, this.recastLoop);
				Laya.timer.once(500, this, this.recastResult)
			}
		}
		recastResult() {
			this.stopTimers();
			if (this.equip) {
				sg.getIns().show([this.equip], 1);
				this.refresh()
			}
		}
		show(e, t = null) {
			this.openUI();
			this.equip = e;
			this.heroIdHex = t;
			this.refresh()
		}
		refresh() {
			Tb.addItemGrid(this.equip, this._ui.boxGrid);
			this.campArr = [1, 2, 3, 4, 5, 6];
			for (let s = 0; s < this.campArr.length; s++) {
				if (this.campArr[s] == this.equip.campMark) {
					this.campArr.splice(s, 1);
					break
				}
			}
			for (let s = 0; s < this.campArr.length; s++) {
				let e = this._ui["imgCamp" + s];
				e.skin = "icon/camp" + this.campArr[s] + ".png"
			}
			this.loopX = 0;
			this.startNormalLoop();
			this._ui.imgCurCamp.skin = "img/baseUI/camp" + this.equip.campMark + ".png";
			let e = od.getGlobalValue(36001, 0);
			let t = this.data.bag.hero.list;
			let i = [];
			for (let s = 0; s < t.length; s++) {
				if (t[s].baseTpl.camp == this.equip.campMark && t[s].baseTpl.star > e) {
					i.push(t[s])
				}
			}
			this._ui.listHero.array = i;
			this._ui.imgNone.visible = i.length <= 0;
			this._ui.boxCost.dataSource = this.equip.baseTpl.recastCost
		}
		onHeroClick(e, t) {
			if (e.type != Laya.Event.CLICK)
				return;
			let i = this._ui.listHero.getItem(t);
			if (!i)
				return;
			Im.getIns().openByHero(i.idHex, i.baseTpl.camp);
			this.closeUI()
		}
		recastClick() {
			if (this.recasting)
				return;
			if (this.heroIdHex) {
				this.sendMsg(jd.EQUIP_RECAST_REQ, {
					equipIdHex: this.equip._idHex,
					heroIdHex: this.heroIdHex,
					pos: this.equip.baseTpl.type
				})
			} else {
				this.sendMsg(jd.EQUIP_RECAST_REQ, {
					equipIdHex: this.equip._idHex
				})
			}
		}
		heroEquipRecast(e) {
			if (!this.isOpen)
				return;
			if (e.idHex != this.heroIdHex)
				return;
			let t = this.data.bag.hero.getItem(e.idHex);
			if (!t)
				return;
			let i = t.equipDic[e.pos];
			if (!i)
				return;
			if (i._idHex != this.equip._idHex)
				return;
			this.equip = i;
			this.startRecastLoop(this.equip.campMark)
		}
		bagEquipRecast(e) {
			if (!this.isOpen)
				return;
			if (!e.equip)
				return;
			let t = e.equip;
			if (t._idHex != this.equip._idHex)
				return;
			this.equip = t;
			this.startRecastLoop(this.equip.campMark)
		}
		equipRecastRec(e) {
			if (e.result == 1) {
				this.closeUI()
			}
		}
	}
