	class gg {
		static get allShopTabData() {
			if (!this._allShopTabData) {
				this.decodeTpl()
			}
			return this._allShopTabData
		}
		static decodeTpl() {
			if (gg._allShopTabData)
				return;
			let e = od.getTplInfo(nd.SHOPINFO);
			gg._allShopTabData = new Array;
			gg._tabTypeIndex = [];
			let t;
			let i;
			for (let s = 0; s < e.length; s++) {
				if (e[s].type0 != undefined) {
					t = e[s].type0 - 1;
					if (!gg._allShopTabData[t]) {
						gg._allShopTabData[t] = {}
					}
					gg._allShopTabData[t].name = e[s].name;
					gg._allShopTabData[t].id = e[s].id
				}
				if (e[s].type1) {
					i = e[s].type1 - 1;
					if (!gg._allShopTabData[t].typeArr) {
						gg._allShopTabData[t].typeArr = []
					}
					gg._allShopTabData[t].typeArr[i] = {};
					gg._allShopTabData[t].typeArr[i].id = e[s].id;
					gg._allShopTabData[t].typeArr[i].name = e[s].name
				}
				if (e[s].tabType) {
					gg._tabTypeIndex[e[s].tabType - 1] = t
				}
			}
		}
		static get tabTypeIndex() {
			if (!this._tabTypeIndex) {
				this.decodeTpl()
			}
			return this._tabTypeIndex
		}
		static getShopTabIndexData(e) {
			return this.allShopTabData[this.tabTypeIndex[e]]
		}
		static checkShopDataRec(e, t) {
			let s = gg.allShopTabData;
			let a = false;
			for (let i = 0; i < s.length; i++) {
				if (s[i].typeArr) {
					let t = s[i].typeArr;
					for (let i = 0; i < t.length; i++) {
						if (t[i].id == e) {
							a = true;
							break
						}
					}
				}
				if (a || s[i].id == e) {
					a = true;
					break
				}
			}
			if (!a) {
				i.reportError("zcqError", "Cửa hàng id Có vấn đề shopId:" + e + "Số liệu" + JSON.stringify(t));
				return
			}
			if (this.shopDataRecord[e] >= 5) {
				i.reportError("zcqError", "Có vấn đề shopId:" + e + "Số lần" + this.shopDataRecord[e] + "Số liệu" + JSON.stringify(t))
			}
		}
		static getShowData(e) {
			if (!gg.allShopData[e]) {
				let t = 0;
				if (!this.shopDataRecord[e]) {
					this.shopDataRecord[e] = 0
				}
				this.shopDataRecord[e]++;
				if (this.shopDataRecord[e] >= 5) {
					i.reportError("normalError", "Có vấn đề shopId:" + e + "Số lần" + this.shopDataRecord[e]);
					t = 1
				}
				FM.shopMan.refreshShopDataById(e, 0, t);
				return null
			}
			if (this.shopDataRecord[e]) {
				this.shopDataRecord[e] = 0
			}
			let t = gg.allShopData[e];
			let s = od.getTplInfo(nd.SHOPINFO, e);
			if (s.limitTime && this.isCanRefresh(t, s)) {
				FM.shopMan.refreshShopDataById(e, 0);
				return null
			}
			if (s.freeTime && this.isCanFreeTimesRefresh(t, s)) {
				FM.shopMan.refreshShopDataById(e, 0);
				return null
			}
			return gg.allShopData[e]
		}
		static getPropShowData() {
			let e = this.allShopTabData[this.PROPSHOPINDEX];
			return this.getShowData(e.id)
		}
		static getPropOneData(e) {
			let t = this.getPropShowData();
			if (!t)
				return null;
			let i = t.itemList;
			for (let s = 0; s < i.length; s++) {
				if (i[s].tid == e) {
					return i[s]
				}
			}
			return null
		}
		static isCanFreeTimesRefresh(e, t) {
			let i = 0;
			if (e.freeTimes < t.freeTimesMax) {
				let i = b_.getRefreshTimeStamp(t.freeTime, e.lastFreeRefreshTime);
				if (b_.getTimeStamp() > i) {
					return true
				} else {
					return false
				}
			}
			return false
		}
		static isCanRefresh(e, t) {
			let i = e.lastAutoRefreshTime;
			let s = b_.getRefreshTimeStamp(t.limitTime, i);
			return b_.getTimeStamp() >= s
		}
		static setShowData(e, t) {
			if (!t)
				return;
			gg.allShopData[e] = t
		}
	}
