	class kg {
		static getInfoSplitStr2Arr(e, t = "#", i = ":") {
			let s = [];
			if (e == "") {
				return s
			}
			let a = e.split(t);
			for (let r = 0; r < a.length; r++) {
				let e = {};
				let t = a[r].split(i);
				e.id = parseInt(t[0]);
				let l = od.getTplInfo(nd.PROPGETINFO, e.id);
				if (l.funcId && !FM.funcMan.checkFuncOpen(l.funcId, false)) {
					e.open = 0
				} else {
					e.open = 1
				}
				if (t[1]) {
					e.isRecommend = parseInt(t[1])
				} else {
					e.isRecommend = 0
				}
				s.push(e)
			}
			return s
		}
	}
