	class Zg {
		static getCurTypes() {
			if (uP.getIns().master.level < od.getGlobalValue(1212)) {
				return [Zg.TYPE_NEW_HAND, Zg.TPYE_CROSS, Zg.TPYE_ZONE, Zg.TPYE_GUILD, Zg.TPYE_PRIVATE, Zg.TPYE_SYSTEM, Zg.TPYE_CW]
			} else if (uP.getIns().master.level >= od.getGlobalValue(1212)) {
				return [Zg.TYPE_OLD_HAND, Zg.TPYE_CROSS, Zg.TPYE_ZONE, Zg.TPYE_GUILD, Zg.TPYE_PRIVATE, Zg.TPYE_SYSTEM, Zg.TPYE_CW]
			}
		}
		static isCanSaveState() {
			if (uP.getIns().master.level >= od.getGlobalValue(1211) && uP.getIns().master.level < od.getGlobalValue(1212)) {
				return 1
			} else if (uP.getIns().master.level >= od.getGlobalValue(1212)) {
				return 2
			}
			return 0
		}
		static set chatData(e) {
			this._chatData = e
		}
		static set lastChatTime(e) {
			if (!this._chatData)
				return;
			this._chatData.lastChatTime = e
		}
		static get lastChatTime() {
			if (!this._chatData)
				return 0;
			return this._chatData.lastChatTime
		}
		static updataChatItem(e, t = false) {
			if (!e)
				return;
			let i = this.getChannelData(e.channel);
			let s = i.items;
			s.push(e);
			if (!t) {
				if (e.channel != this.TPYE_SYSTEM) {
					if (!e.sender || e.sender.id != "sys") {
						this.allChatData[e.channel].newNum++;
						this.updataChatNum()
					}
				}
			}
			this.checkChannelItemsNum(e.channel, t)
		}
		static updataChannelList(e, t) {
			delete this.allChatData[e];
			let i = this.getChannelData(e);
			i.items = t;
			i.newNum = t.length;
			this.updataChatNum()
		}
		static getChannelData(e) {
			if (!this.allChatData[e]) {
				this.allChatData[e] = {};
				this.allChatData[e].newNum = 0;
				this.allChatData[e].items = []
			}
			return this.allChatData[e]
		}
		static getChannelItems(e) {
			let t = this.getChannelData(e);
			return t.items
		}
		static checkChannelItemsNum(e, t = false) {
			let i = 50;
			if (t) {
				i = 80
			}
			let s = this.getChannelData(e);
			if (s.items.length > i) {
				s.items.splice(0, s.items.length - i)
			}
		}
		static getChannelDotNum(e) {
			let t = this.getChannelData(e);
			return t.newNum
		}
		static clearItemData(e) {
			if (!this.allChatData[e])
				return;
			this.allChatData[e].items = [];
			this.clearItemNum(e)
		}
		static clearItemNum(e) {
			if (!this.allChatData[e])
				return;
			if (this.allChatData[e].newNum > 0) {
				this.allChatData[e].newNum = 0;
				this.updataChatNum()
			}
		}
		static updataFriendChat(e) {
			if (!e || !e.length)
				return;
			this.privateChatData = {};
			for (let t = 0; t < e.length; t++) {
				this.updataPrivateChatList(e[t].it, e[t].chatList)
			}
		}
		static updataPrivateChatList(e, t) {
			if (!t || !t.length)
				return;
			let i = e.srv ? e.srv.code : uP.getIns().zoneCode;
			this.getPrivateData(e._idHex, i, true);
			let s = {};
			s.fromId = e._idHex;
			s.fromZoneCode = i;
			for (let a = 0; a < t.length; a++) {
				if (!t[a].c)
					continue;
				if (t[a].i) {
					this.updataPrivateChatMy(e._idHex, t[a].c, t[a].t)
				} else {
					s.content = t[a].c;
					this.updataPrivateChat(s, false, t[a].t)
				}
			}
		}
		static updataPrivateChat(e, t = false, i = 0) {
			if (!e)
				return;
			let s = this.getPrivateData(e.fromId, e.fromZoneCode, true);
			let a = {};
			let r = uP.getIns().master.readNoteBook(this.NOTEPRE + e.fromId);
			if (!r)
				r = 0;
			a.sender = s.sender;
			a.content = e.content;
			if (i == 0) {
				i = b_.getTimeStamp()
			}
			s.t = a.t = i;
			s.items.push(a);
			if (!t) {
				if (i > r) {
					this.privateChatData[e.fromId].newNum++;
					this.updataChatNum()
				}
			} else {
				if (i > r) {
					uP.getIns().master.writeNoteBook(this.NOTEPRE + e.fromId, i)
				}
			}
		}
		static updataPrivateChatMy(e, t, i = 0) {
			if (!this.privateChatData[e]) {
				return
			}
			let s = {};
			s.sender = this.getMySender();
			s.content = t;
			this.privateChatData[e].t = s.t = i == 0 ? b_.getTimeStamp() : i;
			this.privateChatData[e].items.push(s)
		}
		static getMySender() {
			if (!this.mySender) {
				this.mySender = {};
				this.mySender.id = uP.getIns().master.idHex;
				this.mySender.name = uP.getIns().master.name;
				this.mySender.city = 1e4
			}
			return this.mySender
		}
		static getPrivateData(e, t = null, i = false) {
			if (!this.privateChatData[e] && i) {
				this.privateChatData[e] = {};
				this.privateChatData[e].newNum = 0;
				this.privateChatData[e].items = [];
				this.privateChatData[e].sender = {};
				this.privateChatData[e].t = b_.getTimeStamp();
				let i = Xg.getMyFriend(e);
				this.privateChatData[e].sender.id = e;
				if (i) {
					this.privateChatData[e].sender.srvCode = i.it.srv ? i.it.srv.code : uP.getIns().zoneCode;
					this.privateChatData[e].sender.name = i.it.profile.name;
					this.privateChatData[e].sender.headIcon = i.it.profile.headIcon;
					this.privateChatData[e].sender.headFrame = i.it.profile.headFrame;
					this.privateChatData[e].sender.city = i.it.profile.city
				} else {
					this.privateChatData[e].sender.srvCode = t;
					this.privateChatData[e].sender.name = "name"
				}
				if (this.privateList) {
					if (!this.privateList[this.privateList.length - 1]) {
						this.privateList[this.privateList.length - 1] = this.privateChatData[e];
						this.checkPrivateListLenth()
					}
				}
			}
			return this.privateChatData[e]
		}
		static getPrivateIdNum(e) {
			let t = this.getPrivateData(e);
			return t.newNum
		}
		static getPrivateIdItems(e) {
			let t = this.getPrivateData(e);
			return t.items
		}
		static getPrivateListNum() {
			let e = 0;
			for (let t in this.privateChatData) {
				e++
			}
			return e
		}
		static isHasPrivateData(e) {
			return this.privateChatData[e]
		}
		static getPrivateList(e) {
			if (this.privateList) {
				return this.privateList
			}
			let t = [];
			for (let i in this.privateChatData) {
				if (e && this.privateChatData[i].sender.id == e)
					continue;
				t.push(this.privateChatData[i])
			}
			t.sort(this.sortPrivateList);
			if (e && this.privateChatData[e]) {
				t.unshift(this.privateChatData[e])
			}
			this.privateList = t;
			this.checkPrivateListOver();
			this.checkPrivateListLenth();
			return this.privateList
		}
		static sortPrivateList(e, t) {
			if (e.newNum > 0 && t.newNum == 0) {
				return -1e3
			}
			if (e.newNum == 0 && t.newNum > 0) {
				return 1e3
			}
			return t.t - e.t
		}
		static checkPrivateListOver() {
			if (this.privateList && this.privateList.length > 20) {
				for (let e = this.privateList.length - 1; e >= 20; e--) {
					if (this.privateList[e]) {
						FM.chatMan.dltPrivateIdData(this.privateList[e].sender.id)
					}
				}
			}
		}
		static checkPrivateListLenth() {
			if (this.privateList && this.privateList.length < 20) {
				this.privateList[this.privateList.length] = null
			}
		}
		static clearPriveteList() {
			this.privateList = null
		}
		static clearPriveteNum(e) {
			if (this.privateChatData[e] && this.privateChatData[e].newNum > 0) {
				uP.getIns().master.writeNoteBook(this.NOTEPRE + e, b_.getTimeStamp());
				this.privateChatData[e].newNum = 0;
				this.updataChatNum()
			}
		}
		static clearPriveteId(e) {
			if (this.privateChatData[e]) {
				if (this.privateList) {
					for (let t = 0; t < this.privateList.length; t++) {
						if (this.privateList[t] && this.privateList[t].sender.id == e) {
							this.privateList.splice(t, 1)
						}
					}
				}
				delete this.privateChatData[e];
				this.updataChatNum()
			}
		}
		static getPrivateDotNum() {
			let e = 0;
			for (let t in this.privateChatData) {
				e += this.privateChatData[t].newNum
			}
			return e
		}
		static updataChatNum() {
			let e = 0;
			for (let i in this.allChatData) {
				e += this.allChatData[i].newNum
			}
			let t = this.getPrivateDotNum();
			e += t;
			FM.mainCityMan.showPrivateChatTip(t > 0);
			FM.mainCityMan.showBtnChatNum(e)
		}
	}
