	class nm extends g {
		constructor() {
			super("SacrificeHero");
			this.enabledSureTime = 0
		}
		static getIns() {
			if (!this._ins) {
				this._ins = new nm
			}
			return this._ins
		}
		onClick(e) {
			switch (e.target) {
			case this._ui.btnClose:
				this.closeUI();
				break;
			case this._ui.btnSure:
				let t = [];
				for (let e in this._heroDic) {
					t.push(e)
				}
				this.sendMsg(wp.HERO_SACRIFICE_REQ, {
					ids: t
				});
				this.closeUI();
				break;
			case this._ui.btnCancel:
				this.closeUI();
				break
			}
		}
		initUI() {
			this._ui = this.uiView;
			this.setLayer(1, 1, 1, 1)
		}
		afterClose() {
			this.clearBtnSure();
			this._heroDic = null
		}
		show(e) {
			this._heroDic = e;
			this.openUI();
			let t = {};
			let i = [];
			let s = [];
			let a = [];
			for (let l in e) {
				let r = e[l];
				let h = od.getTplInfo(nd.SACRIFICE_LEVEL, r.level);
				this.mergeItem(t, {
					type: c.WEALTH,
					tid: KM.HERO_EXP,
					num: h.exp
				});
				this.mergeItem(t, {
					type: c.WEALTH,
					tid: KM.M0,
					num: h.m0
				});
				if (r.grade) {
					let e = od.getTplInfo(nd.SACRIFICE_GRADE, r.grade);
					this.mergeItem(t, {
						type: c.PROP,
						tid: 100001,
						num: e.item
					});
					this.mergeItem(t, {
						type: c.WEALTH,
						tid: KM.M0,
						num: e.m0
					})
				}
				let n = od.getTplInfo(nd.SACRIFICE_STAR, r.baseTpl.star);
				this.mergeItem(t, {
					type: c.PROP,
					tid: 200014,
					num: n.item0
				});
				this.mergeItem(t, {
					type: c.PROP,
					tid: 100001,
					num: n.item1
				});
				this.mergeItem(t, {
					type: c.WEALTH,
					tid: KM.HERO_EXP,
					num: n.exp
				});
				if (n.item2) {
					this.mergeItem(t, {
						type: c.PROP,
						tid: cm.starProp[r.baseTpl.camp],
						num: n.item2
					})
				}
				for (let e = 0; e < r.equipList.length; e++) {
					this.mergeItem(t, r.equipList[e])
				}
				for (let e in r.talentDic) {
					let i = r.talentDic[e];
					let s = cP.splitStr2Arr(i.tpl.forgetReturn);
					for (let e = 0; e < s.length; e++) {
						this.mergeItem(t, s[e])
					}
				}
				for (let e in r.collectDic) {
					if (r.collectDic[e]) {
						this.mergeItem(t, r.collectDic[e])
					}
				}
				for (let e in r.godEquipDic) {
					if (r.godEquipDic[e]) {
						this.mergeItem(t, r.godEquipDic[e])
					}
				}
				for (let e in r.runeDic) {
					i.push(r.runeDic[e])
				}
				for (let e in r.mingGeDic) {
					s.push(r.mingGeDic[e])
				}
				for (let e in r.fairyDic) {
					a.push(r.fairyDic[e])
				}
				let o = r.hadSegsList;
				for (let e = 0; e < o.length; e++) {
					let i = od.getTplInfo(nd.SACRIFICE_PERIOD_STAR, null, {
							period: o[e],
							star: r.baseTpl.star
						})[0];
					if (!i)
						continue;
					this.mergeItem(t, {
						type: c.PROP,
						tid: 200014,
						num: i.item0
					});
					this.mergeItem(t, {
						type: c.PROP,
						tid: 100001,
						num: i.item1
					});
					this.mergeItem(t, {
						type: c.WEALTH,
						tid: KM.HERO_EXP,
						num: i.exp
					});
					if (i.item2) {
						this.mergeItem(t, {
							type: c.PROP,
							tid: cm.starProp[r.baseTpl.camp],
							num: i.item2
						})
					}
				}
			}
			let r = [];
			for (let l in t) {
				r.push(t[l])
			}
			r = r.concat(i);
			r = r.concat(s);
			r = r.concat(a);
			this._ui.listItem.array = r;
			this._ui.listItem.scrollTo(0)
		}
		mergeItem(e, t) {
			if (!t.num)
				return;
			let i = t.type + "_" + t.tid;
			if (e[i]) {
				e[i].num += t.num
			} else {
				e[i] = t
			}
		}
		afterOpen() {
			if (this.checkGaoji(this._heroDic)) {
				this.enabledSureTime = 3;
				this._ui.tipBox.visible = true
			} else {
				this._ui.tipBox.visible = false
			}
			this.checkBtnSure()
		}
		checkGaoji(e) {
			for (let t in e) {
				let i = e[t];
				if (i.baseTpl.star >= 4) {
					return true
				}
			}
			return false
		}
		checkBtnSure() {
			if (this.enabledSureTime > 0) {
				Laya.timer.loop(1e3, this, this.refreshBtnSure);
				this.refreshBtnSure()
			}
		}
		refreshBtnSure() {
			if (this.enabledSureTime <= 0) {
				this.clearBtnSure();
				return
			}
			this._ui.btnSure.label = WM.getLanCodeTip(20289, [this.enabledSureTime]);
			this._ui.btnSure.disabled = true;
			this.enabledSureTime--
		}
		clearBtnSure() {
			if (!this._ui.btnSure.disabled) {
				return
			}
			this._ui.btnSure.disabled = false;
			this._ui.btnSure.label = WM.getLanCodeTip(10332);
			this.enabledSureTime = 0;
			Laya.timer.clear(this, this.refreshBtnSure)
		}
	}
