		freshFragList() {
			if (!this.isOpen)
				return;
			if (this._ui.tabType.selectedIndex != 2)
				return;
			this.selectFrag = null;
			let e = this.data.bag.fragment.list;
			let t = [];
			for (let i = 0; i < e.length; i++) {
				let s = e[i];
				if (this._ui.list1Camp.selectedItem != 0 && this._ui.list1Camp.selectedItem != s.fragTpl.camp)
					continue;
				t.push({
					fragInfo: s,
					selected: false
				})
			}
			t.sort(this.fragSort);
			this._ui.list1Frag.array = t;
			this._ui.list1Frag.scrollTo(0);
			if (t.length == 0) {
				this._ui.noAnythingBox.visible = true
			} else {
				this._ui.noAnythingBox.visible = false
			}
		}
		fragSort(e, t) {
			let i = e.fragInfo;
			let s = t.fragInfo;
			if (i.fragTpl.star != s.fragTpl.star) {
				return s.fragTpl.star - i.fragTpl.star
			} else {
				let e = i.fragTpl.camp ? i.fragTpl.camp : 6;
				let t = s.fragTpl.camp ? s.fragTpl.camp : 6;
				if (e != t) {
					return e - t
				} else {
					return s.baseTpl.id - i.baseTpl.id
				}
			}
		}
		fragCellClick(e, t) {
			if (e.type != Laya.Event.CLICK)
				return;
			let i = this._ui.list1Frag.getItem(t);
			if (this.selectFrag == i) {
				this.selectFrag = null;
				i.selected = false
			} else {
				if (this.selectFrag) {
					this.selectFrag.selected = false
				}
				this.selectFrag = i;
				i.selected = true
			}
			this._ui.list1Frag.refresh()
		}
