	class eI extends g {
		constructor() {
			super("MingGeMaterial")
		}
		static getIns() {
			if (!this._ins) {
				this._ins = new eI
			}
			return this._ins
		}
		onClick(e) {
			switch (e.target) {
			case this._ui.btnClose:
				this.closeUI();
				break;
			case this._ui.btnSelect:
				this.selectClick();
				break;
			case this._ui.btnOneKey:
				this.oneKeyClick();
				break
			}
		}
		initUI() {
			this._ui = this.uiView;
			this.setLayer(1, 1, 1, 1);
			this._ui.listCell.mouseHandler = Laya.Handler.create(this, this.cellClick, null, false)
		}
		afterClose() {
			if (this.selectHandler) {
				this.selectHandler.recover();
				this.selectHandler = null
			}
		}
		show(e, t, i, s) {
			this.openUI();
			this.selectHandler = s;
			this._needNum = i;
			for (let a = 0; a < e.length; a++) {
				e[a].lock = 0
			}
			e.sort(this.sortFun);
			this._ui.listCell.array = e;
			this._ui.noAnythingBox.visible = false;
			if (e.length <= 0) {
				this._ui.noAnythingBox.visible = true
			}
			this._ui.listCell.scrollTo(0);
			this.freshNum()
		}
		sortFun(e, t) {
			if (e.lock != t.lock) {
				return e.lock - t.lock
			} else {
				return e.cp - t.cp
			}
		}
		cellClick(e, t) {
			if (e.type != Laya.Event.CLICK)
				return;
			let i = this._ui.listCell.getItem(t);
			if (i.getItem) {
				Ng.getIns().showGetInfoDetail(i.tid, c.MING_GE)
			} else {
				if (!i.selected) {
					if (this._selectedList.length >= this._needNum) {
						FM.noticeMan.showNotice(WM.getLanCodeTip(10394));
						return
					}
				}
				i.selected = !i.selected;
				this._ui.listCell.refresh();
				this.freshNum()
			}
		}
		freshNum() {
			this._selectedList = [];
			for (let e = 0; e < this._ui.listCell.array.length; e++) {
				let t = this._ui.listCell.array[e];
				if (t.selected) {
					if (t.mingge) {
						this._selectedList.push(t.mingge._idHex)
					}
				}
			}
			this._ui.labNum.text = this._selectedList.length + "/" + this._needNum
		}
		selectClick() {
			this.selectHandler.runWith([this._selectedList]);
			this.closeUI()
		}
		oneKeyClick() {
			let e = this._ui.listCell.array;
			let t = 0;
			for (let i = 0; i < e.length; i++) {
				if (e[i].selected) {
					t++
				}
			}
			for (let i = 0; i < e.length; i++) {
				if (e[i].getItem)
					break;
				if (e[i].lock)
					break;
				if (e[i].selected)
					continue;
				if (t >= this._needNum)
					break;
				e[i].selected = true;
				t++
			}
			this._ui.listCell.refresh();
			this.freshNum()
		}
		getDogCost(e) {
			let t = {
				items: []
			};
			if (!e || !e.length)
				return t;
			for (let i = 0; i < e.length; i++) {
				let s = e[i];
				let a = this.data.bag.mingGe.getItem(s);
				if (a) {
					if (a.randomNum > 0) {
						for (let e = 0; e < a.randomNum; e++) {
							let e = cP.splitStr2Arr(a.qualityTpl.randomAttrCost);
							cP.mergeItems(t.items, e)
						}
					}
					let e = a.exp;
					if (a.grade >= 1) {
						let i = od.getTplInfo(nd.MING_GE_ADCANCED, null, {
								mingGeId: a.baseTpl.id
							});
						for (let s = 0; s < i.length; s++) {
							if (i[s].advanced >= a.grade) {
								e = e + i[s].exp;
								cP.mergeItems(t.items, cP.splitStr2Arr(i[s].costs))
							}
						}
					}
					let i = [];
					let s = Math.floor(e / 2e3);
					if (s > 0) {
						i.push({
							type: c.MING_GE,
							tid: 30002,
							num: s
						})
					}
					let r = Math.ceil(e % 2e3 / 10);
					if (r > 0) {
						i.push({
							type: c.MING_GE,
							tid: 30001,
							num: r
						})
					}
					cP.mergeItems(t.items, i)
				}
			}
			return t
		}
	}
