		sortFun(e, t) {
			if (e.mingGe.baseTpl.type != t.mingGe.baseTpl.type) {
				return e.mingGe.baseTpl.type - t.mingGe.baseTpl.type
			} else {
				if (e.mingGe.baseTpl.quality != t.mingGe.baseTpl.quality) {
					return e.mingGe.baseTpl.quality - t.mingGe.baseTpl.quality
				} else {
					if (e.mingGe.baseTpl.id != t.mingGe.baseTpl.id) {
						return e.mingGe.baseTpl.id - t.mingGe.baseTpl.id
					} else {
						return e.mingGe.level - t.mingGe.level
					}
				}
			}
		}
