	class nI extends g {
		constructor() {
			super("OptionalGift")
		}
		static getIns() {
			if (!this._ins) {
				this._ins = new nI
			}
			return this._ins
		}
		onClick(e) {
			switch (e.target) {
			case this._ui.btnClose:
				this.closeUI();
				break;
			case this._ui.btnSure:
				this.getReq();
				break
			}
		}
		initUI() {
			this._ui = this.uiView;
			this.setLayer(1, 1, 1, 1)
		}
		afterClose() {
			this.item = null
		}
		show(e) {
			this.openUI();
			this.item = e;
			let t = od.getTplInfo(nd.GIFT_PACK, e.baseTpl.id);
			let i;
			if (!t) {
				i = FM.bagMan.getContinuousGiftBoxTpl(e)
			}
			if (!t && !i) {
				return
			}
			let s;
			if (t) {
				s = t.rwd.split("#");
				this.maxNum = t.num
			} else {
				s = i.rwd.split("#");
				this.maxNum = 1
			}
			let a = [];
			for (let r = 0; r < s.length; r++) {
				a.push({
					index: r,
					item: cP.parseItemStr(s[r]),
					select: false,
					selectFun: Laya.Utils.bind(this.selectFun, this)
				})
			}
			this._ui.listCell.array = a;
			this._ui.listCell.tweenTo(0, 0);
			this.refreshNum()
		}
		selectFun(e, t) {
			if (t == true) {
				if (this.maxNum == 1) {
					let t = this._ui.listCell.array;
					for (let i = 0; i < t.length; i++) {
						if (t[i].index != e) {
							t[i].select = false
						} else {
							t[i].select = true
						}
						let s = this._ui.listCell.getCell(i);
						if (s) {
							s.udpateSelect()
						}
					}
				} else {
					if (this.selectNum >= this.maxNum) {
						FM.noticeMan.showNotice(WM.getLanCodeTip(20051, [this.maxNum]))
					} else {
						this._ui.listCell.array[e].select = true;
						let t = this._ui.listCell.getCell(e);
						if (t) {
							t.udpateSelect()
						}
					}
				}
			}
			this._ui.listCell.refresh();
			this.refreshNum()
		}
		refreshNum() {
			this.selectNum = 0;
			let e = this._ui.listCell.array;
			for (let t = 0; t < e.length; t++) {
				if (e[t].select) {
					this.selectNum++
				}
			}
			this._ui.labDesc.text = WM.getLanCodeTip(20052, [this.maxNum, this.selectNum, this.maxNum])
		}
		getReq() {
			let e = [];
			let t = this._ui.listCell.array;
			for (let i = 0; i < t.length; i++) {
				if (t[i].select) {
					e.push(i)
				}
			}
			if (e.length != this.maxNum) {
				WM.getLanCodeTip(20053, [this.maxNum]);
				return
			}
			if (this.item.baseTpl.batchUse && this.item.num > 1) {
				hI.getIns().show(this.item, {
					indexes: e
				})
			} else {
				ib.usePropReq(this.item, 1, {
					indexes: e
				})
			}
			this.closeUI()
		}
	}
