			this._ui.labDesc.innerHTML = WM.str2Html(e.baseTpl.desc, 2461);
			this._ui.labDesc.height = this._ui.labDesc.contextHeight;
			this._ui.uiPanel.scrollTo(0, 0);
			this._ui.uiPanel.refresh()
