	class fI extends g {
		constructor() {
			super("AdvQuick")
		}
		static getIns() {
			if (!this._ins) {
				this._ins = new fI
			}
			return this._ins
		}
		getMsgs() {
			return [Cd.INFO_REC, Cd.QUICK_TIMES_REC]
		}
		exeMsg(e, t) {
			switch (t) {
			case Cd.INFO_REC:
			case Cd.QUICK_TIMES_REC:
				if (this.isOpen) {
					this.show()
				}
				break
			}
		}
		initUI() {
			this._ui = this.uiView;
			this.setLayer(1, 1, 1, 1);
			this.timesCostArr = WM.splitToNumArr(od.getGlobalValue(8804, 1));
			cd.regDot(dd.ACT_TASK_QUICK_BATTLE_FUNC, this._ui.dotAct)
		}
		onClick(e) {
			switch (e.target) {
			case this._ui.btnQuick:
				let t = FM.adventureMan.playTimes;
				if (this.hasFreeTimes()) {
					this.sendQuickMsg()
				} else {
					let e;
					let i = 0;
					let s = 0;
					if (t.buyTimes[1]) {
						i = t.buyTimes[1]
					}
					if (t.buyTimes[3]) {
						s = t.buyTimes[3]
					}
					if (i >= this.quickBuyTimes1() && s >= this.quickBuyTimes3()) {
						FM.noticeMan.showNotice(WM.getLanCodeTip(10038));
						return
					} else if (i + s >= this.timesCostArr.length) {
						e = WM.getLanCodeTip(20026, [this.timesCostArr[this.timesCostArr.length - 1]])
					} else {
						e = WM.getLanCodeTip(20026, [this.timesCostArr[i + s]])
					}
					Ig.show(e, Ig.QUICKFIGHT, Laya.Utils.bind(this.sureMoneyQuick, this))
				}
				break;
			case this._ui.btnClose:
				this.closeUI();
				break;
			case this._ui.btnTips:
				D_.showById(125);
				break;
			case this._ui.btnActive:
				this.closeUI();
				FM.privilegeShopMan.openUI();
				break;
			case this._ui.btnActQuick:
				this.closeUI();
				FM.actTaskQuickBattleMan.openUI();
				break
			}
		}
		isOverM2() {
			let e = od.getTplInfo(nd.ADVENTURE, this.data.master.missionId);
			if (!e)
				return false;
			let t = 2 * 3600 * 1e3;
			let i = e.m2 * Math.ceil(t / 6e4);
			if (i + this.data.master.wallet.m2 > od.getGlobalValue(11004)) {
				return true
			} else {
				return false
			}
		}
		checkOpen() {
			return FM.funcMan.checkFuncOpen(pd.ADVENTURE_QUICK)
		}
		afterOpen() {
			this.show();
			this.refreshAtcBtn()
		}
		show() {
			this._ui.moneyBox.visible = false;
			this._ui.btnQuick.gray = false;
			this._ui.freeLab.visible = false;
			this._ui.freeTimesBox.visible = false;
			let e = FM.adventureMan.playTimes;
			let t = 0;
			let i = 0;
			let s = this.quickBuyTimes1();
			let a = this.quickBuyTimes3();
			if (e.buyTimes[1]) {
				t = e.buyTimes[1]
			}
			if (e.buyTimes[3]) {
				i = e.buyTimes[3]
			}
			if (!this.hasFreeTimes()) {
				if (t + i >= s + a) {
					this._ui.btnQuick.gray = true
				} else if (t + i >= this.timesCostArr.length) {
					this._ui.moneyBox.visible = true;
					this._ui.moneyBox.dataSource = X_.getWealthTypeData(KM.M1, this.timesCostArr[this.timesCostArr.length - 1], false)
				} else {
					this._ui.moneyBox.visible = true;
					this._ui.moneyBox.dataSource = X_.getWealthTypeData(KM.M1, this.timesCostArr[t + i], false)
				}
				this._ui.freeTimesBox.visible = true;
				let e = s + a - t - i;
				if (e <= 0) {
					e = 0;
					this._ui.timesLab.color = m.NORMAL_RED
				} else {
					this._ui.timesLab.color = m.TIP_GREEN
				}
				this._ui.timesLab.text = String(e)
			} else {
				this._ui.freeLab.visible = true
			}
			let r = this.data.master.missionId;
			if (r < 1)
				r = 1;
			let l = od.getTplInfo(nd.ADVENTURE, r);
			let h = cP.splitStr2Arr(l.rwdDropShow);
			h.sort(dI.sortRwd);
			this._ui.prizeList.array = h;
			this._ui.prizeList.scrollTo(0);
			let n = FM.privilegeShopMan.isPrivilegeActive(pI.ADVQUICK);
			if (n) {
				this._ui.btnActive.visible = false;
				this._ui.activeTip.color = m.TIP_GREEN;
				this._ui.activeTip.text = WM.getLanCodeTip(10590)
			} else {
				this._ui.btnActive.visible = true;
				this._ui.activeTip.color = "#db1b0d";
				this._ui.activeTip.text = WM.getLanCodeTip(10591)
			}
		}
		hasFreeTimes() {
			let e = FM.adventureMan.playTimes;
			if (!e)
				return false;
			if (e.freeTimes[1] == undefined || e.freeTimes[1] < this.quickFreeTimes1())
				return true;
			let t = FM.privilegeShopMan.isPrivilegeActive(pI.ADVQUICK);
			if (t) {
				if (e.freeTimes[3] == undefined || e.freeTimes[3] < this.quickFreeTimes3())
					return true
			}
			return false
		}
		quickFreeTimes1() {
			return od.getGlobalValue(8801, 0)
		}
		quickFreeTimes3() {
			let e = FM.privilegeShopMan.isPrivilegeActive(pI.ADVQUICK);
			let t = 0;
			if (e) {
				t += od.getGlobalValue(23001, 0)
			}
			return t
		}
		quickBuyTimes1() {
			return od.getGlobalValue(8802, 0)
		}
		quickBuyTimes3() {
			let e = FM.privilegeShopMan.isPrivilegeActive(pI.ADVQUICK);
			let t = 0;
			if (e) {
				t += od.getGlobalValue(23002, 0)
			}
			return t
		}
		sureMoneyQuick(e) {
			if (e) {
				Laya.timer.once(30, this, this.sendQuickMsg)
			}
		}
		sendQuickMsg() {
			if (this.isOverM2()) {
				QM.show(WM.getLanCodeTip(10039), Laya.Utils.bind(this.sureQuickMsg, this));
				return
			}
			this.sureQuickMsg(true)
		}
		sureQuickMsg(e) {
			if (e) {
				this.sendMsg(Cd.QUICK_REQ)
			}
		}
		refreshAtcBtn() {
			if (!this.isOpen)
				return;
			this._ui.btnActQuick.visible = FM.actTaskQuickBattleMan.actOpen
		}
	}
