			if (this.posData.beastMap) {
				e = this.posData.beastMap
			}
			DI.getIns().openData(this.posData, this.funcId, Laya.Utils.bind(this.artifactSelect, this), Laya.Utils.bind(this.beastSelect, this), Laya.Utils.bind(this.ShenLongSelect, this), 1)
