				i[s] = T.deepCopy(this.showStartEndArr[s]);
				let a = [{}, {}
				];
				a[0].type = c.WEALTH;
				a[0].tid = KM.M0;
				a[0].num = Math.floor(parseFloat(od.getGlobalValue(this.showGlobalArr[s], 1)) * e * .01);
				a[1].type = c.WEALTH;
				a[1].tid = KM.P2;
				a[1].num = Math.floor(parseFloat(od.getGlobalValue(this.showGlobalArr[s], 1)) * t * .01);
