	class KI extends g {
		constructor(e = "BattleStatis") {
			super(e)
		}
		static getIns() {
			if (!this._ins) {
				this._ins = new KI
			}
			return this._ins
		}
		getMsgs() {
			return [Rd.REPORT_DATA_REC]
		}
		exeMsg(e, t) {
			switch (t) {
			case Rd.REPORT_DATA_REC:
				this.show(e.play);
				break
			}
		}
		onClick(e) {
			switch (e.target) {
			case this._ui.btnSure:
				this.closeUI();
				break
			}
		}
		getReport(e, t, i = 0, s = null) {
			if (!e) {
				FM.noticeMan.showNotice(WM.getLanCodeTip(10118));
				return
			}
			this.sendMsg(Rd.REPORT_DATA_REQ, {
				replayIdHex: e,
				type: i,
				srvCode: s
			})
		}
		initUI() {
			this._ui = this.uiView;
			this.setLayer(1, 1, 1, 1);
			this._ui.tabType.selectHandler = Laya.Handler.create(this, this.typeSelect, null, false)
		}
		afterClose() {
			this.teamA = null;
			this.teamB = null
		}
		typeSelect(e) {
			if (e < 0)
				return;
			this.refreshType(this._ui.listA, this.teamA);
			this.refreshType(this._ui.listB, this.teamB)
		}
		refreshType(e, t) {
			for (let i = 0; i < t.length; i++) {
				t[i].type = this._ui.tabType.selectedIndex
			}
			e.array = t
		}
		show(e) {
			if (!e) {
				i.reportError("normalError", "Xem xét chiến đấu thống kê lúc, không có kịch bản");
				FM.noticeMan.showNotice(WM.getLanCodeTip(10119));
				return
			}
			this.openUI();
			this.teamA = this.parseTeam(e, "a");
			this.teamB = this.parseTeam(e, "b");
			this._ui.tabType.selectedIndex = -1;
			this._ui.tabType.selectedIndex = 0;
			this._ui.labNameA.text = e.a.ms.profile.name;
			this._ui.labNameB.text = e.b.ms.profile.name
		}
		parseTeam(e, t) {
			let i = e.teamEnd[t].heros;
			let s = {};
			let a = {};
			let r = {};
			let l = 1;
			let h = 1;
			for (let u = 0; u < i.length; u++) {
				let e = i[u];
				let t = e.performance;
				let n = t.damage;
				let o = t.heal;
				if (n > l) {
					l = n
				}
				if (o > h) {
					h = o
				}
				s[e.idHex] = n;
				a[e.idHex] = o;
				r[e.idHex] = e.pos
			}
			let n = e[t].hs;
			let o = [];
			for (let u = 0; u < n.length; u++) {
				let e = new yg(n[u]);
				let t = e.idHex;
				let i = s[t];
				let c = a[t];
				let d = r[t];
				if (i == undefined)
					i = s[t + "_cp"];
				if (c == undefined)
					c = a[t + "_cp"];
				if (d == undefined)
					d = r[t + "_cp"];
				o.push({
					heroData: e,
					dmg: i,
					heal: c,
					dmgMax: l,
					healMax: h,
					pos: d
				})
			}
			o.sort(function (e, t) {
				return e.pos - t.pos
			});
			return o
		}
	}
