	class lT extends j_ {
		constructor() {
			super();
			this.itemNum = 0;
			this._selectArr = []
		}
		static getCheckBoxData(e = 0, t = 1, i = null) {
			let s = {};
			s.min = e;
			s.max = t;
			s.handle = i;
			return s
		}
		get dataSource() {
			return super.dataSource
		}
		set dataSource(e) {
			super.dataSource = e;
			if (this.itemNum == 0) {
				let e = this.getChildByName("item" + this.itemNum);
				while (e) {
					e.on(Laya.Event.CHANGE, this, this.onSelectedChange, [this.itemNum]);
					this.itemNum++;
					e = this.getChildByName("item" + this.itemNum)
				}
			}
			this.selectArr = []
		}
		onSelectedChange(e) {
			let t = this.getChildByName("item" + e);
			if (t.selected) {
				if (this._selectArr.indexOf(e) != -1) {
					return
				}
				if (this._selectArr.length >= this.dataSource.max) {
					this._selectArr.push(e);
					let t = this.getChildByName("item" + this.selectArr.shift());
					t.selected = false
				} else {
					this._selectArr.push(e)
				}
				if (this.dataSource.handle) {
					this.dataSource.handle.call(null)
				}
			} else {
				if (this._selectArr.indexOf(e) != -1) {
					if (this._selectArr.length > this.dataSource.min) {
						this._selectArr.splice(this._selectArr.indexOf(e), 1);
						if (this.dataSource.handle) {
							this.dataSource.handle.call(null)
						}
					} else {
						let t = this.getChildByName("item" + e);
						t.selected = true;
						FM.noticeMan.showNotice(WM.getLanCodeTip(20081, [this.dataSource.min]))
					}
				}
			}
		}
		set selectArr(e) {
			if (e.length > this._dataSource.max) {
				return
			}
			if (e.length < this._dataSource.min) {
				return
			}
			for (let t = 0; t < this.itemNum; t++) {
				if (e.indexOf(t) != -1) {
					this.getChildByName("item" + t)["selected"] = true
				} else {
					this.getChildByName("item" + t)["selected"] = false
				}
			}
			this._selectArr = e
		}
		get selectArr() {
			return this._selectArr
		}
	}
