	class IT {
		static start(e, t = true) {
			if (!this.targetArr) {
				this.targetArr = [];
				this.alpha = 1;
				this.dir = -1;
				Laya.timer.loop(30, this, this.fadeInOut)
			}
			if (this.targetArr.indexOf(e) != -1)
				return;
			this.targetArr.push(e);
			if (t) {
				e.on(Laya.Event.UNDISPLAY, this, this.targetUndisplay, [e])
			}
		}
		static targetUndisplay(e) {
			this.stop(e)
		}
		static stop(e) {
			if (!this.targetArr)
				return;
			let t = this.targetArr.indexOf(e);
			if (t == -1)
				return;
			e.alpha = 1;
			e.off(Laya.Event.UNDISPLAY, this, this.targetUndisplay);
			this.targetArr.splice(t, 1);
			if (this.targetArr.length <= 0) {
				this.targetArr = null;
				Laya.timer.clear(this, this.fadeInOut)
			}
		}
		static fadeInOut() {
			if (this.alpha >= 1.3) {
				this.alpha = 1.3;
				this.dir = -1
			}
			if (this.alpha <= 0) {
				this.alpha = 0;
				this.dir = 1
			}
			for (let e = 0; e < this.targetArr.length; e++) {
				if (!this.targetArr[e].displayedInStage)
					continue;
				this.targetArr[e].alpha = this.alpha
			}
			this.alpha += .05 * this.dir
		}
		static startSlow(e, t = true) {
			if (!this.targetArrSlow) {
				this.targetArrSlow = [];
				this.alphaSlow = 1;
				this.dirSlow = -1;
				Laya.timer.loop(30, this, this.fadeInOutSlow)
			}
			if (this.targetArrSlow.indexOf(e) != -1)
				return;
			this.targetArrSlow.push(e);
			if (t) {
				e.on(Laya.Event.UNDISPLAY, this, this.targetUndisplaySlow, [e])
			}
		}
		static targetUndisplaySlow(e) {
			this.stopSlow(e)
		}
		static stopSlow(e) {
			if (!this.targetArrSlow)
				return;
			let t = this.targetArrSlow.indexOf(e);
			if (t == -1)
				return;
			e.alpha = 1;
			e.off(Laya.Event.UNDISPLAY, this, this.targetUndisplaySlow);
			this.targetArrSlow.splice(t, 1);
			if (this.targetArrSlow.length <= 0) {
				this.targetArrSlow = null;
				Laya.timer.clear(this, this.fadeInOutSlow)
			}
		}
		static fadeInOutSlow() {
			if (this.alphaSlow >= 1.3) {
				this.alphaSlow = 1.3;
				this.dirSlow = -1
			}
			if (this.alphaSlow <= 0) {
				this.alphaSlow = 0;
				this.dirSlow = 1
			}
			for (let e = 0; e < this.targetArrSlow.length; e++) {
				if (!this.targetArrSlow[e].displayedInStage)
					continue;
				this.targetArrSlow[e].alpha = this.alphaSlow
			}
			this.alphaSlow += .03 * this.dirSlow
		}
	}
