	class AT {
		static getTimesTplCostObj(e, t) {
			let i = od.getTplInfo(nd.BATTLE_TIME_COST, null, {
					funcId: e
				});
			if (i) {
				for (let a = 0; a < i.length; a++) {
					if (i[a].buyStart - 1 <= t && i[a].buyEnd - 1 >= t) {
						let e = i[a].cost;
						let t = cP.splitStr2Arr(e)[0];
						return t
					}
				}
				let e = i[i.length - 1].cost;
				let s = cP.splitStr2Arr(e)[0];
				return s
			}
		}
		static getTimesTplCostStr(e, t) {
			let i = od.getTplInfo(nd.BATTLE_TIME_COST, null, {
					funcId: e
				});
			if (i) {
				for (let s = 0; s < i.length; s++) {
					if (i[s].buyStart - 1 <= t && i[s].buyEnd - 1 >= t) {
						let e = i[s].cost;
						return e
					}
				}
				let e = i[i.length - 1].cost;
				return e
			}
		}
	}
