class yb extends Cb {
	constructor(e, t, i) {
		super(e);
		this.funcId = 0;
		this.actId = 0;
		this.funcId = t;
		this.tplDropBase = i
	}
	tabSelectCheck() {
		return true
	}
	tabVisibleCheck() {
		return this.checkOpen(false)
	}
	getCmds() {
		return [d.FUNC_INIT, d.FUNC_OPEN, d.ITEM_CHANGE_NUM]
	}
	exeCmd(e, t) {
		switch (t) {
		case d.FUNC_INIT:
			this.checkMainBtn();
			break;
		case d.FUNC_OPEN:
			if (e == this.funcId) {
				this.checkMainBtn();
				this.checkDot()
			}
			break;
		case d.ITEM_CHANGE_NUM:
			this.updateInfo();
			this.checkDot();
			break
		}
	}
	checkOpen(e = true) {
		if (!FM.funcMan.checkFuncOpen(this.funcId, e))
			return false;
		if (!this.srvData || !this.actId) {
			if (e) {
				FM.noticeMan.showNotice(WM.getLanCodeTip(10020))
			}
			return false
		}
		return true
	}
	afterOpen() {
		this.updateInfo();
		this.refreshTime();
		if (this.actTpl) {
			Tb.addWealthGridByInfo(this.dropItem, this._ui.boxDrop);
			this._ui.listRwd.array = cP.splitStr2Arr(this.actTpl.showItem)
		}
	}
	updateInfo() {
		if (!this.isOpen)
			return;
		if (!this.srvData || !this.actTpl)
			return;
		this._ui.labNum.text = "" + this.dropNum
	}
	refreshTime() {
		let e = 0;
		if (this.actTpl && this.actTpl.endTime) {
			e = b_.getActTimeByStr(this.actTpl.endTime).getTime() - b_.getTimeStamp()
		}
		if (e > 0) {
			vg.start(e, this, this.timerFun)
		}
	}
	timerFun(e, t) {
		if (e >= b_.ONEDAYMILLISECONDS) {
			this._ui.labTime.text = b_.getDayHourStr(e)
		} else {
			this._ui.labTime.text = b_.getCdTimeStrByMs(e)
		}
	}
	dropDataRec(e) {
		this.srvData = e.data;
		this.setActId(this.srvData.activityId);
		this.checkMainBtn();
		this.updateInfo();
		this.checkDot()
	}
	get itemList() {
		if (!this.srvData)
			return [];
		return this.srvData.items
	}
	get dropNum() {
		if (!this.srvData)
			return 0;
		if (!this.actTpl)
			return 0;
		return this.data.bag.prop.getNum(this.actTpl.dropItemId)
	}
	setActId(e) {
		if (this.actId == e)
			return;
		this.actId = e;
		this.actTpl = od.getTplInfo(this.tplDropBase, this.actId);
		if (this.actTpl) {
			this.dropItem = {
				type: c.PROP,
				tid: this.actTpl.dropItemId
			}
		}
	}
	checkMainBtn() {}
	checkDot() {}
}
