class Ab {
	constructor() {
		this.arr = []
	}
	add(e, t) {
		for (let i = 0; i < this.arr.length; i++) {
			if (this.arr[i].key == e) {
				this.arr[i].value = t;
				return
			}
		}
		this.arr.push({
			key: e,
			value: t
		})
	}
	remove(e) {
		for (let t = 0; t < this.arr.length; t++) {
			if (this.arr[t].key == e) {
				let e = this.arr[t].value;
				this.arr.splice(t, 1);
				return e
			}
		}
		return null
	}
	find(e) {
		for (let t = 0; t < this.arr.length; t++) {
			if (this.arr[t].key == e) {
				return this.arr[t].value
			}
		}
		return null
	}
	clear() {
		this.arr.splice(0)
	}
}
class Db extends g {
	constructor(e) {
		super(e);
		this.subDic = {};
		this.indexDic = new Ab;
		this.sortDic = {};
		this.regSubMans()
	}
	regSubMan(e, t, i) {
		if (!e) {
			throw new Error("Bảng con quản lý loại còn chưa ban đầu hóa")
		}
		e.mainMan = this;
		this.subDic[t] = e;
		this.sortDic[t] = i;
		this.indexDic.add(e, t)
	}
	afterOpen() {
		super.afterOpen();
		let e = [];
		for (let i = 0; i < this.tabMain.items.length; i++) {
			let t = this.subDic[i];
			let s = this.sortDic[i];
			let a = this.tabMain.items[i];
			if (t) {
				a.visible = t.tabVisibleCheck()
			} else {
				a.visible = true;
				s = 9999
			}
			if (a.visible) {
				e.push({
					btn: a,
					sort: s
				})
			}
		}
		e.sort(function (e, t) {
			return e.sort - t.sort
		});
		if ("horizontal" == this.tabMain.direction) {
			let t = 0;
			for (let i = 0; i < e.length; i++) {
				let s = e[i].btn;
				s.x = t;
				t += s.width + this.tabMain.space
			}
			this.tabMain.width = t
		} else {
			let t = 0;
			for (let i = 0; i < e.length; i++) {
				let s = e[i].btn;
				s.y = t;
				t += s.height + this.tabMain.space
			}
			this.tabMain.height = t
		}
		let t = this.tabMain.parent.parent;
		if (t instanceof Laya.Panel) {
			t.refresh()
		}
	}
	tabSelectCheck(e) {
		let t = this.subDic[e];
		if (!t) {
			FM.noticeMan.showNotice("Số hiệu:" + e + "Liên quan bảng con quản lý loại không tồn tại");
			return true
		}
		if (!t.tabSelectCheck())
			return;
		this.closeAllSubMan();
		t.setLayer(0, 0, 0, 0, this.ctnSub);
		t.directOpenUI()
	}
	openSubMan(e) {
		super.openUI();
		this.closeAllSubMan();
		e.setLayer(0, 0, 0, 0, this.ctnSub);
		e.directOpenUI();
		let t = this.indexDic.find(e);
		this.tabMain.superSetSelect(t);
		let i = this.tabMain.parent.parent;
		if (i instanceof Laya.Panel) {
			let e = this.tabMain.items[t];
			if ("horizontal" == this.tabMain.direction) {
				i.scrollTo(e.x, this.tabMain.y)
			} else {
				i.scrollTo(this.tabMain.x, e.y)
			}
		}
	}
	closeAllSubMan() {
		for (let e in this.subDic) {
			let t = this.subDic[e];
			t.closeUI()
		}
	}
	openUI() {
		let e = [];
		for (let t in this.subDic) {
			let i = this.subDic[t];
			let s = this.sortDic[t];
			e.push({
				subMan: i,
				sort: s
			})
		}
		e.sort(function (e, t) {
			return e.sort - t.sort
		});
		for (let t = 0; t < e.length; t++) {
			let i = e[t].subMan;
			if (i.tabVisibleCheck() && i.tabSelectCheck()) {
				this.openSubMan(i);
				break
			}
		}
	}
	closeUI() {
		super.closeUI();
		this.closeAllSubMan()
	}
}
