class Fb extends g {
	constructor() {
		super("CollectSkill");
		this._selIndex = 0;
		this._isMainShow = false;
		this._dotHasShow = false;
		this._originalX = 0;
		this._originalY = 0;
		this._offsetX = 0;
		this._offsetY = 0;
		this._dataRec = false
	}
	getCmds() {
		return [d.FUNC_INIT, d.FUNC_OPEN]
	}
	exeCmd(e, t) {
		switch (t) {
		case d.FUNC_INIT:
			this.checkMainBtn();
			this.checkDot();
			break;
		case d.FUNC_OPEN:
			if (e == pd.ACT_COLLECTSKILL) {
				this.checkMainBtn();
				this.checkDot()
			}
			break
		}
	}
	getMsgs() {
		return [Sf.DATA_REC]
	}
	exeMsg(e, t) {
		switch (t) {
		case Sf.DATA_REC:
			this.dataRec(e);
			break;
		case vd.HEART_BEAT_REC:
			this.beatRec(e);
			break
		}
	}
	onClick(e) {
		switch (e.target) {
		case this._ui.btnClose:
			this.closeUI();
			break
		}
	}
	initUI() {
		this._ui = this.uiView;
		this.setLayer(1, 1, 1, 1);
		this._originalX = this._ui.imgHero.x;
		this._originalY = this._ui.imgHero.y;
		this._ui.imgName.on(Laya.Event.RESIZE, this, this.adjustTipPos);
		this._ui.imgHero.on(Laya.Event.RESIZE, this, this.adjustHeroImgPos);
		this._ui.listHero.mouseHandler = Laya.Handler.create(this, this.heroClick, null, false)
	}
	checkOpen(e = true) {
		if (!this._srvData || this._srvData.activityId <= 0 || !this._actTpl)
			return false;
		if (this.data.openSrvDay < this._actTpl.openDay) {
			if (e)
				FM.noticeMan.showNotice("Khai phục thứ" + this._actTpl.openDay + "Thiên khai khải");
			return false
		}
		if (!FM.funcMan.checkFuncOpen(pd.ACT_COLLECTSKILL, e)) {
			return false
		}
		return true
	}
	afterOpen() {
		this._dotHasShow = true;
		this.checkDot();
		this.refreshHeroList(0)
	}
	afterClose() {
		this._offsetX = 0;
		this._offsetY = 0
	}
	dataRec(e) {
		this._dataRec = true;
		if (e == null || e.data == null)
			return;
		this._srvData = e.data;
		if (this._actTpl == null || this._actTpl.id != e.data.activityId) {
			this._dotHasShow = false;
			this._selIndex = 0
		}
		this._actTpl = null;
		if (e.data.activityId > 0) {
			this._actTpl = od.getTplInfo(nd.ACT_COLLECTSKILL_BASE, e.data.activityId)
		}
		this.checkMainBtn();
		this.checkDot();
		this.refreshHeroList(this._selIndex)
	}
	beatRec(e) {
		if (this._dataRec) {
			this._dataRec = false;
			this.checkMainBtn();
			this.checkDot()
		}
	}
	heroClick(e, t) {
		if (e.type != Laya.Event.CLICK)
			return;
		if (this._ui.listHero.selectedIndex != t) {
			this.refreshHeroList(t)
		}
	}
	refreshHeroList(e = 0) {
		if (!this.isOpen)
			return;
		this._ui.listHero.selectedIndex = e;
		if (!this._actTpl) {
			this._selIndex = 0;
			this._ui.listHero.array = [];
			return
		}
		let t = this._selIndex == e;
		this._selIndex = e;
		let i = null;
		for (let a = 0; a < this._actTpl.heros.length; a++) {
			this._actTpl.heros[a].isSel = a == e;
			if (a == e) {
				i = this._actTpl.heros[a]
			}
		}
		let s = 0;
		if (this._ui.listHero.array) {
			s = this._ui.listHero.array.length
		}
		this._ui.listHero.array = this._actTpl.heros;
		if (s != this._ui.listHero.array.length) {
			s = this._ui.listHero.array.length;
			this._ui.listHero.width = this._ui.listHero.getCell(0).width * s + this._ui.listHero.spaceX * (s - 1)
		}
		this._ui.listHero.scrollTo(0);
		this.refreshHero(i, t)
	}
	refreshHero(e, t) {
		this._ui.imgBg.skin = "img/herocut/" + e.bg + ".png";
		this._ui.imgName.skin = "img/Activity/" + e.name + ".png";
		this._ui.boxSkill.dataSource = {
			tid: e.skill,
			bg: "img/herocut/collectskill3.png",
			bgX: 3.5,
			bgY: 3.5,
			lvBg: "img/herocut/jinengdengji.png",
			lvBgX: 65,
			lvBgY: 65
		};
		this._offsetX = e.offsetX;
		this._offsetY = e.offsetY;
		this._ui.imgHero.skin = "common/" + e.img + ".png";
		let i = [];
		let s = this.data.master.level;
		let a = this.data.master.vip;
		for (let r = 0; r < this._srvData.items.length; r++) {
			let t = this._srvData.items[r];
			if (!t)
				continue;
			if (!t.tpl) {
				t.tpl = od.getTplInfo(nd.ACT_COLLECTSKILL_ITEM, t.tid)
			}
			if (!t.tpl || t.tpl.type != e.type)
				continue;
			if (t.tpl.minLv && s < t.tpl.minLv) {
				continue
			}
			if (t.tpl.maxLv && s > t.tpl.maxLv) {
				continue
			}
			if (t.tpl.minVip && a < t.tpl.minVip) {
				continue
			}
			if (t.tpl.maxVip && a > t.tpl.maxVip) {
				continue
			}
			let l = {};
			l.purchaseNum = t.purchaseNum;
			l.sellOut = t.purchaseNum >= t.tpl.limitNum;
			l.outOrder = l.sellOut ? 1 : 0;
			l.tpl = t.tpl;
			i.push(l)
		}
		i.sort((e, t) => {
			if (e.outOrder == t.outOrder) {
				if (e.tpl.power == t.tpl.power) {
					return e.tpl.id - t.tpl.id
				} else {
					return e.tpl.power - t.tpl.power
				}
			} else {
				return e.outOrder - t.outOrder
			}
		});
		this._ui.listCell.array = i;
		if (!t) {
			this._ui.listCell.scrollTo(0)
		}
	}
	adjustTipPos() {
		this._ui.imgTip.x = this._ui.imgName.x + this._ui.imgName.displayWidth
	}
	adjustHeroImgPos() {
		this._ui.imgMask.x = this._offsetX;
		this._ui.imgMask.y = this._offsetY;
		this._ui.imgHero.x = this._originalX + this._offsetX;
		this._ui.imgHero.y = this._originalY - this._offsetY
	}
	checkMainBtn() {
		this._isMainShow = false;
		if (this.checkOpen(false)) {
			let e = b_.getActTimeByStr(this._actTpl.starTime);
			let t = b_.getActTimeByStr(this._actTpl.endTime);
			let i = e.getTime();
			let s = t.getTime();
			let a = b_.getTimeStamp();
			if (i <= a && a < s) {
				this._isMainShow = true;
				FM.mainCityMan.setTopBtnOpen(bb.ACT_COLLECTSKILL, this, true);
				vg.start(s - a, this, this.timerFun, 1, null)
			} else {
				FM.mainCityMan.setTopBtnOpen(bb.ACT_COLLECTSKILL, this, false);
				vg.stop(this, this.timerFun);
				if (this.isOpen) {
					this.closeUI()
				}
			}
		} else {
			FM.mainCityMan.setTopBtnOpen(bb.ACT_COLLECTSKILL, this, false);
			vg.stop(this, this.timerFun);
			if (this.isOpen) {
				this.closeUI()
			}
		}
	}
	timerFun(e, t) {
		let i;
		if (e >= b_.ONEDAYMILLISECONDS) {
			i = b_.getDayHourStr(e)
		} else {
			i = b_.getCdTimeStrByMs(e)
		}
		FM.mainCityMan.showActCdTime(Rb.CollectSkill, i);
		if (this.isOpen) {
			this._ui.activeTime.changeText(i)
		}
	}
	checkDot() {
		let e = this._isMainShow && !this._dotHasShow;
		cd.setDot(dd.COLLECT_SKILL_ENTER, this, e);
		cd.setDot(dd.ACT_FOLD2, this, e);
		cd.setDot(dd.CITY_ENTER, this, e)
	}
}
