class Yb extends Hb {
	constructor(e, t = "ActCountTask") {
		super(e, t)
	}
	getCmds() {
		return [d.TASK_INIT, d.TASK_CHANGE_ITEM]
	}
	getMsgs() {
		return [hf.DATA_REC, hf.ONE_DATA_REC]
	}
	exeCmd(e, t) {
		switch (t) {
		case d.TASK_INIT:
			this.checkDot();
			break;
		case d.TASK_CHANGE_ITEM:
			this.refreshList(e);
			this.checkDot();
			break
		}
	}
	exeMsg(e, t) {
		switch (t) {
		case hf.DATA_REC:
			this.dataRec(e);
			break;
		case hf.ONE_DATA_REC:
			this.oneDataRec(e);
			break
		}
	}
	onClick(e) {
		switch (e.target) {
		case this.ui.btnRank:
			Vb.getIns().show(this.funcId, this.value);
			break;
		case this.ui.btnRwd:
			Kb.getIns().show(this.funcId, this.actId);
			break
		}
	}
	initUI() {
		this.ui = this.uiView
	}
	afterOpen() {
		this.refreshActId();
		this.ui.listTask.scrollTo(0);
		Laya.LocalStorage.setItem("ACTTASK" + this.funcId, this.data.openSrvDay + "");
		this.checkDot()
	}
	openUI() {
		FM.limitTimeMan.openAct(this.funcId);
		super.openUI()
	}
	dataRec(e) {
		let t = e.taskCompetition.taskRanks;
		this.actId = 0;
		for (let i in t) {
			let e = t[i];
			if (e.funcId == this.funcId) {
				this.actId = e.activityId;
				this.value = e.value;
				break
			}
		}
		this.actTpl = od.getTplInfo(nd.ACT_TASK, this.actId);
		this.refreshActId();
		this.checkActOpen();
		this.checkDot()
	}
	oneDataRec(e) {
		if (e.taskCompetition && e.taskCompetition.funcId == this.funcId) {
			this.value = e.taskCompetition.value
		}
	}
	refreshActId() {
		if (!this.isOpen)
			return;
		if (!this.actId)
			return;
		this.ui.imgBanner.skin = "icon/hengfu" + this.actTpl.banner;
		let e = od.getTplInfo(nd.ACT_TASK_LIST, null, {
				group: this.actTpl.taskGroup
			});
		let t = [];
		for (let s = 0; s < e.length; s++) {
			t.push({
				funcId: this.funcId,
				tpl: e[s],
				got: this.rwdGot(e[s].taskId)
			})
		}
		t.sort(this.taskSort);
		this.ui.listTask.array = t;
		let i = this.data.openSrvTime + b_.getActEndTime(this.actTpl.endDay, this.actTpl.endTime) - this.data.serverTime;
		vg.start(i, this, this.timerFun, 1, null)
	}
	rwdGot(e) {
		let t = this.data.task.getTaskItem(this.funcId, e);
		if (t && t.rewardGot) {
			return true
		}
		return false
	}
	refreshList(e) {
		if (!this.isOpen)
			return;
		if (e.funcId != this.funcId)
			return;
		let t = this.ui.listTask.array;
		for (let i = 0; i < t.length; i++) {
			t[i].got = this.rwdGot(t[i].tpl.taskId)
		}
		t.sort(this.taskSort);
		this.ui.listTask.refresh()
	}
	taskSort(e, t) {
		if (e.got != t.got) {
			if (!e.got && t.got) {
				return -1
			} else {
				return 1
			}
		} else {
			return e.tpl.taskId - t.tpl.taskId
		}
	}
	timerFun(e, t) {
		if (e >= b_.ONEDAYMILLISECONDS) {
			this.ui.labTime.text = b_.getDayHourStr(e)
		} else {
			this.ui.labTime.text = b_.getCdTimeStrByMs(e)
		}
	}
	checkActOpen() {
		if (!this.funcOpen)
			return;
		FM.mainCityMan.setTopBtnOpen(bb.LIMIT_TIME, this, this.actId ? true : false)
	}
	checkDot() {
		if (!this.funcOpen)
			return;
		let e = false;
		let t = true;
		if (this.actId) {
			let i = od.getTplInfo(nd.ACT_TASK_LIST, null, {
					group: this.actTpl.taskGroup
				});
			for (let s = 0; s < i.length; s++) {
				let a = this.data.task.getTaskItem(this.funcId, i[s].taskId);
				if (a) {
					if (!a.done) {
						t = false
					}
					if (a.done && !a.rewardGot) {
						e = true;
						break
					}
				}
			}
		}
		if (!e && this.actTpl && this.actTpl.dayDot && !t) {
			let t = Laya.LocalStorage.getItem("ACTTASK" + this.funcId);
			let i = this.data.openSrvDay + "";
			if (t != i) {
				e = true
			}
		}
		cd.setDot(this.actDotType, this, e);
		if (this.actFuncDotType != 0) {
			cd.setDot(this.actFuncDotType, this, e)
		}
		cd.setDot(dd.ACT_LIMIT_TIME, this, e);
		cd.setDot(dd.CITY_ENTER, this, e)
	}
}
