class rC extends Hb {
	constructor() {
		super(pd.DAILY_LIMIT, "ActivityDailyBag")
	}
	getCmds() {
		return [d.FUNC_INIT, d.FUNC_OPEN]
	}
	exeCmd(e, t) {
		switch (t) {
		case d.FUNC_INIT:
			this.checkActOpen();
			break;
		case d.FUNC_OPEN:
			if (e == this.funcId) {
				this.checkActOpen()
			}
			break
		}
	}
	getMsgs() {
		return [Ud.DATA_REC]
	}
	exeMsg(e, t) {
		switch (t) {
		case Ud.DATA_REC:
			this.dataRec(e);
			break
		}
	}
	onClick(e) {
		switch (e.target) {}
	}
	initUI() {
		this._ui = this.uiView
	}
	openUI() {
		FM.limitTimeMan.openAct(this.funcId);
		super.openUI()
	}
	afterOpen() {
		this.updateInfo();
		this._ui.listCell.tweenTo(0, 0)
	}
	afterClose() {
		vg.stop(this, this.refreshCdTime);
		super.afterClose()
	}
	refreshCdTime(e, t, i) {
		this._ui.labTime.text = i
	}
	dataRec(e) {
		this.srvData = e.dailyLimit;
		this.setActId(this.srvData.activityId);
		this.checkActOpen();
		if (this.isOpen) {
			this.updateInfo()
		}
	}
	checkActOpen() {
		if (!this.funcOpen)
			return;
		FM.mainCityMan.setTopBtnOpen(bb.LIMIT_TIME, this, this.actId ? true : false)
	}
	updateInfo() {
		if (!this.actOpen || !this.srvData)
			return;
		vg.stop(this, this.refreshCdTime);
		let e = b_.getDayEndTimeStamp() - b_.getTimeStamp();
		if (e > 0) {
			vg.start(e, this, this.refreshCdTime)
		}
		let t = [];
		let i = this.srvData.items;
		for (let s = 0; s < i.length; s++) {
			let e = {};
			e.purchaseNum = i[s].purchaseNum;
			e.tid = i[s].tid;
			t.push(e)
		}
		t.sort(this.sortFun);
		this._ui.listCell.array = t
	}
	sortFun(e, t) {
		let i = od.getTplInfo(nd.DAILY_LIMIT_PRIZE, e.tid);
		let s = od.getTplInfo(nd.DAILY_LIMIT_PRIZE, t.tid);
		let a = i.sortId;
		let r = s.sortId;
		if (i.limitNum - e.purchaseNum <= 0) {
			a += 1e6
		}
		if (s.limitNum - t.purchaseNum <= 0) {
			r += 1e6
		}
		return a - r
	}
	setActId(e) {
		if (this.actId == e)
			return;
		this.actId = e;
		this.actTpl = od.getTplInfo(nd.DAILY_LIMIT, this.actId)
	}
}
