			if (e[a].tpl.minLv && i < e[a].tpl.minLv) {
				continue
			}
			if (e[a].tpl.maxLv && i > e[a].tpl.maxLv) {
				continue
			}
			if (e[a].tpl.minVip && s < e[a].tpl.minVip) {
				continue
			}
