class ly extends g {
	constructor(e = "ShowShop") {
		super(e);
		this.skinId = 0;
		this.funcId = pd.ACT_SKIN_MALL
	}
	getCmds() {
		return [d.FUNC_INIT, d.FUNC_OPEN]
	}
	exeCmd(e, t) {
		switch (t) {
		case d.FUNC_INIT:
			this.checkDot();
			break;
		case d.FUNC_OPEN:
			if (e == this.funcId) {
				this.checkDot()
			}
			break
		}
	}
	getMsgs() {
		return [md.ACTSHOP_DATA_REC, md.ACTSHOP_ONE_REC]
	}
	exeMsg(e, t) {
		switch (t) {
		case md.ACTSHOP_DATA_REC:
			this.shopDataRec(e);
			break;
		case md.ACTSHOP_ONE_REC:
			this.shopOneRec(e);
			break
		}
	}
	onClick(e) {
		switch (e.target) {
		case this._ui.btnClose:
			this.closeUI();
			break
		}
	}
	initUI() {
		this._ui = this.uiView;
		this.setLayer(0, 1, 2);
		this._ui.listCamp.array = [0, 1, 2, 3, 4, 5];
		this._ui.listCamp.selectHandler = Laya.Handler.create(this, this.heroCampSelect, null, false);
		this._ui.listBuy.scrollBar.on(Laya.Event.CHANGE, this, this.scrollBarChange);
		this._ui.boxBuyBack.mouseEnabled = false;
		this._ui.boxBuyBack.scrollRect = new Laya.Rectangle(0, 0, this._ui.boxBuyBack.width, this._ui.boxBuyBack.height)
	}
	scrollBarChange() {
		this._ui.listBuyBack.y = -this._ui.listBuy.scrollBar.value
	}
	showSkinId(e) {
		this.skinId = e;
		this.openUI()
	}
	afterOpen() {
		this._ui.listCamp.selectedIndex = -1;
		this._ui.listCamp.selectedIndex = 0
	}
	updateInfo() {
		if (!this.actId || !this.srvData)
			return;
		let e = this.srvData.items;
		let t = [];
		let i = this.data.master.level;
		let s = this.data.master.vip;
		for (let l = 0; l < e.length; l++) {
			this.setTpl(e[l]);
			if (e[l].tpl.minLv && i < e[l].tpl.minLv) {
				continue
			}
			if (e[l].tpl.maxLv && i > e[l].tpl.maxLv) {
				continue
			}
			if (e[l].tpl.minVip && s < e[l].tpl.minVip) {
				continue
			}
			if (e[l].tpl.maxVip && s > e[l].tpl.maxVip) {
				continue
			}
			e[l].sellOut = false;
			if (e[l].tpl.limitNum <= e[l].purchaseNum) {
				e[l].sellOut = true
			} else {
				let t = this.data.bag.prop.getNum(e[l].tpl.skinPropId);
				if (t > 0) {
					e[l].sellOut = true
				}
				if (M_.isGotSkinForever(e[l].activeTpl.skinId)) {
					e[l].sellOut = true
				}
			}
			if (this._ui.listCamp.selectedIndex == 0 || this._ui.listCamp.selectedIndex == e[l].heroTpl.camp) {
				t.push(e[l])
			}
		}
		t.sort(this.sortFun);
		this._ui.listBuy.array = t;
		let a = Math.ceil(t.length / 3);
		let r = [];
		for (let l = 0; l < a; l++) {
			r.push({})
		}
		this._ui.listBuyBack.height = 331 * a;
		this._ui.listBuyBack.array = r
	}
	heroCampSelect(e) {
		if (e < 0)
			return;
		this.updateInfo();
		let t = 0;
		if (this.skinId) {
			let e = this._ui.listBuy.array;
			if (e && e.length) {
				for (let i = 0; i < e.length; i++) {
					if (e[i].activeTpl.skinId == this.skinId) {
						t = i;
						break
					}
				}
			}
			this.skinId = 0
		}
		this._ui.listBuy.tweenTo(t, 0)
	}
	sortFun(e, t) {
		if (!e.sellOut && t.sellOut) {
			return -1
		} else if (e.sellOut && !t.sellOut) {
			return 1
		}
		return e.tpl.power - t.tpl.power
	}
	shopDataRec(e) {
		let t = e.cycleMall;
		let i = false;
		if (t && t.malls) {
			let e = t.malls;
			for (let t in e) {
				if (e[t].funcId == this.funcId) {
					this.srvData = e[t];
					i = true
				}
			}
		}
		if (!i && this.srvData && this.srvData.activityId) {
			this.srvData.activityId = 0
		}
		this.refreshData()
	}
	shopOneRec(e) {
		let t = e.mall;
		if (t && t.funcId == this.funcId) {
			this.srvData = t;
			this.refreshData()
		}
	}
	refreshData() {
		if (!this.srvData)
			return;
		this.setActId(this.srvData.activityId);
		this.checkDot();
		if (this.isOpen) {
			this.updateInfo()
		}
	}
	setActId(e) {
		if (this.actId == e)
			return;
		this.actId = e;
		this.actTpl = od.getTplInfo(nd.ACT_SHOP_BASE, e)
	}
	setTpl(e) {
		if (e) {
			if (e.tpl) {
				return
			}
			e.tpl = od.getTplInfo(nd.ACT_SHOP_GOODS, e.tid);
			e.activeTpl = od.getTplInfo(nd.SKIN_ACTIVE_ITEM, e.tpl.skinPropId);
			e.skinTpl = od.getTplInfo(nd.SKIN, e.activeTpl.skinId);
			e.wearTpl = od.getTplInfo(nd.SKIN_WEAR, "skin_" + e.activeTpl.skinId);
			e.heroTpl = od.getTplInfo(nd.HERO, null, {
					protoId: e.skinTpl.heroProtoId
				})[0]
		}
	}
	get actDotTypes() {
		return []
	}
	checkDot() {
		let e = this.actDotTypes;
		if (!e || !e.length)
			return;
		let t = false;
		if (this.srvData && this.actId) {
			if (!t) {
				let e = this.srvData.items;
				for (let i = 0; i < e.length; i++) {
					this.setTpl(e[i]);
					if (e[i].tpl.price == 0 && e[i].purchaseNum < e[i].tpl.limit) {
						t = true;
						break
					}
				}
			}
		}
		for (let i = 0; i < e.length; i++) {
			cd.setDot(e[i], this, t)
		}
	}
}
