class fy extends g {
	constructor() {
		super("Zhaohuanfuli");
		this._turn = 0;
		this._showTurn = 0
	}
	getCmds() {
		return [d.FUNC_INIT, d.FUNC_OPEN]
	}
	exeCmd(e, t) {
		switch (t) {
		case d.FUNC_INIT:
			this.checkDot();
			this.checkMainBtn();
			break;
		case d.FUNC_OPEN:
			if (e == pd.ACT_SN_WELFARE) {
				this.checkDot();
				this.checkMainBtn()
			}
			break
		}
	}
	getMsgs() {
		return [uf.DATA_REC]
	}
	exeMsg(e, t) {
		switch (t) {
		case uf.DATA_REC:
			this.dataRec(e);
			break
		}
	}
	onClick(e) {
		switch (e.target) {
		case this._ui.btnClose:
			this.closeUI();
			break;
		case this._ui.btnTips:
			D_.showById(246);
			break;
		case this._ui.btnRwd:
			FM.actSnWfShopMan.openUI();
			break;
		case this._ui.btnGo:
			this.onBtnGoClicked();
			break
		}
	}
	initUI() {
		this._ui = this.uiView;
		this.setLayer(1, 1, 1, 1);
		this._ui.btnPre.on(Laya.Event.CLICK, this, this.onBtnPreClicked)
	}
	afterOpen() {
		this.refreshTurn();
		this.refreshSnTime();
		this._ui.hurtRwdList.scrollTo(0)
	}
	checkOpen(e = false) {
		return this.isOpenServer() && FM.funcMan.checkFuncOpen(pd.ACT_SN_WELFARE, e)
	}
	onBtnGoClicked() {
		FM.recruitMan.openUI();
		this.closeUI()
	}
	onBtnPreClicked(e) {
		FM.actSnWfAwardPre.openUI()
	}
	dataRec(e) {
		if (e == null || e.data == null)
			return;
		if (!this.turnData)
			return;
		this._srvData = e.data;
		this.checkDot();
		this.checkMainBtn();
		if (!this.isOpenServer())
			return;
		let t = this.actTpl;
		if (t.funcId != pd.ACT_SN_WELFARE)
			return;
		this._turn = this._srvData.turn;
		let i = this.turnData.length;
		if (this._turn > i) {
			this._turn = i
		}
		this.refreshTurn();
		this.refreshSnTime()
	}
	refreshTurn() {
		if (!this.isOpen)
			return;
		if (!this.isOpenServer())
			return;
		if (this._turn == this._showTurn)
			return;
		let e = this.turnData;
		if (e == null)
			return;
		this._ui.turnLabel.text = "Thứ" + WM.longNum2Chinese(this._srvData.turn) + "Vòng ban thưởng";
		this._ui.hurtRwdList.array = e[this._turn - 1].list;
		this._showTurn = this._turn
	}
	refreshSnTime() {
		if (!this.isOpen)
			return;
		if (!this.isOpenServer())
			return;
		let e = this._ui.hurtRwdList.array;
		for (let i = 0; i < e.length; i++) {
			let t = this._ui.hurtRwdList.getCell(i);
			let s = 2;
			let a = e[i];
			if (!this._srvData.gotMap.hasOwnProperty(a.id)) {
				s = this._srvData.times < a.callTime ? 0 : 1
			}
			t.state = s
		}
		let t = e[e.length - 1].callTime;
		this._ui.timeLabel.text = this._srvData.times <= t ? this._srvData.times.toString() : t.toString() + "+"
	}
	checkDot() {
		let e = false;
		if (this.checkOpen()) {
			let t = this.turnData[this._turn - 1];
			if (t) {
				for (let i = 0; i < t.list.length; i++) {
					let s = t.list[i];
					if (!this._srvData.gotMap.hasOwnProperty(s.id) && this._srvData.times >= s.callTime) {
						e = true;
						break
					}
				}
			}
		}
		cd.setDot(dd.ZHAOHUANFULI, this, e);
		cd.setDot(dd.ACT_FOLD2, this, e);
		cd.setDot(dd.CITY_ENTER, this, e)
	}
	checkMainBtn() {
		if (this.checkOpen()) {
			FM.mainCityMan.setTopBtnOpen(bb.ZHAOHUANFULI, this, true);
			let e = this.actTpl;
			if (e) {
				let t = this.data.openSrvTime + b_.getActEndTime(e.endDay, e.endTime) - this.data.serverTime;
				vg.start(t, this, this.timerFun, 1, null)
			}
		} else {
			FM.mainCityMan.setTopBtnOpen(bb.ZHAOHUANFULI, this, false);
			vg.stop(this, this.timerFun)
		}
	}
	timerFun(e, t) {
		let i;
		if (e >= b_.ONEDAYMILLISECONDS) {
			i = b_.getDayHourStr(e)
		} else {
			i = b_.getCdTimeStrByMs(e)
		}
		FM.mainCityMan.showActCdTime(Rb.ZhaoHuanFuLi, i);
		if (this.isOpen) {
			this._ui.cdTimeLab.text = i
		}
	}
	isOpenServer() {
		if (!this._srvData)
			return false;
		return this._srvData.activityId == 10001
	}
	get actTpl() {
		return od.getTplInfo(nd.ACT_SN_WF_BASE, this._srvData.activityId)
	}
	get turnData() {
		let e = [];
		if (!this._turnData) {
			let t = [];
			t = od.getTplInfo(nd.ACT_SN_WF_AWARDS, 1);
			for (let i in t.turns) {
				e.push(t.turns[i])
			}
			this._turnData = e
		}
		return this._turnData
	}
}
