class xy extends Hb {
	constructor() {
		super(pd.CYCLE_WEEK_LIMIT, "ActWeekBuy")
	}
	getCmds() {
		return [d.FUNC_INIT, d.FUNC_OPEN]
	}
	exeCmd(e, t) {
		switch (t) {
		case d.FUNC_INIT:
			this.checkActOpen();
			this.checkDot();
			break;
		case d.FUNC_OPEN:
			if (e == this.funcId) {
				this.checkActOpen();
				this.checkDot()
			}
			break
		}
	}
	getMsgs() {
		return [md.WEEK_SHOP_REC]
	}
	exeMsg(e, t) {
		switch (t) {
		case md.WEEK_SHOP_REC:
			this.shopDataRec(e);
			break
		}
	}
	onClick(e) {}
	initUI() {
		this._ui = this.uiView
	}
	openUI() {
		FM.limitTimeMan.openAct(this.funcId);
		super.openUI()
	}
	afterOpen() {
		this._ui.imgBanner.skin = "icon/hengfu" + this.actTpl.hengFu + ".jpg";
		this.updateInfo();
		this._ui.listCell.tweenTo(0, 0)
	}
	afterClose() {
		vg.stop(this, this.refreshCdTime);
		super.afterClose()
	}
	refreshCdTime(e, t, i) {
		if (e >= b_.ONEDAYMILLISECONDS) {
			i = b_.getDayHourStr(e)
		} else {
			i = b_.getCdTimeStrByMs(e)
		}
		this._ui.labTime.text = i
	}
	shopDataRec(e) {
		this.srvData = e.weekLimit;
		this.refreshData()
	}
	refreshData() {
		this.setActId(this.srvData.activityId);
		this.checkActOpen();
		this.checkDot();
		if (this.isOpen) {
			this.updateInfo()
		}
	}
	checkActOpen() {
		if (!this.funcOpen)
			return;
		FM.mainCityMan.setTopBtnOpen(bb.LIMIT_TIME, this, this.actId ? true : false)
	}
	updateInfo() {
		if (!this.actOpen || !this.srvData)
			return;
		vg.stop(this, this.refreshCdTime);
		let e = this.actTpl;
		if (e) {
			let t = this.data.openSrvTime + b_.getActEndTime(e.endDay, e.endTime) - this.data.serverTime;
			vg.start(t, this, this.refreshCdTime, 1, null)
		}
		let t = [];
		let i = this.srvData.items;
		let s = this.data.master.level;
		for (let a = 0; a < i.length; a++) {
			i[a].tpl = od.getTplInfo(nd.ACT_WEEKSHOP_GOODS, i[a].tid);
			if (i[a].tpl.minLv && s < i[a].tpl.minLv) {
				continue
			}
			if (i[a].tpl.maxLv && s > i[a].tpl.maxLv) {
				continue
			}
			let e = {};
			e.purchaseNum = i[a].purchaseNum;
			e.tid = i[a].tid;
			e.tpl = i[a].tpl;
			t.push(e)
		}
		t.sort(this.sortFun);
		this._ui.listCell.array = t
	}
	sortFun(e, t) {
		if (e.tpl.limit - e.purchaseNum > 0 && t.tpl.limit - t.purchaseNum <= 0) {
			return -1
		} else if (e.tpl.limit - e.purchaseNum <= 0 && t.tpl.limit - t.purchaseNum > 0) {
			return 1
		}
		return e.tpl.power - t.tpl.power
	}
	setActId(e) {
		if (this.actId == e)
			return;
		this.actId = e;
		this.actTpl = od.getTplInfo(nd.ACT_WEEKSHOP_BASE, e)
	}
	get actDotType() {
		return dd.ACT_WEEKSHOP
	}
	checkDot() {
		let e = false;
		if (this.funcOpen && this.actId) {
			let t = this.srvData.items;
			for (let i = 0; i < t.length; i++) {
				if (!t[i].tpl) {
					t[i].tpl = od.getTplInfo(nd.ACT_WEEKSHOP_GOODS, t[i].tid)
				}
				if (t[i].tpl.price == 0 && t[i].purchaseNum < t[i].tpl.limit) {
					e = true;
					break
				}
			}
		}
		cd.setDot(this.actDotType, this, e);
		cd.setDot(dd.ACT_LIMIT_TIME, this, e);
		cd.setDot(dd.CITY_ENTER, this, e)
	}
}
