class Py extends g {
	constructor() {
		super("XCXHuTong");
		this.rwdGot = false;
		this.sq = false;
		this.isSupport = false;
		this.cdTimeNum = 0;
		this.funcId = pd.DP_BANGDINGPHONE
	}
	onClick(e) {
		switch (e.target) {
		case this._ui.btnBangDing:
			this.bangDing();
			break;
		case this._ui.btnSend:
			this.sendCode();
			break;
		case this._ui.btnPrize:
			this.onBtnClick();
			break
		}
	}
	getCmds() {
		return [d.FUNC_INIT, d.FUNC_OPEN]
	}
	exeCmd(e, t) {
		if (Laya.Browser.window.ydwxConfig && Laya.Browser.window.ydwxConfig.minish)
			return;
		if (!Laya.Browser.onMiniGame)
			return;
		switch (t) {
		case d.FUNC_INIT:
			this.checkMainBtn();
			this.checkDot();
			break;
		case d.FUNC_OPEN:
			if (e == pd.DP_BANGDINGPHONE) {
				this.checkMainBtn();
				this.checkDot()
			}
			break
		}
	}
	getMsgs() {
		return [If.DATA_REC, mp.INIT_COMPLETE_REC]
	}
	exeMsg(e, t) {
		if (Laya.Browser.window.ydwxConfig && Laya.Browser.window.ydwxConfig.minish)
			return;
		if (!Laya.Browser.onMiniGame)
			return;
		switch (t) {
		case If.DATA_REC:
			this.rwdGot = e.data.gotMap[this.funcId];
			this.refreshPanel();
			this.checkMainBtn();
			this.checkDot();
			break;
		case mp.INIT_COMPLETE_REC:
			if (Laya.Browser.onMiniGame) {
				this.checkBingPhone()
			}
			break
		}
	}
	initUI() {
		this._ui = this.uiView;
		this.setLayer(1, 1, 1, 2);
		let e = od.getTplInfo(nd.DIRECTPRIZE, this.funcId);
		if (e) {
			this._ui.listRwd.array = cP.splitStr2Arr(e.rwd)
		}
	}
	afterOpen() {
		this.refreshPanel();
		this.checkDot()
	}
	refreshPanel() {
		if (!this.isOpen)
			return;
		this._ui.btnBangDing.visible = this._ui.btnPrize.visible = this._ui.btnSend.visible = false;
		this._ui.imgOk.visible = this._ui.imgInput.visible = this._ui.labCdTime.visible = false;
		if (this.rwdGot) {
			this._ui.btnPrize.visible = true;
			this._ui.btnPrize.disabled = true;
			this._ui.imgOk.visible = true
		} else {
			if (this.sq) {
				this._ui.imgOk.visible = true;
				this._ui.btnPrize.visible = true;
				this._ui.btnPrize.disabled = false
			} else {
				this._ui.btnBangDing.visible = true;
				this._ui.imgInput.visible = true;
				if (this.cdTimeNum > 0) {
					this._ui.labCdTime.visible = true
				} else {
					this._ui.btnSend.visible = true
				}
			}
		}
	}
	checkDot() {
		let e = false;
		if (this.isSupport || !this.rwdGot) {
			if (!this._ui || this.sq) {
				e = true
			}
		}
		cd.setDot(dd.DP_BANGDINGPHONE, this, e)
	}
	checkMainBtn() {
		if (Laya.Browser.window.ydwxConfig && Laya.Browser.window.ydwxConfig.minish) {
			FM.mainCityMan.setTopBtnOpen(bb.DP_BANGDINGPHONE, this, false);
			return
		}
		FM.mainCityMan.setTopBtnOpen(bb.DP_BANGDINGPHONE, this, this.isSupport && !this.rwdGot && FM.funcMan.checkFuncOpen(this.funcId, false))
	}
	onBtnClick() {
		if (this.rwdGot)
			return;
		if (this.sq) {
			this.sendMsg(If.PRIZE_REQ, {
				funcId: this.funcId
			})
		}
	}
	checkBingPhone() {
		My.isBindPhone({
			callback: Laya.Handler.create(this, this.isBingPhoneCall),
			supportFun: Laya.Handler.create(this, this.isSupportCall)
		})
	}
	isBingPhoneCall(e) {
		this.sq = e;
		this.checkDot()
	}
	isSupportCall(e) {
		this.isSupport = e;
		this.checkMainBtn();
		this.checkDot()
	}
	sendCode() {
		if (this._ui.inputPhone.text.length != 11) {
			FM.noticeMan.showNotice("Số điện thoại di động không đối");
			return
		}
		My.sendCode({
			phone: this._ui.inputPhone.text,
			callback: Laya.Handler.create(this, this.sendCodeCall)
		})
	}
	sendCodeCall(e) {
		if (e) {
			FM.noticeMan.showNotice("Gửi đi thành công");
			this.cdTimeNum = 60;
			this.refreshPanel();
			Laya.timer.loop(1e3, this, this.cdTimeFun);
			this.cdTimeFun()
		} else {
			FM.noticeMan.showNotice("Gửi đi thất bại")
		}
	}
	cdTimeFun() {
		if (this.cdTimeNum <= 0) {
			this.refreshPanel();
			this.clearCdTimeFun();
			return
		}
		if (this.isOpen) {
			this._ui.labCdTime.text = this.cdTimeNum + "S"
		}
		this.cdTimeNum--
	}
	clearCdTimeFun() {
		Laya.timer.clear(this, this.cdTimeFun);
		this.cdTimeNum = 0
	}
	bangDing() {
		if (this._ui.inputPhone.text.length != 11) {
			FM.noticeMan.showNotice("Số điện thoại di động không đối");
			return
		}
		My.bindPhone({
			phone: this._ui.inputPhone.text,
			code: this._ui.inputCode.text,
			callback: Laya.Handler.create(this, this.bingPhoneCall)
		})
	}
	bingPhoneCall(e) {
		if (e) {
			FM.noticeMan.showNotice("Khóa lại thành công");
			this.sq = true;
			this.refreshPanel()
		} else {
			FM.noticeMan.showNotice("Khóa lại thất bại")
		}
	}
}
class Hy extends g {
	constructor() {
		super("BiliGZGame");
		this.sq = false;
		this.funcId = pd.DP_BILIGZGAME
	}
	getCmds() {
		if (!Laya.Browser.onBLMiniGame)
			return [];
		return [d.FUNC_INIT]
	}
	exeCmd(e, t) {
		if (!Laya.Browser.onBLMiniGame)
			return;
		switch (t) {
		case d.FUNC_INIT:
			this.checkIsSq();
			break
		}
	}
	checkShow() {
		if (this.sq) {
			if (this.isOpen) {
				this.closeUI()
			}
		} else {
			if (!this.isOpen) {
				this.openUI()
			}
		}
	}
	initUI() {
		this.setLayer(2, 2, 0, 0);
		let e = Laya.Browser.window.bl.getMenuButtonBoundingClientRect();
		let t = Laya.stage.height / Laya.Browser.clientHeight;
		this.uiView.x = e.left * t - this.uiView.width;
		this.uiView.y = e.top * t - _.notchHeight + (e.height * t - this.uiView.height) * .5;
		Laya.Browser.window.bl.onGameFollowedFromMenu(function () {
			FM.biliGameGuanZhu.sq = true;
			FM.biliGameGuanZhu.checkShow()
		})
	}
	afterOpen() {
		Laya.timer.once(120 * 1e3, this, this.closeUI)
	}
	checkIsSq() {
		Laya.Browser.window.bl.getGameFollowingStatus({
			success: Laya.Utils.bind(this.isFollowOk, this)
		})
	}
	isFollowOk(e) {
		if (!e)
			return;
		if (e.follow) {
			this.sq = true
		} else {
			this.sq = false
		}
		this.checkShow()
	}
}
