class Zy extends g {
	constructor() {
		super("EliteCallChoose");
		this.spaceXObj = {
			3: 50,
			4: 25,
			5: 7
		}
	}
	static getIns() {
		if (!this._ins) {
			this._ins = new Zy
		}
		return this._ins
	}
	onClick(e) {
		switch (e.target) {
		case this._ui.btnClose:
			this.closeUI();
			break;
		case this._ui.btnCancel:
			this.closeUI();
			break;
		case this._ui.btnSure:
			let t = this._ui.heroList.array;
			for (let e = 0; e < t.length; e++) {
				if (t[e].selected) {
					FM.eliteCallMan.setPickHeroId(t[e].heroId);
					break
				}
			}
			this.closeUI();
			break
		}
	}
	initUI() {
		this._ui = this.uiView;
		this.setLayer(1, 1, 1, 1)
	}
	showDetail() {
		this.openUI()
	}
	afterOpen() {
		this.updateInfo()
	}
	updateInfo() {
		let e = FM.eliteCallMan.selectHeros;
		if (this.spaceXObj[e.length]) {
			this._ui.heroList.spaceX = this.spaceXObj[e.length]
		}
		this._ui.heroList.array = e;
		this.refreshSelected(FM.eliteCallMan.pickHeroId)
	}
	refreshSelected(e) {
		let t = this._ui.heroList.array;
		for (let i = 0; i < t.length; i++) {
			if (t[i].heroId == e) {
				t[i].selected = true
			} else {
				t[i].selected = false
			}
		}
		this._ui.heroList.refresh()
	}
}
