class $y extends g {
	constructor() {
		super("EliteCallTips")
	}
	static getIns() {
		if (!this._ins) {
			this._ins = new $y
		}
		return this._ins
	}
	getMsgs() {
		return []
	}
	exeMsg(e, t) {
		switch (t) {}
	}
	onClick(e) {
		switch (e.target) {
		case this._ui.btnClose:
			this.closeUI();
			break
		}
	}
	initUI() {
		this._ui = this.uiView;
		this.setLayer(1, 1, 1, 1);
		this._ui.contentTip.style.width = this._ui.contentTip.width;
		this._ui.contentTip.style.bold = false;
		this._ui.gailvTip.style.width = this._ui.gailvTip.width;
		this._ui.gailvTip.style.bold = false
	}
	showDetail() {
		this.openUI()
	}
	afterOpen() {
		let e = WM.getExplainTipById(139);
		let t = FM.eliteCallMan.actTpl.heros;
		if (t) {
			let i = t.split("#");
			e = WM.replaceDS(e, [String(i.length)])
		}
		this._ui.contentTip.innerHTML = WM.str2Html(e, 2461);
		this._ui.glBox.y = this._ui.contentBox.y + this._ui.contentTip.y + this._ui.contentTip.contextHeight + 30;
		this.updateInfo()
	}
	updateInfo() {
		let e = jy.getRecruitGroupData(jy.HEIGHT0);
		let t = FM.eliteCallMan.getPickHeroData();
		let i = t.power;
		let s;
		let a = [0, 0, 0, 0, 0];
		let r = e.groupArr;
		let l = e.allPower;
		for (let o = 0; o < r.length; o++) {
			let h = r[o].groupPower;
			let n = e.groupArr[o].heroArr;
			for (let e = 0; e < n.length; e++) {
				if (n[e].heroId == t.heroId) {
					h += i
				}
			}
			for (let e = 0; e < n.length; e++) {
				s = od.getTplInfo(nd.HERO, n[e].heroId);
				if (n[e].heroId == t.heroId) {}
				else {
					a[s.star - 1] += r[o].power * n[e].power / (l * h)
				}
			}
		}
		let h = 0;
		for (let o = 0; o < a.length; o++) {
			a[o] = parseFloat(a[o].toFixed(4));
			h += a[o]
		}
		i = 1 - h;
		let n = WM.replaceDS(WM.getExplainTipById(140), [(100 * i).toFixed(2) + "%", (100 * a[4]).toFixed(2) + "%", (100 * a[3]).toFixed(2) + "%", (100 * a[2]).toFixed(2) + "%"]);
		this._ui.gailvTip.innerHTML = WM.str2Html(n, 2461)
	}
}
