class cE extends g {
	constructor() {
		super("ActivityMXRZ")
	}
	getMsgs() {
		return [nf.GLB_DATA_REC, nf.END_NOTICE_REC]
	}
	exeMsg(e, t) {
		switch (t) {
		case nf.GLB_DATA_REC:
			this.dataRec(e);
			break;
		case nf.END_NOTICE_REC:
			this.endNoticeRec(e);
			break
		}
	}
	getCmds() {
		return [d.TASK_INIT, d.TASK_CHANGE_ITEM, d.CROSS_DAY, d.FUNC_INIT, d.FUNC_OPEN, d.SOCKET_RECONNECTED]
	}
	exeCmd(e, t) {
		switch (t) {
		case d.TASK_INIT:
			this.checkDot();
			break;
		case d.TASK_CHANGE_ITEM:
			this.taskChange(e);
			break;
		case d.CROSS_DAY:
			this.refreshDayTask();
			this.checkDot();
			break;
		case d.FUNC_INIT:
			this.checkMainEnter();
			break;
		case d.FUNC_OPEN:
			if (e == pd.ACT_GLB) {
				this.checkMainEnter()
			}
			break;
		case d.SOCKET_RECONNECTED:
			this.socketReconnected();
			break
		}
	}
	onClick(e) {
		switch (e.target) {
		case this._ui.btnClose:
			this.closeUI();
			break;
		case this._ui.btnTip:
			D_.showById(132);
			break;
		case this._ui.btnRwd:
			uE.getIns().openUI();
			break;
		case this._ui.btnMore:
			oE.getIns().openUI();
			break
		}
	}
	initUI() {
		this._ui = this.uiView;
		this.setLayer(1, 1, 1, 1);
		cd.regDot(dd.ACT_GLB_RWD, this._ui.dotRwd)
	}
	afterOpen() {
		this.refreshTime();
		this.refreshDayTask();
		this.refreshRechargeTask();
		this.refreshLevel()
	}
	afterClose() {
		vg.stop(this, this.timerFun)
	}
	get actTpl() {
		if (!this._actTpl)
			this._actTpl = od.getTplInfo(nd.ACT_OPEN_SERVER, pd.ACT_GLB);
		return this._actTpl
	}
	refreshTime() {
		let e = this.data.openSrvTime + b_.getActEndTime(this.actTpl.endDay, this.actTpl.endTime) - this.data.serverTime;
		vg.start(e, this, this.timerFun, 1, null)
	}
	timerFun(e, t) {
		if (e >= b_.ONEDAYMILLISECONDS) {
			this._ui.labTime.text = b_.getDayHourStr(e)
		} else {
			this._ui.labTime.text = b_.getCdTimeStrByMs(e)
		}
	}
	get actOpen() {
		return this.srvData ? true : false
	}
	get day() {
		let e = od.getTplInfo(nd.ACT_OPEN_SERVER, pd.ACT_GLB);
		return this.data.openSrvDay - e.startDay + 1
	}
	dataRec(e) {
		this.srvData = e.mertis;
		this.checkMainEnter();
		this.refreshLevel();
		this.checkDot()
	}
	endNoticeRec(e) {
		if (e.funId != pd.ACT_GLB)
			return;
		this.srvData = null;
		this.checkMainEnter();
		this.checkDot()
	}
	socketReconnected() {
		this.srvData = null;
		this.checkMainEnter();
		this.checkDot()
	}
	taskChange(e) {
		if (e.funcId != pd.ACT_GLB)
			return;
		this.refreshDayTask();
		this.refreshRechargeTask();
		this.checkDot()
	}
	refreshDayTask() {
		if (!this.isOpen)
			return;
		let e = od.getTplInfo(nd.ACT_GLB_TASK, null, {
				day: this.day
			});
		let t = [];
		for (let i = 0; i < e.length; i++) {
			let s = this.data.task.getTaskItem(pd.ACT_GLB, e[i].taskId);
			t.push({
				tpl: e[i],
				funcId: pd.ACT_GLB,
				got: s && s.rewardGot,
				done: s && s.done
			})
		}
		t.sort(this.taskSort);
		this._ui.listTask.array = t;
		this._ui.listTask.scrollTo(0)
	}
	taskSort(e, t) {
		if (e.got != t.got) {
			if (!e.got && t.got) {
				return -1
			} else {
				return 1
			}
		} else {
			if (e.done != t.done) {
				if (e.done && !t.done) {
					return -1
				} else {
					return 1
				}
			} else {
				return e.tpl.id - t.tpl.id
			}
		}
	}
	refreshRechargeTask() {
		if (!this.isOpen)
			return;
		let e = od.getTplInfo(nd.ACT_GLB_TASK, null, {
				day: 0
			});
		let t;
		for (let i = 0; i < e.length; i++) {
			let s = this.data.task.getTaskItem(pd.ACT_GLB, e[i].taskId);
			if (!s || !s.rewardGot || i == e.length - 1) {
				t = {
					tpl: e[i],
					funcId: pd.ACT_GLB
				};
				break
			}
		}
		this._ui.boxRecharge.dataSource = t
	}
	refreshLevel() {
		if (!this.isOpen)
			return;
		let e = 0;
		let t = 0;
		let i;
		let s = od.getTplInfo(nd.ACT_GLB_RWD);
		for (let a = 0; a < s.length; a++) {
			if (this.exp < s[a].exp) {
				i = s[a];
				break
			}
			e = s[a].id;
			t = s[a].exp
		}
		this._ui.labLevel.text = e + "";
		if (i) {
			this._ui.labProg.text = this.exp - t + "/" + (i.exp - t);
			this._ui.progBar.value = (this.exp - t) / (i.exp - t);
			this._ui.labNext.visible = true;
			this._ui.listRwd.array = cP.splitStr2Arr(i.rwd)
		} else {
			this._ui.labProg.text = "";
			this._ui.progBar.value = 1;
			this._ui.labNext.visible = false;
			this._ui.listRwd.array = []
		}
		uE.getIns().refresh()
	}
	get exp() {
		if (!this.srvData)
			return 0;
		return this.srvData.exp
	}
	isRwdGot(e) {
		if (!this.srvData)
			return false;
		return this.srvData.boxRecord[e] ? true : false
	}
	checkDot() {
		let e = false;
		if (this.actOpen && FM.funcMan.checkFuncOpen(pd.ACT_GLB, false)) {
			let t = od.getTplInfo(nd.ACT_GLB_RWD);
			for (let i = 0; i < t.length; i++) {
				let s = this.isRwdGot(t[i].id);
				if (t[i].exp <= this.exp && !s) {
					e = true;
					break
				}
			}
			cd.setDot(dd.ACT_GLB_RWD, this, e);
			if (!e) {
				let t = od.getTplInfo(nd.ACT_GLB_TASK);
				for (let i = 0; i < t.length; i++) {
					let s = this.data.task.getTaskItem(pd.ACT_GLB, t[i].id);
					if (s && s.done && !s.rewardGot) {
						e = true;
						break
					}
				}
			}
		}
		cd.setDot(dd.ACT_GLB, this, e);
		cd.setDot(dd.CITY_ENTER, this, e)
	}
	checkMainEnter() {
		FM.mainCityMan.setTopBtnOpen(bb.GLB, this, this.actOpen && FM.funcMan.checkFuncOpen(pd.ACT_GLB, false))
	}
}
