class pE extends Hb {
	constructor(e = "ActHangDrop") {
		super(pd.ACT_HANG_DROP, e)
	}
	getMsgs() {
		return [of.DATA_REC, of.UPDATE_NUM_REC]
	}
	exeMsg(e, t) {
		switch (t) {
		case of.DATA_REC:
			this.dataRec(e);
			break;
		case of.UPDATE_NUM_REC:
			this.updateNumRec(e);
			break
		}
	}
	onClick(e) {
		switch (e.target) {
		case this._ui.btnGo:
			dE.getIns().openUI();
			break
		}
	}
	initUI() {
		this._ui = this.uiView;
		cd.regDot(dd.ACT_HANG_DROP_BUY, this._ui.dotGo)
	}
	get actDotType() {
		return dd.ACT_HANG_DROP_TAB
	}
	openUI() {
		if (!this.checkOpen()) {
			return
		}
		FM.limitTimeMan.openAct(this.funcId);
		super.openUI()
	}
	afterOpen() {
		this.refreshActId();
		this.refreshNum()
	}
	afterClose() {
		vg.stop(this, this.timerFun)
	}
	dataRec(e) {
		this.itemList = e.drop.itemList;
		this.dropNum = e.drop.dropItemNum;
		this.actId = e.drop.activityId;
		this.actTpl = od.getTplInfo(nd.ACT_HANG_DROP, this.actId);
		this.refreshActId();
		this.refreshNum();
		this.refreshShop();
		this.checkDot();
		this.checkActOpen()
	}
	updateNumRec(e) {
		this.dropNum = e.dropItemNum;
		this.checkDot();
		this.refreshNum()
	}
	refreshActId() {
		if (!this.isOpen)
			return;
		if (!this.actId)
			return;
		this._ui.imgBg.skin = "icon/" + this.actTpl.imgBg + ".jpg";
		let e = this.actTpl.desc.split("#");
		for (let i = 0; i < e.length; i++) {
			let t = this._ui["desc" + i];
			if (!t)
				break;
			t.text = e[i]
		}
		this._ui.listRwd.array = cP.splitStr2Arr(this.actTpl.showItem);
		this.dropItem = {
			type: c.PROP,
			tid: this.actTpl.dropItemId
		};
		Tb.addWealthGridByInfo(this.dropItem, this._ui.boxDrop);
		let t = this.data.openSrvTime + b_.getActEndTime(this.actTpl.dropEndDay, this.actTpl.dropEndTime) - this.data.serverTime;
		vg.start(t, this, this.timerFun, 1, null)
	}
	timerFun(e, t) {
		if (e >= b_.ONEDAYMILLISECONDS) {
			this._ui.labTime.text = b_.getDayHourStr(e)
		} else {
			this._ui.labTime.text = b_.getCdTimeStrByMs(e)
		}
	}
	refreshNum() {
		if (!this.isOpen)
			return;
		this._ui.labNum.text = this.dropNum + ""
	}
	refreshShop() {
		if (!this.isOpen)
			return;
		if (!this.actId)
			return;
		dE.getIns().refresh()
	}
	checkActOpen() {
		if (!this.funcOpen)
			return;
		FM.mainCityMan.setTopBtnOpen(bb.LIMIT_TIME, this, this.actId ? true : false)
	}
	checkDot() {
		if (!this.funcOpen)
			return;
		let e = false;
		if (this.actId) {
			for (let t = 0; t < this.itemList.length; t++) {
				let i = od.getTplInfo(nd.ACT_HANG_DROP_SHOP, this.itemList[t].tid);
				if (!i.highValue)
					continue;
				if (this.itemList[t].purchaseNum >= i.limit)
					continue;
				if (this.dropNum < i.costNum)
					continue;
				e = true;
				break
			}
		}
		cd.setDot(dd.ACT_HANG_DROP_BUY, this, e);
		cd.setDot(dd.ACT_HANG_DROP_TAB, this, e);
		cd.setDot(dd.ACT_LIMIT_TIME, this, e);
		cd.setDot(dd.CITY_ENTER, this, e)
	}
}
