class ME extends g {
	constructor() {
		super("ActLuckyBag");
		this.numberNum = -1
	}
	getCmds() {
		return [d.FUNC_INIT, d.FUNC_OPEN]
	}
	exeCmd(e, t) {
		switch (t) {
		case d.FUNC_INIT:
			this.checkMainBtn();
			this.checkDot();
			break;
		case d.FUNC_OPEN:
			if (e == pd.ACT_LUCKY_BAG) {
				this.checkMainBtn();
				this.checkDot()
			}
			break
		}
	}
	getMsgs() {
		return [md.LUCKYBAG_MYDATA_REC, md.LUCKYBAG_SRVDATA_REC]
	}
	exeMsg(e, t) {
		switch (t) {
		case md.LUCKYBAG_MYDATA_REC:
			this.dataRec(e);
			break;
		case md.LUCKYBAG_SRVDATA_REC:
			this.srvDataRec(e);
			break
		}
	}
	onClick(e) {
		switch (e.target) {
		case this._ui.btnQuan:
			this.numberNum = this.numbers.length;
			OE.getIns().show();
			this.checkDot();
			break;
		case this._ui.btnClose:
			this.closeUI();
			break;
		case this._ui.btnPrize:
			BE.getIns().openUI();
			break;
		case this._ui.btnTips:
			D_.showById(182);
			break;
		case this._ui.btnBox0:
		case this._ui.btn0:
			this.showBuyQuan(0);
			break;
		case this._ui.btnBox1:
		case this._ui.btn1:
			this.showBuyQuan(1);
			break;
		case this._ui.btnBox2:
		case this._ui.btn2:
			this.showBuyQuan(2);
			break
		}
	}
	showBuyQuan(e) {
		if (!this.srvData.items || !this.srvData.items[e] || !this.totalData.items || !this.totalData.items[e]) {
			FM.noticeMan.showNotice(WM.getLanCodeTip(10024));
			return
		}
		let t = this.srvData.items[e];
		let i = this.totalData.items[e];
		let s = od.getTplInfo(nd.ACT_LUCKYBAG_PRIZE, t.tid);
		if (this.isPassBuyTime()) {
			FM.noticeMan.showNotice(WM.getLanCodeTip(10025));
			return
		}
		let a = this.getTotalQuan();
		if (this.actTpl && s.quanNum + a > this.actTpl.totalNum) {
			let e = this.actTpl.totalNum;
			if (a >= e) {
				FM.noticeMan.showNotice(WM.getLanCodeTip(10026))
			} else {
				QM.show(WM.getLanCodeTip(20016, [e - a]), Laya.Handler.create(this, this.msgBuyCall, [s, t, i, e - a]))
			}
			return
		}
		if (this.isPassBuyTime()) {
			this.msgBuyCall(s, t, i, 0, true);
			return
		}
		this.msgBuyCall(s, t, i, s.quanNum, true)
	}
	msgBuyCall(e, t, i, s, a = true) {
		if (a) {
			wE.getIns().showDetail(e, t, i, s)
		}
	}
	initUI() {
		this._ui = this.uiView;
		this.setLayer(1, 1, 1, 1);
		cd.regDot(dd.LUCKY_BAG_NUM_ENTER, this._ui.dotNum)
	}
	checkOpen(e = false) {
		return this.isOpenServer() && FM.funcMan.checkFuncOpen(pd.ACT_LUCKY_BAG, e)
	}
	afterOpen() {
		this.updateInfo();
		this.refreshPrizeTime();
		let e = this.actTpl;
		if (e) {
			this._ui.previewList.array = cP.splitStr2Arr(e.rwd);
			let t = this.srvData.items;
			for (let e = 0; e < t.length; e++) {
				let i = od.getTplInfo(nd.ACT_LUCKYBAG_PRIZE, t[e].tid);
				this._ui["zheLab" + e].text = WM.getLanCodeTip(20017, [i.discount]);
				this._ui["buyQuanLab" + e].text = WM.getLanCodeTip(20018, [i.quanNum])
			}
		}
		if (this.numberNum < 0) {
			this.numberNum = 0;
			this.checkDot()
		}
	}
	afterClose() {
		vg.stop(this, this.timerFun1)
	}
	updateInfo() {
		if (!this.isOpen)
			return;
		if (!this.isOpenServer())
			return;
		let e = this.actTpl;
		if (!e)
			return;
		let t = this.getTotalQuan();
		let i = this.isPassBuyTime();
		let s = this.isPassPrizeTime();
		let a = this.srvData.items;
		for (let l = 0; l < a.length; l++) {
			let r = od.getTplInfo(nd.ACT_LUCKYBAG_PRIZE, a[l].tid);
			let h = true;
			if (i) {
				this._ui["buyQuanImg" + l].visible = false;
				h = false
			} else {
				this._ui["buyQuanImg" + l].visible = true
			}
			if (s) {
				h = false
			}
			if (h && t >= e.totalNum) {
				h = false
			}
			if (h && r.limitNum) {
				if (a[l].purchaseNum >= r.limitNum) {
					h = false
				}
			}
			if (h && r.limitSrvNum) {
				if (this.totalData.items[l] && this.totalData.items[l].purchaseNum >= r.limitSrvNum) {
					h = false
				}
			}
			if (h) {
				this._ui["btn" + l].gray = false;
				this._ui["btn" + l].label = WM.getLanCodeTip(20001, [r.price])
			} else {
				this._ui["btn" + l].gray = true;
				this._ui["btn" + l].label = WM.getLanCodeTip(10012)
			}
		}
		let r = b_.getActTimeByStr(e.prizeTime).getTime() - this.data.serverTime;
		this._ui.numBox.visible = this._ui.quanBox.visible = false;
		if (r > 0) {
			this._ui.quanBox.visible = true;
			let i = this.getPlayerNum();
			this._ui.quanLeftLab.text = e.totalNum - t + "";
			let s = od.getTplInfo(nd.ACT_LUCKYBAG_NUM, null, {
					group: e.numGroup,
					rwdNum: i + 1
				});
			this._ui.playerNumTipBox.visible = this._ui.playerNumTipLab.visible = false;
			if (!s || !s.length) {
				this._ui.playerNumTipLab.visible = true;
				this._ui.playerNumTipLab.text = WM.getLanCodeTip(20019, [i])
			} else {
				this._ui.playerNumTipBox.visible = true;
				this._ui.quanBuyNum.text = WM.getLanCodeTip(20020, [s[0].rwdOp - t]);
				this._ui.quanPlayerNum.text = i + 1 + ""
			}
		} else {
			this._ui.numBox.visible = true;
			let e = [];
			let t = this.masters;
			for (let i = 0; i < t.length; i++) {
				e.push({
					number: t[i].number
				})
			}
			this._ui.numList.array = e
		}
	}
	refreshPrizeTime() {
		let e = this.actTpl;
		if (!e)
			return;
		let t = b_.getActTimeByStr(e.prizeTime).getTime() - this.data.serverTime;
		vg.stop(this, this.timerFun1);
		if (t > 0) {
			this._ui.cdTimeBox.visible = true;
			vg.start(t + 500, this, this.timerFun1)
		} else {
			this._ui.cdTimeBox.visible = false
		}
	}
	isPassBuyTime() {
		if (!this.actTpl)
			return true;
		let e = b_.getActTimeByStr(this.actTpl.buyTime).getTime() - this.data.serverTime;
		return e < 0
	}
	isPassPrizeTime() {
		if (!this.actTpl)
			return true;
		let e = b_.getActTimeByStr(this.actTpl.prizeTime).getTime() - this.data.serverTime;
		return e < 0
	}
	timerFun1(e, t) {
		let i;
		if (e >= b_.ONEDAYMILLISECONDS) {
			i = b_.getDayHourStr(e)
		} else {
			i = b_.getCdTimeStrByMs(e)
		}
		this._ui.cdTimeLab.text = i;
		if (t) {
			this.refreshPrizeTime()
		}
	}
	dataRec(e) {
		this.srvData = e.data;
		this.updateInfo();
		this.checkDot();
		this.checkMainBtn()
	}
	srvDataRec(e) {
		this.totalData = e.data;
		this.updateInfo();
		this.checkDot();
		this.checkMainBtn()
	}
	get actTpl() {
		return od.getTplInfo(nd.ACT_LUCKYBAG_BASE, this.srvData.activityId)
	}
	get numbers() {
		if (!this.srvData || !this.srvData.numbers)
			return [];
		return this.srvData.numbers
	}
	get masters() {
		if (!this.totalData || !this.totalData.masters)
			return [];
		return this.totalData.masters
	}
	getTotalQuan() {
		if (!this.totalData || !this.actTpl)
			return 0;
		return this.actTpl.totalNum - this.totalData.remainCount
	}
	getPlayerNum() {
		if (!this.actTpl)
			return 0;
		let e = this.actTpl.rwdNum;
		let t = od.getTplInfo(nd.ACT_LUCKYBAG_NUM, null, {
				group: this.actTpl.numGroup
			});
		let i = this.getTotalQuan();
		for (let s = t.length - 1; s >= 0; s--) {
			if (i >= t[s].rwdOp) {
				e = t[s].rwdNum;
				break
			}
		}
		return e
	}
	isOpenServer() {
		if (!this.srvData)
			return false;
		if (!this.totalData)
			return false;
		return this.srvData.activityId > 0 && this.totalData.activityId > 0
	}
	checkDot() {
		let e = false;
		if (this.checkOpen()) {
			let t = this.numbers;
			if (t.length > this.numberNum) {
				e = true
			}
		}
		cd.setDot(dd.LUCKY_BAG_ENTER, this, e);
		cd.setDot(dd.ACT_FOLD2, this, e);
		cd.setDot(dd.LUCKY_BAG_NUM_ENTER, this, e && this.numbers.length > 0);
		cd.setDot(dd.CITY_ENTER, this, e)
	}
	checkMainBtn() {
		if (this.checkOpen()) {
			FM.mainCityMan.setTopBtnOpen(bb.LUCKYBAG, this, true);
			let e = this.actTpl;
			if (e) {
				let t = b_.getActTimeByStr(e.endTime).getTime() - this.data.serverTime;
				if (t > 0) {
					vg.start(t, this, this.timerFun, 1, null)
				}
			}
		} else {
			FM.mainCityMan.setTopBtnOpen(bb.LUCKYBAG, this, false)
		}
	}
	timerFun(e, t) {
		let i;
		if (e >= b_.ONEDAYMILLISECONDS) {
			i = b_.getDayHourStr(e)
		} else {
			i = b_.getCdTimeStrByMs(e)
		}
		FM.mainCityMan.showActCdTime(Rb.LUCKYBAG, i)
	}
}
