		this.ease = t.ease || mS.easeNone;
		this.comHandler = t.complete;
		this.props = [];
		mS.insArr.push(this);
		if (e.destroyed) {
			this.clear();
			return
		}
		for (let s in t) {
			if (typeof e[s] == "number") {
				let i = e[s];
				let a = t[s];
				this.props.push([s, i, a])
			}
		}
		this.progress = 0;
		this.calcStartTime();
