		if (this.target.destroyed) {
			mS.clearTarget(this.target);
			return
		}
		this.progress = (Laya.Browser.now() - this.startTime) / (this.duration / mS.playRate);
		if (this.progress >= 1) {
			this.complete();
			return
		}
		let e = this.progress * this.duration;
		let t = e > 0 ? this.ease(e, 0, 1, this.duration) : 0;
		let i = this.props;
		for (let s = 0; s < this.props.length; s++) {
			let e = i[s];
			this.target[e[0]] = e[1] + t * (e[2] - e[1])
		}
