			if (t.team == 1) {
				s += i.closeAttackDis
			} else {
				s -= i.closeAttackDis
			}
			Laya.Tween.to(e, {
				x: s,
				y: a
			}, VE.MOVE_TIME, null, Laya.Handler.create(this, this.hitMotion, [i, e, t]))
