class BS extends g {
	constructor() {
		super("ArtifactSeal");
		this.openTid = 1
	}
	static getIns() {
		if (!this._ins) {
			this._ins = new BS
		}
		return this._ins
	}
	onClick(e) {
		switch (e.target) {
		case this._ui.btnClose:
			this.closeUI();
			break;
		case this._ui.btnUse:
			if (this.subAndAdd.nowNum > 0) {
				FM.artifactMan.upSealArtifact(this.openTid, this.subAndAdd.nowNum)
			}
			this.closeUI();
			break;
		case this._ui.btnTotal:
			OS.getIns().show(this.openTid);
			break
		}
	}
	initUI() {
		this._ui = this.uiView;
		this._ui.useNum.style.color = "#683f12";
		this._ui.useNum.style.fontSize = 24;
		this._ui.useNum.style.align = "center";
		this._ui.useNum.style.width = 600;
		this._ui.useNum.style.bold = true;
		this.subAndAdd = this._ui.subAndAdd;
		this.setLayer(1, 1, 1, 1)
	}
	openTidSeal(e) {
		this.openTid = e;
		this.openUI()
	}
	afterOpen() {
		let e = __.getArtifactById(this.openTid);
		let t = od.getTplInfo(nd.ARTIFACT_SEAL, e.level);
		Tb.addItemGrid({
			tid: od.getGlobalValue(3004),
			type: c.PROP
		}, this._ui.shenYIngIcon);
		let i = t.propNumLimit - e.sealNum;
		i = Math.min(this.data.bag.prop.getNum(od.getGlobalValue(3004)), i);
		let s = {};
		s.maxNum = i;
		s.nowNum = s.maxNum;
		s.callBack = this.subAndAddCall;
		s.caller = this;
		this.subAndAdd.dataSource = s;
		this.subAndAddCall()
	}
	subAndAddCall() {
		this._ui.propNum.text = this.data.bag.prop.getNum(od.getGlobalValue(3004)) + "/" + this.subAndAdd.nowNum;
		let e = __.getArtifactById(this.openTid);
		let t = od.getTplInfo(nd.ARTIFACT_SEAL, e.level);
		let i = od.getTplInfo(nd.ARTIFACT_SEAL, e.level + 1);
		let s = od.getGlobalValue(3400, 1);
		let a = n_.splitStr2Arr(s);
		for (let l = 0; l < a.length; l++) {
			let t = this._ui["attr" + l];
			let i = t.getChildByName("imgType");
			let s = t.getChildByName("labAttr");
			let r = t.getChildByName("labAdd");
			let h = a[l];
			i.skin = n_.toSkin(a[l].type);
			s.text = n_.toName(h.type) + ":" + n_.toStr(h.type, h.value * e.sealNum);
			if (this.subAndAdd.nowNum) {
				r.text = "+" + n_.toStr(h.type, h.value * this.subAndAdd.nowNum)
			} else {
				r.text = ""
			}
			r.x = s.x + s.textField.textWidth
		}
		let r = "Trước mắt đã sử dụng:" + e.sealNum + (this.subAndAdd.nowNum ? WM.getHtmlByColor("+" + this.subAndAdd.nowNum, m.NORMAL_GREEN) : "") + "/" + t.propNumLimit;
		if (i) {
			r += WM.getHtmlSpace(2) + "Cấp tiếp theo pháp bảo +" + (i.propNumLimit - t.propNumLimit) + "Hạn mức cao nhất"
		}
		this._ui.useNum.innerHTML = r
	}
}
