	fragSort(e, t) {
		var i = e.num >= e.fragTpl.cost ? 1 : 0;
		var s = t.num >= t.fragTpl.cost ? 1 : 0;
		if (i != s) {
			return s - i
		} else {
			if (e.fragTpl.star != t.fragTpl.star) {
				return t.fragTpl.star - e.fragTpl.star
			} else {
				let i = e.fragTpl.camp ? e.fragTpl.camp : 6;
				let s = t.fragTpl.camp ? t.fragTpl.camp : 6;
				if (i != s) {
					return i - s
				} else {
					return t.baseTpl.id - e.baseTpl.id
				}
			}
		}
	}
