	mingGeSort(e, t) {
		if (e.baseTpl.power != t.baseTpl.power) {
			return t.baseTpl.power - e.baseTpl.power
		} else {
			if (e.baseTpl.quality != t.baseTpl.quality) {
				return t.baseTpl.quality - e.baseTpl.quality
			} else {
				if (e.baseTpl.id != t.baseTpl.id) {
					return e.baseTpl.id - t.baseTpl.id
				} else {
					let i = e.level;
					if (e.shareLevel > 0) {
						i = e.shareLevel
					}
					let s = t.level;
					if (t.shareLevel > 0) {
						s = t.shareLevel
					}
					if (i != s) {
						return s - i
					} else {
						if (e._idHex < t._idHex) {
							return -1
						} else {
							return 1
						}
					}
				}
			}
		}
	}
