	freshFairyList() {
		if (!this.isOpen)
			return;
		if (this._itemType != c.FAIRY)
			return;
		this._ui.listFairy.visible = false;
		this._ui.panelJobFairy.visible = false;
		this._ui.boxFairyFarg.visible = false;
		let e;
		switch (this._ui.tabFairy.selectedIndex) {
		case 0:
			e = this.data.bag.fairy.list.concat([]);
			e = this.data.bag.fairyFrag.list.concat(e);
			this._ui.listFairy.visible = true;
			e.sort(this.fairySort);
			this.alignShowList(e);
			this._ui.listFairy.array = e;
			this._ui.listFairy.showEffect(this, this.compelteFun, 15, 5, 1, VS.SCALE);
			break;
		case 1:
			e = this.getFairyListType(1);
			this._ui.listFairy.visible = true;
			e.sort(this.fairySort);
			this.alignShowList(e);
			this._ui.listFairy.array = e;
			this._ui.listFairy.showEffect(this, this.compelteFun, 15, 5, 1, VS.SCALE);
			break;
		case 2:
			e = this.getFairyListType(2);
			this._ui.listFairy.visible = true;
			e.sort(this.fairySort);
			this.alignShowList(e);
			this._ui.listFairy.array = e;
			this._ui.listFairy.showEffect(this, this.compelteFun, 15, 5, 1, VS.SCALE);
			break;
		case 3:
			e = this.getFairyMaxLvList();
			this._ui.boxFairyFarg.visible = true;
			this._ui.listFairyFarg.array = e;
			break;
		case 4:
			this.isCanJobFairyAcitve = true;
			this._ui.panelJobFairy.visible = true;
			this._ui.boxJob1.dataSource = T_.J1;
			this._ui.boxJob2.dataSource = T_.J2;
			this._ui.boxJob3.dataSource = T_.J3;
			this._ui.boxJob4.dataSource = T_.J4;
			let t = 0;
			this._ui.boxJob1.y = t;
			t += this._ui.boxJob1.getUseHeight();
			this._ui.boxJob2.y = t;
			t += this._ui.boxJob2.getUseHeight();
			this._ui.boxJob3.y = t;
			t += this._ui.boxJob3.getUseHeight();
			this._ui.boxJob4.y = t;
			t += this._ui.boxJob4.getUseHeight();
			this._ui.boxJobFairy.height = t + 5;
			break
		}
		this.openNum++;
		this.checkFairyDot();
		this.checkJobFairyDot()
	}
	getFairyListType(e) {
		let t = this.data.bag.fairy.list;
		let i = [];
		for (let s = 0; s < t.length; s++) {
			if (t[s].baseTpl.type == e) {
				i.push(t[s])
			}
		}
		return i
	}
	getFairyMaxLvList() {
		if (!this._showFairyMaxLvs) {
			this._showFairyMaxLvs = [];
			let e = od.getTplInfo(nd.FAIRY);
			let t;
			for (let i = 0; i < e.length; i++) {
				if (t != e[i].protoId) {
					let s = {};
					t = e[i].protoId;
					s.id = e[i].id;
					s.tpl = e[i];
					if (this._showFairyMaxLvs.length > 0 && i > 0) {
						this._showFairyMaxLvs[this._showFairyMaxLvs.length - 1].maxTpl = e[i - 1]
					}
					this._showFairyMaxLvs.push(s)
				}
			}
			this._showFairyMaxLvs[this._showFairyMaxLvs.length - 1].maxTpl = e[e.length - 1];
			this._showFairyMaxLvs.sort(this.fairyMaxSort)
		}
		return this._showFairyMaxLvs
	}
	fairyMaxSort(e, t) {
		return e.tpl.sort - t.tpl.sort
	}
	fairySort(e, t) {
		if (e.type != t.type) {
			return e.type - t.type
		} else {
			if (e.type == c.FAIRY) {
				if (e.baseTpl.protoId != t.baseTpl.protoId) {
					return e.baseTpl.sort - t.baseTpl.sort
				} else {
					return t.baseTpl.level - e.baseTpl.level
				}
			} else {
				if (FM.bagMan.isFairyFragOK[e.baseTpl.fairyId] && !FM.bagMan.isFairyFragOK[t.baseTpl.fairyId]) {
					return -1
				} else if (!FM.bagMan.isFairyFragOK[e.baseTpl.fairyId] && FM.bagMan.isFairyFragOK[t.baseTpl.fairyId]) {
					return 1
				} else {
					if (e.baseTpl.fairyId == t.baseTpl.fairyId) {
						return e.tid - t.tid
					} else {
						let i = od.getTplInfo(nd.FAIRY, e.baseTpl.fairyId);
						let s = od.getTplInfo(nd.FAIRY, t.baseTpl.fairyId);
						return i.sort - s.sort
					}
				}
			}
		}
	}
	isFairyFragOK(e) {
		return this.recordFairyFragObj[e]
	}
	isHasFairyFragOK() {
		for (let e in this.recordFairyFragObj) {
			if (this.recordFairyFragObj[e])
				return true
		}
		return false
	}
	checkFairyDot(e = true) {
		if (e) {
			this.refreshRecordObj()
		}
		let t = false;
		for (let r in this.recordFairyFragObj) {
			if (this.recordFairyFragObj[r] >= this.openNum) {
				t = true;
				break
			}
		}
		let i = false;
		let s = od.getTplInfo(nd.JOB_FAIRY, null, {
				level: 1
			});
		let a = [];
		if (this.data.bag.jobFairy && this.data.bag.jobFairy.list)
			a = this.data.bag.jobFairy.list;
		if (a) {
			for (let e = 0; e < s.length; e++) {
				const t = s[e];
				let r = false;
				for (let e = 0; e < a.length; e++) {
					const i = a[e];
					if (i.porotId == t.protoId) {
						r = true
					}
				}
				if (!r) {
					if (cP.checkEnough(t.activeStarCost)) {
						i = true;
						break
					}
				}
			}
			for (let e = 0; e < s.length; e++) {
				const t = s[e];
				let r = false;
				for (let e = 0; e < a.length; e++) {
					const s = a[e];
					if (s.porotId == t.protoId) {
						if (s && Hm.getIns().isCanCostEnough(s)) {
							i = true;
							break
						}
					}
				}
			}
		}
		cd.setDot(dd.BAG_JOB_FAIRY_ACT_TAB, this, i);
		cd.setDot(dd.BAG_FAIRY_TAB, this, t || i);
		cd.setDot(dd.BAG_ENTER, dd.BAG_FAIRY_TAB, t || i)
	}
