class _L {
	static push(e, t, i, s, a = 120) {
		let r = this.flyWordDic[i];
		if (!r) {
			r = {};
			this.flyWordDic[i] = r
		}
		let l = r[s];
		if (!l) {
			l = {};
			l.list = [];
			r[s] = l
		}
		l.list.push({
			flyWord: e,
			ctn: t,
			pid: i,
			type: s,
			delayTime: a
		});
		this.checkNext(i, s)
	}
	static checkNext(e, t) {
		let i = this.flyWordDic[e];
		if (!i)
			return;
		let s = i[t];
		if (!s)
			return;
		if (!s.list || !s.list.length)
			return;
		if (s.delay)
			return;
		s.delay = true;
		let a = s.list.shift();
		let r = a.ctn;
		let l = a.flyWord;
		r.addChild(l);
		l.start();
		mS.to(this, {
			complete: Laya.Handler.create(this, this.delayEnd, [e, t])
		}, a.delayTime)
	}
	static delayEnd(e, t) {
		let i = this.flyWordDic[e];
		if (!i)
			return;
		let s = i[t];
		if (!s)
			return;
		s.delay = false;
		this.checkNext(e, t)
	}
	static clear() {
		this.flyWordDic = {}
	}
}
