class tA {
	static set bodhiTreeData(e) {
		this._bodhiTreeData = e
	}
	static get bodhiTreeData() {
		return this._bodhiTreeData
	}
	static get fruits() {
		if (!this._bodhiTreeData.fruits)
			return {};
		return this._bodhiTreeData.fruits
	}
	static get level() {
		if (!this._bodhiTreeData.level)
			return 1;
		return this._bodhiTreeData.level
	}
	static get isMaxLv() {
		return this.level == 4
	}
	static get exp() {
		if (!this._bodhiTreeData.exp)
			return 0;
		return this._bodhiTreeData.exp
	}
	static isFreeWater() {
		return this._bodhiTreeData.freeWater < od.getGlobalValue(26001)
	}
	static waterTimes() {
		return od.getGlobalValue(26001) + od.getGlobalValue(26002) - this._bodhiTreeData.freeWater - this._bodhiTreeData.payWater
	}
	static isFreeFertilize() {
		return this._bodhiTreeData.freeFertilize < od.getGlobalValue(26005)
	}
	static fertilizeTimes() {
		return od.getGlobalValue(26005) + od.getGlobalValue(26006) - this._bodhiTreeData.freeFertilize - this._bodhiTreeData.payFertilize
	}
	static getFruitData(e) {
		if (!this._bodhiTreeData.fruits)
			return {};
		return this._bodhiTreeData.fruits[e]
	}
	static isDot() {
		if (!this._bodhiTreeData.fruits)
			return false;
		if (this.isFreeWater())
			return true;
		if (!this.isMaxLv && this.isFreeFertilize())
			return true;
		for (let e in this._bodhiTreeData.fruits) {
			if (this.isDotPos(Number(e))) {
				return true
			}
		}
		return false
	}
	static isDotPos(e) {
		let t = this._bodhiTreeData.fruits[e];
		return b_.getTimeStamp() >= t.harvestTime
	}
}
