class aA extends g {
	constructor() {
		super("BottomBar");
		this.funcInit = false;
		this.showStates = []
	}
	getCmds() {
		return [d.FUNC_INIT, d.FUNC_OPEN]
	}
	exeCmd(e, t) {
		switch (t) {
		case d.FUNC_INIT:
			this.funcInit = true;
			this.checkFuncOpen();
			break;
		case d.FUNC_OPEN:
			this.checkFuncOpen(e);
			break
		}
	}
	onClick(e) {
		switch (e.target) {
		case this._ui.btnMainCity:
			FM.mainCityMan.openUI();
			a_.playSound("se_uiopen_click.wav");
			break;
		case this._ui.btnHero:
			FM.heroMan.openByType(0);
			a_.playSound("se_uiopen_click.wav");
			break;
		case this._ui.btnBag:
			FM.bagMan.openByType(c.PROP);
			a_.playSound("se_uiopen_click.wav");
			break;
		case this._ui.btnAdventure:
			FM.adventureMan.openUI();
			a_.playSound("se_uiopen_click.wav");
			this._ui.boxHangRwd.visible = false;
			break;
		case this._ui.btnExper:
			FM.liLianMan.openUI();
			a_.playSound("se_uiopen_click.wav");
			break;
		case this._ui.btnGuild:
			HT.open();
			a_.playSound("se_uiopen_click.wav");
			break;
		case this._ui.btnArtifact:
			FM.artifactMan.openUiTid();
			a_.playSound("se_uiopen_click.wav");
			break
		}
	}
	initUI() {
		this._ui = this.uiView;
		this.setLayer(1, 2);
		this._ui.boxHangRwd.visible = false;
		this._ui.tabEnter.checkHandler = Laya.Handler.create(this, this.checkTab, null, false);
		cd.regDot(dd.CITY_ENTER, this._ui.dotCity);
		cd.regDot(dd.HERO_ENTER, this._ui.dotHero);
		cd.regDot(dd.BAG_ENTER, this._ui.dotBag);
		cd.regDot(dd.ADVENTURE_ENTER, this._ui.dotAdventure);
		cd.regDot(dd.LI_LIAN_ENTER, this._ui.dotExper);
		cd.regDot(dd.GUILD_ENTER, this._ui.dotGuild);
		cd.regDot(dd.ARTIFACT_ENTER, this._ui.dotArtifact);
		N_.addEffect("portal", this._ui.btnAdventure, false);
		this.funcReg()
	}
	afterOpen() {}
	selectEnter(e) {
		if (!this._ui)
			return;
		this._ui.tabEnter.selectedIndex = e;
		for (let t = 0; ; t++) {
			let i = this._ui.tabEnter.getChildByName("item" + t);
			if (!i)
				break;
			if (e == t) {
				i.y = -10
			} else {
				i.y = 0
			}
		}
	}
	checkTab(e) {
		switch (e) {
		case 3:
			return FM.funcMan.checkFuncOpen(pd.DAILY_FB, false);
			break;
		case 4:
			return FM.funcMan.checkFuncOpen(pd.GUILD, false);
			break;
		case 5:
			return FM.funcMan.checkFuncOpen(pd.ARTIFACT, false);
			break
		}
		return true
	}
	funcReg() {
		this.funcArr = [];
		this.funcArr.push({
			funcId: pd.DAILY_FB,
			target: this._ui.btnExper
		});
		this.funcArr.push({
			funcId: pd.GUILD,
			target: this._ui.btnGuild
		});
		this.funcArr.push({
			funcId: pd.ARTIFACT,
			target: this._ui.btnArtifact
		});
		this.checkFuncOpen()
	}
	checkFuncOpen(e = 0) {
		if (!this.funcArr)
			return;
		if (!this.funcInit)
			return;
		for (let t = 0; t < this.funcArr.length; t++) {
			let i = this.funcArr[t];
			if (e == 0 || e == i.funcId) {
				let e = i.target;
				if (FM.funcMan.checkFuncOpen(i.funcId, false)) {
					let t = e.getChildByName("labOpen");
					if (t) {
						t.removeSelf()
					}
				} else {
					let t = new Laya.Label;
					t.name = "labOpen";
					t.stroke = 4;
					t.color = "#f9f3e3";
					t.text = FM.funcMan.getOpenTip(i.funcId);
					t.x = (e.width - t.textField.textWidth) / 2;
					t.y = 40;
					e.addChild(t)
				}
			}
		}
	}
	showHangRwdTip() {
		if (!this.isOpen)
			return;
		this._ui.boxHangRwd.visible = true
	}
	regShowState(e, t) {
		for (let i = 0; i < this.showStates.length; i++) {
			let t = this.showStates[i];
			if (t.caller == e) {
				this.showStates.splice(i, 1);
				break
			}
		}
		this.showStates.push({
			caller: e,
			show: t
		});
		this.updateShowState()
	}
	unregShowState(e) {
		for (let t = 0; t < this.showStates.length; t++) {
			let i = this.showStates[t];
			if (i.caller == e) {
				this.showStates.splice(t, 1);
				break
			}
		}
		this.updateShowState()
	}
	updateShowState() {
		if (this.showStates.length) {
			if (this.showStates[this.showStates.length - 1].show) {
				this.openUI()
			} else {
				this.closeUI()
			}
		} else {
			this.openUI()
		}
	}
}
