class oA extends g {
	constructor() {
		super("Champion");
		this.nowIndex = 0
	}
	getCmds() {
		return [d.ITEM_CHANGE_NUM]
	}
	exeCmd(e, t) {
		switch (t) {
		case d.ITEM_CHANGE_NUM:
			if (this.isOpen && this._ui.tabType.selectedIndex == 0) {
				this.refreshFightMoney()
			}
			break
		}
	}
	getMsgs() {
		return [Rp.ARENA_RANK_REC]
	}
	exeMsg(e, t) {
		switch (t) {
		case Rp.ARENA_RANK_REC:
			if (this.isOpen) {
				this._ui.rankLab0.text = String(RS.rank)
			}
			break
		}
	}
	onClick(e) {
		switch (e.target) {
		case this._ui.btnClose:
			this.closeUI();
			break;
		case this._ui.btnTips:
			if (this._ui.tabType.selectedIndex == 0) {
				rA.getIns().openUI()
			} else {
				nA.getIns().openUI()
			}
			break;
		case this._ui.btnSpace:
			JT.getIns().openTab(2);
			break;
		case this._ui.btnRank:
			lA.getIns().openUI();
			break;
		case this._ui.btnArea:
			FM.arena.openUI();
			break;
		case this._ui.btnChampion:
			FM.championshipsMan.openUI();
			break;
		case this._ui.btnPostion:
			FM.positionMan.openByFuncId(pd.CHAMPION);
			break;
		case this._ui.btnAdd:
			FM.arena.buyFightProp();
			break
		}
	}
	initUI() {
		this._ui = this.uiView;
		this.setLayer(0, 1, 0, 2);
		this._ui.tabType.selectHandler = Laya.Handler.create(this, this.typeSelect, null, false);
		cd.regDot(dd.CHAM_ARENA_ENTER, this._ui.dotArea);
		cd.regDot(dd.CHAM_CHAMPION_ENTER, this._ui.dotChampion)
	}
	openTabUi(e = -1) {
		if (e != -1) {
			this.nowIndex = e
		} else {
			if (gC.round != gC.R0) {
				this.nowIndex = 1
			}
		}
		this.openUI()
	}
	checkOpen() {
		return FM.funcMan.checkFuncOpen(pd.ARENA)
	}
	afterOpen() {
		this._ui.tabType.selectedIndex = -1;
		this._ui.tabType.selectedIndex = this.nowIndex;
		this._ui.admiredTimesLab.text = String(RS.admiredTimes);
		this.nowIndex = 0;
		this.checkSettle()
	}
	afterClose() {
		vg.stop(this, this.cdTimeFun0)
	}
	typeSelect(e) {
		this.hideAllBox();
		switch (e) {
		case 0:
			this.showArenaBox();
			break;
		case 1:
			this.showChampionBox();
			break
		}
	}
	hideAllBox() {
		this._ui.detailBox0.visible = false;
		this._ui.detailBox1.visible = false;
		this._ui.titleTag0.visible = this._ui.titleTag1.visible = false;
		this._ui.btnRank.visible = false;
		this._ui.btnPostion.visible = false;
		this._ui.btnArea.visible = this._ui.btnChampion.visible = false;
		vg.stop(this, this.cdTimeFun0)
	}
	showArenaBox() {
		this._ui.detailBox0.visible = true;
		this._ui.titleTag0.visible = true;
		this._ui.btnArea.visible = true;
		this._ui.pointLab0.text = String(RS.points);
		this._ui.rankLab0.text = String(RS.rank);
		this.refreshFightMoney();
		let e = b_.getWeekStartTimeStamp();
		let t = b_.getWeekEndTimeStamp() - 1;
		this._ui.timeTip0.text = b_.getTimeStmapStr(e, "[MM].[DD]") + "-" + b_.getTimeStmapStr(t, "[MM].[DD]");
		vg.start(t - b_.getTimeStamp(), this, this.cdTimeFun0);
		this._ui.topShowBox.showFuncId(pd.ARENA, 0)
	}
	cdTimeFun0(e, t) {
		if (t) {
			Laya.timer.once(500, this, this.refreshshowArenaBox)
		} else {
			this._ui.timeLeft0.text = WM.getLanCodeTip(20331, [b_.getCdTimeStrByMs(e, WM.getLanCodeTip(10640))])
		}
	}
	refreshshowArenaBox() {
		if (this.isOpen && this._ui.tabType.selectedIndex == 0) {
			this.showArenaBox()
		}
	}
	refreshFightMoney() {
		let e = this.data.bag.prop.getNum(od.getGlobalValue(5004));
		this._ui.propNumLab0.text = WM.num2Str(e)
	}
	showChampionBox() {
		this._ui.detailBox1.visible = true;
		this._ui.titleTag1.visible = true;
		this._ui.btnRank.visible = true;
		this._ui.btnPostion.visible = true;
		this._ui.btnChampion.visible = true;
		this._ui.roundTipLab.text = gC.roundTip;
		let e = gC.rank;
		let t = b_.getTimeStamp();
		if (t < gC.openTime) {
			this._ui.rankLab1.text = WM.getLanCodeTip(10124)
		} else {
			this._ui.rankLab1.text = e < 0 ? WM.getLanCodeTip(10124) : String(e + 1)
		}
		let i = gC.topRank;
		this._ui.rankHistory1.text = i < 0 ? WM.getLanCodeTip(10124) : String(i + 1);
		this._ui.roundTipLab.text = gC.roundTip;
		let s = gC.openTime;
		let a = gC.overTime;
		this._ui.timeTip1.text = b_.getTimeStmapStr(s, "[MM].[DD]") + "-" + b_.getTimeStmapStr(a, "[MM].[DD]");
		let r = s - t;
		if (r < 0) {
			r = a - t
		}
		vg.start(r, this, this.cdTimeFun1);
		this._ui.topShowBox.showFuncId(pd.CHAMPION, 1)
	}
	cdTimeFun1(e, t) {
		if (t) {
			Laya.timer.once(500, this, this.refreshShowChampionBox)
		} else {
			this._ui.timeLeft1.text = WM.getLanCodeTip(20331, [b_.getCdTimeStrByMs(e, WM.getLanCodeTip(10640))])
		}
	}
	refreshShowChampionBox() {
		if (this.isOpen && this._ui.tabType.selectedIndex == 1) {
			this.showChampionBox()
		}
	}
	checkSettle() {
		let e = gC.seasonResult;
		if (!e || !e.season)
			return;
		let t = this.data.master.readNoteBook("championSettle");
		if (t && t >= e.season)
			return;
		hA.getIns().openUI();
		this.data.master.writeNoteBook("championSettle", e.season)
	}
}
