			i = [n_.ATK, n_.HP, n_.DEF, n_.SPD, n_.CRT, n_.CRT_R, n_.CRT_P, n_.BE_STRIKE_IGN, n_.CTR, n_.CTR_R, n_.HIT, n_.EVA, n_.DMG_P, n_.DMG_R, n_.HEAL, n_.HEAL_P, n_.PHY_P, n_.PHY_R, n_.MAG_P, n_.MAG_R, n_.DEF_IGN];
			t[n_.CRT_P] = t[n_.CRT_P] ? t[n_.CRT_P] + 15e3 : 15e3;
			t[n_.HIT] = t[n_.HIT] ? t[n_.HIT] + 1e4 : 1e4;
			n_.positiveAttr(t)
