class yA extends g {
	constructor() {
		super("Collectgift3")
	}
	static getIns() {
		if (!this._ins) {
			this._ins = new yA
		}
		return this._ins
	}
	getMsgs() {
		return [Dd.COLLECT_DATA_REC]
	}
	exeMsg(e, t) {
		switch (t) {
		case Dd.COLLECT_DATA_REC:
			if (this.isOpen) {
				this.updateInfo()
			}
			break
		}
	}
	onClick(e) {
		switch (e.target) {
		case this._ui.btnClose:
			this.closeUI();
			break
		}
	}
	initUI() {
		this._ui = this.uiView;
		this.setLayer(1, 1, 1, 1)
	}
	showDetail(e = false) {
		this._isHunDun = e;
		this.openUI()
	}
	afterOpen() {
		let e = [];
		let t = 0;
		if (this._isHunDun) {
			t = 1
		}
		let i = od.getTplInfo(nd.COLLECT_PRIZE, null, {
				isHD: t
			});
		let s = Math.min(10, i.length);
		for (let a = 0; a < s; a++) {
			e[a] = {};
			e[a].num = i[a].times;
			if (this._ui["rwdBox" + a]) {
				e[a].x = this._ui["timesBox" + a].x;
				let t = this._ui["rwdBox" + a].getChildByName("numTxt");
				t.text = String(i[a].times)
			}
		}
		this._ui.timesPro["data"] = e;
		this.updateInfo()
	}
	updateInfo() {
		let e = FM.collectCallMan.getCurCallTime();
		if (this._isHunDun) {
			e = FM.collectCallMan.getCurCallTime2()
		}
		this._ui.timesPro.value = e;
		this._ui.callTimeLab.text = String(e);
		let t = 0;
		if (this._isHunDun) {
			t = 1
		}
		let i = od.getTplInfo(nd.COLLECT_PRIZE, null, {
				isHD: t
			});
		for (let s = 0; s < i.length; s++) {
			if (this._ui["rwdBox" + s]) {
				let e = {
					item: i[s],
					isHunDun: this._isHunDun
				};
				this._ui["rwdBox" + s].dataSource = e
			}
		}
	}
}
