		this._ui.labCityPrize.style.width = this._ui.labCityPrize.width;
		this._ui.labCityPrize.style.bold = true;
		this._ui.labCityPrize.style.color = "#65fe36";
		this._ui.labCityPrizeExt.style.width = this._ui.labCityPrizeExt.width;
		this._ui.labCityPrizeExt.style.bold = true;
		this._ui.labCityPrizeExt.style.color = "#65fe36";
		this._ui.boxMap.on(Laya.Event.MOUSE_DOWN, this, this.boxMapIn);
		this._ui.boxMap.on(Laya.Event.DRAG_MOVE, this, this.boxMapMove);
