class XA extends g {
	constructor() {
		super("laohujishop")
	}
	static getIns() {
		if (!this._ins) {
			this._ins = new XA
		}
		return this._ins
	}
	getMsgs() {
		return [Xf.DATA_REC]
	}
	exeMsg(e, t) {
		switch (t) {
		case Xf.DATA_REC:
			this.dataRec(e);
			break
		}
	}
	getCmds() {
		return [d.ITEM_CHANGE_NUM]
	}
	exeCmd(e, t) {
		switch (t) {
		case d.ITEM_CHANGE_NUM:
			if (!this.isOpen)
				return;
			this.refreshMoney();
			break
		}
	}
	onClick(e) {
		switch (e.target) {
		case this._ui.btnClose:
			this.closeUI();
			break
		}
	}
	initUI() {
		this._ui = this.uiView;
		this.setLayer(1, 1, 1, 1);
		this._ui.typeTab.selectHandler = Laya.Handler.create(this, this.typeSelect, null, false)
	}
	show(e) {
		this._data = e;
		if (!this._data)
			return;
		if (!this._data.openStoreList)
			this._data.openStoreList = [1];
		this.openUI()
	}
	dataRec(e) {
		if (!this.isOpen)
			return;
		this._data = e.data.mall;
		this.showShopData(this._ui.typeTab.selectedIndex + 1)
	}
	afterOpen() {
		this._ui.typeTab.selectedIndex = -1;
		this._ui.typeTab.selectedIndex = 0;
		this._ui.lock1.visible = this._data.openStoreList.indexOf(2) == -1;
		this._ui.lock2.visible = this._data.openStoreList.indexOf(3) == -1
	}
	typeSelect(e) {
		if (e < 0)
			return;
		this.showShopData(e + 1);
		this._ui.propList.tweenTo(0);
		this._ui.boxTimes.visible = false;
		switch (e) {
		case 0:
			this._ui.moneyBox.visible = true;
			break;
		case 1:
			if (this._ui.lock1.visible) {
				this._ui.boxTimes.visible = true;
				let e = od.getTplInfo(nd.CP_WAKE_SHOP, 2);
				let t = e.times - FM.cpWeakMan.totalSeizeTimes;
				if (t < 0)
					t = 0;
				this._ui.labLeftTimes.text = t + " lần"
			}
			break;
		case 2:
			if (this._ui.lock2.visible) {
				this._ui.boxTimes.visible = true;
				let e = od.getTplInfo(nd.CP_WAKE_SHOP, 3);
				let t = e.times - FM.cpWeakMan.totalSeizeTimes;
				if (t < 0)
					t = 0;
				this._ui.labLeftTimes.text = t + " lần"
			}
			break
		}
		this.refreshMoney()
	}
	refreshMoney() {
		if (!this.isOpen)
			return;
		if (this._ui.moneyBox.visible) {
			this._ui.moneyBox.dataSource = X_.getTypeData({
					type: 3,
					tid: 590009,
					num: this.data.bag.prop.getNum(590009)
				}, false)
		}
	}
	refreshTime(e) {
		if (!e || !this.isOpen)
			return;
		this._ui.labTime.text = e
	}
	showShopData(e) {
		let t = this._data.storeMap[e].itemList;
		let i = [];
		for (let s in t) {
			this.setTpl(t[s]);
			i.push(t[s])
		}
		i.sort(this.sortFun);
		this._ui.propList.array = i;
		this._ui.propList.scrollTo(0)
	}
	setTpl(e) {
		if (!e.tpl && e.tid) {
			e.tpl = od.getTplInfo(nd.CP_WAKE_GOODS, e.tid)
		}
	}
	sortFun(e, t) {
		if (e.tpl.limitNum - e.purchaseNum > 0 && t.tpl.limitNum - t.purchaseNum <= 0) {
			return -1
		} else if (e.tpl.limitNum - e.purchaseNum <= 0 && t.tpl.limitNum - t.purchaseNum > 0) {
			return 1
		}
		return e.tpl.id - t.tpl.id
	}
}
