		if (!this.srvData)
			return;
		if (!this.srvData.rankList)
			return;
		let e = this.srvData.rankList;
		if (!e)
			return;
		for (let t = 0; t < 3; t++) {
			let i = this._ui["rank" + t];
			let s = i.getChildByName("labName");
			let a = i.getChildByName("labTier");
			if (e[t]) {
				let i = jg.getPlayerData(e[t].owner);
				s.text = i.zoneIndexName + i.name;
				a.text = WM.num2Str(Math.round(e[t].value)) + "Long châu"
			} else {
				s.text = WM.getLanCodeTip(10030);
				a.text = ""
			}
		}
