		if (!this.srvData.rankList)
			return;
		let e = this.srvData.rankList;
		if (!e)
			return;
		for (let t = 0; t < 3; t++) {
			let i = this._ui["rank" + t];
			let s = i.getChildByName("labName");
			let a = i.getChildByName("labTier");
			if (e[t]) {
				s.text = e[t].owner.profile.name;
				a.text = WM.num2Str(Math.round(e[t].value)) + " VNĐ"
			} else {
				s.text = WM.getLanCodeTip(10030);
				a.text = ""
			}
		}
		this._ui.hurtRwdList.array = cP.splitStr2Arr(this.actTplBase.prize);
		this._ui.myNum.text = "0";
		if (this.srvData && this.srvData.my && this.srvData.my.value != null) {
			this._ui.myNum.text = this.srvData.my.value
		}
