			let l = a[r];
			this._ui.enemyLevelName.text = l.levelName;
			this._ui.enemyLevelImg.skin = "img/Areanlevel/level" + l.iconImage + ".png";
			this._ui.enemyZX.skin = "img/zhandou/ZhenX_" + this._srcmatchData.ps[pd.ARENA_LEVEL].positionTid + ".png";
			this._ui.enmyHeroList.array = [];
