class BD extends g {
	constructor() {
		super("ShopBuy")
	}
	static getIns() {
		if (!this._ins) {
			this._ins = new BD
		}
		return this._ins
	}
	onClick(e) {
		switch (e.target) {
		case this._ui.btnBuy:
			this.sureBuy();
			this.closeUI();
			break;
		case this._ui.btnCancel:
			this.closeUI();
			break;
		case this._ui.btnClose:
			this.closeUI();
			break
		}
	}
	initUI() {
		this._ui = this.uiView;
		this.setLayer(1, 1, 1, 1);
		this.subAndAdd = this._ui.subAndAdd
	}
	showBuyDetail(e, t = 0, i = 1, s = "shop") {
		this._info = e;
		this._nowNum = i;
		this._openType = s;
		this._type = t;
		this.openUI()
	}
	getMaxNumByObj(e) {
		let t = od.getTplInfo(nd.ARENA_LEVEL_SHOP, e.tid);
		let i = cP.splitStr2Arr(t.moneyType)[0];
		let s = KM.toTypeTidValue(i.type, i.tid);
		let a = Math.floor(s / i.num);
		if (t.limitTimes && t.limitTimes > 0) {
			return Math.min(a, t.limitTimes - e.purchaseNum)
		}
		return a
	}
	afterOpen() {
		let e = {};
		e.nowNum = this._nowNum;
		e.maxNum = this.getMaxNumByObj(this._info);
		e.callBack = this.updateInfo;
		e.caller = this;
		this.subAndAdd.dataSource = e
	}
	updateInfo() {
		let e = od.getTplInfo(nd.ARENA_LEVEL_SHOP, this._info.tid);
		let t = Tb.addItemGrid(cP.splitStr2Arr(e.propStr)[0], this._ui.propIcon);
		this._nowNum = this.subAndAdd.nowNum;
		this._ui.propName.text = t.info.baseTpl.name;
		this._ui.propName.color = ud.toColor(t.info.baseTpl.quality);
		let i = cP.splitStr2Arr(e.moneyType);
		this._ui.propMoneyNum.text = WM.num2Str(i[0].num);
		Tb.addWealthGridByInfo(i[0], this._ui.propMoneyIcon);
		if (e.limitTimes && e.limitTimes > 0) {
			this._ui.propLimitInfo.visible = true;
			this._ui.propLimitInfo.text = WM.getLanCodeTip(20002, [e.limitTimes])
		} else {
			this._ui.propLimitInfo.visible = false
		}
		this._ui.buyNumNum.text = String(this._nowNum);
		Tb.addWealthGridByInfo(i[0], this._ui.buyPriceType);
		this._ui.buyPricePrice.text = String(i[0].num * this._nowNum)
	}
	sureBuy() {
		if (this._nowNum == 0)
			return;
		switch (this._openType) {
		case "shop":
			let e = od.getTplInfo(nd.ARENA_LEVEL_SHOP, this._info.tid);
			this.sendMsg(Sd.ARENA_LEVEL_SHOP_BUY_REQ, {
				tid: this._info.tid,
				count: this._nowNum,
				type: this._type
			});
			break
		}
	}
}
class MD extends g {
	constructor() {
		super("ArenaLevelShop")
	}
	static getIns() {
		if (!this._ins) {
			this._ins = new MD
		}
		return this._ins
	}
	getCmds() {
		return [d.ITEM_CHANGE_NUM, d.M1_CHANGE, d.LADDERSORCE_CHANGE]
	}
	exeCmd(e, t) {
		if (!this.isOpen)
			return;
		this.updateMoney()
	}
	getMsgs() {
		return [Sd.ARENA_LEVEL_SHOP_REC]
	}
	exeMsg(e, t) {
		switch (t) {
		case Sd.ARENA_LEVEL_SHOP_REC:
			this.shopData = e.data;
			this.updateInfo();
			this.updateMoney();
			break
		}
	}
	onClick(e) {
		switch (e.target) {
		case this._ui.btnClose:
			this.closeUI();
			break
		}
	}
	initUI() {
		this._ui = this.uiView;
		this.setLayer(1, 1, 1, 1);
		this._ui.propList.mouseHandler = Laya.Handler.create(this, this.onShopClick, null, false);
		this._ui.jiFenTab.selectedIndex = 0;
		this._ui.jiFenTab.selectHandler = Laya.Handler.create(this, this.jiFenTabSelectedFun, null, false)
	}
	jiFenTabSelectedFun() {
		let e = [];
		if (this._ui.jiFenTab.selectedIndex < 0)
			return;
		if (this._ui.jiFenTab.selectedIndex == 0) {
			this.updateInfo()
		} else if (this._ui.jiFenTab.selectedIndex == 1) {
			this.updateInfo()
		}
	}
	afterOpen() {
		this._ui.jiFenTab.selectedIndex = 0;
		this.sendMsg(Sd.ARENA_LEVEL_SHOP_REQ);
		this.updateInfo();
		this._ui.propList.scrollTo(0)
	}
	updateInfo() {
		if (!this.isOpen) {
			return
		}
		let e = this.shopData;
		if (!e)
			return;
		this._ui.jiFenTab.visible = false;
		this._ui.propList.y = 88;
		this._ui.propList.height = 846;
		this._ui.backBlock.y = 76;
		this._ui.backBlock.height = 865;
		if (e.season > 1) {
			this._ui.propList.y = 144;
			this._ui.propList.height = 790;
			this._ui.jiFenTab.visible = true;
			this._ui.backBlock.y = 135;
			this._ui.backBlock.height = 806
		}
		let t;
		let i = [];
		let s = e.itemList;
		if (this._ui.jiFenTab.selectedIndex == 1) {
			s = e.preSeasonItemList
		}
		for (let a = 0; a < s.length; a++) {
			t = od.getTplInfo(nd.ARENA_LEVEL_SHOP, s[a].tid);
			s[a].power = t.power;
			s[a].buyType = this._ui.jiFenTab.selectedIndex;
			i.push(s[a])
		}
		i.sort(this.sortFun);
		this._ui.propList.array = i;
		this.hideAllList();
		this._ui.noAnythingBox.visible = false;
		if (this._ui.propList.array.length <= 0) {
			this._ui.noAnythingBox.visible = true
		}
	}
	hideAllList() {
		this._ui.btnMoneyRefresh.visible = false;
		this._ui.btnFreeRefresh.visible = false;
		this._ui.refreshTime.visible = false;
		this._ui.refreshTimes.visible = false
	}
	sortFun(e, t) {
		return e.power - t.power
	}
	updateMoney() {
		let e = od.getTplInfo(nd.ARENA_LEVEL_SHOP)[0];
		let t = cP.parseItemStr(e.moneyType);
		t.num = KM.toTypeTidValue(t.type, t.tid);
		this._ui.moneyBox1.dataSource = X_.getTypeData(t, false)
	}
	onShopClick(e, t) {
		if (e.type != Laya.Event.CLICK)
			return;
		if (!this._ui.propList.array) {
			return
		}
		let i = this._ui.propList.getItem(t);
		if (this.canShowDetail(i)) {
			BD.getIns().showBuyDetail(i, this._ui.jiFenTab.selectedIndex)
		}
	}
	canShowDetail(e) {
		let t = e.tid;
		let i = od.getTplInfo(nd.ARENA_LEVEL_SHOP, t);
		if (i.limitVip && uP.getIns().master.vip < i.limitVip) {
			FM.noticeMan.showNotice("vip" + i.limitVip + " trở lên có thể mua");
			return
		}
		if (i.limitTimes && i.limitTimes > 0 && e.purchaseNum >= i.limitTimes) {
			FM.noticeMan.showNotice("Đã bán xong");
			return false
		}
		if (!cP.checkEnough(i.moneyType)) {
			let e = cP.parseItemStr(i.moneyType);
			Ng.getIns().showGetInfoDetail(e.tid, e.type);
			return false
		}
		return true
	}
}
