class hx {
	constructor() {
		this.isFirst = false;
		qM.regCmd(d.CLOSE_UI, this, this.exeCmd);
		qM.regCmd(d.OPEN_UI, this, this.exeCmd);
		qM.regMsg(Rd.SHOW_DATA_REC, this, this.exeMsg);
		qM.regMsg(Rd.VIDEO_DATA_REC, this, this.exeMsg)
	}
	static getIns() {
		if (!this._ins) {
			this._ins = new hx
		}
		return this._ins
	}
	exeCmd(e, t) {
		switch (t) {
		case d.CLOSE_UI:
			if (e.uiName == FM.battleMan.uiClass) {
				this.addOverTime()
			}
			break;
		case d.OPEN_UI:
			if (e.uiName == FM.battleMan.uiClass) {
				this.remOverTime()
			}
			break
		}
	}
	exeMsg(e, t) {
		switch (t) {
		case Rd.SHOW_DATA_REC:
			this.showDataRec(e);
			break;
		case Rd.VIDEO_DATA_REC:
			this.videoDataRec(e);
			break
		}
	}
	showArr(e, t, i, s = 1) {
		if (b_.getTimeStamp() > t[t.length - 1].endTime) {
			return false
		}
		this._funcId = e;
		this._data = t;
		this._callBack = i;
		this._type = s;
		this.isFirst = true;
		this.checkWatchBattle();
		return true
	}
	videoDataRec(e) {
		if (!e.live || !e.play || !this._data)
			return;
		for (let t = 0; t < this._data.length; t++) {
			let i = this._data[t];
			if (!i)
				continue;
			if (i.replayIdHex == e.play._idHex) {
				if (this._funcId == pd.PEAK_PVP_KO) {
					e.play.startTime = i.startTime;
					e.play.endTime = i.endTime
				}
				break
			}
		}
		this.play = e.play;
		this.checkWatchBattle()
	}
	showDataRec(e) {
		this.play = e.play;
		this.checkWatchBattle()
	}
	checkWatchBattle() {
		let e = b_.getTimeStamp();
		let t;
		for (let i = 0; i < this._data.length; i++) {
			if (this._data[i].endTime > e && !this._data[i].hasShow) {
				t = this._data[i].replayIdHex;
				console.log("Chọn trúng chiến đấu ID:" + t);
				break
			}
		}
		if (!t) {
			this.battleResultRec()
		} else {
			if (this.play && this.play._idHex == t) {
				let e = 3;
				if (this.isFirst) {
					if (this._type == 1) {
						e = 3
					} else {
						e = 1
					}
				} else {
					if (this._type == 1) {
						e = 4
					} else {
						e = 2
					}
				}
				FM.battleMan.watchBattle(this.play, this._funcId, null, Laya.Utils.bind(this.playEnd, this), e);
				this.isFirst = false;
				for (let i = 0; i < this._data.length; i++) {
					if (this._data[i].replayIdHex == t) {
						this._data[i].hasShow = true;
						break
					}
				}
			} else {
				this.play = null;
				if (this._funcId != pd.PEAK_PVP_KO) {
					qM.sendMsg(Rd.SHOW_DATA_REQ, {
						replayIdHex: t,
						type: 2
					})
				} else {
					qM.sendMsg(Rd.VIDEO_DATA_REQ, {
						replayIdHex: t,
						type: 3,
						srvCode: "group",
						live: true
					})
				}
			}
		}
	}
	playEnd(e = "end") {
		if (this._type != 1 && e == "close") {
			this.battleResultRec();
			return
		}
		if (this.play && this._data) {
			let e = b_.getTimeStamp();
			for (let t = 0; t < this._data.length; t++) {
				if (this._data[t].replayIdHex == this.play._idHex) {
					this._data[t].endTime = e - 1;
					e = e - this._data[t].endTime;
					for (let i = t + 1; i < this._data.length; i++) {
						this._data[i].endTime += e
					}
					break
				}
			}
		}
		this.checkWatchBattle()
	}
	addOverTime() {
		if (!this._data || !this._data.length || !this._callBack || this._type != 1)
			return;
		let e = b_.getTimeStamp();
		if (this._data[this._data.length - 1].endTime > e) {
			Laya.timer.once(this._data[this._data.length - 1].endTime - e + 200, this, this.battleResultRec)
		}
	}
	remOverTime() {
		Laya.timer.clear(this, this.battleResultRec)
	}
	battleResultRec() {
		FM.battleMan.stopWatch(this._funcId);
		if (this._callBack) {
			this._callBack.call(null)
		}
		this.play = null;
		this._data = null;
		this._callBack = null
	}
}
