		this._ui.htmlRecord.style.bold = true;
		this._ui.htmlRecord.style.wordWrap = false;
		this._ui.htmlMoreLevel.style.bold = true;
		this._ui.htmlMoreLevel.style.wordWrap = false;
		this._ui.cHtmlFirst.style.bold = true;
		this._ui.cHtmlFirst.style.fontSize = 20;
		this._ui.cHtmlFirst.style.stroke = 2;
		this._ui.cHtmlFirst.style.strokeColor = "#5d2d07";
		this._ui.cHtmlFirst.style.color = "#fef6eb";
		this._ui.cHtmlFirst.style.align = "center";
		this._ui.cHtmlFirst.style.width = this._ui.cHtmlFirst.width;
		let e = od.getTplInfo(nd.ENDLESS_RWD_SHOW, 4);
