class zx {
	constructor(e, t) {
		this._diff = e;
		this._box = t;
		let i = od.getTplInfo(nd.EXPEDITION_DIFF, e);
		this._cp = i.cp;
		if (i.cp) {
			let e = this._box.getChildByName("boxCP");
			let t = e.getChildByName("labCP");
			t.text = WM.num2Str(i.cp)
		}
		let s = this._box.getChildByName("btnChose");
		s.on(Laya.Event.CLICK, this, this.onChose);
		let a = [];
		let r = od.getTplInfo(nd.EXPEDITION, null, {
				diff: this._diff
			});
		for (let h = 0; h < r.length; h++) {
			let e = cP.splitStr2Arr(r[h].rwd);
			cP.mergeItems(a, e);
			if (r[h].chest != "") {
				let e = cP.splitStr2Arr(r[h].chest);
				cP.mergeItems(a, e)
			}
		}
		let l = this._box.getChildByName("listRwd");
		l.array = a
	}
	onChose(e) {
		qM.sendMsg(zd.DIFF_CHOSE_REQ, {
			difficulty: this._diff
		})
	}
	updateState() {
		if (this._cp) {
			let e = this._box.getChildByName("boxCP");
			let t = this._box.getChildByName("btnChose");
			if (uP.getIns().master.cp >= this._cp && FM.expeditionMan.getPassDiff() + 1 >= this._diff) {
				t.visible = true;
				e.visible = false;
				this._box.off(Laya.Event.CLICK, this, this.lockClick)
			} else {
				t.visible = false;
				e.visible = true;
				this._box.on(Laya.Event.CLICK, this, this.lockClick)
			}
		}
	}
	lockClick(e) {
		if (FM.expeditionMan.getPassDiff() + 1 < this._diff) {
			FM.noticeMan.showNotice(WM.getLanCodeTip(10289));
			return
		}
		if (uP.getIns().master.cp < this._cp) {
			FM.noticeMan.showNotice(WM.getLanCodeTip(10290));
			return
		}
	}
}
