class ak extends g {
	constructor() {
		super("JLDZMaterial")
	}
	static getIns() {
		if (!this._ins) {
			this._ins = new ak
		}
		return this._ins
	}
	initUI() {
		this._ui = this.uiView;
		this.setLayer(1, 1, 1, 1);
		this._ui.listCell.mouseHandler = Laya.Handler.create(this, this.onCellClick, null, false)
	}
	onClick(e) {
		switch (e.target) {
		case this._ui.btnClose:
			this.closeUI();
			break;
		case this._ui.btnSelect:
			this.selectClick();
			break
		}
	}
	afterClose() {
		this.callback = null
	}
	show(e, t) {
		this.openUI();
		this.callback = t;
		if (e.length) {
			e.sort(function (e, t) {
				if (e.equip.campMark && !t.equip.campMark) {
					return -1
				} else if (!e.equip.campMark && t.equip.campMark) {
					return 1
				} else if (e.equip.campMark && t.equip.campMark) {
					return e.equip.campMak - t.equip.campMark
				} else {
					return 0
				}
			});
			this._ui.listCell.array = e;
			this._ui.listCell.scrollTo(0);
			this._ui.boxNone.visible = false
		} else {
			this._ui.listCell.array = [];
			this._ui.boxNone.visible = true
		}
	}
	selectClick() {
		if (!this._ui.listCell.array.length) {
			this.closeUI();
			return
		}
		let e;
		for (let t = 0; t < this._ui.listCell.array.length; t++) {
			let i = this._ui.listCell.array[t];
			if (i.select) {
				e = i.equip;
				break
			}
		}
		if (this.callback) {
			this.callback.runWith(e)
		}
		this.closeUI()
	}
	onCellClick(e, t) {
		if (e.type != Laya.Event.CLICK)
			return;
		for (let i = 0; i < this._ui.listCell.array.length; i++) {
			let e = this._ui.listCell.array[i];
			let s = this._ui.listCell.getCell(i);
			if (i == t) {
				e.select = !e.select;
				if (s) {
					s.dataSource = e
				}
			} else {
				if (e.select) {
					e.select = false;
					if (s) {
						s.dataSource = e
					}
				}
			}
		}
	}
}
