	refreshXqList() {
		if (!this.isOpen)
			return;
		if (this._ui.tabType.selectedIndex != 3)
			return;
		let e = Jx.allFairyData;
		let t = [];
		for (let i = 0; i < e.length; i++) {
			t[i] = {};
			t[i].tpl = e[i];
			let s = e[i].makeArr;
			let a = 0;
			for (let e = 0; e < s.length; e++) {
				if (cP.checkEnough(s[e])) {
					a++
				}
			}
			t[i].okNum = a;
			t[i].dot = a >= s.length && cP.checkEnough(e[i].makeArr1)
		}
		t.sort(this.sortXqFun);
		this._ui.xqForgeList.array = t;
		this.checkXqTabDot()
	}
	sortXqFun(e, t) {
		if (e.dot && t.dot) {
			return e.tpl.id - t.tpl.id
		} else if (e.dot && !t.dot) {
			return -1
		} else if (!e.dot && t.dot) {
			return 1
		} else {
			if (e.okNum != t.okNum) {
				return t.okNum - e.okNum
			} else {
				return e.tpl.id - t.tpl.id
			}
		}
	}
	refreshCostList() {
		if (!this.isOpen)
			return;
		if (this._ui.tabType.selectedIndex != 3)
			return;
		this._ui.xqCostList.refresh();
		this._ui.xqMoneyBox.dataSource = this._ui.xqMoneyBox.dataSource
	}
	onXqListClick(e, t) {
		if (e && e.type != Laya.Event.CLICK)
			return;
		if (t < 0)
			return;
		let i = this._ui.xqForgeList.getItem(t);
		if (!i) {
			return
		}
		this.fairyId = i.tpl.id;
		Tb.addItemGrid({
			tid: i.tpl.id,
			type: c.FAIRY
		}, this._ui.xqTarGrid);
		let s = i.tpl.make.split("#");
		this._ui.xqCostList.array = s;
		this._ui.xqMoneyBox.dataSource = X_.getStrTypeData(i.tpl.make1, true)
	}
