		if (!this.isOpen || !this.actTpl)
			return;
		let e = WM.splitToNumArr(this.actTpl.showProp);
		for (let t = 0; t < 4; t++) {
			if (this._ui["moneyBox" + (t + 1)]) {
				this._ui["moneyBox" + (t + 1)].visible = false
			}
		}
		for (let t = 0; t < e.length; t++) {
			if (this._ui["moneyBox" + (t + 1)]) {
				this._ui["moneyBox" + (t + 1)].dataSource = X_.getTypeData({
						tid: e[t],
						type: c.PROP,
						num: this.data.bag.prop.getNum(e[t])
					}, false);
				this._ui["moneyBox" + (t + 1)].visible = true
			}
		}
