class vk extends g {
	constructor() {
		super("OptionalYanMo")
	}
	static getIns() {
		if (!this._ins) {
			this._ins = new vk
		}
		return this._ins
	}
	onClick(e) {
		switch (e.target) {
		case this._ui.btnClose:
			this.closeUI();
			break;
		case this._ui.btnSure:
			this.getReq();
			break
		}
	}
	initUI() {
		this._ui = this.uiView;
		this.setLayer(1, 1, 1, 1)
	}
	afterClose() {}
	show() {
		this.openUI();
		let e = od.getTplInfo(nd.ACT_DATE_YAN_MO_ITEM, null, {
				group: FM.guoQingYanMoMan.actTpl.shopGroup
			});
		this.maxNum = 1;
		let t = [];
		for (let i = 0; i < e.length; i++) {
			let s = cP.splitStr2Arr(e[i].itemId)[0].tid;
			if (this.data.bag.prop.getNum(s) > 0) {
				t.push({
					index: i,
					item: {
						tid: s,
						type: c.PROP,
						num: this.data.bag.prop.getNum(s)
					},
					select: false,
					selectFun: Laya.Utils.bind(this.selectFun, this)
				})
			}
		}
		this._ui.listCell.array = t;
		this._ui.noThing.visible = true;
		if (t.length > 0) {
			this._ui.noThing.visible = false
		}
		this._ui.listCell.tweenTo(0, 0);
		this.refreshNum()
	}
	selectFun(e, t) {
		if (t == true) {
			if (this.maxNum == 1) {
				let t = this._ui.listCell.array;
				for (let i = 0; i < t.length; i++) {
					if (t[i].index != e) {
						t[i].select = false
					} else {
						t[i].select = true
					}
					let s = this._ui.listCell.getCell(i);
					if (s) {
						s.udpateSelect()
					}
				}
			} else {
				if (this.selectNum >= this.maxNum) {
					FM.noticeMan.showNotice(WM.getLanCodeTip(20051, [this.maxNum]))
				} else {
					this._ui.listCell.array[e].select = true;
					let t = this._ui.listCell.getCell(e);
					if (t) {
						t.udpateSelect()
					}
				}
			}
		}
		this._ui.listCell.refresh();
		this.refreshNum()
	}
	refreshNum() {
		this.selectNum = 0;
		let e = this._ui.listCell.array;
		for (let t = 0; t < e.length; t++) {
			if (e[t].select) {
				this.selectNum++
			}
		}
	}
	getReq() {
		let e = [];
		let t = this._ui.listCell.array;
		for (let i = 0; i < t.length; i++) {
			if (t[i].select) {
				e.push(t[i])
			}
		}
		if (e.length != this.maxNum) {
			WM.getLanCodeTip(20053, [this.maxNum]);
			return
		}
		if (e.length > 0) {
			let t = od.getTplInfo(nd.ACT_DATE_YAN_MO_ITEM, null, {
					group: FM.guoQingYanMoMan.actTpl.shopGroup
				});
			for (let i = 0; i < t.length; i++) {
				let s = cP.splitStr2Arr(t[i].itemId)[0].tid;
				if (s == e[0].item.tid) {
					FM.guoQingYanMoMan.reqYanMo(t[i].id, this.data.bag.prop.getNum(s))
				}
			}
			this.closeUI()
		} else {
			FM.noticeMan.showNotice("Mời lựa chọn chí ít một loại")
		}
	}
}
