class Ok {
	static set notepadData(e) {
		this._notepadData = e;
		if (e.activityId && e.activityId != this.actTpl.id) {
			this._actTpl = od.getTplInfo(nd.GUOQING_NOTEPAD_BASE, e.activityId);
			let t = od.getTplInfo(nd.GUOQING_NOTEPAD_PRIZE, null, {
					group: this.actTpl.prizeGroup
				});
			this._maxPoint = t[t.length - 1].point
		}
	}
	static get notepadData() {
		return this._notepadData
	}
	static get beginTime() {
		if (!this._notepadData)
			return b_.getTimeStamp();
		return this._notepadData.beginTime
	}
	static get endTime() {
		if (!this._notepadData)
			return b_.getTimeStamp();
		return this._notepadData.endTime
	}
	static get actTpl() {
		return this._actTpl
	}
	static set point(e) {
		if (!this._notepadData)
			return;
		this._notepadData.point = e
	}
	static get point() {
		if (!this._notepadData)
			return 0;
		return this._notepadData.point
	}
	static get isMaxPoint() {
		return this.point >= this._maxPoint
	}
	static get activeAdvanced() {
		if (!this._notepadData)
			return 0;
		return this._notepadData.activeAdvanced
	}
	static isBaseGot(e) {
		if (!this._notepadData)
			return false;
		return this._notepadData.baseGot[e]
	}
	static isAdvanceGot(e) {
		if (!this._notepadData)
			return false;
		return this._notepadData.advanceGot[e]
	}
	static isEnterShow() {
		return this._notepadData && this._notepadData.activityId && b_.getTimeStamp() >= this._notepadData.beginTime
	}
	static isDot() {
		return this.isPrizeDot() || this.isDailyDot() || this.isWeekDot()
	}
	static isPrizeDot() {
		if (!this.actTpl || !this._notepadData)
			return false;
		if (this._notepadData.beginTime > b_.getTimeStamp())
			return false;
		let e = od.getTplInfo(nd.GUOQING_NOTEPAD_PRIZE, null, {
				group: this.actTpl.prizeGroup
			});
		let t = this.point;
		for (let i = 0; i < e.length; i++) {
			if (t >= e[i].point) {
				if (!this.isBaseGot(e[i].id)) {
					return true
				}
				if (this.activeAdvanced && !this.isAdvanceGot(e[i].id)) {
					return true
				}
			}
		}
		return false
	}
	static isDailyDot() {
		if (!this.actTpl || !this._notepadData)
			return false;
		if (this._notepadData.beginTime > b_.getTimeStamp())
			return false;
		let e = uP.getIns().task.getTaskDataByFuncId(pd.NATIONAL_DAY_BATTLE);
		let t = e.doneList;
		for (let i = 0; i < t.length; i++) {
			let e = od.getTplInfo(nd.GUOQING_NOTEPAD_TASK, t[i].tid);
			if (e && e.type == 1 && t[i].done && !t[i].rewardGot) {
				return true
			}
		}
		return false
	}
	static isWeekDot() {
		if (!this.actTpl || !this._notepadData)
			return false;
		if (this._notepadData.beginTime > b_.getTimeStamp())
			return false;
		let e = uP.getIns().task.getTaskDataByFuncId(pd.NATIONAL_DAY_BATTLE);
		let t = e.doneList;
		for (let i = 0; i < t.length; i++) {
			let e = od.getTplInfo(nd.GUOQING_NOTEPAD_TASK, t[i].tid);
			if (e && e.type == 2 && t[i].done && !t[i].rewardGot) {
				return true
			}
		}
		return false
	}
	static isCompleted(e) {
		return uP.getIns().task.isCompleted(pd.NATIONAL_DAY_BATTLE, e)
	}
	static checkComplete(e) {
		return uP.getIns().task.checkComplete(pd.NATIONAL_DAY_BATTLE, e)
	}
	static getTaskItem(e) {
		return uP.getIns().task.getTaskItem(pd.NATIONAL_DAY_BATTLE, e)
	}
	static getWeekEndTime() {
		if (!Ok.actTpl || !Ok.actTpl.startTime) {
			if (Ok.notepadData) {
				i.reportError("normalError", "Kỳ nghỉ hè đại tác chiến hoạt động phối trí có vấn đề:" + Ok.notepadData.activityId);
				return b_.getWeekEndTimeStamp()
			}
		}
		let e = this.beginTime;
		let t = this.endTime;
		let s = b_.getTimeStamp();
		for (let i = 0; i < 100; i++) {
			e += od.getGlobalValue(38002) * b_.ONEDAYMILLISECONDS;
			if (e > t)
				return t;
			if (e > s) {
				return e
			}
		}
		return t
	}
}
