class Jk extends g {
	constructor() {
		super("HeroLevelShareMaterial");
		this.campArr = [0, g_.C1, g_.C2, g_.C3, g_.C4, g_.C5, g_.C6];
		this._selectCamp = 0
	}
	static getIns() {
		if (!this._ins) {
			this._ins = new Jk
		}
		return this._ins
	}
	onClick(e) {
		switch (e.target) {
		case this._ui.btnClose:
			this.closeUI();
			break;
		case this._ui.btnSelect:
			this.selectClick();
			break;
		case this._ui.btnOneKey:
			this.closeUI();
			break
		}
	}
	initUI() {
		this._ui = this.uiView;
		this.setLayer(1, 1, 1, 1);
		this._ui.collectHeroCampList.selectHandler = Laya.Handler.create(this, this.heroFilterCampSelect, null, false);
		this._ui.collectHeroCampList.array = this.campArr;
		this._ui.collectHeroCampList.selectedIndex = 0;
		this._ui.listCell.mouseHandler = Laya.Handler.create(this, this.cellClick, null, false)
	}
	afterClose() {
		if (this.selectHandler) {
			this.selectHandler.recover();
			this.selectHandler = null
		}
	}
	show(e, t) {
		this.selectHandler = t;
		this._canSelectList = e;
		this._needNum = 1;
		this.openUI();
		this.refresh();
		this._ui.collectHeroCampList.selectedIndex = 0
	}
	refresh() {
		for (let i = 0; i < this._canSelectList.length; i++) {
			if (this._canSelectList[i].heroData) {
				this._canSelectList[i].lock = V_.checkLockStatus(this._canSelectList[i].heroData, false, true, true, true, false, true, false) ? 1 : 0;
				this._canSelectList[i].selected = false
			}
		}
		this._canSelectList.sort(this.sortFun);
		let e = 0;
		if (this._selectCamp >= 0 && this.campArr.length > this._selectCamp && this.campArr[this._selectCamp] != null) {
			e = this.campArr[this._selectCamp]
		}
		let t = [];
		for (let i = 0; i < this._canSelectList.length; i++) {
			if (e == 0 || e == this._canSelectList[i].heroData.baseTpl.camp) {
				t.push(this._canSelectList[i])
			}
		}
		this._ui.listCell.array = t;
		this._ui.noAnythingBox.visible = false;
		if (this._canSelectList.length <= 0) {
			this._ui.noAnythingBox.visible = true
		}
		this._ui.listCell.scrollTo(0);
		this.freshNum()
	}
	heroFilterCampSelect(e) {
		if (e < 0)
			return;
		this._selectCamp = e;
		this.refresh()
	}
	sortFun(e, t) {
		if (e.lock != t.lock) {
			return e.lock - t.lock
		} else {
			let i = e.level;
			let s = t.level;
			if (e.shareLevel > 0) {
				i = e.shareLevel
			}
			if (t.shareLevel > 0) {
				s = t.shareLevel
			}
			if (s != i) {
				return s - i
			} else {
				return e.cp - t.cp
			}
		}
	}
	cellClick(e, t) {
		if (e.type != Laya.Event.CLICK)
			return;
		let i = this._ui.listCell.getItem(t);
		if (i.lock) {
			V_.checkLockStatus(i.heroData, true, true, true, true, false, true, false);
			return
		}
		if (i.getItem) {
			Ng.getIns().showGetInfoDetail(i.tid, c.MING_GE)
		} else {
			if (!i.selected) {
				for (let e = 0; e < this._selectedList.length; e++) {
					for (let t = 0; t < this._ui.listCell.array.length; t++) {
						if (this._ui.listCell.array[t].heroData.idHex == this._selectedList[e]) {
							this._ui.listCell.array[t].selected = false
						}
					}
					for (let t = 0; t < this._canSelectList.length; t++) {
						if (this._canSelectList[t].heroData.idHex == this._selectedList[e]) {
							this._canSelectList[t].selected = false
						}
					}
				}
				this._selectedList = [];
				if (this._selectedList.length >= this._needNum) {
					FM.noticeMan.showNotice(WM.getLanCodeTip(10394));
					return
				}
			}
			i.selected = !i.selected;
			this._ui.listCell.refresh();
			this.freshNum()
		}
	}
	freshNum() {
		this._selectedList = [];
		for (let e = 0; e < this._canSelectList.length; e++) {
			let t = this._canSelectList[e];
			if (t.selected) {
				if (t.heroData) {
					this._selectedList.push(t.heroData.idHex)
				}
			}
		}
	}
	selectClick() {
		this.selectHandler.runWith([this._selectedList]);
		this.closeUI()
	}
	oneKeyClick() {
		let e = this._ui.listCell.array;
		let t = 0;
		for (let i = 0; i < e.length; i++) {
			if (e[i].selected) {
				t++
			}
		}
		for (let i = 0; i < e.length; i++) {
			if (e[i].getItem)
				break;
			if (e[i].lock)
				break;
			if (e[i].selected)
				continue;
			if (t >= this._needNum)
				break;
			e[i].selected = true;
			t++
		}
		this._ui.listCell.refresh();
		this.freshNum()
	}
}
