	freshHeroList() {
		if (!this.isOpen)
			return;
		var e = this.data.bag.hero.list;
		var t = [];
		for (var i = 0; i < e.length; i++) {
			if (this.mode === 1) {
				if (e[i].realmGrade > 0)
					continue;
				let t = od.getTplInfo(nd.HERO_INHERIT_RACE);
				let s = e[i].baseTpl.camp;
				let a = e[i].baseTpl.star;
				let r = t[0].rawRace.split("#");
				if (r.indexOf(s + "") < 0 || a < 6) {
					continue
				}
			}
			if (this._ui.list0Camp.selectedItem == 0 || e[i].baseTpl.camp == this._ui.list0Camp.selectedItem) {
				t.push(e[i])
			}
		}
		t.sort(this.heroSort);
		this._ui.list0Hero.array = t;
		this._ui.list0Hero.scrollTo(0);
		this._ui.list0Hero.showEffect(this, this.compelteFun, 15, 5, 1, VS.SCALE);
		if (t.length == 0) {
			this._ui.noAnythingBox.visible = true
		} else {
			this._ui.noAnythingBox.visible = false
		}
		this.freshCapacity()
	}
	heroSort(e, t) {
		let i = f_.checkHeroInPosition(e.idHex, pd.ADVENTURE_BOSS) ? 1 : 0;
		let s = f_.checkHeroInPosition(t.idHex, pd.ADVENTURE_BOSS) ? 1 : 0;
		if (i != s) {
			return s - i
		} else {
			if (e.baseTpl.star != t.baseTpl.star) {
				return t.baseTpl.star - e.baseTpl.star
			} else {
				let i = e.level;
				let s = t.level;
				if (e.shareLevel > 0) {
					i = e.shareLevel
				}
				if (t.shareLevel > 0) {
					s = t.shareLevel
				}
				if (s != i) {
					return s - i
				} else {
					if (e.baseTpl.camp != t.baseTpl.camp) {
						return t.baseTpl.camp - e.baseTpl.camp
					} else {
						if (e.baseTpl.job != t.baseTpl.job) {
							return e.baseTpl.job - t.baseTpl.job
						}
						return e.baseTpl.id - t.baseTpl.id
					}
				}
			}
		}
	}
	onHeroClick(e, t) {
		if (e.type != Laya.Event.CLICK)
			return;
		var i = this._ui.list0Hero.getItem(t);
		if (i.isFetterHero) {
			let e = this.data.bag.hero.getFetterMaster(i);
			if (e) {
				QM.show("Nên anh hùng chính làm" + WM.getHtmlByColor(e.baseTpl.star + " sao" + e.baseTpl.name, m.TIP_GREEN) + "Phó tướng, tạm thời không cách nào thao tác, phải chăng tiến đến xem xét?", Laya.Handler.create(this, this.lookMaster, [e]))
			}
			return
		}
		if (this.mode === 0) {
			Im.getIns().openByHero(i.idHex, this._ui.list0Camp.selectedItem)
		} else if (this.mode === 1) {
			let e = V_.checkMainPositionMsg(i);
			if (e) {
				let t = function () {
					FM.positionMan.openByFuncId(pd.ADVENTURE_BOSS)
				};
				QM.show(e, Laya.Handler.create(this, t))
			} else {
				this.closeUI();
				FM.mainCityMan.openUI();
				FM.heroInherit.openUI();
				this.sendCmd(d.HERO_INHERIT_LEFT, i)
			}
		}
	}
