	freshTJList() {
		if (!this._tjList) {
			this._tjList = [];
			let e = od.getTplInfo(nd.HERO, null, {
					tjShow: 1
				});
			for (let t = 0; t < e.length; t++) {
				let i = {
					tid: e[t].id,
					baseTpl: e[t],
					level: e[t].maxLevel,
					grade: e[t].maxGrade,
					type: c.HERO
				};
				let s = od.getTplInfo(nd.HERO_REALM_BASE, e[t].protoId);
				if (s && i.baseTpl.star >= s.star) {
					i.realm = {
						breach: {
							grade: 101
						}
					}
				}
				this._tjList.push(i)
			}
		}
		let e = [];
		for (let t = 0; t < this._tjList.length; t++) {
			if (this._tjList[t].baseTpl.camp == this._ui.list1Camp.selectedItem) {
				e.push(this._tjList[t])
			}
		}
		e.sort(this.tjSort);
		this._ui.list1Hero.array = e;
		this._ui.list1Hero.scrollTo(0);
		this._ui.list1Hero.showEffect(this, this.compelteFun, 15, 5, 1, VS.SCALE)
	}
