	oneTotemDataRec(e) {
		let t = F_.getTotemData(e.item.tid);
		if (!t)
			return;
		let i = e.item.totalInjectNum - t.totalInjectNum;
		if (i > 0) {
			let e = F_.getInjectAttr();
			let t = "";
			for (let i = 0; i < e.length; i++) {
				t += n_.toName(e[i].type) + "+" + n_.toStr(e[i].type, e[i].value) + ","
			}
			t = t.substr(0, t.length - 1);
			FM.noticeMan.showNotice(t)
		}
		if (e.item.grade > t.grade) {
			sN.getIns().show(e.item.tid, e.item.grade)
		}
		if (e.isLevelUp) {
			let i = t;
			let s = i.level;
			let a = F_.getTotalAttr(i);
			F_.updateTotemData(e.item);
			let r = F_.getTotemData(e.item.tid);
			let l = r.level;
			let h = F_.getTotalAttr(r);
			let n = n_.attrDic2Arr(a);
			for (let e = 0; e < n.length; e++) {
				n[e].nextValue = h[n[e].type]
			}
			p_.getIns().openUpUi(p_.getShowData(t.baseTpl.name, s, l, n))
		} else {
			F_.updateTotemData(e.item)
		}
		this.refreshTotem();
		this.checkTotemDot()
	}
