	showChaosTotem() {
		let e = 6;
		this._ui.tab2Type.selectedIndex = 1;
		this._ui.box20Cost.visible = false;
		this._ui.lab20Max.visible = true;
		let t = od.getTplInfo(nd.TOTEM, e);
		let i = t.id;
		let s = F_.getMaxLevelInfo();
		let a = s.level >= 100 ? s.level : 100;
		let r = s.id;
		let l = od.getTplInfo(nd.TOTEM, r);
		this._ui.rawTotemIcon.skin = "common/" + l.icon + ".png";
		this._ui.rawTotemBox.visible = a > 100;
		this._ui.img2Totem.skin = "common/" + t.icon + ".png";
		this._ui.lab2Name.text = t.name + "Lv." + a;
		this._ui.rawTotemLevel.text = a + "";
		let h = n_.attrDic2Arr(F_.getChaosTotemAttr(a));
		this._ui.list20Attr.array = n_.sort(h);
		this._ui.list2Attr.array = h;
		this._ui.lab20Lv.text = "LV." + a;
		Tb.addTotemGrid({
			tid: t.id,
			grade: 10
		}, this._ui.ctn21Cur).showLevel = true;
		this._ui.list21Cur.visible = true;
		this._ui.list21Cur.repeatX = 10;
		this._ui.ctn21Cur.x = 273;
		this._ui.ctn21Next.visible = false;
		this._ui.ctn21Cur.gray = false;
		this._ui.box21UnMax.visible = false;
		this._ui.lab21Max.visible = false;
		this._ui.dot20.visible = this._ui.imgDot20.visible = F_.checkLevelDot(i);
		this._ui.dot21.visible = this._ui.imgDot21.visible = F_.checkGradeDot(i);
		this._ui.list2Camp.refresh()
	}
	refreshTotem() {
		if (!this.isOpen)
			return;
		this.selectHeroArr = [];
		if (this.curCamp !== 6 && this.curCamp !== 0) {
			this.saveTab2Type = this._ui.tab2Type.selectedIndex
		}
		let e = this._ui.list2Camp.selectedItem;
		if (this.curCamp === 6 && e !== 6) {
			this._ui.tab2Type.selectedIndex = this.saveTab2Type
		}
		this.curCamp = e;
		this._ui.btn21Preview.visible = e !== 6;
		this._ui.tab2Type.visible = e !== 6;
		this._ui.chaosTotemTips.visible = e === 6;
		if (e === 6) {
			this.showChaosTotem();
			return
		}
		this._ui.rawTotemBox.visible = false;
		this.curTotemData = F_.getTotemData(e);
		if (!this.curTotemData)
			return;
		let t = od.getTplInfo(nd.TOTEM, e);
		this._ui.img2Totem.skin = "common/" + t.icon + ".png";
		this._ui.lab2Name.text = t.name + "Lv." + this.curTotemData.level;
		this._ui.lab2Name.text = t.name + "Lv." + this.curTotemData.level;
		let i = od.getTplInfo(nd.TOTEM_LEVEL, e)[this.curTotemData.level];
		if (!i)
			return;
		this._ui.list20Attr.array = n_.sort(F_.getLevelAttr(this.curTotemData));
		this._ui.lab20Lv.text = "LV." + this.curTotemData.level;
		let s = this.curTotemData.injectNum * i.onceExp;
		let a = i.needTimes * i.onceExp;
		this._ui.lab20Prog.text = s + "/" + a;
		this._ui.prog20.value = s / a;
		if (this.curTotemData.level >= t.maxLevel && s >= a) {
			this._ui.box20Cost.visible = false;
			this._ui.lab20Max.visible = true
		} else {
			this._ui.box20Cost.visible = true;
			this._ui.lab20Max.visible = false;
			this._ui.list20Cost.array = [i.costItem, i.costM0]
		}
		this._ui.list21Next.repeatX = this.curTotemData.grade >= t.maxGrade ? this.curTotemData.grade : this.curTotemData.grade + 1;
		if (this.curTotemData.grade <= 0) {
			this._ui.list21Cur.visible = false;
			Tb.addTotemGrid({
				tid: this.curTotemData.tid,
				grade: 1
			}, this._ui.ctn21Cur).showLevel = true;
			this._ui.ctn21Cur.gray = true
		} else {
			this._ui.list21Cur.visible = true;
			this._ui.list21Cur.repeatX = this.curTotemData.grade;
			Tb.addTotemGrid({
				tid: this.curTotemData.tid,
				grade: this.curTotemData.grade
			}, this._ui.ctn21Cur).showLevel = true;
			this._ui.ctn21Cur.gray = false
		}
		if (this.curTotemData.grade >= t.maxGrade || this.curTotemData.grade <= 0) {
			this._ui.ctn21Cur.x = 273;
			this._ui.ctn21Next.visible = false;
			Tb.removeGrid(this._ui.ctn21Next)
		} else {
			this._ui.ctn21Cur.x = 149;
			this._ui.ctn21Next.visible = true;
			Tb.addTotemGrid({
				tid: this.curTotemData.tid,
				grade: this.curTotemData.grade + 1
			}, this._ui.ctn21Next).showLevel = true
		}
		if (this.curTotemData.grade >= t.maxGrade) {
			this._ui.box21UnMax.visible = false;
			this._ui.lab21Max.visible = true
		} else {
			this._ui.box21UnMax.visible = true;
			this._ui.lab21Max.visible = false;
			let e = od.getTplInfo(nd.TOTEM_GRADE, this.curTotemData.tid)[this.curTotemData.grade];
			let t = cP.parseItemStr(e.costHero);
			t.num = 0;
			Tb.addItemGrid(t, this._ui.ctn21Hero);
			this._ui.ctn21Hero.mouseEnabled = false;
			this.refreshTotemSelectHero();
			this._ui.lab21NeedLevel.text = WM.getLanCodeTip(20213, [e.needLevel]);
			this._ui.box21Cost.dataSource = e.costItem
		}
		let r = F_.getTotalAttr(this.curTotemData);
		let l = n_.attrDic2Arr(r);
		n_.sort(l);
		this._ui.list2Attr.array = l;
		this._ui.dot20.visible = this._ui.imgDot20.visible = F_.checkLevelDot(this.curTotemData.tid);
		this._ui.dot21.visible = this._ui.imgDot21.visible = F_.checkGradeDot(this.curTotemData.tid);
		this._ui.list2Camp.refresh()
	}
