class uN extends g {
	constructor(e = "HeroinheritChoose") {
		super(e);
		this.heroTable = {}
	}
	afterOpen() {
		let e = FM.heroInherit.heroData1;
		let t = e.baseTpl.camp;
		let i = od.getTplInfo(nd.HERO_INHERIT_RULE);
		let s = od.getTplInfo(nd.HERO_INHERIT_COST, null, {
				rawStar: e.baseTpl.star
			});
		this.minStar = s[0].inheritStar;
		this.camps = [];
		for (let a = 0; a < i.length; a++) {
			let e = i[a];
			let s = e.rawRace;
			let r = e.inheritRace;
			let l = s.split("#");
			if (l.indexOf(t + "") >= 0) {
				let e = r.split("#");
				for (let t = 0; t < e.length; t++) {
					let i = e[t].split("-");
					this.camps[t] = parseInt(i[0]);
					if (i.length === 1) {
						this.heroTable[i[0]] = 0
					} else {
						let e = [];
						for (let t = 1; t < i.length; t++) {
							e.push(parseInt(i[t]))
						}
						this.heroTable[i[0]] = e
					}
				}
				break
			}
		}
		if (this.camps.length <= 0)
			return;
		this.camps.unshift(0);
		this._ui.list0Camp.array = this.camps;
		this._ui.list0Camp.selectedIndex = -1;
		this._ui.list0Camp.selectedIndex = 0
	}
	initUI() {
		this._ui = this.uiView;
		this.setLayer(1, 1, 1, 1);
		this._ui.list0Hero.mouseHandler = Laya.Handler.create(this, this.heroCellClick, null, false);
		this._ui.list0Camp.selectHandler = Laya.Handler.create(this, this.heroCampSelect, null, false)
	}
	afterClose() {
		let e = this._ui.list0Hero.array;
		for (let t = 0; t < e.length; t++) {
			e[t].selected = false
		}
		this._ui.list0Hero.refresh()
	}
	heroCellClick(e, t) {
		if (e.type != Laya.Event.CLICK)
			return;
		let i = this._ui.list0Hero.getItem(t);
		if (i.selected) {
			i.selected = false;
			this._tjData = null;
			this._ui.list0Hero.refresh()
		} else {
			let e = this._ui.list0Hero.array;
			for (let t = 0; t < e.length; t++) {
				e[t].selected = false
			}
			i.selected = true;
			this._tjData = i;
			this._ui.list0Hero.refresh()
		}
	}
	onClick(e) {
		switch (e.target) {
		case this._ui.btnClose:
			this.closeUI();
			break;
		case this._ui.btnSure:
			let t = this.getSelectHero();
			if (!t) {
				FM.noticeMan.showNotice(WM.getLanCodeTip(10413));
				return
			}
			this.sendCmd(d.HERO_INHERIT_RIGHT, t);
			this.closeUI();
			break
		}
	}
	getSelectHero() {
		return this._tjData
	}
	heroCampSelect(e) {
		if (e < 0)
			return;
		this.freshHeroList()
	}
	checkHero(e, t) {
		let i = e.baseTpl;
		let s = this.heroTable[i.camp];
		if (t === 0) {
			if (this.camps.indexOf(i.camp) >= 0 && i.star >= this.minStar) {
				if (s === 0) {
					return true
				} else {
					return s.indexOf(i.id) >= 0
				}
			} else {
				return false
			}
		} else {
			if (i.camp == this._ui.list0Camp.selectedItem && i.star >= this.minStar) {
				if (s === 0) {
					return true
				} else {
					return s.indexOf(i.id) >= 0
				}
			} else {
				return false
			}
		}
	}
	freshHeroList() {
		if (!this.isOpen)
			return;
		if (!this.heroList) {
			this.heroList = [];
			let e = od.getTplInfo(nd.HERO, null, {
					tjShow: 1,
					star: 5
				});
			for (let t = 0; t < e.length; t++) {
				this.heroList.push({
					tid: e[t].id,
					baseTpl: e[t],
					grade: e[t].maxGrade,
					type: c.HERO
				})
			}
		}
		let e = FM.heroInherit.heroData1;
		let t = [];
		for (let i = 0; i < this.heroList.length; i++) {
			let s = this.heroList[i].baseTpl;
			let a = this.checkHero(this.heroList[i], this._ui.list0Camp.selectedItem);
			if (e.baseTpl.protoId === s.protoId) {
				a = false
			}
			if (a) {
				t.push(this.heroList[i])
			}
		}
		t.sort(this.heroSort);
		this._ui.list0Hero.array = t;
		this._ui.list0Hero.scrollTo(0);
		if (t.length == 0) {
			this._ui.boxNone.visible = true
		} else {
			this._ui.boxNone.visible = false
		}
	}
	heroSort(e, t) {
		if (e.baseTpl.star != t.baseTpl.star) {
			return e.baseTpl.star - t.baseTpl.star
		} else {
			return e.baseTpl.id - t.baseTpl.id
		}
	}
}
