class dN extends g {
	constructor() {
		super("HeroWish1")
	}
	static getIns() {
		if (!this._ins) {
			this._ins = new dN
		}
		return this._ins
	}
	onClick(e) {
		switch (e.target) {
		case this._ui.btnClose:
			this.closeUI();
			break;
		case this._ui.btnCancel:
			this.closeUI();
			break;
		case this._ui.btnSure:
			let t = this.getSelectHero();
			if (!t) {
				FM.noticeMan.showNotice(WM.getLanCodeTip(10413));
				return
			}
			if (this._callBack) {
				this._callBack.call(null, t)
			}
			this.closeUI();
			break
		}
	}
	initUI() {
		this._ui = this.uiView;
		this.setLayer(1, 1, 1, 1);
		this._ui.list0Hero.mouseHandler = Laya.Handler.create(this, this.heroCellClick, null, false);
		this._ui.list0Camp.array = [0, 1, 2, 3, 4, 5];
		this._ui.list0Camp.selectHandler = Laya.Handler.create(this, this.heroCampSelect, null, false);
		this._ui.titleLab.text = WM.getLanCodeTip(10414)
	}
	show(e, t = null) {
		this._tid = e;
		this._callBack = t;
		this.openUI()
	}
	afterOpen() {
		this._ui.list0Camp.selectedIndex = -1;
		this._ui.list0Camp.selectedIndex = 0
	}
	heroCampSelect(e) {
		if (e < 0)
			return;
		this.freshHeroList()
	}
	freshHeroList() {
		if (!this.isOpen)
			return;
		let e = this.getHeroDatas();
		let t = [];
		let i = 0;
		for (let s = 0; s < e.length; s++) {
			let i = e[s];
			if (this._ui.list0Camp.selectedIndex != 0 && this._ui.list0Camp.selectedIndex != i.baseTpl.camp)
				continue;
			let a = {};
			a.heroData = i;
			a.lock = 0;
			if (this._tid == i.tid) {
				a.selected = true
			} else {
				a.selected = false
			}
			t.push(a)
		}
		t.sort(this.heroSort);
		for (let s = 0; s < t.length; s++) {
			if (t[s].selected) {
				i = s;
				break
			}
		}
		this._ui.list0Hero.array = t;
		this._ui.list0Hero.tweenTo(i, 0);
		if (t.length == 0) {
			this._ui.boxNone.visible = true
		} else {
			this._ui.boxNone.visible = false
		}
	}
	heroCellClick(e, t) {
		if (e.type != Laya.Event.CLICK)
			return;
		let i = this._ui.list0Hero.getItem(t);
		if (i.selected) {
			i.selected = false;
			this._ui.list0Hero.refresh()
		} else {
			let e = this._ui.list0Hero.array;
			for (let t = 0; t < e.length; t++) {
				e[t].selected = false
			}
			i.selected = true;
			this._tid = i.heroData.tid;
			this._ui.list0Hero.refresh()
		}
	}
	getSelectHero() {
		return this._tid
	}
	heroSort(e, t) {
		if (e.heroData.baseTpl.star != t.heroData.baseTpl.star) {
			return t.heroData.baseTpl.star - e.heroData.baseTpl.star
		} else {
			if (e.heroData.baseTpl.camp != t.heroData.baseTpl.camp) {
				return t.heroData.baseTpl.camp - e.heroData.baseTpl.camp
			} else {
				if (e.heroData.baseTpl.job != t.heroData.baseTpl.job) {
					return e.heroData.baseTpl.job - t.heroData.baseTpl.job
				}
				return e.heroData.baseTpl.id - t.heroData.baseTpl.id
			}
		}
	}
	getHeroDatas() {
		if (this._heroDatas)
			return this._heroDatas;
		let e = od.getTplInfo(nd.HEROPRAY_HERO);
		this._heroDatas = [];
		for (let t = 0; t < e.length; t++) {
			let i = {
				tid: e[t].id,
				type: c.HERO
			};
			YM.queryItem(i);
			this._heroDatas.push(i)
		}
		return this._heroDatas
	}
}
