class SN extends j_ {
	get dataSource() {
		return super.dataSource
	}
	set dataSource(e) {
		super.dataSource = e;
		if (!e)
			return;
		let t = this.getChildByName("btnChange");
		let i = this.getChildByName("inputText");
		i.text = SN.getNumStr(e.num);
		if (e.modifyNum >= 1) {
			t.disabled = true;
			i.editable = false
		} else {
			i.editable = true;
			t.disabled = false;
			t.on(Laya.Event.CLICK, this, this.changeNum)
		}
	}
	changeNum() {
		let e = this.getChildByName("inputText");
		if (SN.getNumStr(this.dataSource.num) == e.text) {
			FM.noticeMan.showNotice(WM.getLanCodeTip(10417));
			return
		}
		let t = e.text;
		if (t.length < 3) {
			FM.noticeMan.showNotice(WM.getLanCodeTip(10418));
			return
		}
		FM.koiFishMan.changeNum(this.dataSource._idHex, Number(t))
	}
	static getNumStr(e) {
		if (e < 10) {
			return "00" + e
		} else if (e < 100) {
			return "0" + e
		} else {
			return e.toString()
		}
	}
}
class LN extends g {
	constructor() {
		super("LuckFish");
		this.lotteryNum = 0
	}
	getCmds() {
		return [d.FUNC_INIT, d.FUNC_OPEN]
	}
	exeCmd(e, t) {
		switch (t) {
		case d.FUNC_INIT:
			this.checkMainBtn();
			this.checkDot();
			break;
		case d.FUNC_OPEN:
			if (e == pd.KOI_FISH) {
				this.checkMainBtn();
				this.checkDot()
			}
			break
		}
	}
	getMsgs() {
		return [op.DATA_REC, op.SRV_DATA_REC, op.NUM_REC]
	}
	exeMsg(e, t) {
		switch (t) {
		case op.DATA_REC:
			this.dataRec(e);
			break;
		case op.SRV_DATA_REC:
			this.srvDataRec(e);
			break;
		case op.NUM_REC:
			this.numChange(e);
			break
		}
	}
	onClick(e) {
		switch (e.target) {
		case this._ui.btnMyNum:
			this.lotteryNum = this.lotterys.length;
			EN.getIns().show();
			this.checkDot();
			break;
		case this._ui.btnClose:
			this.closeUI();
			break;
		case this._ui.btnPrize:
			yN.getIns().openUI();
			break;
		case this._ui.btnTips:
			D_.showById(155);
			break
		}
	}
	getSrvData() {
		this.sendMsg(op.SRV_DATA_REQ)
	}
	changeNum(e, t) {
		this.sendMsg(op.NUM_REQ, {
			_idHex: e,
			num: t
		})
	}
	initUI() {
		this._ui = this.uiView;
		this.setLayer(1, 1, 1, 1);
		cd.regDot(dd.KOI_FISH_NUM_ENTER, this._ui.dotNum)
	}
	checkOpen(e = false) {
		return this.isOpenServer() && FM.funcMan.checkFuncOpen(pd.KOI_FISH, e)
	}
	afterOpen() {
		this.updateInfo()
	}
	afterClose() {
		vg.stop(this, this.timerFun1)
	}
	updateInfo() {
		if (!this.isOpen)
			return;
		if (!this.isOpenServer())
			return;
		let e = this.actTpl;
		if (!e)
			return;
		this._ui.previewList.array = cP.splitStr2Arr(e.previewPrize);
		this.checkTotalData()
	}
	checkTotalData() {
		if (!this.totalData) {
			this.getSrvData();
			return
		}
		if (b_.getTimeStamp() >= this.totalData.nextDrawTime) {
			this.getSrvData();
			return
		}
		this.updateNameList()
	}
	updateNameList() {
		if (!this.isOpen)
			return;
		if (!this.srvData || !this.totalData)
			return;
		vg.stop(this, this.timerFun1);
		if (b_.isSameToday(this.totalData.nextDrawTime)) {
			this._ui.prizeNumBox.visible = false;
			this._ui.cdPrizeBox.visible = true;
			vg.start(this.totalData.nextDrawTime - b_.getTimeStamp(), this, this.timerFun1)
		} else {
			this._ui.prizeNumBox.visible = true;
			this._ui.cdPrizeBox.visible = false;
			this._ui.prizeNumLab.text = SN.getNumStr(this.totalData.award.winningNum)
		}
		let e = this.getNamesByType(1);
		let t = this.getNamesByType(2);
		let i = this.getNamesByType(3);
		let s = this.getNamesByType(4);
		let a = e.length;
		if (t.length > a)
			a = t.length;
		if (i.length > a)
			a = i.length;
		if (s.length > a)
			a = s.length;
		let r = [];
		for (let l = 0; l < a; l++) {
			r[l] = [];
			r[l][0] = e[l];
			r[l][1] = t[l];
			r[l][2] = i[l];
			r[l][3] = s[l]
		}
		this._ui.nameList.array = r;
		this._ui.nameList.refresh()
	}
	getNamesByType(e) {
		let t = this.totalData.award.list;
		let i;
		if (t && t.length) {
			for (let s = 0; s < t.length; s++) {
				if (t[s].type == e) {
					i = t[s].names
				}
			}
		}
		if (!i || !i.length) {
			i = ["Để trống chỗ"]
		}
		return i
	}
	timerFun1(e, t) {
		let i;
		if (e >= b_.ONEDAYMILLISECONDS) {
			i = b_.getDayHourStr(e)
		} else {
			i = b_.getCdTimeStrByMs(e)
		}
		this._ui.cdPrizeTimeLab.text = i
	}
	dataRec(e) {
		this.srvData = e.koiFish;
		if (this.lotterys.length < this.lotteryNum) {
			this.lotteryNum = 0
		}
		this.updateInfo();
		this.checkDot();
		this.checkMainBtn()
	}
	srvDataRec(e) {
		this.totalData = e.status;
		this.updateNameList()
	}
	numChange(e) {
		if (!this.srvData || !e.lottery)
			return;
		let t = this.srvData.lotterys;
		if (!t)
			return;
		for (let i = 0; i < t.length; i++) {
			if (t[i]._idHex == e.lottery._idHex) {
				t[i] = e.lottery;
				break
			}
		}
	}
	get actTpl() {
		return od.getTplInfo(nd.KOI_FISH_BASE, this.srvData.activityId)
	}
	get lotterys() {
		if (!this.srvData)
			return [];
		return this.srvData.lotterys
	}
	isOpenServer() {
		if (!this.srvData)
			return false;
		return this.srvData.activityId
	}
	checkDot() {
		let e = false;
		if (this.checkOpen()) {
			let t = this.lotterys;
			if (t.length > this.lotteryNum) {
				e = true
			}
		}
		cd.setDot(dd.KOI_FISH_ENTER, this, e);
		cd.setDot(dd.KOI_FISH_NUM_ENTER, this, e);
		cd.setDot(dd.ACT_FOLD2, this, e);
		cd.setDot(dd.CITY_ENTER, this, e)
	}
	checkMainBtn() {
		if (this.checkOpen()) {
			FM.mainCityMan.setTopBtnOpen(bb.KOIFISH, this, true);
			let e = this.actTpl;
			if (e) {
				let t = this.data.openSrvTime + b_.getActEndTime(e.endDay, e.endTime) - this.data.serverTime;
				vg.start(t, this, this.timerFun, 1, null)
			}
		} else {
			FM.mainCityMan.setTopBtnOpen(bb.KOIFISH, this, false);
			vg.stop(this, this.timerFun)
		}
	}
	timerFun(e, t) {
		let i;
		if (e >= b_.ONEDAYMILLISECONDS) {
			i = b_.getDayHourStr(e)
		} else {
			i = b_.getCdTimeStrByMs(e)
		}
		if (this.isOpen) {
			this._ui.cdActTimeLab.text = i
		}
		FM.mainCityMan.showKoiFishCdTime(i)
	}
}
class AN extends g {
	constructor() {
		super("PVPViFa");
		this._isShare0 = false;
		this._isShare1 = false;
		this._isShare2 = false
	}
	static getIns() {
		if (!this._ins) {
			this._ins = new AN
		}
		return this._ins
	}
	openOverUi(e, t) {
		this.overData = e;
		this._isShare0 = false;
		this._isShare1 = false;
		this._isShare2 = false;
		this.play = t;
		this.openUI()
	}
	onClick(e) {
		switch (e.target) {
		case this._ui.btnHurt:
			if (!this.play) {
				FM.noticeMan.showNotice(WM.getLanCodeTip(10419));
				return
			}
			KI.getIns().show(this.play);
			break;
		case this._ui.btnChatShare:
			if (!this.play) {
				FM.noticeMan.showNotice(WM.getLanCodeTip(10420));
				return
			}
			if (this._isShare0) {
				FM.noticeMan.showNotice("Đã chia sẻ thành công");
				return
			}
			this._isShare0 = true;
			FM.chatMan.chatToServer(Zg.TPYE_ZONE, this.getChatContent());
			FM.noticeMan.showNotice(WM.getLanCodeTip(10421));
			break;
		case this._ui.btnKuaFuShare:
			if (this._isShare1) {
				FM.noticeMan.showNotice("Đã chia sẻ thành công");
				return
			}
			this._isShare1 = true;
			let t = Zg.isCanSaveState();
			let i = null;
			if (t == 1) {
				i = Zg.TYPE_NEW_HAND
			} else if (t == 2) {
				i = Zg.TYPE_OLD_HAND
			}
			FM.chatMan.chatToServer(i, this.getChatContent());
			FM.noticeMan.showNotice(WM.getLanCodeTip(10421));
			break;
		case this._ui.btnGuildShare:
			if (!this.play) {
				FM.noticeMan.showNotice(WM.getLanCodeTip(10420));
				return
			}
			if (!E_.hasGuild()) {
				FM.noticeMan.showNotice(WM.getLanCodeTip(10422));
				return
			}
			if (this._isShare2) {
				FM.noticeMan.showNotice("Đã chia sẻ thành công");
				return
			}
			this._isShare2 = true;
			FM.chatMan.chatToServer(Zg.TPYE_GUILD, this.getChatContent());
			FM.noticeMan.showNotice(WM.getLanCodeTip(10421));
			break;
		case this._ui.btnVideo:
			if (!this.play) {
				FM.noticeMan.showNotice(WM.getLanCodeTip(10423));
				return
			}
			let s = this.play._idHex;
			this.closeUI();
			FM.videoMan.getVideo(s);
			break
		}
	}
	getChatContent() {
		let e = WM.getLanCodeTip(10424);
		e += qg.getFightChat(this.play._idHex, "[" + this.play.a.ms.profile.name + "VS" + this.play.b.ms.profile.name + "]", this.play.a.ms.srv.code);
		e += WM.getLanCodeTip(10613);
		return e
	}
	initUI() {
		this._ui = this.uiView;
		this.setLayer(1, 1, 1, 1)
	}
	afterClose() {
		this.clearEffect();
		this.play = null;
		FM.battleMan.stopWatch(pd.LEARN_FROM);
		if (FM.learnFromMan.isOpen) {
			FM.learnFromMan.closeUI()
		}
	}
	afterOpen() {
		this._ui.btnKuaFuShare.mouseEnabled = true;
		this._ui.btnKuaFuShare.gray = false;
		let e = Zg.isCanSaveState();
		if (e != 1 && e != 2) {
			this._ui.btnKuaFuShare.mouseEnabled = false;
			this._ui.btnKuaFuShare.gray = true
		}
		this.clearEffect();
		if (this.overData.win) {
			this.showWinEffect()
		} else {
			this.showFailEffect()
		}
	}
	clearEffect() {
		Laya.timer.clear(this, this.showEffect1);
		Laya.timer.clear(this, this.showEffect3);
		Laya.timer.clear(this, this.showEffect4);
		if (this.winEffect1) {
			this.winEffect1.dispose();
			this.winEffect1 = null
		}
		if (this.winEffect2) {
			this.winEffect2.dispose();
			this.winEffect2 = null
		}
		if (this.winEffect3) {
			this.winEffect3.dispose();
			this.winEffect3 = null
		}
		if (this.winEffect4) {
			this.winEffect4.dispose();
			this.winEffect4 = null
		}
		if (this.failEffect) {
			this.failEffect.dispose();
			this.failEffect = null
		}
	}
	showWinEffect() {
		Laya.timer.once(500, this, this.showEffect1);
		this.showEffect2();
		Laya.timer.once(350, this, this.showEffect3);
		Laya.timer.once(500, this, this.showEffect4)
	}
	showEffect1() {
		this.winEffect1 = new k_("UI/shengli_1", true);
		this._ui.boxWin1.addChild(this.winEffect1);
		this.winEffect1.pos(this._ui.width / 2, 68)
	}
	showEffect2() {
		this.winEffect2 = new L_("UI/shengli_2", false);
		this._ui.boxWin2.addChild(this.winEffect2);
		this.winEffect2.pos(this._ui.width / 2, 108)
	}
	showEffect3() {
		this.winEffect3 = new k_("UI/shengli_3", false);
		this._ui.boxWin3.addChild(this.winEffect3);
		this.winEffect3.pos(this._ui.width / 2, 108)
	}
	showEffect4() {
		this.winEffect4 = new k_("UI/shengli_4", true);
		this._ui.boxWin4.addChild(this.winEffect4);
		this.winEffect4.pos(this._ui.width / 2, 58)
	}
	showFailEffect() {
		this.failEffect = new L_("UI/shibai_1", false);
		this._ui.boxFail.addChild(this.failEffect);
		this.failEffect.pos(this._ui.width / 2, 10)
	}
}
