class vN extends g {
	constructor(e = "leichonggift") {
		super(e);
		this.funcId = pd.LEI_PAY
	}
	getCmds() {
		return [d.FUNC_INIT, d.FUNC_OPEN]
	}
	exeCmd(e, t) {
		switch (t) {
		case d.FUNC_INIT:
			this.checkDot();
			this.checkMainBtn();
			break;
		case d.FUNC_OPEN:
			if (e == this.funcId) {
				this.checkDot();
				this.checkMainBtn()
			}
			break
		}
	}
	getMsgs() {
		return [pf.DATA_REC]
	}
	exeMsg(e, t) {
		switch (t) {
		case pf.DATA_REC:
			this.dataRec(e);
			break
		}
	}
	initUI() {
		this._ui = this.uiView;
		this.setLayer(1, 1, 1, 1)
	}
	afterOpen() {
		this.updateInfo();
		this._ui.listTask.scrollTo(0)
	}
	checkOpen(e = true) {
		if (!Laya.Browser.window.ydwxConfig.miniH5 && !Laya.Browser.onQQMiniGame)
			return false;
		if (!this.srvData || !this.actId) {
			return false
		}
		return FM.funcMan.checkFuncOpen(this.funcId, e)
	}
	updateInfo() {
		if (!this.isOpen)
			return;
		if (!this.actId || !this.srvData)
			return;
		let e = od.getTplInfo(nd.LEI_PAY_PRIZE, null, {
				group: this.actTpl.prizeGroup
			});
		let t = [];
		for (let i = 0; i < e.length; i++) {
			t.push({
				tpl: e[i],
				got: this.srvData.gotMap[e[i].id],
				canGet: this.srvData.payValue >= e[i].rmb,
				pay: this.srvData.payValue
			})
		}
		t.sort(this.sortFun);
		this._ui.listTask.array = t
	}
	sortFun(e, t) {
		if (e.got && !t.got) {
			return 1
		} else if (!e.got && t.got) {
			return -1
		}
		if (e.tpl.sort) {
			return e.tpl.sort - t.tpl.sort
		} else {
			return e.tpl.idid - t.tpl.id
		}
	}
	dataRec(e) {
		this.srvData = e.specialPay;
		this.refreshData()
	}
	refreshData() {
		if (!this.srvData)
			return;
		this.setActId(this.srvData.activityId);
		this.checkDot();
		this.checkMainBtn();
		this.updateInfo()
	}
	setActId(e) {
		if (this.actId == e)
			return;
		this.actId = e;
		this.actTpl = od.getTplInfo(nd.LEI_PAY_BASE, e)
	}
	get actDotTypes() {
		return [dd.LEI_PAY, dd.ACT_FOLD2, dd.CITY_ENTER]
	}
	checkDot() {
		let e = this.actDotTypes;
		if (!e || !e.length)
			return;
		let t = false;
		if (this.srvData && this.actId) {
			let e = od.getTplInfo(nd.LEI_PAY_PRIZE, null, {
					group: this.actTpl.prizeGroup
				});
			for (let i = 0; i < e.length; i++) {
				if (!this.srvData.gotMap[e[i].id] && this.srvData.payValue >= e[i].rmb) {
					t = true;
					break
				}
			}
		}
		for (let i = 0; i < e.length; i++) {
			cd.setDot(e[i], this, t)
		}
	}
	checkMainBtn() {
		let e = this.checkOpen(false);
		FM.mainCityMan.setTopBtnOpen(bb.LEI_PAY, this, e);
		let t = this.actTpl;
		vg.stop(this, this.timerFun);
		if (e && t) {
			let e = this.data.openSrvTime + b_.getActEndTime(t.endDay, t.endTime) - this.data.serverTime;
			if (e > 0) {
				vg.start(e, this, this.timerFun, 1, null)
			}
		}
	}
	timerFun(e, t) {
		let i;
		if (e >= b_.ONEDAYMILLISECONDS) {
			i = b_.getDayHourStr(e)
		} else {
			i = b_.getCdTimeStrByMs(e)
		}
		FM.mainCityMan.showActCdTime(Rb.LeiPay, i);
		if (this.isOpen) {
			this._ui.cdTimeLab.text = i
		}
	}
}
class wN extends g {
	constructor(e = "LevelGift") {
		super(e);
		this.funcId = pd.LEVEL_GIFT
	}
	getCmds() {
		return [d.FUNC_INIT, d.FUNC_OPEN, d.LEVEL_CHANGE]
	}
	exeCmd(e, t) {
		if (!Laya.Browser.onQQMiniGame)
			return;
		switch (t) {
		case d.FUNC_INIT:
			this.checkDot();
			this.checkMainBtn();
			break;
		case d.FUNC_OPEN:
			if (e == this.funcId) {
				this.checkDot();
				this.checkMainBtn()
			}
			break;
		case d.LEVEL_CHANGE:
			if (this.data.master.level >= 30) {
				this.checkAutoOpen()
			}
			break
		}
	}
	getMsgs() {
		return [md.ACTSHOP_DATA_REC, md.ACTSHOP_ONE_REC]
	}
	exeMsg(e, t) {
		if (!Laya.Browser.onQQMiniGame)
			return;
		switch (t) {
		case md.ACTSHOP_DATA_REC:
			this.shopDataRec(e);
			break;
		case md.ACTSHOP_ONE_REC:
			this.shopOneRec(e);
			break
		}
	}
	onClick(e) {
		switch (e.target) {
		case this._ui.btnClose:
			this.closeUI();
			break
		}
	}
	checkOpen(e = true) {
		if (!Laya.Browser.onQQMiniGame)
			return false;
		if (!this.actId) {
			return false
		}
		return FM.funcMan.checkFuncOpen(this.funcId, e)
	}
	initUI() {
		this._ui = this.uiView;
		this.setLayer(1, 1, 1, 1)
	}
	afterOpen() {
		this.updateInfo();
		this._ui.listCell.scrollTo(0);
		this.checkDot()
	}
	updateInfo() {
		if (!this.actId || !this.srvData)
			return;
		let e = this.srvData.items;
		let t = [];
		let i = this.data.master.level;
		for (let s = 0; s < e.length; s++) {
			this.setTpl(e[s]);
			e[s].got = false;
			if (e[s].tpl.limitNum <= e[s].purchaseNum) {
				e[s].got = true
			}
			e[s].canGet = i >= e[s].tpl.levelGift;
			t.push(e[s])
		}
		t.sort(this.sortFun);
		this._ui.listCell.array = t
	}
	sortFun(e, t) {
		if (!e.got && t.got) {
			return -1
		} else if (e.got && !t.got) {
			return 1
		}
		return e.tpl.power - t.tpl.power
	}
	shopDataRec(e) {
		let t = e.cycleMall;
		let i = false;
		if (t && t.malls) {
			let e = t.malls;
			for (let t in e) {
				if (e[t].funcId == this.funcId) {
					this.srvData = e[t];
					i = true
				}
			}
		}
		if (!i && this.srvData && this.srvData.activityId) {
			this.srvData.activityId = 0
		}
		this.refreshData()
	}
	shopOneRec(e) {
		let t = e.mall;
		if (t && t.funcId == this.funcId) {
			this.srvData = t;
			this.refreshData()
		}
	}
	refreshData() {
		if (!this.srvData)
			return;
		this.setActId(this.srvData.activityId);
		this.checkDot();
		this.checkMainBtn();
		if (this.isOpen) {
			this.updateInfo()
		}
	}
	checkAutoOpen() {
		if (Laya.LocalStorage.getItem("levelGiftRmbOpen") == "1") {
			return
		}
		if (this.checkOpen(false)) {
			if (this.srvData) {
				let e = this.srvData.items;
				let t = true;
				for (let i = 0; i < e.length; i++) {
					this.setTpl(e[i]);
					if (e[i].purchaseNum > 0) {
						t = false;
						break
					}
				}
				if (t)
					this.openUI();
				Laya.LocalStorage.setItem("levelGiftRmbOpen", "1")
			}
		}
	}
	setActId(e) {
		if (this.actId == e)
			return;
		this.actId = e;
		this.actTpl = od.getTplInfo(nd.ACT_SHOP_BASE, e)
	}
	setTpl(e) {
		if (e) {
			if (e.tpl) {
				return
			}
			e.tpl = od.getTplInfo(nd.ACT_SHOP_GOODS, e.tid)
		}
	}
	get actDotTypes() {
		return [dd.LEVELGIFT]
	}
	checkMainBtn() {
		let e = this.checkOpen(false);
		if (e) {
			e = false;
			let t = this.srvData.items;
			for (let i = 0; i < t.length; i++) {
				this.setTpl(t[i]);
				if (t[i].tpl.limitNum > t[i].purchaseNum) {
					e = true;
					break
				}
			}
		}
		FM.mainCityMan.setTopBtnOpen(bb.LEVELGIFT, this, e)
	}
	checkDot() {
		let e = this.actDotTypes;
		if (!e || !e.length)
			return;
		let t = false;
		if (this.srvData && this.actId) {
			if (!this._ui)
				t = true;
			if (t) {
				t = false;
				let e = this.srvData.items;
				for (let i = 0; i < e.length; i++) {
					this.setTpl(e[i]);
					if (e[i].purchaseNum < e[i].tpl.limitNum) {
						t = true;
						break
					}
				}
			}
		}
		for (let i = 0; i < e.length; i++) {
			cd.setDot(e[i], this, t)
		}
	}
}
