class $N extends g {
	constructor(e = "RaceTower2") {
		super(e);
		this._curType = 0;
		this._isShowRwd = true
	}
	static getIns() {
		if (!this._ins) {
			this._ins = new $N
		}
		return this._ins
	}
	getMsgs() {
		return [$p.TOWER_MOP_RESULT_REC, Cp.TOWER_MOP_RESULT_REC]
	}
	exeMsg(e, t) {
		switch (t) {
		case $p.TOWER_MOP_RESULT_REC:
			if (this.isOpen) {
				this.closeUI()
			}
			break;
		case Cp.TOWER_MOP_RESULT_REC:
			if (this.isOpen) {
				this.closeUI()
			}
			break
		}
	}
	getCmds() {
		return [d.TOWER_MOP_STATUS_CHANGE]
	}
	exeCmd(e, t) {
		switch (t) {
		case d.TOWER_MOP_STATUS_CHANGE:
			this._curType = e.type;
			this.freshPanel();
			break
		}
	}
	onClick(e) {
		switch (e.target) {
		case this._ui.btnClose:
			this.closeUI();
			break;
		case this._ui.btnBattle:
			this.stopAutoFight();
			break;
		case this._ui.arrowDown:
			this._isShowRwd = !this._isShowRwd;
			this.freshPanel();
			break
		}
	}
	initUI() {
		this._ui = this.uiView;
		this.setLayer(0, 1, 1, 2);
		this._ui.arrowDown.visible = false
	}
	show(e = 0) {
		this._curType = e;
		this.openUI()
	}
	afterOpen() {
		this.freshPanel()
	}
	stopAutoFight() {
		if (this._curType == 0) {
			this.sendMsg($p.TOWER_MOP_STATUS_REQ, {})
		} else {
			this.sendMsg(Cp.TOWER_MOP_STATUS_REQ, {})
		}
	}
	static getFightHeroList(e) {
		let t = e.split("#");
		let i = [];
		for (let s = 0; s < t.length; s++) {
			let e = {};
			let a = t[s].split(":");
			e.tid = parseInt(a[0]);
			e.level = parseInt(a[1]);
			i.push(e)
		}
		return i
	}
	freshPanel() {
		if (!this.isOpen)
			return;
		if (this._curType == 0) {
			if (!DT.mopStatus)
				return;
			if (!DT.mopStatus.moping)
				return
		} else {
			if (!DT.mopNewStatus)
				return;
			if (!DT.mopNewStatus.moping)
				return
		}
		if (this._curType == 0) {
			this._ui.beginTowerTitle.text = "Bắt đầu Linh Lung Tháp số tầng:";
			this._ui.curTowerTitle.text = "Trước mắt Linh Lung Tháp số tầng:"
		} else {
			if (this._curType == 1) {
				this._ui.beginTowerTitle.text = "Bắt đầu nhân tộc tháp số tầng:";
				this._ui.curTowerTitle.text = "Trước mắt nhân tộc tháp số tầng:"
			}
			if (this._curType == 2) {
				this._ui.beginTowerTitle.text = "Bắt đầu Tiên Tộc tháp số tầng:";
				this._ui.curTowerTitle.text = "Trước mắt Tiên Tộc tháp số tầng:"
			}
			if (this._curType == 3) {
				this._ui.beginTowerTitle.text = "Bắt đầu yêu tộc tháp số tầng:";
				this._ui.curTowerTitle.text = "Trước mắt yêu tộc tháp số tầng:"
			}
			if (this._curType == 4) {
				this._ui.beginTowerTitle.text = "Bắt đầu Thần tộc tháp số tầng:";
				this._ui.curTowerTitle.text = "Trước mắt Thần tộc tháp số tầng:"
			}
			if (this._curType == 5) {
				this._ui.beginTowerTitle.text = "Bắt đầu ma tộc tháp số tầng:";
				this._ui.curTowerTitle.text = "Trước mắt ma tộc tháp số tầng:"
			}
		}
		if (this._curType == 0) {
			this._ui.beginTowerTxt.text = WM.getLanCodeTip(20306, [DT.mopStatus.startFloor]);
			this._ui.curTowerTxt.text = WM.getLanCodeTip(20306, [DT.mopStatus.currentFloor]);
			this._ui.completeTowerTxt.text = WM.getLanCodeTip(20306, [DT.mopStatus.pass])
		} else {
			this._ui.beginTowerTxt.text = WM.getLanCodeTip(20306, [DT.mopNewStatus.startFloor]);
			this._ui.curTowerTxt.text = WM.getLanCodeTip(20306, [DT.mopNewStatus.currentFloor]);
			this._ui.completeTowerTxt.text = WM.getLanCodeTip(20306, [DT.mopNewStatus.pass])
		}
		let e = null;
		if (this._curType == 0) {
			e = od.getTplInfo(nd.TOWER, DT.mopStatus.currentFloor)
		} else {
			let t = nd.RACE_TOWER_TYPE_1;
			if (this._curType - 1 == 1)
				t = nd.RACE_TOWER_TYPE_2;
			if (this._curType - 1 == 2)
				t = nd.RACE_TOWER_TYPE_3;
			if (this._curType - 1 == 3)
				t = nd.RACE_TOWER_TYPE_4;
			if (this._curType - 1 == 4)
				t = nd.RACE_TOWER_TYPE_5;
			e = od.getTplInfo(t, DT.mopNewStatus.currentFloor)
		}
		let t = $N.getFightHeroList(e.preview);
		let i = [];
		for (let r = 0; r < t.length; r++) {
			let e = new yg(t[r]);
			i.push(e)
		}
		this._ui.teamList.array = i;
		this._ui.backCurTZ.height = this._ui.backTopTitle.height + this._ui.teamList.height + 5 + 10;
		this._ui.showCurRwdBox.visible = false;
		this._ui.selfRwdContainBox.height = this._ui.backCurTZ.height;
		this._ui.arrowDown.skin = "img/preUI/Arrow_1.png";
		if (this._isShowRwd) {
			let t = cP.splitStr2Arr(e.firstRwd);
			t = t.concat(cP.splitStr2Arr(e.rwd));
			this._ui.listRwd.array = t;
			this._ui.showCurRwdBox.visible = true;
			this._ui.showCurRwdBox.y = this._ui.backTopTitle.height + this._ui.teamList.height + 5 + 15;
			this._ui.backCurTZ.height = this._ui.backTopTitle.height + this._ui.teamList.height + 5 + this._ui.rwdTitleContainBox.height + 10 + this._ui.showCurRwdBox.height;
			this._ui.arrowDown.skin = "img/preUI/Arrow_0.png";
			this._ui.selfRwdContainBox.height = this._ui.backCurTZ.height
		}
		let s = [];
		if (this._curType == 0 && DT.mopStatus.reward) {
			s = DT.mopStatus.reward.items
		} else if (this._curType > 0 && DT.mopNewStatus.reward) {
			s = DT.mopNewStatus.reward.items
		}
		this._ui.totalRwdList.array = s;
		this._ui.showAllRwdBox.y = this._ui.selfRwdContainBox.y + this._ui.selfRwdContainBox.height + 10;
		let a = Math.ceil(s.length / 5);
		this._ui.totalRwdList.height = this._ui.totalRwdList.getCell(0).height * a + this._ui.totalRwdList.spaceY * (a - 1) + 5;
		this._ui.showAllRwdBox.height = this._ui.totalRwdList.y + this._ui.totalRwdList.height + 5;
		this._ui.backAllTZ.height = this._ui.btnBattle.y - this._ui.containPanel.y - 20 - this._ui.btnBattle.height * .5 - this._ui.showAllRwdBox.y;
		this._ui.containBox.height = this._ui.showAllRwdBox.y + this._ui.showAllRwdBox.height;
		this._ui.noAnythingBox.visible = false;
		if (s.length <= 0) {
			this._ui.noAnythingBox.visible = true;
			this._ui.noAnythingBox.x = (this._ui.backAllTZ.width - this._ui.noAnythingBox.width) * .5;
			this._ui.noAnythingBox.y = this._ui.backAllTopTitle.height + (this._ui.backAllTZ.height - this._ui.backAllTopTitle.height - this._ui.noAnythingBox.height) * .5
		}
	}
}
