	checkDayNight() {
		let e = (new Date).getHours();
		if (e >= 18 || e < 6) {
			for (let e = 1; e <= 5; e++) {
				let t = this._ui["imgLayer" + e];
				if (!t)
					continue;
				t.skin = "common/city" + e + "_night.png"
			}
			this._ui.imgScroll.skin = "img/mainCity/scroll_night.png";
			this._ui.imgIsland.skin = "img/mainCity/island_night.png"
		} else {
			for (let e = 1; e <= 5; e++) {
				let t = this._ui["imgLayer" + e];
				if (!t)
					continue;
				t.skin = "common/city" + e + ".png"
			}
			this._ui.imgScroll.skin = "img/mainCity/scroll.png";
			this._ui.imgIsland.skin = "img/mainCity/island.png"
		}
	}
	startDrag() {
		if (FM.guideMan.isOpen)
			return;
		var e = this._dragLayer.width - this._ui.width;
		this._dragLayer.startDrag(new Laya.Rectangle(-e, 0, e, 0), true);
		this._dragLayer.on(Laya.Event.DRAG_MOVE, this, this.onDragMove);
		this._dragLayer.on(Laya.Event.DRAG_END, this, this.onDragEnd);
		this._dragMoving = false
	}
	onDragMove(e) {
		var t = this._dragLayer.x / (this._dragLayer.width - this._ui.width);
		for (var i = 0; i < this._layers.length; i++) {
			var s = this._layers[i];
			if (s === this._dragLayer)
				continue;
			s.x = t * (s.width - this._ui.width)
		}
		if (e) {
			this._dragMoving = true
		}
	}
	onDragEnd(e) {
		this._dragLayer.off(Laya.Event.DRAG_MOVE, this, this.onDragMove);
		this._dragLayer.off(Laya.Event.DRAG_END, this, this.onDragEnd);
		this._dragMoving = false
	}
	scroll2X(e) {
		this._dragLayer.x = -e;
		this.onDragMove(null)
	}
	checkScroll2Btn(e) {
		let t;
		for (let l = 0; l < this._layers.length; l++) {
			if (e.parent == this._layers[l]) {
				t = this._layers[l];
				break
			}
		}
		if (!t)
			return;
		let i = e.x + e.pivotX;
		let s = (t.width / 2 - i) / (t.width - this._ui.width);
		if (s < 0)
			s = 0;
		if (s > 1)
			s = 1;
		for (var a = 0; a < this._layers.length; a++) {
			var r = this._layers[a];
			if (r === this._dragLayer)
				continue;
			r.x = s * (r.width - this._ui.width)
		}
	}
	btnBindBox(e, t) {
		this.boxBtnArr.push({
			box: e,
			btn: t
		});
		e.on(Laya.Event.MOUSE_DOWN, this, this.boxBtnScaleIn);
		e.on(Laya.Event.MOUSE_UP, this, this.boxBtnScaleOut);
		e.on(Laya.Event.MOUSE_OUT, this, this.boxBtnScaleOut);
		e.on(Laya.Event.CLICK, this, this.boxBtnClick);
		t.on(Laya.Event.MOUSE_DOWN, this, this.boxBtnScaleIn);
		t.on(Laya.Event.MOUSE_UP, this, this.boxBtnScaleOut);
		t.on(Laya.Event.MOUSE_OUT, this, this.boxBtnScaleOut);
		t.on(Laya.Event.CLICK, this, this.boxBtnClick)
	}
	getBtnByBox(e) {
		for (let t = 0; t < this.boxBtnArr.length; t++) {
			if (this.boxBtnArr[t].box == e) {
				return this.boxBtnArr[t].btn
			}
		}
	}
	boxBtnScaleIn(e) {
		let t;
		if (e.target instanceof Laya.Box) {
			t = this.getBtnByBox(e.target)
		} else {
			t = e.target
		}
		Laya.Tween.to(t, {
			scaleX: 1.1,
			scaleY: 1.1
		}, 100, undefined, undefined, 0, true)
	}
	boxBtnScaleOut(e) {
		let t;
		if (e.target instanceof Laya.Box) {
			t = this.getBtnByBox(e.target)
		} else {
			t = e.target
		}
		Laya.Tween.to(t, {
			scaleX: 1,
			scaleY: 1
		}, 100, undefined, undefined, 0, true)
	}
