class Ov extends g {
	constructor() {
		super();
		this._noticeStrs = [];
		this._noticeBars = [];
		this._noticePool = [];
		this._bulletinStrs = [];
		this._bulletinBars = [];
		this._bulletinPool = [];
		this.hasTimeFun = false
	}
	getMsgs() {
		return [vd.NOTICE_REC, vd.BULLETIN_REC]
	}
	exeMsg(e, t) {
		switch (t) {
		case vd.NOTICE_REC:
			this.noticeRec(e);
			break;
		case vd.BULLETIN_REC:
			this.bulletinRec(e);
			break
		}
	}
	noticeRec(e) {
		if (e.contentId == 0) {
			this.showNotice(e.paramList[0])
		} else {
			let t = od.getTplInfo(nd.NOTICE, e.contentId);
			if (!t) {
				this.showNotice("Vô hiệu hệ thống nhắc nhở số hiệu:" + e.contentId)
			}
			this.showNotice(t.content)
		}
	}
	showNotice(e) {
		for (let t = 0; t < this._noticeBars.length; t++) {
			if (this._noticeBars[t].content == e)
				return
		}
		this._noticeStrs.unshift(e);
		this.nextNotice()
	}
	nextNotice() {
		if (this._noticeBars.length >= 3)
			return;
		if (this._noticeStrs.length <= 0)
			return;
		var e = this._noticeStrs.pop();
		var t;
		if (this._noticePool.length) {
			t = this._noticePool.pop()
		} else {
			t = new wv
		}
		_.addChild(t, 2);
		t.setContent(e);
		this._noticeBars.unshift(t);
		this.tweenNotice()
	}
	tweenNotice() {
		if (this._noticeBars.length == 0)
			return;
		for (var e = 0; e < this._noticeBars.length; e++) {
			var t = this._noticeBars[e];
			Laya.Tween.clearTween(t);
			t.x = (t.parent["width"] - t.width) / 2;
			t.y = 350 - e * 45;
			Laya.Tween.to(t, {
				y: t.y - 45
			}, 500)
		}
	}
	removeNotice(e) {
		e.removeSelf();
		this._noticeBars.splice(this._noticeBars.indexOf(e), 1);
		this._noticePool.push(e);
		this.nextNotice()
	}
	bulletinRec(e) {
		let t;
		if (e.contentId) {
			let i = od.getTplInfo(nd.BULLETIN, e.contentId);
			if (!i)
				return;
			t = WM.replaceDS(i.content, e.paramList)
		} else {
			if (e.paramList && e.paramList[0] && e.paramList[0] != "") {
				t = e.paramList[0]
			}
		}
		this.showbulletin(WM.str2Html(t, 2212))
	}
	showbulletin(e) {
		this._bulletinStrs.unshift(e);
		this.nextbulletin()
	}
	nextbulletin() {
		if (this._bulletinStrs.length <= 0) {
			if (this._bulletinBars.length == 0) {
				this.stopTimeFun()
			}
			return
		}
		let e = this._bulletinBars[this._bulletinBars.length - 1];
		if (e && e.x + e.textWidth > e.parent["width"] - 60) {
			return
		}
		var t = this._bulletinStrs.pop();
		if (this._bulletinPool.length) {
			e = this._bulletinPool.pop()
		} else {
			e = new vv
		}
		FM.topBarMan.addChildBulletin(e);
		e.setContent(t);
		this._bulletinBars.push(e);
		e.startTween();
		if (!this.hasTimeFun) {
			this.startTimeFun()
		}
	}
	startTimeFun() {
		this.hasTimeFun = true;
		Laya.timer.loop(1e3, this, this.nextbulletin);
		FM.topBarMan.showBulletinBack()
	}
	stopTimeFun() {
		this.hasTimeFun = false;
		Laya.timer.clear(this, this.nextbulletin);
		FM.topBarMan.hideBulletinBack()
	}
	removeBulletin(e) {
		e.removeSelf();
		this._bulletinBars.splice(this._bulletinBars.indexOf(e), 1);
		this._bulletinPool.push(e)
	}
}
class Bv {
	static set notepadData(e) {
		this._notepadData = e;
		if (e.activityId && e.activityId != this.actTpl.id) {
			this._actTpl = od.getTplInfo(nd.PALACE_NOTEPAD_BASE, e.activityId);
			let t = od.getTplInfo(nd.PALACE_NOTEPAD_PRIZE, null, {
					group: this.actTpl.prizeGroup
				});
			this._maxPoint = t[t.length - 1].point
		}
	}
	static get notepadData() {
		return this._notepadData
	}
	static get actTpl() {
		return this._actTpl
	}
	static set point(e) {
		if (!this._notepadData)
			return;
		this._notepadData.point = e
	}
	static get point() {
		if (!this._notepadData)
			return 0;
		return this._notepadData.point
	}
	static get isMaxPoint() {
		return this.point >= this._maxPoint
	}
	static get activeAdvanced() {
		if (!this._notepadData)
			return 0;
		return this._notepadData.activeAdvanced
	}
	static isBaseGot(e) {
		if (!this._notepadData)
			return false;
		return this._notepadData.baseGot[e]
	}
	static isAdvanceGot(e) {
		if (!this._notepadData)
			return false;
		return this._notepadData.advanceGot[e]
	}
	static isEnterShow() {
		return this._notepadData && this._notepadData.activityId
	}
	static isDot() {
		return this.isPrizeDot()
	}
	static isPrizeDot() {
		if (!this.actTpl)
			return false;
		let e = od.getTplInfo(nd.PALACE_NOTEPAD_PRIZE, null, {
				group: this.actTpl.prizeGroup
			});
		let t = this.point;
		for (let i = 0; i < e.length; i++) {
			if (t >= e[i].point) {
				if (!this.isBaseGot(e[i].id)) {
					return true
				}
				if (this.activeAdvanced && !this.isAdvanceGot(e[i].id)) {
					return true
				}
			}
		}
		return false
	}
}
