class Fv extends xI {
	constructor(e = "ExpeditionPosition") {
		super(e)
	}
	static getIns() {
		if (!this._insExpeditionPalaceBoss) {
			this._insExpeditionPalaceBoss = new Fv
		}
		return this._insExpeditionPalaceBoss
	}
	initUI() {
		this._ui = this.uiView;
		this.initPanel()
	}
	setData() {
		let e = FM.palaceMan.getHeroHPExtend();
		this.heroList = [];
		let t = this.data.bag.hero.list;
		for (let s = 0; s < t.length; s++) {
			let e = t[s];
			let i = FM.palaceMan.getHeroHPObj(e.idHex);
			if (i) {
				let t = V_.getAttr(e);
				let s = t[n_.HP];
				this.heroList.push({
					heroData: e,
					hire: 0,
					hpExtend: i.hpRate * s
				})
			} else {
				this.heroList.push({
					heroData: e,
					hire: 0,
					hpExtend: undefined
				})
			}
		}
		t = FM.palaceMan.getCanHireHeros();
		for (let s = 0; s < t.length; s++) {
			let e = new yg(t[s]);
			let i = FM.palaceMan.getHeroHPObj(e.idHex);
			let a = V_.getAttr(e);
			let r = a[n_.HP];
			this.heroList.push({
				heroData: e,
				hire: 1,
				hpExtend: i != null ? i.hpRate * r : undefined
			})
		}
		this.heroList.sort(this.heroSort);
		this.posData = f_.clonePosData(this.funcId, this.heroList);
		let i = this.posData.grids;
		for (let s = 0; s < i.length; ) {
			let e = i[s]._idHex;
			let t = FM.palaceMan.getHeroHPObj(e);
			if (t && t.hpRate <= 0) {
				i.splice(s, 1)
			} else {
				s++
			}
		}
	}
	heroSort(e, t) {
		if (e.hire != t.hire) {
			return t.hire - e.hire
		} else {
			if (e.heroData.baseTpl.star != t.heroData.baseTpl.star) {
				return t.heroData.baseTpl.star - e.heroData.baseTpl.star
			} else {
				if (t.heroData.level != e.heroData.level) {
					return t.heroData.level - e.heroData.level
				} else {
					if (e.heroData.baseTpl.camp != t.heroData.baseTpl.camp) {
						return t.heroData.baseTpl.camp - e.heroData.baseTpl.camp
					} else {
						if (e.heroData.baseTpl.job != t.heroData.baseTpl.job) {
							return e.heroData.baseTpl.job - t.heroData.baseTpl.job
						}
						return e.heroData.baseTpl.id - t.heroData.baseTpl.id
					}
				}
			}
		}
	}
	onHeroClick(e, t) {
		if (e.type != Laya.Event.CLICK)
			return;
		let i = this._ui.listHero.getItem(t);
		if (i.hpExtend != undefined && i.hpExtend <= 0) {
			return
		}
		let s = this._ui.listHero.getCell(t);
		if (i.select) {
			this.takeOffHero(i.heroData)
		} else {
			this.takeOnHero(i.heroData, s.localToGlobal(new Laya.Point))
		}
	}
	oneKeyTakeOnHeros() {
		let e = [];
		for (let t = 0; t < this.heroList.length; t++) {
			let i = this.heroList[t];
			if (i.hpExtend != undefined && i.hpExtend <= 0)
				continue;
			e.push(i)
		}
		this.posData.grids = f_.getOnekeyHero(this.posData.tid, e);
		this.freshPanel()
	}
}
