class Wv extends g {
	constructor() {
		super("PalaceCure");
		this.showType = 0;
		this.isHasDeadHero = false;
		this.isHasBloodHero = false
	}
	static getIns() {
		if (!this._ins) {
			this._ins = new Wv
		}
		return this._ins
	}
	onClick(e) {
		switch (e.target) {
		case this._ui.btnClose:
			this.closeUI();
			break;
		case this._ui.btnFuHuo:
			if (this.cellData.type == 6) {
				if (!this.isHasBloodHero) {
					QM.show(WM.getLanCodeTip(10466), Laya.Utils.bind(this.fuHuoClickCallBack, this))
				} else {
					FM.palaceMan.callAction(jv.PalaceCure, this.cellData.x, -1);
					this.closeUI()
				}
			} else if (this.cellData.type == 7) {
				if (!this.isHasDeadHero) {
					QM.show(WM.getLanCodeTip(10467), Laya.Utils.bind(this.fuHuoClickCallBack, this))
				} else {
					FM.palaceMan.callAction(jv.PalaceCure, this.cellData.x, -1);
					this.closeUI()
				}
			}
			break
		}
	}
	fuHuoClickCallBack(e) {
		if (e) {
			FM.palaceMan.callAction(jv.PalaceCure, this.cellData.x, -1);
			this.closeUI()
		} else {}
	}
	initUI() {
		this._ui = this.uiView;
		this.setLayer(1, 1, 1, 1);
		this._ui.htmlText.style.width = this._ui.htmlText.width
	}
	show(e, t) {
		this.level = e;
		this.cellData = t;
		this.openUI()
	}
	afterOpen() {
		if (this.cellData.type == 6) {
			this._ui.typeImage.skin = "img/Palace/cure.png";
			this._ui.tileName.text = WM.getLanCodeTip(10468);
			this._ui.htmlText.style.color = "#804015";
			this._ui.htmlText.innerHTML = WM.getLanCodeTip(10469, [WM.getHtmlByColor("30%", m.PALACE_CURE_NUM_GREEN)]);
			this._ui.downTitleName.text = WM.getLanCodeTip(10468);
			let e = this._ui.btnFuHuo;
			e.label = WM.getLanCodeTip(10470)
		} else if (this.cellData.type == 7) {
			this._ui.typeImage.skin = "img/Palace/resurrect.png";
			this._ui.tileName.text = WM.getLanCodeTip(10471);
			this._ui.htmlText.style.color = "#804015";
			this._ui.htmlText.innerHTML = WM.getLanCodeTip(10472, [WM.getHtmlByColor("70%", m.PALACE_CURE_NUM_GREEN), WM.getHtmlByColor("100%", m.PALACE_CURE_NUM_GREEN)]);
			this._ui.downTitleName.text = WM.getLanCodeTip(10471);
			let e = this._ui.btnFuHuo;
			e.label = WM.getLanCodeTip(10473)
		}
		let e = FM.palaceMan.getHeroHPExtend();
		this.isHasDeadHero = false;
		this.heroList = [];
		let t = this.data.bag.hero.list;
		for (let i = 0; i < t.length; i++) {
			let e = t[i];
			let s = FM.palaceMan.getHeroHPObj(e.idHex);
			this.heroList.push({
				heroData: e,
				hire: 0,
				hpExtend: s
			});
			if (s) {
				if (s && s.hpRate <= 0) {
					this.isHasDeadHero = true
				}
				if (s && s.hpRate < 1 && s.hpRate > 0) {
					this.isHasBloodHero = true
				}
			}
		}
		t = FM.palaceMan.getCanHireHeros();
		for (let i = 0; i < t.length; i++) {
			let e = new yg(t[i]);
			let s = FM.palaceMan.getHeroHPObj(e.idHex);
			this.heroList.push({
				heroData: e,
				cp: e.power,
				hire: 1,
				hpExtend: s
			});
			if (s && s.hpRate <= 0) {
				this.isHasDeadHero = true
			}
			if (s && s.hpRate < 1 && s.hpRate > 0) {
				this.isHasBloodHero = true
			}
		}
		this.heroList.sort(this.heroSort);
		this._ui.list.array = this.heroList
	}
	heroSort(e, t) {
		if (e.hire != t.hire) {
			return t.hire - e.hire
		} else {
			if (e.heroData.baseTpl.star != t.heroData.baseTpl.star) {
				return t.heroData.baseTpl.star - e.heroData.baseTpl.star
			} else if (e.hpExtend && e.hpExtend.hpRate <= 0) {
				return -1e3
			} else if (t.hpExtend && t.hpExtend.hpRate <= 0) {
				return 1e3
			} else {
				let i = e.heroData.level;
				let s = t.heroData.level;
				if (e.heroData.shareLevel > 0) {
					i = e.heroData.shareLevel
				}
				if (t.heroData.shareLevel > 0) {
					s = t.heroData.shareLevel
				}
				if (s != i) {
					return s - i
				} else {
					if (e.heroData.baseTpl.camp != t.heroData.baseTpl.camp) {
						return t.heroData.baseTpl.camp - e.heroData.baseTpl.camp
					} else {
						if (e.heroData.baseTpl.job != t.heroData.baseTpl.job) {
							return e.heroData.baseTpl.job - t.heroData.baseTpl.job
						}
						return e.heroData.baseTpl.id - t.heroData.baseTpl.id
					}
				}
			}
		}
	}
}
