	playPoSuiAnimation() {
		let e = this.lastSelectLevel;
		let t = this.lastSelectCellData;
		this._isPlayPoSuiAni = true;
		let i = this.getLevelAllCellKey(e, t.x);
		if (i.length > 0) {
			if (this.poSui1) {
				this.poSui1.removeSelf();
				this.poSui1 = null
			}
			if (this.poSui2) {
				this.poSui2.removeSelf();
				this.poSui2 = null
			}
			for (let e = 0; e < i.length; e++) {
				let t = i[e];
				let s = this.getGirdContent(t);
				if (s) {
					let i = this.getGridTopContent(t);
					let a = this.getGridDownImage(t);
					let r = this.getGridDownContent(t);
					let l = this.getArrowImage(t);
					Laya.Tween.to(l, {
						alpha: 0
					}, 100);
					Laya.Tween.to(i, {
						alpha: 0
					}, 100);
					Laya.Tween.to(a, {
						alpha: 0
					}, 100);
					if (e == 0) {
						this.poSui1 = new k_("palace/tianjietaizisui", false);
						this.poSui1.on(Laya.Event.STOPPED, this, this.poSuiComplete, [t]);
						this.poSui1.x = r.x + r.width * .5;
						this.poSui1.y = r.y + r.height * .5;
						s.addChild(this.poSui1)
					} else if (e == 1) {
						this.poSui2 = new k_("palace/tianjietaizisui", false);
						this.poSui2.x = r.x + r.width * .5;
						this.poSui2.y = r.y + r.height * .5;
						s.addChild(this.poSui2)
					}
				}
			}
		} else {
			this.playPoSuiAnimationComplete()
		}
	}
	poSuiComplete(e) {
		let t = this.getGirdContent(e);
		t.visible = false;
		t.alpha = 1;
		let i = this.getGridTopContent(e);
		i.alpha = 1;
		let s = this.getGridDownImage(e);
		s.alpha = 1;
		let a = this.getArrowImage(e);
		a.alpha = 1;
		if (this.poSui1) {
			this.poSui1.removeSelf();
			this.poSui1 = null
		}
		if (this.poSui2) {
			this.poSui2.removeSelf();
			this.poSui2 = null
		}
		this.playPoSuiAnimationComplete()
	}
