class uw extends Cb {
	constructor() {
		super("plantTree3");
		this.isOpenDot = false
	}
	tabSelectCheck() {
		return true
	}
	tabVisibleCheck() {
		return this.checkOpen(false)
	}
	getCmds() {
		return [d.FUNC_INIT, d.FUNC_OPEN]
	}
	exeCmd(e, t) {
		switch (t) {
		case d.FUNC_INIT:
			this.checkMainBtn();
			break;
		case d.FUNC_OPEN:
			if (e == pd.PLANT_TREE_SHOP) {
				this.checkMainBtn();
				this.checkDot()
			}
			break
		}
	}
	getMsgs() {
		return [Lf.SHOP_REC, Lf.DATA_REC]
	}
	exeMsg(e, t) {
		switch (t) {
		case Lf.SHOP_REC:
			if (!FM.plantTreeMan.srvData) {
				FM.plantTreeMan.srvData = {}
			}
			if (!FM.plantTreeMan.srvData.mall) {
				FM.plantTreeMan.srvData.mall = {}
			}
			FM.plantTreeMan.srvData.mall.items = e.data.items;
			this.shopDataRec();
			break;
		case Lf.DATA_REC:
			FM.plantTreeMan.srvData = e.data;
			this.shopDataRec();
			break
		}
	}
	initUI() {
		this._ui = this.uiView
	}
	checkOpen(e = true) {
		if (!FM.funcMan.checkFuncOpen(pd.PLANT_TREE_GAME, e))
			return false;
		if (!FM.plantTreeMan.srvData)
			return false;
		if (!FM.plantTreeMan.srvData || !this.actId) {
			if (e) {
				FM.noticeMan.showNotice(WM.getLanCodeTip(10020))
			}
			return false
		}
		return true
	}
	afterOpen() {
		this.refreshPanel();
		this.refreshTime();
		this.isOpenDot = false;
		this.checkDot()
	}
	afterClose() {
		vg.stop(this, this.timerFun)
	}
	refreshPanel() {
		if (!this.isOpen)
			return;
		if (!FM.plantTreeMan.srvData || !FM.plantTreeMan.srvData.mall.items)
			return;
		let e = FM.plantTreeMan.srvData.mall.items;
		let t = [];
		for (let i = 0; i < e.length; i++) {
			if (!e[i].tpl)
				e[i].tpl = od.getTplInfo(nd.PLANT_TREE_SHOP, e[i].tid);
			t.push(e[i])
		}
		t.sort(this.sortFun);
		this._ui.listCell.array = t;
		this._ui.listCell.scrollTo(0)
	}
	sortFun(e, t) {
		let i = e.tpl.limitNum > 0 && e.purchaseNum >= e.tpl.limitNum;
		let s = t.tpl.limitNum > 0 && t.purchaseNum >= t.tpl.limitNum;
		if (!i && s) {
			return -1
		} else if (!s && i) {
			return 1
		} else {
			return e.tpl.id - t.tpl.id
		}
	}
	refreshTime() {
		let e = 0;
		if (this.actTpl && this.actTpl.endTime) {
			e = b_.getActTimeByStr(this.actTpl.endTime).getTime() - b_.getTimeStamp()
		}
		if (e > 0) {
			vg.start(e, this, this.timerFun)
		}
	}
	timerFun(e, t) {
		if (e >= b_.ONEDAYMILLISECONDS) {
			this._ui.labTime.text = b_.getDayHourStr(e)
		} else {
			this._ui.labTime.text = b_.getCdTimeStrByMs(e)
		}
	}
	shopDataRec() {
		this.setActId(FM.plantTreeMan.srvData.activityId);
		this.checkMainBtn();
		this.refreshPanel();
		this.checkDot()
	}
	checkDot() {
		let e = false;
		if (this.isOpenDot && this.tabVisibleCheck()) {
			e = true
		}
		cd.setDot(dd.PLANT_TREE_SHOP, this, e);
		cd.setDot(dd.PLANT_TREE_ENTER, this, e);
		cd.setDot(dd.ACT_FOLD2, this, e);
		cd.setDot(dd.CITY_ENTER, this, e)
	}
	setActId(e) {
		if (this.actId == e)
			return;
		this.actId = e;
		this.actTpl = od.getTplInfo(nd.PLANT_TREE_ACT_BASE, this.actId)
	}
	checkMainBtn() {
		FM.mainCityMan.setTopBtnOpen(bb.PLANT_TREE, this, this.tabVisibleCheck())
	}
}
class cw extends Cb {
	constructor(e = "plantTree4") {
		super(e);
		this.funcId = pd.PLANT_TREE_GAME
	}
	tabSelectCheck() {
		return true
	}
	tabVisibleCheck() {
		return this.checkOpen(false)
	}
	getCmds() {
		return [d.TASK_INIT, d.FUNC_INIT, d.FUNC_OPEN, d.TASK_CHANGE_ITEM]
	}
	getMsgs() {
		return [Lf.DATA_REC]
	}
	exeCmd(e, t) {
		switch (t) {
		case d.TASK_INIT:
			this.checkDot();
			break;
		case d.FUNC_INIT:
			this.checkMainBtn();
			this.checkDot();
			break;
		case d.FUNC_OPEN:
			if (e == pd.SPRING_GAME) {
				this.checkMainBtn();
				this.checkDot()
			}
			break;
		case d.TASK_CHANGE_ITEM:
			this.taskChange(e);
			break
		}
	}
	exeMsg(e, t) {
		switch (t) {
		case Lf.DATA_REC:
			this.dataRec();
			break
		}
	}
	initUI() {
		this.ui = this.uiView
	}
	checkOpen(e) {
		if (!this.actId || !this.actTpl)
			return false;
		if (!FM.plantTreeMan.srvData)
			return false;
		return FM.funcMan.checkFuncOpen(this.funcId, e)
	}
	afterOpen() {
		this.refreshActId();
		this.ui.listTask.scrollTo(0)
	}
	afterClose() {
		vg.stop(this, this.timerFun)
	}
	openUI() {
		FM.limitTimeMan.openAct(this.funcId);
		super.openUI()
	}
	dataRec() {
		this.setActId(FM.plantTreeMan.srvData.activityId);
		this.checkMainBtn();
		this.checkDot()
	}
	refreshActId() {
		if (!this.isOpen)
			return;
		if (!this.actId)
			return;
		let e = od.getTplInfo(nd.PLANT_TREE_TASK, null, {
				group: this.actTpl.group
			});
		let t = [];
		for (let i = 0; i < e.length; i++) {
			t.push({
				funcId: this.funcId,
				tpl: e[i]
			})
		}
		this.ui.listTask.array = t;
		this.refreshList();
		this.refreshTime()
	}
	refreshTime() {
		let e = b_.getActTimeByStr(this.actTpl.endTime).getTime() - b_.getTimeStamp();
		vg.start(e, this, this.timerFun, 1, null)
	}
	rwdGot(e) {
		let t = this.data.task.getTaskItem(this.funcId, e);
		if (t && t.rewardGot) {
			return true
		}
		return false
	}
	rwdDone(e) {
		let t = this.data.task.getTaskItem(this.funcId, e);
		if (t && t.done) {
			return true
		}
		return false
	}
	refreshList() {
		if (!this.isOpen)
			return;
		let e = this.ui.listTask.array;
		for (let t = 0; t < e.length; t++) {
			e[t].got = this.rwdGot(e[t].tpl.taskId);
			e[t].done = this.rwdDone(e[t].tpl.taskId)
		}
		e.sort(this.taskSort);
		this.ui.listTask.refresh()
	}
	taskSort(e, t) {
		if (e.got != t.got) {
			if (!e.got && t.got) {
				return -1
			} else {
				return 1
			}
		} else {
			if (e.done != t.done) {
				if (!e.done && t.done) {
					return 1
				} else {
					return -1
				}
			}
			return e.tpl.taskId - t.tpl.taskId
		}
	}
	timerFun(e, t) {
		if (e >= b_.ONEDAYMILLISECONDS) {
			this.ui.labTime.text = b_.getDayHourStr(e)
		} else {
			this.ui.labTime.text = b_.getCdTimeStrByMs(e)
		}
	}
	taskChange(e) {
		if (e.funcId != this.funcId)
			return;
		this.refreshList();
		this.checkDot()
	}
	setActId(e) {
		if (this.actId == e)
			return;
		this.actId = e;
		this.actTpl = od.getTplInfo(nd.PLANT_TREE_ACT_BASE, this.actId)
	}
	checkMainBtn() {
		FM.mainCityMan.setTopBtnOpen(bb.PLANT_TREE, this, this.tabVisibleCheck())
	}
	checkDot() {
		if (!this.actId)
			return;
		let e = false;
		if (this.actId) {
			let t = od.getTplInfo(nd.PLANT_TREE_TASK, null, {
					group: this.actTpl.group
				});
			for (let i = 0; i < t.length; i++) {
				let s = this.data.task.getTaskItem(this.funcId, t[i].taskId);
				if (s && s.done && !s.rewardGot) {
					e = true;
					break
				}
			}
		}
		cd.setDot(dd.PLANT_TREE_ENTER, this, e);
		cd.setDot(dd.PLANT_TREE_TASK, this, e);
		cd.setDot(dd.ACT_FOLD2, this, e);
		cd.setDot(dd.CITY_ENTER, this, e)
	}
}
