class Sw extends Cb {
	constructor(e, t = "ActShop") {
		super(t);
		this.funcId = e
	}
	tabSelectCheck() {
		return true
	}
	tabVisibleCheck() {
		return this.checkOpen(false)
	}
	getCmds() {
		return [d.FUNC_INIT, d.FUNC_OPEN, d.LOGIN_DAYS_CHANGE]
	}
	exeCmd(e, t) {
		switch (t) {
		case d.FUNC_INIT:
			this.checkDot();
			break;
		case d.FUNC_OPEN:
			if (e == this.funcId) {
				this.checkDot()
			}
			break;
		case d.LOGIN_DAYS_CHANGE:
			this.refreshCdTimeLab();
			break
		}
	}
	getMsgs() {
		return [md.ACTDATAESHOP_DATA_REC, md.ACTDATAESHOP_ONE_REC]
	}
	exeMsg(e, t) {
		switch (t) {
		case md.ACTDATAESHOP_DATA_REC:
			this.shopDataRec(e);
			break;
		case md.ACTDATAESHOP_ONE_REC:
			this.shopOneRec(e);
			break
		}
	}
	initUI() {
		this._ui = this.uiView
	}
	afterOpen() {
		this._ui.imgBanner.skin = "icon/hengfu" + this.actTpl.hengFu + ".jpg";
		this.refreshCdTimeLab();
		this.updateInfo();
		this._ui.listCell.tweenTo(0, 0)
	}
	afterClose() {
		vg.stop(this, this.refreshCdTime);
		super.afterClose()
	}
	checkOpen(e = false) {
		if (!this.actId) {
			return false
		}
		return FM.funcMan.checkFuncOpen(this.funcId, e)
	}
	updateInfo() {
		if (!this.actId || !this.srvData)
			return;
		let e = [];
		let t = this.srvData.items;
		let i = this.data.master.level;
		let s = this.data.master.vip;
		for (let a = 0; a < t.length; a++) {
			this.setTpl(t[a]);
			if (t[a].tpl.minLv && i < t[a].tpl.minLv) {
				continue
			}
			if (t[a].tpl.maxLv && i > t[a].tpl.maxLv) {
				continue
			}
			if (t[a].tpl.minVip && s < t[a].tpl.minVip) {
				continue
			}
			if (t[a].tpl.maxVip && s > t[a].tpl.maxVip) {
				continue
			}
			let r = {};
			r.purchaseNum = t[a].purchaseNum;
			r.tid = t[a].tid;
			r.type = 1;
			r.tpl = t[a].tpl;
			if (r.tpl.limitNum < 0) {
				r.sellOut = false
			} else {
				r.sellOut = r.tpl.limitNum <= r.purchaseNum
			}
			e.push(r)
		}
		e.sort(this.sortFun);
		this._ui.listCell.array = e
	}
	sortFun(e, t) {
		if (!e.sellOut && t.sellOut) {
			return -1
		} else if (e.sellOut && !t.sellOut) {
			return 1
		}
		return e.tpl.power - t.tpl.power
	}
	shopDataRec(e) {
		let t = e.cycleDateMall;
		let i = false;
		if (t && t.malls) {
			let e = t.malls;
			for (let t in e) {
				if (e[t].funcId == this.funcId) {
					this.srvData = e[t];
					i = true
				}
			}
		}
		if (!i && this.srvData && this.srvData.activityId) {
			this.srvData.activityId = 0
		}
		this.refreshData()
	}
	shopOneRec(e) {
		let t = e.mall;
		if (t && t.funcId == this.funcId) {
			this.srvData = t;
			try {
				this.refreshData()
			} catch (e) {}
		}
	}
	refreshData() {
		if (!this.srvData)
			return;
		this.setActId(this.srvData.activityId);
		this.checkDot();
		this.checkActOpen();
		if (this.isOpen) {
			this.updateInfo()
		}
	}
	setActId(e) {
		if (this.actId == e)
			return;
		this.actId = e;
		this.actTpl = od.getTplInfo(nd.ACT_DATE_SHOP_BASE, e)
	}
	setTpl(e) {
		if (e) {
			if (e.tpl) {
				return
			}
			e.tpl = od.getTplInfo(nd.ACT_DATE_SHOP_GOODS, e.tid)
		}
	}
	get actDotTypes() {
		return []
	}
	checkDot() {
		let e = false;
		if (this.srvData && this.actId) {
			if (!e) {
				let t = this.srvData.items;
				for (let i = 0; i < t.length; i++) {
					this.setTpl(t[i]);
					if (t[i].tpl.price == 0 && t[i].purchaseNum < t[i].tpl.limit) {
						e = true;
						break
					}
				}
			}
		}
		let t = this.actDotTypes;
		for (let i = 0; i < t.length; i++) {
			cd.setDot(t[i], this, e)
		}
	}
	refreshCdTimeLab() {
		if (!this.isOpen)
			return;
		vg.stop(this, this.refreshCdTime);
		let e = this.actTpl;
		if (e) {
			let e = b_.getActTimeByStr(this.actTpl.endTime).getTime() - this.data.serverTime;
			if (e > 0) {
				vg.start(e, this, this.refreshCdTime, 1, null)
			}
		}
	}
	refreshCdTime(e, t, i) {
		if (e >= b_.ONEDAYMILLISECONDS) {
			i = b_.getDayHourStr(e)
		} else {
			i = b_.getCdTimeStrByMs(e)
		}
		this._ui.labTime.text = i
	}
	checkActOpen() {}
}
