class Aw extends Cb {
	constructor(e = "qumorenwu") {
		super(e);
		this.funcId = pd.QUMO_TASK
	}
	tabSelectCheck() {
		return true
	}
	tabVisibleCheck() {
		return this.checkOpen(false)
	}
	getCmds() {
		return [d.TASK_INIT, d.FUNC_INIT, d.FUNC_OPEN, d.TASK_CHANGE_ITEM]
	}
	getMsgs() {
		return [Qf.DATA_REC, Qf.BOSS_TASK_REC]
	}
	exeCmd(e, t) {
		switch (t) {
		case d.TASK_INIT:
			this.checkDot();
			break;
		case d.FUNC_INIT:
			this.checkMainBtn();
			this.checkDot();
			break;
		case d.FUNC_OPEN:
			if (e == pd.QUMO_TASK) {
				this.checkMainBtn();
				this.checkDot()
			}
			break;
		case d.TASK_CHANGE_ITEM:
			this.taskChange(e);
			break
		}
	}
	exeMsg(e, t) {
		switch (t) {
		case Qf.DATA_REC:
			this.dataRec(e.data);
			break;
		case Qf.BOSS_TASK_REC:
			this.taskDataRec(e);
			break
		}
	}
	initUI() {
		this._ui = this.uiView;
		cd.regDot(dd.QUMO_TASK_GET, this._ui.dotGet)
	}
	onClick(e) {
		switch (e.target) {
		case this._ui.btnGet:
			this.getPrize();
			break
		}
	}
	getPrize() {
		this.sendMsg(Qf.BOSS_TASK_PRIZE_REQ, {
			tid: this.getPrizeTid()
		})
	}
	getPrizeTid() {
		if (!this.srvData.task)
			return 1;
		let e = od.getTplInfo(nd.QUMO_TASK_RWD);
		for (let t = 0; t < e.length; t++) {
			if (!this.srvData.task.gotMap[e[t].id]) {
				return e[t].id
			}
		}
		return e[e.length - 1].id
	}
	checkOpen(e) {
		if (!this.actId || !this.actTpl)
			return false;
		return FM.funcMan.checkFuncOpen(this.funcId, e)
	}
	afterOpen() {
		this.refreshActId()
	}
	afterClose() {
		vg.stop(this, this.timerFun)
	}
	dataRec(e) {
		this.srvData = e;
		this.setActId(e.activityId);
		this.checkMainBtn();
		this.checkDot();
		this.refreshRwd()
	}
	taskDataRec(e) {
		if (!this.srvData)
			return;
		this.srvData.task = e.task;
		this.checkDot();
		this.refreshRwd()
	}
	refreshActId() {
		if (!this.isOpen)
			return;
		if (!this.actId)
			return;
		this.refreshList();
		this.refreshTime();
		this.refreshRwd()
	}
	refreshRwd() {
		if (!this.isOpen)
			return;
		if (!this.actId)
			return;
		let e = this.getPrizeTid();
		let t = od.getTplInfo(nd.QUMO_TASK_RWD, e);
		this._ui.labOneNums.text = t.taskNum + "";
		this._ui.labTaskNum.text = (this.srvData.task.taskDone > t.taskNum ? t.taskNum : this.srvData.task.taskDone) + "";
		Tb.addItemGrid(cP.splitStr2Arr(t.rwd)[0], this._ui.boxPrize);
		if (t.taskNum > this.srvData.task.taskDone) {
			this._ui.btnGet.gray = true;
			this._ui.btnGet.label = "Nhận lấy"
		} else {
			if (this.srvData.task.gotMap[t.id]) {
				this._ui.btnGet.gray = true;
				this._ui.btnGet.label = "Đã nhận"
			} else {
				this._ui.btnGet.gray = false;
				this._ui.btnGet.label = "Nhận lấy"
			}
		}
	}
	refreshTime() {
		if (!this.isOpen)
			return;
		if (!this.actId)
			return;
		let e = b_.getActTimeByStr(this.actTpl.endTime).getTime() - b_.getTimeStamp();
		vg.start(e, this, this.timerFun, 1, null)
	}
	rwdGot(e) {
		let t = this.data.task.getTaskItem(this.funcId, e);
		if (t && t.rewardGot) {
			return true
		}
		return false
	}
	rwdDone(e) {
		let t = this.data.task.getTaskItem(this.funcId, e);
		if (t && t.done) {
			return true
		}
		return false
	}
	refreshList() {
		if (!this.isOpen)
			return;
		let e = od.getTplInfo(nd.QUMO_TASK);
		let t = [];
		for (let i = 0; i < e.length; i++) {
			t.push({
				funcId: this.funcId,
				tpl: e[i]
			})
		}
		for (let i = 0; i < t.length; i++) {
			t[i].got = this.rwdGot(t[i].tpl.taskId);
			t[i].done = this.rwdDone(t[i].tpl.taskId)
		}
		t = this.checkArr(t);
		t.sort(this.taskSort);
		this._ui.listCell.array = t
	}
	checkArr(e) {
		let t = [];
		let i = -1;
		let s = true;
		for (let a = 0; a < e.length; a++) {
			if (i != e[a].tpl.group) {
				i = e[a].tpl.group;
				if (!s && e[a - 1]) {
					t.push(e[a - 1])
				}
				s = false
			}
			if (e[a].got)
				continue;
			if (s)
				continue;
			t.push(e[a]);
			s = true
		}
		if (!s && e[e.length - 1]) {
			t.push(e[e.length - 1])
		}
		return t
	}
	taskSort(e, t) {
		if (e.got != t.got) {
			if (!e.got && t.got) {
				return -1
			} else {
				return 1
			}
		} else {
			if (e.done != t.done) {
				if (!e.done && t.done) {
					return 1
				} else {
					return -1
				}
			}
			return e.tpl.taskId - t.tpl.taskId
		}
	}
	timerFun(e, t) {
		let i;
		if (e >= b_.ONEDAYMILLISECONDS) {
			i = b_.getDayHourStr(e)
		} else {
			i = b_.getCdTimeStrByMs(e)
		}
		this._ui.labCdTime.text = i
	}
	taskChange(e) {
		if (e.funcId != this.funcId)
			return;
		this.refreshList();
		this.checkDot()
	}
	setActId(e) {
		if (this.actId == e)
			return;
		this.actId = e;
		this.actTpl = od.getTplInfo(nd.QUMO_BASE, this.actId)
	}
	checkMainBtn() {
		FM.mainCityMan.setTopBtnOpen(bb.QUMO, this, this.tabVisibleCheck())
	}
	checkDot() {
		if (!this.actId)
			return;
		let e = false;
		let t = false;
		if (this.actId) {
			let i = od.getTplInfo(nd.QUMO_TASK);
			for (let t = 0; t < i.length; t++) {
				let s = this.data.task.getTaskItem(this.funcId, i[t].taskId);
				if (s && s.done && !s.rewardGot) {
					e = true;
					break
				}
			}
			let s = od.getTplInfo(nd.QUMO_TASK_RWD);
			if (s) {
				for (let e = 0; e < s.length; e++) {
					if (!this.srvData.task.gotMap[s[e].id] && this.srvData.task.taskDone >= s[e].taskNum) {
						t = true;
						break
					}
				}
			}
		}
		cd.setDot(dd.QUMO_ENTER, this, e && t);
		cd.setDot(dd.QUMO_TASK_ENTER, this, e && t);
		cd.setDot(dd.QUMO_TASK_GET, this, t)
	}
}
