class vw extends Cb {
	constructor() {
		super("DailyGift")
	}
	tabSelectCheck() {
		return true
	}
	tabVisibleCheck() {
		return this.checkOpen(false)
	}
	getCmds() {
		return [d.FUNC_INIT, d.FUNC_OPEN, d.VIP_CHANGE]
	}
	exeCmd(e, t) {
		switch (t) {
		case d.FUNC_INIT:
			this.checkMainBtn();
			break;
		case d.FUNC_OPEN:
			if (e == pd.DAILY_GIFT) {
				this.checkMainBtn()
			}
			break;
		case d.VIP_CHANGE:
			this.vipChange();
			break
		}
	}
	getMsgs() {
		return [xp.RECHARGE_DATA_REC, xp.DAILY_GIFT_DATA_REC]
	}
	exeMsg(e, t) {
		switch (t) {
		case xp.RECHARGE_DATA_REC:
			this.rechargeDataRec(e);
			break;
		case xp.DAILY_GIFT_DATA_REC:
			this.dailyGiftDataRec(e);
			break
		}
	}
	onClick(e) {
		switch (e.target) {
		case this._ui.btnGetRwd:
			this.getRwdClick();
			break;
		case this._ui.btnBuy:
			if (!this.isShowAllBuyBtn) {
				FM.noticeMan.showNotice(WM.getLanCodeTip(10506));
				return
			}
			FM.payMan.payOrderReq(this.buyAllTpl.payItemId);
			break;
		case this._ui.btnShop:
			QT.getIns().showShopIndex(gg.DAILYGIFTINDEX);
			break
		}
	}
	initUI() {
		this._ui = this.uiView;
		N_.addEffect("zawu/saoguang", this._ui.btnShop)
	}
	checkOpen(e = true) {
		return FM.funcMan.checkFuncOpen(pd.DAILY_GIFT, e)
	}
	afterOpen() {
		this.refreshPanel()
	}
	vipChange() {
		if (!this._ui || !this.data.master)
			return;
		this._ui.txtViplv.text = "VIP " + this.data.master.vip;
		this._ui.txtViplv.x = 17;
		this._ui.txtViplv.y = 75;
		this._ui.txtViplv.width = 100;
		this._ui.txtViplv.height = 26;
		this._ui.txtViplv.fontSize = 20;
		this._ui.txtViplv.align = "center"
	}
	rechargeDataRec(e) {
		this.srvData = e.pay.dailyGift;
		this.checkDot()
	}
	dailyGiftDataRec(e) {
		this.srvData = e.dailyGift;
		this.refreshPanel();
		this.checkDot()
	}
	get canGetRwd() {
		return this.srvData && !this.srvData.getDailyReward
	}
	getBuyNum(e) {
		if (!this.srvData)
			return 0;
		if (!this.srvData.giftMap[e])
			return 0;
		return this.srvData.giftMap[e].num
	}
	refreshPanel() {
		if (!this.isOpen)
			return;
		this._ui.dotRwd.visible = this.canGetRwd;
		let e = od.getTplInfo(nd.DAILY_GIFT);
		let t = [];
		for (let i = 0; i < e.length; i++) {
			if (e[i].allBuyType == 1) {
				this.buyAllTpl = e[i];
				continue
			}
			if (this.srvData.giftMap[e[i].id]) {
				t.push({
					tpl: e[i],
					buyNum: this.getBuyNum(e[i].id)
				})
			}
		}
		this.isShowAllBuyBtn = true;
		for (let i = 0; i < t.length; i++) {
			if (!this.isShowAllBuyBtnFun(t[i])) {
				this.isShowAllBuyBtn = false
			}
		}
		this._ui.btnBuy.gray = true;
		if (this.isShowAllBuyBtn) {
			this._ui.btnBuy.gray = false
		}
		this._ui.listCell.array = t
	}
	isShowAllBuyBtnFun(e) {
		return e.tpl.limitNum - e.buyNum > 0
	}
	getRwdClick() {
		this.sendMsg(xp.DAILY_GIFT_GET_RWD_REQ)
	}
	checkMainBtn() {
		FM.mainCityMan.setTopBtnOpen(bb.RECHARGE, this, this.tabVisibleCheck())
	}
	checkDot() {
		let e = this.canGetRwd;
		cd.setDot(dd.DAILY_GIFT_ENTER, this, e);
		cd.setDot(dd.RECHARGE_ENTER, this, e);
		cd.setDot(dd.CITY_ENTER, this, e)
	}
}
