		if (!this.isOpen || !this.actTpl)
			return;
		let t = od.getTplInfo(nd.DATELOGIN_GOODS, null, {
				group: this.actTpl.shopGroup
			});
		let i = t[e - 1];
		if (!i)
			return;
		this.chooseTpl = i;
		this._ui.btnGet.gray = false;
		this._ui["grid" + (e - 1)].addChildAt(this._ui.imgSelectMask, 0);
