class dO extends g {
	constructor(e = "SevenDay3") {
		super(e)
	}
	initUI() {
		this._ui = this.uiView;
		this.setLayer(1, 1, 1, 1)
	}
	afterOpen() {
		this.updateInfo();
		this.checkCdTime()
	}
	getCmds() {
		return [d.FUNC_OPEN]
	}
	exeCmd(e, t) {
		switch (t) {
		case d.FUNC_OPEN:
			if (e == pd.SEVEN_DAY3) {
				this.checkEnterBtn();
				this.checkDot()
			}
			break;
		default:
			break
		}
	}
	getMsgs() {
		return [Pf.DATA_REC]
	}
	exeMsg(e, t) {
		switch (t) {
		case Pf.DATA_REC:
			this.dataRec(e);
			break
		}
	}
	dataRec(e) {
		this.srvData = e.data;
		this.setActId(this.srvData.activityId);
		this.checkEnterBtn();
		this.updateInfo();
		this.checkDot();
		this.checkCdTime()
	}
	checkOpen(e = false) {
		return FM.funcMan.checkFuncOpen(pd.SEVEN_DAY3, e)
	}
	checkEnterBtn() {
		let e = true;
		if (!this.srvData || !this.actId || !this.checkOpen()) {
			e = false
		}
		FM.mainCityMan.setTopBtnOpen(bb.SEVEN_DAY3, this, e)
	}
	onClick(e) {
		let t = e.target;
		switch (t) {
		case this._ui.btnClose:
			this.closeUI();
			break
		}
	}
	checkCdTime() {
		if (this.actTpl) {
			let e = b_.getActTimeByStr(this.actTpl.exstartTime);
			let t = b_.getActTimeByStr(this.actTpl.exendTime);
			let i = b_.getActTimeByStr(this.actTpl.rwdstartTime);
			let s = b_.getActTimeByStr(this.actTpl.rwdendTime);
			let a = i.getTime() - this.data.serverTime;
			let r = t.getTime() - this.data.serverTime;
			vg.stop(this, this.timerFuncOpen);
			vg.stop(this, this.timerFuncClose);
			if (a > 0) {
				vg.start(a, this, this.timerFuncOpen);
				if (this._ui) {
					this._ui.timeSuffix.text = "Sau nhưng nhận lấy"
				}
			} else if (r > 0) {
				vg.start(r, this, this.timerFuncClose);
				if (this._ui) {
					this._ui.timeSuffix.text = "Sau quan bế"
				}
			} else {
				if (this._ui) {
					this._ui.timeSuffix.text = "";
					this._ui.cdTimeLab.text = ""
				}
				FM.mainCityMan.showActCdTime(Rb.SEVENDAY3, null)
			}
		}
	}
	timerFunc(e) {
		let t;
		if (e >= b_.ONEDAYMILLISECONDS) {
			t = b_.getDayHourStr(e)
		} else {
			t = b_.getCdTimeStrByMs(e)
		}
		if (this._ui) {
			this._ui.cdTimeLab.text = t
		}
		return t
	}
	timerFuncClose(e, t, i) {
		let s = this.timerFunc(e);
		FM.mainCityMan.showActCdTime(Rb.SEVENDAY3, s)
	}
	timerFuncOpen(e, t, i) {
		this.timerFunc(e);
		if (this.actTpl) {
			let e = b_.getActTimeByStr(this.actTpl.exendTime);
			let t = e.getTime() - this.data.serverTime;
			let i;
			if (t >= b_.ONEDAYMILLISECONDS) {
				i = b_.getDayHourStr(t)
			} else {
				i = b_.getCdTimeStrByMs(t)
			}
			FM.mainCityMan.showActCdTime(Rb.SEVENDAY3, i)
		}
	}
	updateInfo() {
		if (!this.srvData || !this.actTpl) {
			return
		}
		if (!this._ui) {
			return
		}
		let e = od.getTplInfo(nd.NEW_SEVEN_LOGIN_REWARD, null, {
				group: this.actTpl.group
			});
		e.sort(this.sortRwd);
		let t = b_.getActTimeByStr(this.actTpl.rwdstartTime);
		let i = b_.getDayEndTimeStamp(t.getTime());
		let s = i - t.getTime();
		let a = this.data.serverTime - t.getTime();
		let r = a - s;
		let l = 1;
		if (r > 0) {
			l = 1 + Math.ceil(r / b_.ONEDAYMILLISECONDS)
		} else if (a < 0) {
			l = 0
		}
		for (let h = 0; h < e.length; h++) {
			let t = e[h].rwd;
			t = cP.splitStr2Arr(t)[0];
			YM.queryItem(t);
			let i = this._ui.box0.getChildByName("box" + (h + 1));
			let s = i.getChildByName("imgIcon");
			s.width = 108;
			s.height = 108;
			s.skin = "";
			let a = i.getChildByName("imgMask");
			let r = i.getChildByName("dayLab");
			let n = i.getChildByName("nameLab");
			let o = i.getChildByName("imgChose");
			n.text = t.baseTpl.name;
			a.visible = this.srvData.gotMap[h + 1];
			r.text = WM.getLanCodeTip(20244, [h + 1]);
			o.visible = this.srvData.gotMap[h + 1] || l >= h + 1;
			let u = Tb.addItemGrid(t, s);
			u.mouseEnabled = false;
			u.hideBg();
			i.offAll();
			i.on(Laya.Event.CLICK, this, this.getReward, [h + 1])
		}
	}
	getReward(e) {
		this.sendMsg(Pf.DATA_REQ, {
			day: e
		})
	}
	checkDot() {
		if (!this.srvData)
			return;
		if (!this.actTpl)
			return;
		let e = b_.getActTimeByStr(this.actTpl.rwdstartTime);
		let t = this.data.serverTime;
		let i = this.data.serverTime - e.getTime();
		let s = false;
		if (i <= 0) {
			s = false
		} else {
			let t = 1;
			let a = b_.getDayEndTimeStamp(e.getTime());
			let r = a - e.getTime();
			let l = i - r;
			if (l > 0) {
				t = 1 + Math.ceil(l / b_.ONEDAYMILLISECONDS);
				t = t > 7 ? 7 : t
			}
			if (!this.srvData.gotMap[t]) {
				s = true
			}
		}
		cd.setDot(dd.SEVEN_DAY3_ENTER, this, s)
	}
	sortRwd(e, t) {
		return e.day - t.day
	}
	setActId(e) {
		if (this.actId == e)
			return;
		this.actId = e;
		this.actTpl = od.getTplInfo(nd.NEW_SEVEN_LOGIN_BASE, this.actId);
		if (!this.actId) {
			vg.stop(this, this.timerFuncOpen);
			vg.stop(this, this.timerFuncClose)
		}
	}
}
