	refreshDailyBox() {
		if (!this.isOpen)
			return;
		if (!this.dailyData)
			return;
		let e = 0;
		let t = od.getTplInfo(nd.MINI_SHARE_DAILY);
		let i = [];
		for (let s = 0; s < t.length; s++) {
			let a = {};
			a.tpl = t[s];
			a.num = this.dailyData.numInvited;
			a.got = this.dailyData.rewardGot[a.tpl.id] ? 1 : 0;
			i.push(a);
			if (a.tpl.num > e) {
				e = a.tpl.num
			}
		}
		i.sort(function (e, t) {
			if (e.got != t.got) {
				return e.got - t.got
			} else {
				return e.tpl.id - t.tpl.id
			}
		});
		this.ui.labNum0.text = "(" + (this.dailyData.numInvited > e ? e : this.dailyData.numInvited) + "/" + e + ")";
		this.ui.listCell0.array = i;
		this.ui.listCell0.scrollTo(0)
	}
