class mO extends g {
	constructor() {
		super("ShenLongMaterial")
	}
	static getIns() {
		if (!this._ins) {
			this._ins = new mO
		}
		return this._ins
	}
	onClick(e) {
		switch (e.target) {
		case this._ui.btnClose:
			this.closeUI();
			break;
		case this._ui.btnSelect:
			this.selectClick();
			break;
		case this._ui.btnOneKey:
			this.oneKeyClick();
			break
		}
	}
	initUI() {
		this._ui = this.uiView;
		this.setLayer(1, 1, 1, 1)
	}
	afterClose() {
		if (this.selectHandler) {
			this.selectHandler.recover();
			this.selectHandler = null
		}
	}
	show(e, t, i) {
		this.openUI();
		this.selectHandler = i;
		this._needNum = t;
		e.sort(this.sortFun);
		this._ui.listCell.array = e;
		this._ui.listCell.scrollTo(0);
		this.freshNum()
	}
	sortFun(e, t) {
		if (e.data && t.data) {
			return e.data.enhanceLevel - t.data.enhanceLevel
		}
		return e.data.tid - t.data.tid
	}
	cellClick(e) {
		if (!e.selected) {
			if (this._selectedList.length >= this._needNum) {
				FM.noticeMan.showNotice("Lựa chọn số lượng đã đủ");
				return
			}
		}
		e.selected = !e.selected;
		this._ui.listCell.refresh();
		this.freshNum()
	}
	freshNum() {
		this._selectedList = [];
		for (let e = 0; e < this._ui.listCell.array.length; e++) {
			let t = this._ui.listCell.array[e];
			if (t.selected) {
				this._selectedList.push(t.data._idHex)
			}
		}
		this._ui.labNum.text = this._selectedList.length + "/" + this._needNum
	}
	selectClick() {
		this.selectHandler.runWith([this._selectedList]);
		this.closeUI()
	}
	oneKeyClick() {
		let e = this._ui.listCell.array;
		let t = 0;
		for (let i = 0; i < e.length; i++) {
			if (e[i].selected) {
				t++
			}
		}
		for (let i = 0; i < e.length; i++) {
			if (e[i].selected)
				continue;
			if (t >= this._needNum)
				break;
			e[i].selected = true;
			t++
		}
		this._ui.listCell.refresh();
		this.freshNum()
	}
}
class IO extends g {
	constructor() {
		super("ShenLongXianJi1");
		this.enabledSureTime = 0
	}
	static getIns() {
		if (!this._ins) {
			this._ins = new IO
		}
		return this._ins
	}
	onClick(e) {
		switch (e.target) {
		case this._ui.btnClose:
			this.closeUI();
			break;
		case this._ui.btnSure:
			let t = [];
			for (let e in this._shenLongDic) {
				t.push(e)
			}
			this.sendMsg(Gf.SACRIFICE_REQ, {
				idList: t
			});
			this.closeUI();
			break;
		case this._ui.btnCancel:
			this.closeUI();
			break
		}
	}
	initUI() {
		this._ui = this.uiView;
		this.setLayer(1, 1, 1, 1)
	}
	afterClose() {
		this.clearBtnSure();
		this._shenLongDic = null
	}
	show(e) {
		this._shenLongDic = e;
		this.openUI();
		let t = [];
		for (let i in e) {
			let s = e[i];
			cP.mergeItems(t, this.getStrongBack(s));
			cP.mergeItems(t, cP.splitStr2CostArr(s.baseTpl.sacrificeItem))
		}
		this._ui.listItem.array = t;
		this._ui.listItem.scrollTo(0)
	}
	getStrongBack(e) {
		let t = [];
		if (!e.enhanceLevel)
			return t;
		let i = od.getTplInfo(nd.SHENLONG_STRONG, null, {
				protoId: e.baseTpl.protoId
			});
		for (let s = 0; s < i.length; s++) {
			if (i[s].level < e.enhanceLevel) {
				cP.mergeItems(t, cP.splitStr2CostArr(i[s].cost))
			}
		}
		return t
	}
	afterOpen() {
		this.checkBtnSure()
	}
	checkBtnSure() {
		if (this.enabledSureTime > 0) {
			Laya.timer.loop(1e3, this, this.refreshBtnSure);
			this.refreshBtnSure()
		}
	}
	refreshBtnSure() {
		if (this.enabledSureTime <= 0) {
			this.clearBtnSure();
			return
		}
		this._ui.btnSure.label = WM.getLanCodeTip(20289, [this.enabledSureTime]);
		this._ui.btnSure.disabled = true;
		this.enabledSureTime--
	}
	clearBtnSure() {
		if (!this._ui.btnSure.disabled) {
			return
		}
		this._ui.btnSure.disabled = false;
		this._ui.btnSure.label = WM.getLanCodeTip(10332);
		this.enabledSureTime = 0;
		Laya.timer.clear(this, this.refreshBtnSure)
	}
}
class TO extends g {
	constructor() {
		super("shenlongxianji")
	}
	static getIns() {
		if (!this._ins) {
			this._ins = new TO
		}
		return this._ins
	}
	getCmds() {
		return [d.ITEM_DELETE]
	}
	exeCmd(e, t) {
		switch (t) {
		case d.ITEM_DELETE:
			if (!this.isOpen)
				return;
			this.refreshView();
			break
		}
	}
	onClick(e) {
		switch (e.target) {
		case this._ui.btnClose:
			this.closeUI();
			break;
		case this._ui.btnSelect:
			this.selectClick();
			break;
		case this._ui.btnOneKey:
			this.oneKeyClick();
			break;
		case this._ui.btnCancel:
			this.onClickCancel();
			break
		}
	}
	initUI() {
		this._ui = this.uiView;
		this.setLayer(1, 1, 1, 1)
	}
	afterOpen() {
		this.refreshView()
	}
	refreshView() {
		if (!this.isOpen)
			return;
		this._needNum = 16;
		let e = this.data.bag.shenLong.list;
		let t = [];
		for (let i = 0; i < e.length; i++) {
			t[i] = {
				data: e[i],
				isSelect: false
			}
		}
		t.sort(this.sortFun);
		this._ui.listShenLong.array = t;
		this._ui.listShenLong.scrollTo(0);
		this.freshNum()
	}
	afterClose() {
		this._selectedDic = null
	}
	sortFun(e, t) {
		if (e.data.baseTpl.quality != t.data.baseTpl.quality) {
			return e.data.baseTpl.quality - t.data.baseTpl.quality
		} else if (e.data.baseTpl.star != t.data.baseTpl.star) {
			return e.data.baseTpl.star - t.data.baseTpl.star
		}
		return e.data.enhanceLevel - t.data.enhanceLevel
	}
	freshNum() {
		this._selectedDic = {};
		this._selectNum = 0;
		for (let e = 0; e < this._ui.listShenLong.array.length; e++) {
			let t = this._ui.listShenLong.array[e];
			if (t.isSelect) {
				this._selectedDic[t.data._idHex] = t.data;
				this._selectNum++
			}
		}
		this._ui.labNum.text = this._selectNum + "/" + this._needNum
	}
	selectClick() {
		if (!this._selectedDic)
			return;
		if (!this._selectNum) {
			FM.noticeMan.showNotice("Không có lựa chọn thần long");
			return
		}
		IO.getIns().show(this._selectedDic)
	}
	onClickCancel() {
		let e = this._ui.listShenLong.array;
		for (let t = 0; t < e.length; t++) {
			e[t].isSelect = false
		}
		this._ui.listShenLong.refresh();
		this.freshNum()
	}
	oneKeyClick() {
		let e = this._ui.listShenLong.array;
		let t = 0;
		for (let i = 0; i < e.length; i++) {
			if (e[i].isSelect) {
				t++
			}
		}
		for (let i = 0; i < e.length; i++) {
			if (e[i].data.baseTpl.star > 1 || e[i].data.baseTpl.quality > 2)
				continue;
			if (e[i].isSelect)
				continue;
			if (t >= this._needNum)
				break;
			e[i].isSelect = true;
			t++
		}
		this._ui.listShenLong.refresh();
		this.freshNum()
	}
}
