		this._ui.tab0Type.selectHandler = Laya.Handler.create(this, this.type0Select, null, false);
		this._ui.tab1Type.selectHandler = Laya.Handler.create(this, this.type1Select, null, false);
		this._ui.list0Call.selectHandler = Laya.Handler.create(this, this.list0CallSelect, null, false);
		this._ui.list0Strong.selectHandler = Laya.Handler.create(this, this.list0StrongSelect, null, false);
		this._ui.list1Long.mouseHandler = Laya.Handler.create(this, this.list1LongSelect, null, false);
		cd.regDot(dd.SHENLONG_STRONG, this._ui.dotType0);
		cd.regDot(dd.SHENLONG_CALL, this._ui.dotCall);
