class NO {
	static set notepadData(e) {
		this._notepadData = e;
		if (e.activityId) {
			this._actTpl = od.getTplInfo(nd.SHILIAN_NOTPAD_BASE, e.activityId);
			let t = od.getTplInfo(nd.SHILIAN_NOTPAD_RWD, null, {
					group: this.actTpl.prizeGroup
				});
			this._maxPoint = t[t.length - 1].point
		}
	}
	static get notepadData() {
		return this._notepadData
	}
	static get actTpl() {
		return this._actTpl
	}
	static set point(e) {
		if (!this._notepadData)
			return;
		this._notepadData.point = e
	}
	static get point() {
		if (!this._notepadData)
			return 0;
		return this._notepadData.point
	}
	static get isMaxPoint() {
		return this.point >= this._maxPoint
	}
	static get activeAdvanced() {
		if (!this._notepadData)
			return 0;
		return this._notepadData.activeAdvanced
	}
	static isBaseGot(e) {
		if (!this._notepadData || !this._notepadData.baseGot)
			return false;
		return this._notepadData.baseGot[e]
	}
	static isAdvanceGot(e) {
		if (!this._notepadData || !this._notepadData.advanceGot)
			return false;
		return this._notepadData.advanceGot[e]
	}
	static isEnterShow() {
		return this._notepadData && this._notepadData.activityId && this._notepadData.isActive
	}
	static isDot() {
		return this.isPrizeDot() || this.isDailyDot() || this.isWeekDot()
	}
	static isPrizeDot() {
		if (!this.actTpl)
			return false;
		let e = od.getTplInfo(nd.SHILIAN_NOTPAD_RWD, null, {
				group: this.actTpl.prizeGroup
			});
		let t = this.point;
		for (let i = 0; i < e.length; i++) {
			if (t >= e[i].point) {
				if (!this.isBaseGot(e[i].id)) {
					return true
				}
				if (this.activeAdvanced && !this.isAdvanceGot(e[i].id)) {
					return true
				}
			}
		}
		return false
	}
	static isDailyDot() {
		if (!this.actTpl || !this._notepadData)
			return false;
		let e = uP.getIns().task.getTaskDataByFuncId(pd.SHILIAN_NODEPAD);
		let t = e.doneList;
		for (let i = 0; i < t.length; i++) {
			let e = od.getTplInfo(nd.SHILIAN_NOTPAD_TASK, t[i].tid);
			if (e.type == 1 && t[i].done && !t[i].rewardGot) {
				return true
			}
		}
		return false
	}
	static isWeekDot() {
		if (!this.actTpl || !this._notepadData)
			return false;
		let e = uP.getIns().task.getTaskDataByFuncId(pd.SHILIAN_NODEPAD);
		let t = e.doneList;
		for (let i = 0; i < t.length; i++) {
			let e = od.getTplInfo(nd.SHILIAN_NOTPAD_TASK, t[i].tid);
			if (e.type == 2 && t[i].done && !t[i].rewardGot) {
				return true
			}
		}
		return false
	}
	static isCompleted(e) {
		return uP.getIns().task.isCompleted(pd.SHILIAN_NODEPAD, e)
	}
	static checkComplete(e) {
		return uP.getIns().task.checkComplete(pd.SHILIAN_NODEPAD, e)
	}
	static getTaskItem(e) {
		return uP.getIns().task.getTaskItem(pd.SHILIAN_NODEPAD, e)
	}
	static get endTime() {
		if (!FM.shiLianMan.actTpl)
			return b_.getTimeStamp();
		return b_.getActTimeByStr(FM.shiLianMan.actTpl.zlEndTime).getTime()
	}
}
