class _B extends g {
	constructor() {
		super("TempleShop1");
		this.SHOPINDEX = 8;
		this.SHOPPROPID = 100024
	}
	static getIns() {
		if (!this._ins) {
			this._ins = new _B
		}
		return this._ins
	}
	getCmds() {
		return [d.ITEM_CHANGE_NUM]
	}
	exeCmd(e, t) {
		if (!this.isOpen)
			return;
		this.updateMoney()
	}
	getMsgs() {
		return [Hp.SHOP_LIST_REC]
	}
	exeMsg(e, t) {
		switch (t) {
		case Hp.SHOP_LIST_REC:
			if (!this.isOpen) {
				return
			}
			let i = e.mallDetail.id;
			gg.setShowData(i, e.mallDetail);
			if (i == this.getNowShopId()) {
				this.updateInfo()
			}
			break
		}
	}
	onClick(e) {
		switch (e.target) {
		case this._ui.btnClose:
			this.closeUI();
			break
		}
	}
	initUI() {
		gg.decodeTpl();
		this._ui = this.uiView;
		this.setLayer(1, 1, 1, 1);
		this._ui.propList.mouseHandler = Laya.Handler.create(this, this.onShopClick, null, false)
	}
	afterOpen() {
		this.updateInfo();
		this._ui.propList.scrollTo(0);
		this.updateMoney()
	}
	getNowShopId() {
		return gg.allShopTabData[this.SHOPINDEX].id
	}
	updateInfo() {
		let e = gg.allShopTabData[this.SHOPINDEX];
		let t = gg.getShowData(e.id);
		if (!t)
			return;
		let i;
		if (t.itemList[0].power == undefined) {
			for (let e = 0; e < t.itemList.length; e++) {
				i = od.getTplInfo(nd.SHOPGOODS, t.itemList[e].tid);
				t.itemList[e].power = i.power
			}
		}
		let s;
		s = t.itemList;
		s.sort(this.sortFun);
		this._ui.propList.array = s
	}
	sortFun(e, t) {
		return e.power - t.power
	}
	updateMoney() {
		this._ui.moneyBox1.dataSource = X_.getTypeData({
				tid: this.SHOPPROPID,
				num: this.data.bag.prop.getNum(this.SHOPPROPID),
				type: c.PROP
			}, false)
	}
	onShopClick(e, t) {
		if (e.type != Laya.Event.CLICK)
			return;
		if (!this._ui.propList.array) {
			let e = gg.allShopTabData[this.SHOPINDEX];
			let t = gg.getShowData(e.id);
			if (!t) {
				i.reportError("normalError", "Hiểu số mệnh con người cửa hàng số liệu không có tăng thêm ra")
			}
			return
		}
		let s = this._ui.propList.getItem(t);
		if (FM.shopMan.canShowDetail(s)) {
			_I.getIns().showBuyDetail(s)
		}
	}
}
