	checkDot() {
		let e = false;
		if (this.checkOpen(false)) {
			e = this.isShowRedPoint
		}
		cd.setDot(dd.VALUE_PACK, this, e);
		cd.setDot(dd.ACT_FOLD2, this, e);
		cd.setDot(dd.CITY_ENTER, this, e)
	}
	get actTpl() {
		if (!this.srvData)
			return null;
		return od.getTplInfo(nd.SUPER_GIFT_BASE, this.srvData.activityId)
	}
	isOpenSrv() {
		return this.srvData && this.srvData.activityId
	}
