		cd.regDot(dd.SPACE_ENTER, this._ui.dotSpace);
		this.setLayer(1, 2);
		if (!i.debug) {
			this._ui.labSrvTime.visible = false;
			this._ui.boxSpeed.visible = false
		} else {
			this._ui.labSrvTime.visible = true;
			this._ui.boxSpeed.visible = true;
			Laya.timer.loop(500, this, this.updateSrvTime)
		}
		this._ui.labSrvTime.on(Laya.Event.DOUBLE_CLICK, this, this.srvDoubleClick);
		this.updateM1HeroExp();
		this._ui.boxBulletin.scrollRect = new Laya.Rectangle(0, 0, this._ui.boxBulletin.width, this._ui.boxBulletin.height);
		this.hideBulletinBack();
