EB.NOT_UNLOCK = "Trước mắt độ khó chưa giải tỏa";
class SB extends g {
	constructor() {
		super("TotemRHZX");
		this._diffs = [];
		this._viewHeight = 0;
		this._bgHeight = 0
	}
	static getIns() {
		if (!this._ins) {
			this._ins = new SB
		}
		return this._ins
	}
	getCmds() {
		return [d.FUSETEM_DIFF_CHOOSE, d.FUSETEM_DIFF_RESET]
	}
	exeCmd(e, t) {
		switch (t) {
		case d.FUSETEM_DIFF_CHOOSE:
		case d.FUSETEM_DIFF_RESET:
			this.diffChange();
			break
		}
	}
	onClick(e) {
		switch (e.target) {
		case this._ui.btnClose:
			this.closeUI();
			break;
		case this._ui.btnCancel:
			this.closeUI();
			break;
		case this._ui.btnSure:
			this.btnSureClick();
			break
		}
	}
	initUI() {
		this._ui = this.uiView;
		this.setLayer(1, 1, 1, 1);
		this._ui.listDiff.mouseHandler = Laya.Handler.create(this, this.diffClick, null, false);
		let e = od.getTplInfo(nd.FUSETEM_DIFF);
		if (!!e && e.length > 0) {
			for (let t = 0; t < e.length; t++) {
				let i = {};
				i.baseTpl = e[t];
				i.isSel = false;
				i.isPreview = false;
				i.isLock = false;
				i.isDot = false;
				i.csAwards = [];
				let s = od.getTplInfo(nd.FUSETEM_CHOOSEAWARD, null, {
						diff: i.baseTpl.id
					});
				for (let e = 0; e < s.length; e++) {
					i.csAwards.push({
						index: e,
						tpl: s[e],
						item: cP.parseItemStr(s[e].award),
						select: false,
						selectFun: Laya.Utils.bind(this.selectFun, this),
						isPreview: false,
						isLock: false
					})
				}
				this._diffs.push(i)
			}
		}
		this._viewHeight = this._ui.height;
		this._bgHeight = this._ui.imgBg.height
	}
	checkOpen(e = true) {
		if (!oL.isAllPass()) {
			if (e)
				FM.noticeMan.showNotice(EB.NOT_ALL_PASS);
			return false
		}
		if (!FM.funcMan.checkFuncOpen(pd.FUSE_TEMPLE, e)) {
			return false
		}
		return true
	}
	afterOpen() {
		let e = 0;
		if (this._isPreview) {
			e = nL.choseDiff - 1
		} else {
			e = nL.lockDiff - 1 - 1;
			if (e < 0) {
				e = 0
			} else if (e > this._diffs.length - 1) {
				e = this._diffs.length - 1
			}
		}
		this.selectDiff(e, true);
		this._ui.listDiff.scrollTo(e);
		let t = SB.SHOW_TPL[this._isPreview ? 1 : 0];
		this._ui.labTitle.text = t.title;
		this._ui.labTitle0.text = t.title0;
		this._ui.labTitle1.text = t.title1;
		this._ui.boxBottom.visible = !this._isPreview;
		this._ui.height = this._isPreview ? this._viewHeight - this._ui.boxBottom.height : this._viewHeight;
		this._ui.imgBg.height = this._isPreview ? this._bgHeight - this._ui.boxBottom.height : this._bgHeight
	}
	show(e) {
		this._isPreview = e;
		this.openUI()
	}
	diffClick(e, t) {
		if (e.type != Laya.Event.CLICK)
			return;
		if (this._ui.listDiff.selectedIndex != t) {
			this.selectDiff(t, false)
		}
	}
	selectDiff(e = 0, t) {
		if (!this.isOpen)
			return;
		this._ui.listDiff.selectedIndex = e;
		let i = null;
		for (let s = 0; s < this._diffs.length; s++) {
			let a = this._diffs[s];
			a.isSel = s == e;
			a.isPreview = this._isPreview;
			a.isLock = a.baseTpl.id >= nL.lockDiff;
			if (!t) {
				a.isDot = s == e ? false : a.isDot
			} else {
				a.isDot = !a.isPreview && s > e && !a.isLock
			}
			if (s == e) {
				i = a
			}
		}
		this._ui.listDiff.array = this._diffs;
		this.refreshDiff(i)
	}
	refreshDiff(e) {
		if (!e)
			return;
		this._selDiff = e;
		for (let t = 0; t < e.csAwards.length; t++) {
			e.csAwards[t].select = false;
			e.csAwards[t].isPreview = e.isPreview;
			e.csAwards[t].isLock = e.isLock
		}
		this._ui.listCell.array = e.csAwards;
		this._ui.listCell.scrollTo(0);
		this._selAward = null;
		this._ui.btnSure.gray = true
	}
	selectFun(e, t) {
		if (t) {
			if (!!this._selAward) {
				this.selectAward(this._selAward.index, false)
			}
			this.selectAward(e, true)
		} else if (!!this._selAward) {
			this.selectAward(e, false)
		}
		this._ui.btnSure.gray = !this._selDiff || !this._selAward
	}
	selectAward(e, t) {
		if (!this._ui.listCell.array)
			return;
		let i = this._ui.listCell.array[e];
		if (!i)
			return;
		i.select = t;
		let s = this._ui.listCell.getCell(i.index);
		if (s) {
			s.udpateSelect()
		}
		this._selAward = t ? i : null
	}
	btnSureClick() {
		if (this._isPreview)
			return;
		if (this._selDiff.isLock) {
			FM.noticeMan.showNotice(EB.NOT_UNLOCK);
			return
		}
		if (!this._selDiff) {
			FM.noticeMan.showNotice(EB.NOT_SEL_DIFF);
			return
		}
		if (!this._selAward) {
			FM.noticeMan.showNotice(EB.NOT_SEL_AWARD);
			return
		}
		this.sendMsg(kf.DIFF_CHOOSE, {
			difficulty: this._selDiff.baseTpl.id,
			pickRwdTid: this._selAward.tpl.id
		})
	}
	diffChange() {
		if (!this.isOpen)
			return;
		this.closeUI()
	}
}
