class LB extends g {
	constructor() {
		super("TotemGKRANK")
	}
	static getIns() {
		if (!this._ins) {
			this._ins = new LB
		}
		return this._ins
	}
	getCmds() {
		return [d.FUSETEM_DIFF_CHOOSE, d.FUSETEM_DIFF_RESET]
	}
	exeCmd(e, t) {
		switch (t) {
		case d.FUSETEM_DIFF_CHOOSE:
		case d.FUSETEM_DIFF_RESET:
			this.diffChange();
			break
		}
	}
	getMsgs() {
		return [Rp.FUSETEM_RANK_REC]
	}
	exeMsg(e, t) {
		switch (t) {
		case Rp.FUSETEM_RANK_REC:
			this.rankDataRec(e);
			break
		}
	}
	onClick(e) {
		switch (e.target) {
		case this._ui.btnClose:
			this.closeUI();
			break
		}
	}
	initUI() {
		this._ui = this.uiView;
		this._ui.tabType.selectHandler = Laya.Handler.create(this, this.typeSelect, null, false);
		this.setLayer(1, 1, 1, 1);
		this._ui.listRwd.array = od.getTplInfo(nd.FUSETEM_RANKRWD)
	}
	checkOpen(e = true) {
		return true
	}
	afterOpen() {
		this.sendMsg(Rp.FUSETEM_RANK_REQ, {
			limit: 100
		});
		this._ui.tabType.selectedIndex = -1;
		this._ui.tabType.selectedIndex = 0
	}
	diffChange() {
		if (!this.isOpen)
			return;
		this.closeUI()
	}
	typeSelect(e) {
		this._ui.box0.visible = e == 0;
		this._ui.box1.visible = e == 1;
		let t = 0;
		switch (e) {
		case 0:
			this._ui.listRank.scrollTo(0);
			if (this._ui.listRank.array) {
				t = this._ui.listRank.array.length
			}
			break;
		case 1:
			this._ui.listRwd.scrollTo(0);
			if (this._ui.listRwd.array) {
				t = this._ui.listRwd.length
			}
			break
		}
		this._ui.noAnythingBox.visible = t <= 0
	}
	rankDataRec(e) {
		if (!this.isOpen || !e)
			return;
		let t = e.list;
		for (let s = 0; s < t.length; s++) {
			t[s].index = s + 1
		}
		this._ui.listRank.array = t;
		this._ui.listRank.scrollTo(0);
		this._ui.noAnythingBox.visible = t.length == 0;
		this._ui.myRank.dataSource = e.myRank + 1;
		UI.addMyPlayerHead(this._ui.myHead);
		this._ui.myName.text = this.data.master.name;
		if (e.my) {
			let t = od.getTplInfo(nd.FUSETEM_DIFF, e.my.difficulty);
			this._ui.myNum.text = t.name + "-" + e.my.star + " sao";
			this._ui.myCP.text = this.data.master.cp + ""
		} else {
			this._ui.myNum.text = "";
			this._ui.myCP.text = this.data.master.cp + ""
		}
		let i = e.myRank + 1;
		this._ui.prizeMyRank.text = i <= 0 ? WM.getLanCodeTip(10042) : i.toString();
		if (i <= 0) {
			this._ui.prizeMyList.array = []
		} else {
			let e = this._ui.listRwd.array;
			if (!e || !e.length) {
				this._ui.prizeMyList.array = []
			}
			for (let t of e) {
				if (t.start <= i && i <= t.end) {
					this._ui.prizeMyList.array = cP.splitStr2Arr(t.rwd);
					break
				}
			}
		}
	}
}
class AB extends g {
	constructor(e = "ToTemGKVictory") {
		super(e)
	}
	static getIns() {
		if (!this._ins) {
			this._ins = new AB
		}
		return this._ins
	}
	onClick(e) {
		switch (e.target) {
		case this._ui.btnSure:
			this.closeUI();
			break;
		case this._ui.btnReturn:
			this.isReturn = true;
			this.closeUI();
			break;
		case this._ui.btnStatis:
			KI.getIns().show(this.play);
			break
		}
	}
	initUI() {
		this._ui = this.uiView;
		this.setLayer(1, 1, 1, 1);
		for (let e = 0; e < 3; e++) {
			let t = this._ui["battleChal" + e];
			let i = t.getChildByName("desc");
			i.style.bold = true;
			i.style.width = i.width;
			i.style.color = "#ffdd74";
			i.style.fontSize = 22
		}
	}
	afterOpen() {
		vg.start(1e4, this, this.timerListener, 1)
	}
	afterClose() {
		this.clearEffect();
		this.clearStarEffect();
		this.play = null;
		this.result = null;
		if (this.callBack) {
			this.callBack.call(this, this.isReturn, true);
			this.callBack = null
		}
		vg.stop(this, this.timerListener)
	}
	timerListener(e, t) {
		this._ui.labCD.text = WM.getLanCodeTip(20032, [Math.ceil(e / 1e3)]);
		if (t) {
			this.closeUI()
		}
	}
	show(e, t, i) {
		this.openUI();
		this.clearEffect();
		this.showWinEffect();
		a_.stopMusic();
		a_.playSound("se_battlewin.wav", Laya.Handler.create(a_, a_.playBGM));
		this.isReturn = false;
		this.callBack = i;
		this.play = e;
		this.result = t;
		if (!!t.reward) {
			this._ui.listRwd.array = t.reward.items;
			this._ui.listRwd.scrollTo(0)
		} else {
			this._ui.listRwd.array = []
		}
		for (let s = 0; s < t.level.challenges.length; s++) {
			let e = t.level.challenges[s];
			if (!e)
				continue;
			let i = od.getTplInfo(nd.FUSETEM_CHALLENGE, e.challengeTid);
			if (!i)
				continue;
			let a = this._ui["battleChal" + s];
			let r = a.getChildByName("desc");
			let l = a.getChildByName("star");
			let h = a.getChildByName("boxEff");
			r.innerHTML = WM.str2Html(i.desc, 0);
			if (s != 0) {
				let e = a.getChildByName("listHero");
				if (i.type != 105 && i.type != 106) {
					e.array = []
				} else {
					e.array = i.param.split("#");
					if (e.array) {
						let t = e.array.length;
						e.width = e.getCell(0).width * t + e.spaceX * (t - 1)
					}
					e.x = r.x + r.contextWidth
				}
			}
			if (e.done) {
				h.visible = true;
				l.visible = false;
				if (!this["effectStar" + s]) {
					this["effectStar" + s] = new L_("zawu/xingxingbao", false);
					h.addChild(this["effectStar" + s]);
					this["effectStar" + s].on(Laya.Event.STOPPED, this, this.refreshStar)
				}
			} else {
				h.visible = false;
				l.visible = true;
				l.skin = "img/Destiny/star1.png"
			}
		}
	}
	refreshStar() {
		for (let e = 0; e < this.result.level.challenges.length; e++) {
			let t = this.result.level.challenges[e];
			if (!t)
				continue;
			let i = od.getTplInfo(nd.FUSETEM_CHALLENGE, t.challengeTid);
			if (!i)
				continue;
			let s = this._ui["battleChal" + e];
			let a = s.getChildByName("star");
			let r = s.getChildByName("boxEff");
			r.visible = false;
			a.visible = true;
			if (t.done) {
				a.skin = "img/Destiny/star.png"
			} else {
				a.skin = "img/Destiny/star1.png"
			}
		}
	}
	clearStarEffect() {
		if (this.effectStar0) {
			this.effectStar0.dispose();
			this.effectStar0 = null
		}
		if (this.effectStar1) {
			this.effectStar1.dispose();
			this.effectStar1 = null
		}
		if (this.effectStar2) {
			this.effectStar2.dispose();
			this.effectStar2 = null
		}
	}
	clearEffect() {
		Laya.timer.clear(this, this.showEffect1);
		Laya.timer.clear(this, this.showEffect3);
		Laya.timer.clear(this, this.showEffect4);
		if (this.winEffect1) {
			this.winEffect1.dispose();
			this.winEffect1 = null
		}
		if (this.winEffect2) {
			this.winEffect2.dispose();
			this.winEffect2 = null
		}
		if (this.winEffect3) {
			this.winEffect3.dispose();
			this.winEffect3 = null
		}
		if (this.winEffect4) {
			this.winEffect4.dispose();
			this.winEffect4 = null
		}
	}
	showWinEffect() {
		Laya.timer.once(500, this, this.showEffect1);
		this.showEffect2();
		Laya.timer.once(350, this, this.showEffect3);
		Laya.timer.once(500, this, this.showEffect4)
	}
	showEffect1() {
		this.winEffect1 = new k_("UI/shengli_1", true);
		this._ui.boxWin1.addChild(this.winEffect1);
		this.winEffect1.pos(this._ui.width / 2, 110)
	}
	showEffect2() {
		this.winEffect2 = new L_("UI/shengli_2", false);
		this._ui.boxWin2.addChild(this.winEffect2);
		this.winEffect2.pos(this._ui.width / 2, 160)
	}
	showEffect3() {
		this.winEffect3 = new k_("UI/shengli_3", false);
		this._ui.boxWin3.addChild(this.winEffect3);
		this.winEffect3.pos(this._ui.width / 2, 160)
	}
	showEffect4() {
		this.winEffect4 = new k_("UI/shengli_4", true);
		this._ui.boxWin4.addChild(this.winEffect4);
		this.winEffect4.pos(this._ui.width / 2, 110)
	}
}
class DB extends g {
	constructor() {
		super("TotemGK");
		this._moveNum = 0;
		this._flyLevel = 0
	}
	getCmds() {
		return [d.SOCKET_RECONNECTED, d.FUSETEM_DIFF_CHOOSE, d.FUSETEM_DIFF_RESET]
	}
	exeCmd(e, t) {
		switch (t) {
		case d.SOCKET_RECONNECTED:
			this.socketReconnected();
			break;
		case d.FUSETEM_DIFF_CHOOSE:
			this.deffChoose();
			break;
		case d.FUSETEM_DIFF_RESET:
			this.diffReset();
			break
		}
	}
	getMsgs() {
		return [kf.DATA_REC, kf.AWARD_GET_REC, kf.CHALLENGE_REC, Rd.BATTLE_PLAY_REC]
	}
	exeMsg(e, t) {
		switch (t) {
		case kf.DATA_REC:
			this.dataRec(e);
			this.checkDot(false);
			break;
		case kf.AWARD_GET_REC:
			this.awardGetRec(e);
			this.checkDot(false);
			break;
		case kf.CHALLENGE_REC:
			this.battleResultRec(e);
			this.checkDot(false);
			break;
		case Rd.BATTLE_PLAY_REC:
			this.battlePlayRec(e);
			break
		}
	}
	onClick(e) {
		switch (e.target) {
		case this._ui.btnClose:
			this.closeUI();
			break;
		case this._ui.btnRank:
			LB.getIns().openUI();
			break;
		case this._ui.btnPreview:
			SB.getIns().show(true);
			break
		}
	}
	initUI() {
		this._ui = this.uiView;
		this.setLayer(0, 1);
		this._ui.imgListBg.height = _.displayHeight - this._ui.imgListBg.y;
		Laya.stage.on(Laya.Event.RESIZE, this, this.onResize)
	}
	openUI(e = true) {
		if (nL.isChose) {
			super.openUI(e)
		} else {
			SB.getIns().show(false)
		}
	}
	checkOpen(e = true) {
		if (!oL.isAllPass()) {
			if (e)
				FM.noticeMan.showNotice(EB.NOT_ALL_PASS);
			return false
		}
		if (!FM.funcMan.checkFuncOpen(pd.FUSE_TEMPLE, e)) {
			return false
		}
		return true
	}
	afterOpen() {
		if (this._ui.height != _.displayHeight) {
			this.onResize()
		}
		this.refreshDiff(true);
		this.checkWatchBattle()
	}
	afterClose() {
		this._flyLevel = 0;
		this._point = null;
		let e = this._ui.listLevel.cells;
		if (!e || e.length == 0)
			return;
		for (let t = 0; t < e.length; t++) {
			let i = e[t];
			if (i) {
				i.clean()
			}
		}
		for (let t = 0; t < 3; t++) {
			let e = this._ui["imgStar" + (t + 1)];
			if (e) {
				this.resetStar(e)
			}
		}
	}
	onResize() {
		this._ui.height = _.displayHeight;
		this._ui.imgListBg.height = _.displayHeight - this._ui.imgListBg.y;
		this._ui.listLevel.height = _.displayHeight - this._ui.listLevel.y - 141;
		this._moveNum = 0;
		this._ui.listLevel.mouseEnabled = true;
		this.doTo0()
	}
	deffChoose() {
		if (this.isOpen) {
			this.closeUI()
		}
		this.openUI()
	}
	diffReset() {
		if (!this.isOpen)
			return;
		this.closeUI();
		SB.getIns().show(false)
	}
	dataRec(e) {
		if (!e)
			return;
		nL.setData(e.fusion)
	}
	awardGetRec(e) {
		if (!e)
			return;
		nL.hasGotRwd = e.gotPickRwd;
		this.refreshAward()
	}
	battleResultRec(e) {
		if (nL.choseDiff == 0) {
			this._play = null
		}
		if (!this._play) {
			FM.battleMan.stopWatch(pd.FUSE_TEMPLE);
			return
		}
		let t = this._play;
		this._play = null;
		if (!this.isOpen) {
			this.openUI()
		}
		if (e.win) {
			AB.getIns().show(t, e, Laya.Utils.bind(this.resultCallBack, this));
			nL.updateLevel(e)
		} else {
			ET.getIns().show(pd.FUSE_TEMPLE, t, Laya.Utils.bind(this.resultCallBack, this))
		}
		FM.battleMan.stopWatch(pd.FUSE_TEMPLE)
	}
	resultCallBack(e) {
		this.refreshDiff(false)
	}
	battlePlayRec(e) {
		if (e.funcId != pd.FUSE_TEMPLE)
			return;
		this._play = e.play;
		this.checkWatchBattle()
	}
	socketReconnected() {
		this._play = null;
		this.checkWatchBattle()
	}
	checkWatchBattle() {
		if (!this.isOpen)
			return;
		if (this._play) {
			FM.battleMan.watchBattle(this._play, pd.FUSE_TEMPLE)
		}
	}
	refreshDiff(e) {
		if (!this.isOpen)
			return;
		let t = nL.choseDiff;
		if (!this._diffTpl || this._diffTpl.id != t) {
			this._diffTpl = od.getTplInfo(nd.FUSETEM_DIFF, t);
			this._levelTpl = od.getTplInfo(nd.FUSETEM_LEVEL, t);
			this._ui.labDiffName.text = this._diffTpl.name + "Độ khó";
			this._ui.listLevel.array = null
		}
		if (e) {
			this.refreshPro();
			this.refreshAward()
		}
		this.refreshLevels(e)
	}
	refreshPro() {
		if (!this.isOpen || !this._diffTpl || !this._levelTpl)
			return;
		this._ui.proBox.dataSource = mI.getProgBarData(nL.starNum, this._diffTpl.starNum, true)
	}
	refreshAward() {
		if (!this.isOpen || !this._diffTpl || !this._levelTpl)
			return;
		let e = od.getTplInfo(nd.FUSETEM_CHOOSEAWARD, nL.choseRwdTid);
		if (!e)
			return;
		let t = Tb.addItemGrid(cP.splitStr2Arr(e.award)[0], this._ui.prizeGrid);
		let i = this._ui.proBox.now >= this._diffTpl.starNum;
		t.mouseEnabled = !i || nL.hasGotRwd;
		this._ui.prizeGrid.gray = nL.hasGotRwd;
		if (i && !nL.hasGotRwd) {
			this._ui.imgGet.visible = true;
			N_.addEffect("qiandao/qiandaoshanguang", this._ui.boxEffect).scale(1.25, 1.25);
			this._ui.boxAward.on(Laya.Event.CLICK, this, this.boxAwardClick)
		} else {
			this._ui.imgGet.visible = false;
			N_.removeEffect(this._ui.boxEffect);
			this._ui.boxAward.off(Laya.Event.CLICK, this, this.boxAwardClick)
		}
		this._ui.imgGot.visible = nL.hasGotRwd
	}
	boxAwardClick() {
		if (this._ui.proBox.now < this._diffTpl.starNum)
			return;
		this.sendMsg(kf.AWARD_GET_REQ)
	}
	refreshLevels(e) {
		if (!this.isOpen || !this._diffTpl || !this._levelTpl)
			return;
		let t = this._ui.listLevel.array;
		if (!t || t.length == 0) {
			t = [];
			for (let e = 0; e < this._levelTpl.length; e++) {
				let i = {
					tpl: this._levelTpl[e],
					heros: [],
					endFun: Laya.Utils.bind(this.levelMoveEnd, this),
					flyFun: Laya.Utils.bind(this.starPlayEnd, this)
				};
				for (let e = 0; e < i.tpl.heros.length; e++) {
					i.heros.push(new yg(i.tpl.heros[e]))
				}
				t.push(i)
			}
		}
		this._moveNum = 0;
		this._flyLevel = 0;
		this._point = null;
		if (e) {
			this._ui.listLevel.array = t;
			let e = nL.firstCanChallLevel - 1;
			if (e > 0) {
				this._ui.listLevel.scrollTo(e - 1)
			} else {
				this._ui.listLevel.scrollTo(0)
			}
			Laya.timer.frameOnce(2, this, this.doMove);
			this._ui.listLevel.mouseEnabled = false
		} else {
			if (nL.hasNewLevel > 0) {
				let e = this._ui.proBox.progBar;
				if (!!e) {
					let t = new Laya.Point(e.width * e.value, e.height / 2);
					t = e.localToGlobal(t, true);
					this._point = this._ui.globalToLocal(t, true)
				}
				this._ui.listLevel.array = t;
				this._ui.listLevel.mouseEnabled = false;
				let i = nL.hasNewLevel - 1;
				if (i > 0) {
					this._ui.listLevel.scrollTo(i - 1)
				} else {
					this._ui.listLevel.scrollTo(0)
				}
				this._flyLevel = nL.hasNewLevel;
				nL.hasNewLevel = 0;
				Laya.timer.frameOnce(2, this, this.doPlayStar)
			} else {
				this._ui.listLevel.mouseEnabled = true
			}
			this.doTo0()
		}
	}
	doMove() {
		if (!this.isOpen)
			return;
		let e = this._ui.listLevel.cells;
		if (!e || e.length == 0)
			return;
		for (let t = 0; t < e.length; t++) {
			let i = e[t];
			if (!!i.dataSource) {
				this._moveNum++
			}
			i.doMove(t * 100)
		}
	}
	levelMoveEnd() {
		this._moveNum--;
		if (this._moveNum <= 0) {
			this._moveNum = 0;
			this._ui.listLevel.mouseEnabled = true
		}
	}
	doTo0() {
		if (!this.isOpen)
			return;
		let e = this._ui.listLevel.cells;
		if (!e || e.length == 0)
			return;
		for (let t = 0; t < e.length; t++) {
			let i = e[t];
			if (i) {
				i.doTo0()
			}
		}
	}
	doPlayStar() {
		if (!this.isOpen)
			return;
		if (nL.choseDiff == 0 || this._flyLevel == 0) {
			this._ui.listLevel.mouseEnabled = true;
			return
		}
		let e = this._ui.listLevel.cells;
		if (!e || e.length == 0) {
			this._ui.listLevel.mouseEnabled = true;
			return
		}
		for (let t = 0; t < e.length; t++) {
			let i = e[t];
			if (!!i && !!i.dataSource && i.dataSource.tpl.level == this._flyLevel) {
				i.doPlayStar();
				return
			}
		}
		this._ui.listLevel.mouseEnabled = true
	}
	starPlayEnd(e, t) {
		if (this._flyLevel == 0)
			return;
		let i = this._ui["imgStar" + e];
		if (this._point) {
			let e = this._ui.globalToLocal(t, true);
			i.pos(e.x, e.y);
			i.visible = true;
			Laya.Tween.to(i, {
				x: this._point.x - i.width / 2 * i.scaleX,
				y: this._point.y - i.height / 2 * i.scaleY
			}, 400, Laya.Ease.sineOut, Laya.Handler.create(this, this.starFlyEnd, [i]), 0, true)
		} else {
			this.starFlyEnd(i)
		}
	}
	starFlyEnd(e) {
		this.resetStar(e);
		if (this._flyLevel == 0)
			return;
		let t = nL.getLevel(this._flyLevel);
		t.newNum--;
		if (t.newNum <= 0) {
			t.newNum = 0;
			this._flyLevel = 0;
			this.refreshPro();
			this.refreshAward();
			this._ui.listLevel.mouseEnabled = true
		}
	}
	resetStar(e) {
		if (!e)
			return;
		Laya.Tween.clearAll(e);
		e.visible = false
	}
	checkDot(e) {
		let t = false;
		if (nL.isChose) {
			let i = this._diffTpl;
			if (!i) {
				i = od.getTplInfo(nd.FUSETEM_DIFF, nL.choseDiff)
			}
			if (nL.starNum < i.starNum) {
				if (e) {
					nL.showDot = false
				}
				t = nL.showDot
			} else {
				nL.showDot = !nL.hasGotRwd;
				t = nL.showDot
			}
		} else {
			if (e) {
				nL.showDot = false
			}
			t = nL.showDot
		}
		t = t && this.checkOpen(false);
		cd.setDot(dd.TOTEM_ENTER, this, t);
		cd.setDot(dd.FUSETEM_ENTER, this, t)
	}
}
class RB {
	constructor(e, t) {
		this._yoyo = false;
		this.yoyoTime = 0;
		this.type = t;
		this.tpl = od.getTplInfo(nd.TOTEM_FB, t);
		this.box = e;
		this.labName = e.getChildByName("labName");
		this.imgTiemBg = e.getChildByName("imgTiemBg");
		this.labTime = e.getChildByName("labTime");
		this.imgLock = e.getChildByName("imgLock");
		this.imgIsland = e.getChildByName("imgIsland");
		this.proBox = e.getChildByName("proBox");
		e.on(Laya.Event.CLICK, this, this.onClick);
		e.on(Laya.Event.UNDISPLAY, this, this.undisplay)
	}
	onClick(e) {
		if (this.type != 6) {
			let e = new Date;
			e.setTime(uP.getIns().serverTime);
			let t = e.getDay();
			if (t == this.tpl.openDay || t == 0 || t == 6) {
				uL.getIns().show(this.type)
			} else {
				FM.noticeMan.showNotice(WM.getLanCodeTip(20344, [b_.getWeekDayStr(this.tpl.openDay)]))
			}
		} else {
			FM.fuseTempleMan.openUI();
			FM.fuseTempleMan.checkDot(true)
		}
	}
	refresh() {
		if (this.type != 6) {
			this.refreshToTem()
		} else {
			this.refreshFuseTem()
		}
	}
	refreshToTem() {
		this.labName.text = this.tpl.name;
		let e = new Date;
		e.setTime(uP.getIns().serverTime);
		let t = e.getDay();
		if (t == this.tpl.openDay || t == 0 || t == 6) {
			let i;
			if (t == this.tpl.openDay) {
				i = b_.getDayEndTimeStamp(e.getTime()) - e.getTime()
			} else {
				i = b_.getWeekEndTimeStamp(e.getTime()) - e.getTime()
			}
			vg.start(i, this, this.timerHandler, 1, WM.getLanCodeTip(10632));
			this.labTime.color = "#52e20c";
			this.imgLock.visible = false;
			this.yoyo = true;
			this.imgIsland.filters = []
		} else {
			vg.stop(this, this.timerHandler);
			this.labTime.text = WM.getLanCodeTip(20344, [b_.getWeekDayStr(this.tpl.openDay)]);
			this.labTime.color = m.NORMAL_RED;
			this.imgLock.visible = true;
			this.yoyo = false;
			this.imgIsland.filters = [(new Laya.ColorFilter).adjustColor(-50, 0, -80, 0)]
		}
		if (this.proBox) {
			this.proBox.dataSource = mI.getProgBarData(oL.getPassMaxLevel(this.type), oL.getTplMaxLevel(this.type), false);
			this.proBox.visible = !oL.isAllPass()
		}
		let i = RB.TPL[this.type];
		if (!oL.isAllPass()) {
			this.box.scale(1, 1);
			this.box.x = i.x0;
			this.box.y = i.y0;
			this.imgTiemBg.scale(1, 1);
			this.labTime.scale(1, 1);
			this.imgLock.scale(1, 1)
		} else {
			this.box.scale(RB.SCALE, RB.SCALE);
			this.box.x = i.x1;
			this.box.y = i.y1;
			let e = 1 + 1 - RB.SCALE;
			this.imgTiemBg.scale(e, e);
			this.labTime.scale(e, e);
			this.imgLock.scale(e, e)
		}
	}
	refreshFuseTem() {
		this.box.visible = oL.isAllPass() && FM.funcMan.checkFuncOpen(pd.FUSE_TEMPLE, false);
		if (this.box.visible) {
			let e = nL.getCdTime();
			if (e > 0) {
				vg.start(e, this, this.timerHandler, 1, WM.getLanCodeTip(10632));
				this.labTime.color = "#52e20c";
				this.yoyo = true;
				this.imgIsland.filters = []
			} else {
				vg.stop(this, this.timerHandler);
				this.labTime.text = WM.getLanCodeTip(10013);
				this.labTime.color = m.NORMAL_RED;
				this.yoyo = false;
				this.imgIsland.filters = [(new Laya.ColorFilter).adjustColor(-50, 0, -80, 0)]
			}
		} else {
			vg.stop(this, this.timerHandler);
			this.yoyo = false
		}
	}
	timerHandler(e, t, i) {
		this.labTime.text = i
	}
	undisplay(e) {
		this.yoyo = false
	}
	set yoyo(e) {
		if (this._yoyo == e)
			return;
		this._yoyo = e;
		if (this._yoyo) {
			this.startYoYo()
		} else {
			this.stopYoYo()
		}
	}
	get yoyo() {
		return this._yoyo
	}
	startYoYo() {
		this.yoyoTime = 0;
		Laya.timer.frameLoop(1, this, this.yoyoLoop)
	}
	stopYoYo() {
		Laya.timer.clear(this, this.yoyoLoop)
	}
	yoyoLoop() {
		this.yoyoTime++;
		this.imgIsland.y = Math.sin(this.yoyoTime / 100 * Math.PI + 30 * this.type) * 5
	}
}
