class QB {
	static setAllTurnableData(e) {
		this.allTurnableData = e
	}
	static getShowData() {
		if (!this.allTurnableData) {
			FM.trunableMan.refreshTurnableData(0);
			return null
		}
		if (this.isCanRefresh(this.allTurnableData)) {
			FM.trunableMan.refreshTurnableData(0);
			return null
		}
		return this.allTurnableData
	}
	static isCanRefresh(e) {
		let t = od.getTplInfo(nd.TURNABLEREFRESH, 1);
		if (e.freeTimes > 0)
			return false;
		let i = e.lastFreeRefreshTime;
		if (i == 0)
			return false;
		let s = b_.getRefreshTimeStamp(t.limitTime, i);
		return b_.getTimeStamp() >= s
	}
	static isHasFreeTimes() {
		let e = this.getShowData();
		if (!e)
			return true;
		return e.freeTimes > 0
	}
	static getFreeRefreshTime() {
		let e = this.getShowData();
		if (!e)
			return 0;
		let t = od.getTplInfo(nd.TURNABLEREFRESH, 1);
		return b_.getRefreshTimeStamp(t.limitTime, e.lastFreeRefreshTime) - b_.getTimeStamp()
	}
	static isShowDotNormal(e) {
		let t = this.getShowData();
		if (!t)
			return false;
		let i = od.getTplInfo(nd.TURNABLETURN, null, {
				turn: t.turn,
				group: e
			});
		for (let s = 0; s < i.length; s++) {
			if (!t.gotMap[i[s].id] && t.times >= i[s].times) {
				return true
			}
		}
		return false
	}
	static getMaxTurn(e) {
		if (this._maxTurn == 0) {
			let t = od.getTplInfo(nd.TURNABLETURN, null, {
					group: e
				});
			for (let e = 0; e < t.length; e++) {
				if (t[e].turn > this._maxTurn) {
					this._maxTurn = t[e].turn
				}
			}
		}
		return this._maxTurn
	}
	static setLogData(e) {
		if (!e)
			return;
		this.trunabledLogData = e
	}
	static getLogData() {
		if (!this.trunabledLogData) {
			FM.trunableMan.getTurnableLogs();
			return null
		}
		return this.trunabledLogData
	}
	static clearLogs() {
		this.trunabledLogData = null
	}
	static getShowChance() {
		if (this.showChanceData) {
			return this.showChanceData
		}
		let e = [];
		let t = od.getTplInfo(nd.TURNABLEGROUP);
		let i = 0;
		for (let s = 0; s < t.length; s++) {
			let a = od.getTplInfo(nd.TURNABLEPRIZE, null, {
					group: t[s].id
				});
			let r = [];
			let l = 0;
			i += t[s].power;
			for (let e = 0; e < a.length; e++) {
				r[e] = cP.splitStr2Arr(a[e].prize)[0];
				l += a[e].power
			}
			for (let i = 0; i < a.length; i++) {
				let h = false;
				for (let n = 0; n < e.length; n++) {
					if (e[n].type == r[i].type && e[n].tid == r[i].tid) {
						h = true;
						e[n].power += t[s].power * (a[i].power / l)
					}
				}
				if (!h) {
					r[i].power = t[s].power * (a[i].power / l);
					e.push(r[i])
				}
			}
		}
		for (let s = 0; s < e.length; s++) {
			e[s].power = e[s].power * 100 / i
		}
		this.showChanceData = e;
		return this.showChanceData
	}
}
