class eM extends Cb {
	constructor() {
		super("WelDaily")
	}
	tabSelectCheck() {
		return true
	}
	tabVisibleCheck() {
		return this.checkOpen(false)
	}
	getCmds() {
		return [d.TASK_CHANGE_ITEM, d.TASK_INIT, d.FUNC_INIT, d.FUNC_OPEN]
	}
	exeCmd(e, t) {
		switch (t) {
		case d.TASK_CHANGE_ITEM:
			if (e.funcId != pd.DAILY_CHARGE) {
				break
			}
			this.checkDot();
			if (this.isOpen) {
				this.updateInfo()
			}
			break;
		case d.TASK_INIT:
			this.checkDot();
			break;
		case d.FUNC_INIT:
			this.checkMainBtn();
			break;
		case d.FUNC_OPEN:
			if (e == pd.DAILY_CHARGE) {
				this.checkMainBtn();
				this.checkDot()
			}
			break
		}
	}
	initUI() {
		this._ui = this.uiView
	}
	checkOpen(e) {
		if (!FM.funcMan.checkFuncOpen(pd.DAILY_CHARGE, e))
			return false;
		return true
	}
	afterOpen() {
		this.updateInfo();
		this._ui.listTask.scrollTo(0)
	}
	updateInfo() {
		let e = this.data.task.getTaskDataByFuncId(pd.DAILY_CHARGE);
		if (!e)
			return;
		let t = [];
		for (let s = 0; s < e.doneList.length; s++) {
			t.push(e.doneList[s])
		}
		for (let s = 0; s < e.ingList.length; s++) {
			t.push(e.ingList[s])
		}
		t.sort(this.sortFun);
		this._ui.listTask.array = t;
		let i = b_.getDayEndTimeStamp() - b_.getTimeStamp();
		vg.start(i, this, this.timerFun);
		this.timerFun(i, false)
	}
	sortFun(e, t) {
		if (!e.rewardGot && t.rewardGot) {
			return -1
		} else if (e.rewardGot && !t.rewardGot) {
			return 1
		}
		if (e.done && !t.done) {
			return -1
		} else if (!e.done && t.done) {
			return 1
		}
		return e.tid - t.tid
	}
	timerFun(e, t) {
		this._ui.labTime.text = b_.getCdTimeStrByMs(e)
	}
	checkMainBtn() {
		FM.mainCityMan.setTopBtnOpen(bb.WELFARE, this, this.tabVisibleCheck())
	}
	checkDot() {
		let e = false;
		if (this.tabVisibleCheck()) {
			let t = this.data.task.getTaskDataByFuncId(pd.DAILY_CHARGE);
			for (let i = 0; i < t.doneList.length; i++) {
				if (t.doneList[i].done && !t.doneList[i].rewardGot) {
					e = true;
					break
				}
			}
		}
		cd.setDot(dd.WELFARE_ENTER, this, e);
		cd.setDot(dd.DAILY_CHARGE_ENTER, this, e)
	}
}
