class sM extends Cb {
	constructor() {
		super("WelMonth")
	}
	tabSelectCheck() {
		return true
	}
	tabVisibleCheck() {
		return this.checkOpen(false)
	}
	getCmds() {
		return [d.FUNC_INIT, d.FUNC_OPEN, d.LOGIN_DAYS_CHANGE]
	}
	exeCmd(e, t) {
		switch (t) {
		case d.FUNC_INIT:
			this.checkMainBtn();
			break;
		case d.FUNC_OPEN:
			if (e == pd.MONTH_LIMIT_MALL) {
				this.checkMainBtn();
				this.checkDot()
			}
			break;
		case d.LOGIN_DAYS_CHANGE:
			this.refreshPanel();
			break
		}
	}
	getMsgs() {
		return [xp.RECHARGE_DATA_REC, xp.MONTH_LIMIT_SHOP_REC]
	}
	exeMsg(e, t) {
		switch (t) {
		case xp.RECHARGE_DATA_REC:
			this.rechargeDataRec(e);
			break;
		case xp.MONTH_LIMIT_SHOP_REC:
			this.monthMallDataRec(e);
			break
		}
	}
	initUI() {
		this._ui = this.uiView
	}
	checkOpen(e = true) {
		if (!FM.funcMan.checkFuncOpen(pd.MONTH_LIMIT_MALL, e))
			return false;
		if (!this.srvData)
			return false;
		return true
	}
	afterOpen() {
		this.refreshPanel()
	}
	rechargeDataRec(e) {
		this.srvData = e.pay.monthMall;
		this.checkMainBtn();
		this.refreshPanel();
		this.checkDot()
	}
	monthMallDataRec(e) {
		this.srvData = e.monthMall;
		this.checkMainBtn();
		this.refreshPanel();
		this.checkDot()
	}
	refreshPanel() {
		if (!this.isOpen)
			return;
		if (!this.srvData || !this.srvData.items)
			return;
		let e = this.srvData.items;
		let t = [];
		let i = this.data.openSrvDay;
		for (let a = 0; a < e.length; a++) {
			if (!e[a].tpl)
				e[a].tpl = od.getTplInfo(nd.MONTH_LIMIT_SHOP, e[a].tid);
			if (e[a].tpl.minOpenSrvDay && i < e[a].tpl.minOpenSrvDay) {
				continue
			}
			if (e[a].tpl.maxOpenSrvDay && i > e[a].tpl.maxOpenSrvDay) {
				continue
			}
			t.push(e[a])
		}
		t.sort(this.sortFun);
		this._ui.listCell.array = t;
		this._ui.listCell.scrollTo(0);
		let s = b_.getMonthEndTimeStamp() - b_.getTimeStamp();
		vg.start(s, this, this.timerFun);
		this.timerFun(s, false)
	}
	timerFun(e, t) {
		if (e >= b_.ONEDAYMILLISECONDS) {
			this._ui.labTime.text = b_.getDayHourStr(e)
		} else {
			this._ui.labTime.text = b_.getCdTimeStrByMs(e)
		}
	}
	sortFun(e, t) {
		if (e.purchaseNum < e.tpl.limit && t.purchaseNum >= t.tpl.limit) {
			return -1
		} else if (t.purchaseNum < t.tpl.limit && e.purchaseNum >= e.tpl.limit) {
			return 1
		} else {
			return e.tpl.power - t.tpl.power
		}
	}
	checkDot() {
		if (!this.srvData || !this.tabVisibleCheck())
			return;
		let e = this.srvData.items;
		let t = false;
		let i = this.data.openSrvDay;
		for (let s = 0; s < e.length; s++) {
			if (!e[s].tpl) {
				e[s].tpl = od.getTplInfo(nd.MONTH_LIMIT_SHOP, e[s].tid)
			}
			if (e[s].tpl.minOpenSrvDay && i < e[s].tpl.minOpenSrvDay) {
				continue
			}
			if (e[s].tpl.maxOpenSrvDay && i > e[s].tpl.maxOpenSrvDay) {
				continue
			}
			if (e[s].tpl.price == 0 && e[s].purchaseNum < e[s].tpl.limit) {
				t = true;
				break
			}
		}
		cd.setDot(dd.MONTH_LIMIT_ENTER, this, t);
		cd.setDot(dd.WELFARE_ENTER, this, t)
	}
	checkMainBtn() {
		FM.mainCityMan.setTopBtnOpen(bb.WELFARE, this, this.tabVisibleCheck())
	}
}
