class lM {
	static set signData(e) {
		this._signData = e
	}
	static isCanTodaySign() {
		let e = this._signData;
		if (!e)
			return true;
		return !b_.isSameToday(e.lastSignTime)
	}
	static isPayToday() {
		let e = uP.getIns().master.payData.lastTime;
		return b_.isSameToday(e)
	}
	static isCanTodayExtraSign() {
		if (!this.isPayToday())
			return false;
		let e = this._signData;
		if (!e)
			return false;
		return !b_.isSameToday(e.lastExtraSignTime)
	}
	static curMonthSignTimes() {
		let e = this._signData;
		if (!e)
			return 0;
		return e.signTimes
	}
	static curCfgSignType(e) {
		let t = this.curMonthSignTimes();
		if (t > e.signDays) {
			return 0
		} else if (t == e.signDays) {
			if (this.isCanTodaySign()) {
				return 0
			} else {
				if (this.isPayToday()) {
					if (this.isCanTodayExtraSign()) {
						return 2
					} else {
						return 0
					}
				} else {
					return 1
				}
			}
		} else if (t == e.signDays - 1) {
			if (this.isCanTodaySign()) {
				return 3
			} else {
				return 4
			}
		} else {
			return 4
		}
	}
	static isSignDot() {
		return this.isCanTodaySign() || this.isCanTodayExtraSign()
	}
	static isShowDot() {
		return this.isSignDot()
	}
}
