class pM extends Cb {
	constructor() {
		super("WelPayGift")
	}
	tabSelectCheck() {
		return true
	}
	tabVisibleCheck() {
		return this.checkOpen(false)
	}
	getCmds() {
		return [d.FUNC_INIT, d.FUNC_OPEN]
	}
	exeCmd(e, t) {
		switch (t) {
		case d.FUNC_INIT:
			this.checkMainBtn();
			break;
		case d.FUNC_OPEN:
			if (e == pd.ACCUMULATE_PAY_GIFT) {
				this.checkMainBtn();
				this.checkDot()
			}
			break
		}
	}
	getMsgs() {
		return [xp.RECHARGE_DATA_REC, xp.WELPAY_GIFT_DATA_REC]
	}
	exeMsg(e, t) {
		switch (t) {
		case xp.RECHARGE_DATA_REC:
			this.rechargeDataRec(e);
			break;
		case xp.WELPAY_GIFT_DATA_REC:
			this.welPayGiftDataRec(e);
			break
		}
	}
	initUI() {
		this._ui = this.uiView
	}
	checkOpen(e = true) {
		if (!FM.funcMan.checkFuncOpen(pd.ACCUMULATE_PAY_GIFT, e))
			return false;
		if (!this.srvData || this.srvData.over)
			return false;
		return true
	}
	afterOpen() {
		this.refreshPanel()
	}
	refreshPanel() {
		if (!this.isOpen)
			return;
		if (!this.srvData)
			return;
		let e = od.getTplInfo(nd.WELPAY_GIFT);
		for (let t = 0; t < e.length; t++) {
			e[t].isGot = this.isGotPrizeId(e[t].id)
		}
		e.sort(this.sortFun);
		this._ui.listCell.array = e;
		this._ui.listCell.scrollTo(0)
	}
	sortFun(e, t) {
		if (e.isGot && !t.isGot) {
			return 1
		} else if (!e.isGot && t.isGot) {
			return -1
		} else {
			return e.days - t.days
		}
	}
	rechargeDataRec(e) {
		this.srvData = e.pay.accPayGift;
		this.checkMainBtn();
		this.refreshPanel();
		this.checkDot()
	}
	welPayGiftDataRec(e) {
		this.srvData = e.accPayGift;
		this.checkMainBtn();
		this.refreshPanel();
		this.checkDot()
	}
	isCanPrizeDay(e) {
		if (!this.srvData)
			return false;
		return this.srvData.day >= e
	}
	isGotPrizeId(e) {
		if (!this.srvData)
			return false;
		return this.srvData.rewardGot[e]
	}
	getDays() {
		if (!this.srvData)
			return 0;
		return this.srvData.day
	}
	checkDot() {
		if (!this.tabVisibleCheck())
			return;
		let e = false;
		let t = od.getTplInfo(nd.WELPAY_GIFT);
		for (let i = 0; i < t.length; i++) {
			if (this.isCanPrizeDay(t[i].days) && !this.isGotPrizeId(t[i].id)) {
				e = true;
				break
			}
		}
		cd.setDot(dd.WELPAY_GIFT_ENTER, this, e);
		cd.setDot(dd.WELFARE_ENTER, this, e)
	}
	checkMainBtn() {
		FM.mainCityMan.setTopBtnOpen(bb.WELFARE, this, this.tabVisibleCheck())
	}
}
