class DM extends g {
	constructor(e = "YuanXiaoShop") {
		super(e);
		this.activityId = 100001
	}
	static getIns() {
		if (!this._ins) {
			this._ins = new DM
		}
		return this._ins
	}
	getCmds() {
		return [d.FUNC_INIT, d.FUNC_OPEN]
	}
	exeCmd(e, t) {
		switch (t) {
		case d.FUNC_INIT:
			break;
		case d.FUNC_OPEN:
			break
		}
	}
	getMsgs() {
		return [Ef.YUANXIAO_SHOP_REC]
	}
	exeMsg(e, t) {
		switch (t) {
		case Ef.YUANXIAO_SHOP_REC:
			this.shopDataRec(e);
			break
		}
	}
	onClick(e) {
		switch (e.target) {
		case this._ui.btnClose:
			this.closeUI();
			break
		}
	}
	initUI() {
		this._ui = this.uiView;
		this.setLayer(1, 1, 1, 1)
	}
	afterOpen() {
		this.reqYuanXiaoShop();
		this.updateInfo();
		this._ui.listCell.scrollTo(0)
	}
	reqYuanXiaoShop() {
		this.sendMsg(Ef.YUANXIAO_SHOP_REQ)
	}
	updateInfo() {
		let e = [];
		let t = null;
		if (this.srvData && this.srvData.data && this.srvData.data.list) {
			t = this.srvData.data.list
		}
		let i = od.getTplInfo(nd.YUANXIAO_SHOP);
		for (let s = 0; s < i.length; s++) {
			let a = {};
			a.tpl = i[s];
			a.type = 1;
			a.tid = i[s].id;
			a.purchaseNum = 0;
			if (t) {
				for (let e = 0; e < t.length; e++) {
					if (t[e].tid == a.tid) {
						a.purchaseNum = t[e].purchaseNum
					}
				}
			}
			if (a.tpl.limitNum < 0) {
				a.sellOut = false
			} else {
				a.sellOut = a.tpl.limitNum <= a.purchaseNum
			}
			e.push(a)
		}
		e.sort(this.sortFun);
		this._ui.listCell.array = e
	}
	sortFun(e, t) {
		if (!e.sellOut && t.sellOut) {
			return -1
		} else if (e.sellOut && !t.sellOut) {
			return 1
		}
		return e.tpl.power - t.tpl.power
	}
	shopDataRec(e) {
		this.srvData = e;
		this.refreshData()
	}
	refreshData() {
		if (!this.srvData)
			return;
		if (this.isOpen) {
			this.updateInfo()
		}
	}
}
