		if (!e)
			return;
		let t = e.list;
		if (!t)
			return;
		for (let i = 0; i < 3; i++) {
			let e = this._ui["rank" + i];
			let s = e.getChildByName("labName");
			let a = e.getChildByName("labTier");
			if (t[i]) {
				s.text = t[i].owner.profile.name;
				a.text = WM.getLanCodeTip(20160, [WM.num2Str(Math.round(t[i].damage))])
			} else {
				s.text = WM.getLanCodeTip(10030);
				a.text = ""
			}
		}
