class BP extends Laya.List {
	constructor() {
		super(...arguments);
		this._initWidth = null;
		this._initHeight = null
	}
	get array() {
		return super.array
	}
	set array(e) {
		super.array = e;
		if (this._initWidth == null) {
			this._initWidth = this.width
		}
		if (this._initHeight == null) {
			this._initHeight = this.height
		}
		this.centerX = 0;
		this.centerY = 0;
		var t = this.cells[0];
		if (!t) {
			t = this.createItem()
		}
		var i = t.width * e.length + this.spaceX * (e.length - 1);
		if (i > this._initWidth) {
			this.width = this._initWidth
		} else {
			this.width = i
		}
		if (this.scrollBar && this.scrollBar.isVertical) {
			var s = t.width + this.spaceX;
			var a = this.scrollBar.isVertical ? Math.round(this._initWidth / s) : Math.ceil(this._initWidth / s);
			var r = Math.ceil(e.length / a);
			var l = t.height * r + this.spaceY * (r - 1);
			if (l > this._initHeight) {
				this.height = this._initHeight
			} else {
				this.height = l
			}
		}
	}
}
class MP extends Laya.Script {
	constructor() {
		super();
		this.distance = 10;
		this.speed = 2500;
		this.moveTimes = 0
	}
	onEnable() {
		if (isNaN(this.initY)) {
			this.initY = this.owner["y"]
		}
		Laya.timer.loop(30, this, this.loopHandler)
	}
	onDisable() {
		Laya.timer.clear(this, this.loopHandler)
	}
	loopHandler() {
		if (this.owner["hasOwnProperty"]("moveStop") && this.owner["moveStop"]) {
			return
		}
		if (this.owner["hasOwnProperty"]("moveStartY")) {
			this.initY = this.owner["moveStartY"]
		}
		this.moveTimes++;
		this.owner["y"] = this.initY + Math.sin(this.moveTimes * 30 / this.speed * Math.PI) * this.distance
	}
}
