class VP extends Laya.Image {
	constructor() {
		super();
		this._value = NaN
	}
	set data(e) {
		this._data = e;
		if (isNaN(this._initWidth)) {
			this._initWidth = this.width
		}
	}
	set value(e) {
		if (this._value == e || !this._data)
			return;
		this._value = e;
		let t = this._initWidth;
		for (let i = 0; i < this._data.length; i++) {
			if (this._data[i].num > e) {
				if (i == 0) {
					t = e / this._data[i].num * this._data[i].x
				} else {
					t = this._data[i - 1].x + (this._data[i].x - this._data[i - 1].x) * ((e - this._data[i - 1].num) / (this._data[i].num - this._data[i - 1].num))
				}
				break
			}
		}
		if (t == 0) {
			t = 1e-4
		}
		this.width = t
	}
	get value() {
		return this._value
	}
}
