class jP extends g {
	constructor() {
		super("ActPersonChoose")
	}
	static getIns() {
		if (!this._ins) {
			this._ins = new jP
		}
		return this._ins
	}
	onClick(e) {
		switch (e.target) {
		case this._ui.btnSure:
			this.refreshList();
			let t = od.getTplInfo(nd.ACT_PRIVATE_GOODS, this._data.tid);
			for (let e = 0; e < t.privateNum; e++) {
				if (!this._customTids[e]) {
					this._customTids[e] = -1
				}
			}
			this.sendMsg(Td.SET_PRIZE_REQ, {
				tid: this._data.tid,
				customTids: this._customTids
			});
			this.closeUI();
			break
		}
	}
	initUI() {
		this._ui = this.uiView;
		this.setLayer(1, 1, 1, 1)
	}
	show(e, t) {
		this._index = t;
		this._data = e;
		this._customTids = e.customTids;
		if (!this._customTids) {
			this._customTids = []
		}
		this.openUI()
	}
	refreshList() {
		let e = this._ui.propList.array;
		this._customTids[this._index] = -1;
		for (let t = 0; t < e.length; t++) {
			if (e[t].selected) {
				this._customTids[this._index] = e[t].propData.id
			}
		}
	}
	refrshChooseNum() {
		let e = 0;
		let t = this._ui.propList.array;
		for (let i = 0; i < t.length; i++) {
			if (t[i].selected) {
				e++
			}
		}
		this._ui.chooseNumLab.text = WM.getLanCodeTip(20327, [e, 1])
	}
	checkSelect(e) {
		let t = this._ui.propList.array;
		let i = 0;
		for (let s = 0; s < t.length; s++) {
			if (t[s].selected) {
				i++
			}
		}
		if (i >= 1) {
			FM.noticeMan.showNotice(WM.getLanCodeTip(10017));
			return false
		}
		i++;
		return true
	}
	afterOpen() {
		this.updateInfo()
	}
	updateInfo() {
		let e = od.getTplInfo(nd.ACT_PRIVATE_GOODS, this._data.tid);
		let t = od.getTplInfo(nd.ACT_PRIVATE_PRIZE, null, {
				group: e.prizeGroup
			});
		let i = [];
		for (let s = 0; s < t.length; s++) {
			if (t[s].pos != 0 && t[s].pos != this._index + 1)
				continue;
			let e = {};
			e.propData = t[s];
			e.selected = this._customTids[this._index] == t[s].id;
			i.push(e)
		}
		this._ui.propList.array = i;
		this.refrshChooseNum()
	}
}
class XP extends j_ {
	get dataSource() {
		return super.dataSource
	}
	set dataSource(e) {
		super.dataSource = e;
		if (!e)
			return;
		let t = this.getChildByName("listRwd");
		let i = this.getChildByName("btnGet");
		let s = this.getChildByName("btnGo");
		let a = this.getChildByName("imgGot");
		let r = this.getChildByName("labNum");
		let l = this.getChildByName("labDesc");
		let h = this.getChildByName("boxCtn");
		let n = e.tid;
		let o = od.getTplInfo(nd.ACT_PRIVATE_GOODS, n);
		l.text = WM.getLanCodeTip(20003, [o.price]);
		r.text = WM.getLanCodeTip(20004, [o.limitNum, e.purchaseNum, o.limitNum]);
		Tb.addItemGrid(cP.splitStr2Arr(o.rwd)[0], h);
		let u = [];
		let c = e.customTids;
		if (!c)
			c = [];
		for (let d = 0; d < c.length; d++) {
			let e = od.getTplInfo(nd.ACT_PRIVATE_PRIZE, c[d]);
			if (!e) {
				u.push({})
			} else {
				u.push(cP.parseItemStr(e.rwd))
			}
		}
		for (let d = u.length; d < o.privateNum; d++) {
			u.push({})
		}
		t.dataSource = u;
		t.mouseHandler = Laya.Handler.create(this, this.onClickGrid, null, false);
		i.visible = s.visible = a.visible = false;
		if (o.limitNum - e.purchaseNum <= 0) {
			a.visible = true
		} else {
			if (c.length >= o.privateNum) {
				i.label = WM.getLanCodeTip(20001, [o.price]);
				i.visible = true;
				i.on(Laya.Event.CLICK, this, this.onCheckBtnClick)
			} else {
				s.visible = true;
				s.on(Laya.Event.CLICK, this, this.onBtnGoTo)
			}
		}
	}
	onBtnGoTo() {
		let e = this.dataSource.customTids;
		if (!e)
			e = [];
		let t = 0;
		for (let i = 1; i < e.length; i++) {
			if (e[i] <= 0) {
				t = i;
				break
			}
		}
		this.onBtnGo(t)
	}
	onClickGrid(e, t) {
		if (e && e.type != Laya.Event.CLICK)
			return;
		this.onBtnGo(t)
	}
	onBtnGo(e) {
		if (this.dataSource) {
			let t = od.getTplInfo(nd.ACT_PRIVATE_GOODS, this.dataSource.tid);
			if (t.limitNum - this.dataSource.purchaseNum <= 0)
				return;
			jP.getIns().show(this.dataSource, e)
		}
	}
	onCheckBtnClick() {
		let e = this.dataSource.tid;
		let t = od.getTplInfo(nd.ACT_PRIVATE_GOODS, e);
		FM.payMan.payOrderReq(t.payItemId)
	}
}
