class $P extends j_ {
	get dataSource() {
		return super.dataSource
	}
	set dataSource(e) {
		super.dataSource = e;
		if (!e)
			return;
		let t = this.getChildByName("listRwd");
		let i = this.getChildByName("btnGet");
		let s = this.getChildByName("imgGot");
		let a = this.getChildByName("leftLab");
		let r = this.getChildByName("limitLabTip");
		t.dataSource = cP.splitStr2Arr(e.tpl.rwd);
		if (r) {
			let t = this.getChildByName("leftLabTip");
			t.visible = a.visible = r.visible = false;
			if (e.tpl.limitNum <= 0) {
				r.visible = true
			} else {
				t.visible = a.visible = true;
				a.text = (e.tpl.limitNum - e.purchaseNum).toString()
			}
		} else {
			if (e.tpl.limitNum <= 0) {
				a.text = WM.getLanCodeTip(10018)
			} else {
				a.text = (e.tpl.limitNum - e.purchaseNum).toString()
			}
		}
		if (!e.tpl.payItemId && e.tpl.ybShop) {
			i.label = e.tpl.ybShop + " KNB"
		} else {
			i.label = WM.getLanCodeTip(20001, [e.tpl.price])
		}
		s.visible = false;
		i.visible = true;
		if (e.tpl.limitNum > 0 && e.tpl.limitNum - e.purchaseNum <= 0) {
			s.visible = true;
			i.visible = false
		}
		i.on(Laya.Event.CLICK, this, this.onCheckBtnClick)
	}
	onCheckBtnClick() {
		if (this.dataSource.tpl.payItemId) {
			FM.payMan.payOrderReq(this.dataSource.tpl.payItemId)
		} else {
			if (this.dataSource.funcId) {}
			else {
				if (!this.dataSource.tpl.payItemId && this.dataSource.tpl.ybShop) {
					wP.getIns().showBuyDetail(cP.splitStr2Arr(this.dataSource.tpl.rwd)[0], this.dataSource.tpl.limitNum - this.dataSource.purchaseNum, {
						type: c.WEALTH,
						tid: KM.M1
					}, this.dataSource.tpl.ybShop, KM.toValue(KM.M1), Laya.Handler.create(this, this.buyReq, [this.dataSource.tid]))
				} else {
					this.buyReq(this.dataSource.tid, 1)
				}
			}
		}
	}
	buyReq(e, t) {
		if (this.dataSource.type) {
			qM.sendMsg(md.ACTDATAESHOP_PRIZE_REQ, {
				tid: e,
				num: t
			})
		} else {
			qM.sendMsg(md.ACTSHOP_PRIZE_REQ, {
				tid: e,
				num: t
			})
		}
	}
}
