class tH extends g {
	constructor() {
		super("ShopBuy")
	}
	static getIns() {
		if (!this._ins) {
			this._ins = new tH
		}
		return this._ins
	}
	onClick(e) {
		switch (e.target) {
		case this._ui.btnBuy:
			this.sureBuy();
			this.closeUI();
			break;
		case this._ui.btnCancel:
			this.closeUI();
			break;
		case this._ui.btnClose:
			this.closeUI();
			break
		}
	}
	initUI() {
		this._ui = this.uiView;
		this.setLayer(1, 1, 1, 1);
		this.subAndAdd = this._ui.subAndAdd
	}
	showBuyDetail(e, t = 1) {
		this._info = e;
		this._nowNum = t;
		this.openUI()
	}
	getMaxNumByObj(e) {
		let t = Math.floor(this.data.master.wallet.m1 / e.tpl.m1);
		let i = 1e8;
		if (e.tpl.limitNum > 0) {
			i = e.tpl.limitNum - e.purchaseNum
		}
		return Math.min(i, t)
	}
	afterOpen() {
		let e = {};
		e.nowNum = this._nowNum;
		e.maxNum = this.getMaxNumByObj(this._info);
		e.callBack = this.updateInfo;
		e.caller = this;
		this.subAndAdd.dataSource = e
	}
	updateInfo() {
		let e = Tb.addItemGrid(cP.splitStr2Arr(this._info.tpl.rwd)[0], this._ui.propIcon);
		this._nowNum = this.subAndAdd.nowNum;
		this._ui.propName.text = e.info.baseTpl.name;
		this._ui.propName.color = ud.toColor(e.info.baseTpl.quality);
		this._ui.propMoneyNum.text = WM.num2Str(this._info.tpl.m1);
		Tb.addWealthGrid(KM.M1, this._ui.propMoneyIcon);
		this._ui.propLimitInfo.visible = false;
		if (this._info.tpl.limitNum > 0) {
			this._ui.propLimitInfo.visible = true;
			this._ui.propLimitInfo.text = WM.getLanCodeTip(20002, [String(this._info.tpl.limitNum - this._info.purchaseNum)])
		}
		this._ui.buyNumNum.text = String(this._nowNum);
		Tb.addWealthGrid(KM.M1, this._ui.buyPriceType);
		this._ui.buyPricePrice.text = String(this._info.tpl.m1 * this._nowNum)
	}
	sureBuy() {
		if (this._nowNum == 0)
			return;
		this.sendMsg(Fp.PROP_REQ, {
			tid: this._info.tpl.id,
			num: this._nowNum
		})
	}
}
class iH extends j_ {
	get dataSource() {
		return super.dataSource
	}
	set dataSource(e) {
		super.dataSource = e;
		if (!e)
			return;
		let t = this.getChildByName("btnGet");
		let i = t.getChildByName("moneyType");
		i.mouseEnabled = false;
		let s = t.getChildByName("moneyValue");
		let a = this.getChildByName("box0");
		let r = this.getChildByName("leftLab");
		let l = this.getChildByName("numLab");
		let h;
		let n;
		let o;
		let u;
		if (e.tpl.shopId) {
			h = cP.splitStr2Arr(e.tpl.propStr)[0];
			n = h.num;
			if (e.tpl.limitTimes && e.tpl.limitTimes > 0) {
				o = e.tpl.limitTimes
			} else {
				o = -1
			}
			u = cP.parseItemStr(e.tpl.moneyType).num
		} else {
			h = cP.splitStr2Arr(e.tpl.rwd)[0];
			n = h.num;
			o = e.tpl.limitNum;
			u = e.tpl.m1
		}
		h.num = 1;
		Tb.addItemGrid(h, a);
		let c = 1e8;
		if (r) {
			if (o < 0) {
				r.text = WM.getLanCodeTip(10031)
			} else {
				c = o - e.purchaseNum;
				r.text = c + ""
			}
		}
		l.text = "X" + n;
		if (c > 0) {
			t.disabled = false;
			i.visible = s.visible = true;
			Tb.addWealthGrid(KM.M1, i);
			s.text = u + "";
			t.on(Laya.Event.CLICK, this, this.onClick);
			t.label = ""
		} else {
			i.visible = s.visible = false;
			t.label = WM.getLanCodeTip(10012);
			t.disabled = true
		}
	}
	onClick(e) {
		if (this.dataSource.tpl.shopId) {
			FM.shopMan.onShopClick(this.dataSource)
		} else {
			tH.getIns().showBuyDetail(this.dataSource)
		}
	}
}
