class aH extends j_ {
	get dataSource() {
		return super.dataSource
	}
	set dataSource(e) {
		super.dataSource = e;
		if (!e) {
			return
		}
		if (!e.srvData || !e.myData) {
			return
		}
		let t = this.getChildByName("nameLab");
		let i = this.getChildByName("listBox");
		let s = i.getChildByName("rwdList");
		let a = this.getChildByName("btnBuy");
		let r = this.getChildByName("zoneBuyPro");
		let l = this.getChildByName("zonePrizeBox0");
		let h = this.getChildByName("zonePrizeBox1");
		let n = this.getChildByName("zonePrizeBox2");
		let o = {
			0: l,
			1: h,
			2: n
		};
		let u = this.getChildByName("myLimitTimes");
		let c = this.getChildByName("srvLimitTimes");
		let d = this.getChildByName("srvLimitMaxTimes");
		let p = this.getChildByName("oldPrice");
		let f = [];
		let _ = od.getTplInfo(nd.ACT_ZONELIMIT_PRIZE, null, {
				propId: e.srvData.tid
			});
		for (let I = 0; I < _.length; I++) {
			f[I] = {};
			f[I].num = _[I].buyTimes;
			if (I == _.length - 1) {
				f[I].x = r.width
			} else {
				f[I].x = o[I].x - r.x
			}
			o[I].dataSource = _[I]
		}
		r.data = f;
		r.value = e.srvData.purchaseNum;
		let g = od.getTplInfo(nd.ACT_ZONELIMIT_GOODS, e.myData.tid);
		s.array = cP.splitStr2Arr(g.prop);
		t.text = g.propName;
		p.text = WM.getLanCodeTip(20001, [g.oldPrice]);
		if (e.myData.purchaseNum >= g.limitNum) {
			a.label = WM.getLanCodeTip(10012);
			a.disabled = true;
			u.text = "0"
		} else {
			if (g.m1Price) {
				a.label = WM.getLanCodeTip(20022, [g.m1Price])
			} else {
				a.label = WM.getLanCodeTip(20001, [g.price])
			}
			a.disabled = false;
			a.on(Laya.Event.CLICK, this, this.onBtnBuy);
			u.text = String(g.limitNum - e.myData.purchaseNum)
		}
		let m = e.srvData.purchaseNum;
		if (g.zoneLimitNum < m)
			m = g.zoneLimitNum;
		c.text = String(m);
		d.x = c.x + c.textField.width + 1;
		d.text = "/" + String(g.zoneLimitNum)
	}
	onBtnBuy() {
		if (this.dataSource && this.dataSource.srvData) {
			let e = od.getTplInfo(nd.ACT_ZONELIMIT_GOODS, this.dataSource.myData.tid);
			if (e.m1Price) {
				QM.show(WM.getLanCodeTip(20023, [e.m1Price]), Laya.Utils.bind(this.sureBtn, this))
			} else {
				this.sureBtn(true)
			}
		}
	}
	sureBtn(e) {
		if (e) {
			if (this.dataSource && this.dataSource.srvData) {
				FM.actZoneLimit.buyGift(this.dataSource.srvData.tid)
			}
		}
	}
}
