class _H extends j_ {
	constructor() {
		super(...arguments);
		this.isOpen = false;
		this.funcId = 0;
		this.showType = 0;
		this.isRefresh = false
	}
	onAwake() {
		qM.regCmd(d.PROFILE_CHANGE, this, this.exeCmd);
		qM.regMsg(Rp.ARENA_RANK_REC, this, this.exeMsg);
		qM.regMsg(Rp.CHAMPION_RANK_REC, this, this.exeMsg);
		qM.regMsg(Up.RANK_REC, this, this.exeMsg);
		qM.regMsg(Ed.RANK_REC, this, this.exeMsg)
	}
	exeCmd(e, t) {
		if (!this.isOpen)
			return;
		switch (t) {
		case d.PROFILE_CHANGE:
			if (this.isRefresh) {
				this.dataSource = this.dataSource
			}
			break
		}
	}
	exeMsg(e, t) {
		if (!this.isOpen)
			return;
		switch (t) {
		case Rp.ARENA_RANK_REC:
			if (this.funcId == pd.ARENA) {
				this.dataSource = e.list;
				if (e.myRank < 3) {
					this.isRefresh = true
				}
			}
			break;
		case Rp.CHAMPION_RANK_REC:
			if (this.funcId == pd.CHAMPION) {
				this.dataSource = e.list;
				if (e.myRank < 3) {
					this.isRefresh = true
				}
			}
			break;
		case Up.RANK_REC:
			if (this.funcId == pd.SKYBATTLE) {
				this.dataSource = e.msList
			}
			break;
		case Ed.RANK_REC:
			if (this.funcId == pd.ARENA3V3) {
				this.dataSource = e.msList
			}
			break
		}
	}
	onEnable() {
		this.isOpen = true
	}
	onDisable() {
		this.isOpen = false
	}
	showFuncId(e, t = 0) {
		this.funcId = e;
		this.showType = t;
		this.askRank()
	}
	askRank() {
		switch (this.funcId) {
		case pd.ARENA:
			zM.getIns().sendMsg(Rp.ARENA_RANK_ASK, {
				limit: 3
			});
			break;
		case pd.CHAMPION:
			if (gC.isFighting) {
				this.dataSource = []
			} else {
				zM.getIns().sendMsg(Rp.CHAMPION_RANK_REQ, {
					limit: 3
				})
			}
			break;
		case pd.SKYBATTLE:
			zM.getIns().sendMsg(Up.RANK_REQ, {
				count: 3
			});
			break;
		case pd.ARENA3V3:
			zM.getIns().sendMsg(Ed.RANK_REQ, {
				count: 3
			});
			break
		}
	}
	get dataSource() {
		return super.dataSource
	}
	set dataSource(e) {
		super.dataSource = e;
		if (!e)
			return;
		for (let t = 0; t < 3; t++) {
			this.refreshHead(e[t], t)
		}
	}
	refreshHead(e, t) {
		let i = this.getChildByName("model" + t);
		let s = this.getChildByName("nameLab" + t);
		let a = this.getChildByName("guildLab" + t);
		let r = this.getChildByName("boxInfo" + t);
		let l = this.getChildByName("kongLab" + t);
		let h = this.getChildByName("btnAdmired" + t);
		let n = this.getChildByName("chengHaoBox" + t);
		if (a) {
			a.visible = false
		}
		h.visible = l.visible = s.visible = false;
		if (e) {
			if (e.owner._idHex == uP.getIns().master.idHex) {
				e.owner.profile = uP.getIns().master.profile
			}
			let l = od.getTplInfo(nd.AVATAR, e.owner.profile.avatarId);
			if (l) {
				let e = .7;
				if (t == 0) {
					e *= 1
				} else {
					e *= .9
				}
				q_.addUIRole(l.model, i, l.star).scale(e, e)
			}
			if (n) {
				let i = n.getChildByName("name");
				let a = n.getChildByName("img");
				if (this.showType == 0) {
					n.visible = false;
					s.visible = true;
					s.text = e.owner.profile.name
				} else {
					n.visible = true;
					i.text = e.owner.profile.name;
					a.skin = this.getTitleUrl(t)
				}
			} else {
				s.visible = true;
				s.text = e.owner.profile.name;
				if (a) {
					a.visible = true;
					if (e.owner.guildName) {
						a.text = e.owner.guildName
					} else {
						a.text = WM.getLanCodeTip(10229)
					}
				}
			}
			h.visible = true;
			h.label = String(e.admiredTimes);
			if (this.isCanAdmired(e, t)) {
				h.disabled = false;
				h.on(Laya.Event.CLICK, this, this.onClickAdm, [e.owner, t])
			} else {
				h.disabled = true
			}
			r.on(Laya.Event.CLICK, this, this.onClick, [e.owner])
		} else {
			if (n) {
				n.visible = false
			}
			q_.removeUIRole(i);
			l.visible = true;
			r.off(Laya.Event.CLICK, this, this.onClick)
		}
	}
	onClickAdm(e, t) {
		let i = this.getChildByName("btnAdmired" + t);
		switch (this.funcId) {
		case pd.ARENA:
			i.disabled = true;
			this.dataSource[t].admiredTimes += 1;
			i.label = String(this.dataSource[t].admiredTimes);
			FM.arena.sendThumb(t);
			break;
		case pd.CHAMPION:
			i.disabled = true;
			this.dataSource[t].admiredTimes += 1;
			i.label = String(this.dataSource[t].admiredTimes);
			FM.championshipsMan.sendThumb(t);
			break;
		case pd.SKYBATTLE:
			i.disabled = true;
			this.dataSource[t].admiredTimes += 1;
			i.label = String(this.dataSource[t].admiredTimes);
			FM.skyBattleMan.admire(t + 1);
			break;
		case pd.ARENA3V3:
			i.disabled = true;
			this.dataSource[t].admiredTimes += 1;
			i.label = String(this.dataSource[t].admiredTimes);
			FM.arena3V3.admire(t, this.dataSource[t].owner._idHex);
			break
		}
	}
	onClick(e) {
		if (e._idHex == uP.getIns().master.idHex || !e.srv || !e.srv.code) {
			return
		}
		HI.getIns().showDetail(e)
	}
	isCanAdmired(e, t) {
		switch (this.funcId) {
		case pd.ARENA:
		case pd.CHAMPION:
			return RS.isCanAdmired(e.owner._idHex);
		case pd.SKYBATTLE:
			return AD.isCanAdmired(t + 1);
		case pd.ARENA3V3:
			return gD.isCanAdmired(t)
		}
	}
	getTitleUrl(e) {
		let t = 1;
		let i;
		switch (this.funcId) {
		case pd.ARENA:
			i = od.getTplInfo(nd.ARENA_SEASON_PRIZE, e + 1);
			if (i)
				t = i.titleId;
			break;
		case pd.CHAMPION:
			i = od.getTplInfo(nd.CHAMPION_PRIZE, e + 1);
			if (i)
				t = i.titleId;
			break
		}
		let s = od.getTplInfo(nd.TITLE, t);
		if (s)
			return h.getUrl(l.IMAGE_ICON, "title" + s.icon);
		return "icon/title40001.png"
	}
}
