class SH extends j_ {
	get dataSource() {
		return super.dataSource
	}
	set dataSource(e) {
		super.dataSource = e;
		if (!e)
			return;
		this.clearTween();
		let t = e.tid;
		let i;
		if (t)
			i = od.getTplInfo(nd.ARENA3V3_FIGHT_PRIZE, t);
		let s = this.getChildByName("gridBox");
		let a = s.getChildByName("boxCtn");
		let r = s.getChildByName("labName");
		let l = s.getChildByName("gotImg");
		let h = s.getChildByName("gridBack");
		let n = this.getChildByName("btnSure");
		let o = this.getChildByName("backImg");
		s.visible = o.visible = n.visible = false;
		if (SD.getIns().isGotPrize(this.dataSource.index) && i) {
			s.visible = true;
			let e = Tb.addItemGrid(cP.splitStr2Arr(i.rwd)[0], a);
			a.gray = true;
			r.color = ud.toColor(e.info.baseTpl.quality);
			r.text = e.info.baseTpl.name;
			if (e.info.baseTpl.quality == 3) {
				h.skin = "img/kuafu3v3/ka2.png"
			} else {
				h.skin = "img/kuafu3v3/ka1.png"
			}
		} else {
			if (i) {
				n.visible = true;
				let e = n.getChildByName("btnMoneyBox");
				e.mouseEnabled = false;
				e.dataSource = X_.getTypeData(SD.getIns().openCost, false);
				n.on(Laya.Event.CLICK, this, this.onOpen)
			}
			o.visible = true;
			o.on(Laya.Event.CLICK, this, this.onOpen)
		}
	}
	onOpen() {
		if (SD.getIns().isGotPrize(this.dataSource.index)) {
			FM.noticeMan.showNotice(WM.getLanCodeTip(10036))
		} else {
			SD.getIns().openReward(this.dataSource.index, this.dataSource.tid)
		}
	}
	startEffect() {
		let e = this.getChildByName("gridBox");
		let t = this.getChildByName("backImg");
		e.visible = false;
		t.visible = true;
		Laya.timer.once(30, this, this.step0)
	}
	step0() {
		let e = this.getChildByName("backImg");
		Laya.Tween.to(e, {
			scaleX: .03
		}, 110, null, Laya.Handler.create(this, this.step1))
	}
	step1() {
		let e = this.getChildByName("gridBox");
		let t = this.getChildByName("backImg");
		t.visible = false;
		e.visible = true;
		e.scaleX = .03;
		Laya.Tween.to(e, {
			scaleX: 1
		}, 90)
	}
	clearTween() {
		let e = this.getChildByName("gridBox");
		let t = this.getChildByName("backImg");
		Laya.Tween.clearAll(e);
		Laya.Tween.clearAll(t);
		e.scaleX = t.scaleX = 1
	}
}
