class xH extends j_ {
	get dataSource() {
		return super.dataSource
	}
	set dataSource(e) {
		super.dataSource = e;
		if (!e)
			return;
		let t = e.tid;
		let i = od.getTplInfo(nd.ARENA_LEVEL_SHOP, t);
		let s = this.getChildByName("discount");
		let a = this.getChildByName("sellout");
		let r = this.getChildByName("learnedImg");
		let l = this.getChildByName("propIcon");
		let h = this.getChildByName("propName");
		let n = this.getChildByName("propInfo");
		if (n) {
			n.style.color = "#683f12";
			n.style.fontSize = 24;
			n.style.bold = true
		}
		let o = this.getChildByName("btnBuy");
		let u;
		let c;
		if (o) {
			u = o.getChildByName("cellMoneyIcon");
			c = o.getChildByName("cellMoneyNum")
		} else {
			u = this.getChildByName("cellMoneyIcon");
			c = this.getChildByName("cellMoneyNum")
		}
		if (s) {
			if (i.discount && i.discount != 10) {
				s.visible = true;
				let e = s.getChildByName("label");
				e.text = WM.getLanCodeTip(20017, [i.discount])
			} else {
				s.visible = false
			}
		}
		let d = cP.splitStr2Arr(i.propStr);
		let p = Tb.addItemGrid(d[0], l);
		l.gray = false;
		h.text = p.info.baseTpl.name;
		if (r) {
			r.visible = false;
			if (i.shopId == 40 && V_.checkTalentForSkillShop(d[0].tid)) {
				r.visible = true
			}
		}
		if (a) {
			a.visible = false
		}
		if (i.limitTimes && i.limitTimes > 0 && n) {
			n.visible = true;
			if (i.limitVip && uP.getIns().master.vip < i.limitVip) {
				n.innerHTML = WM.getHtmlByColor("VIP" + i.limitVip, m.TIP_GREEN) + "Chuyên môn"
			} else {
				let t;
				if (i.limitTime) {
					t = i.limitTime
				}
				n.innerHTML = this.getTimeName(t) + WM.getHtmlByColor(String(e.purchaseNum) + "/" + String(i.limitTimes), m.TIP_GREEN)
			}
			n.x = 21 + (158 - n.contextWidth) * .5;
			if (e.purchaseNum == i.limitTimes) {
				if (a) {
					a.visible = true
				}
				l.gray = true
			}
		} else {
			if (n) {
				n.visible = false
			}
		}
		let f = cP.splitStr2Arr(i.moneyType);
		c.text = WM.num2Str(f[0].num);
		let _ = Tb.addWealthGridByInfo(f[0], u);
		_.mouseEnabled = false;
		if (o)
			o.on(Laya.Event.CLICK, this, this.onBuyClick)
	}
	onBuyClick() {
		let e = this.dataSource;
		if (this.canShowDetail(e)) {
			BD.getIns().showBuyDetail(e, e.buyType)
		}
	}
	canShowDetail(e) {
		let t = e.tid;
		let i = od.getTplInfo(nd.ARENA_LEVEL_SHOP, t);
		if (i.limitVip && uP.getIns().master.vip < i.limitVip) {
			FM.noticeMan.showNotice("vip" + i.limitVip + "Trở lên có thể mua");
			return
		}
		if (i.limitTimes && i.limitTimes > 0 && e.purchaseNum >= i.limitTimes) {
			FM.noticeMan.showNotice("Đã bán xong");
			return false
		}
		if (!cP.checkEnough(i.moneyType)) {
			let e = cP.parseItemStr(i.moneyType);
			Ng.getIns().showGetInfoDetail(e.tid, e.type);
			return false
		}
		return true
	}
	getTimeName(e) {
		if (!e) {
			return WM.getLanCodeTip(10549)
		}
		let t = e.split(":");
		switch (parseInt(t[0])) {
		case b_.TIMETYPE_HOUR:
			return WM.getLanCodeTip(10547);
			break;
		case b_.TIMETYPE_DAY:
			return WM.getLanCodeTip(10548);
			break;
		case b_.TIMETYPE_WEEK:
			return WM.getLanCodeTip(10508);
			break;
		case b_.TIMETYPE_MONTH:
			return WM.getLanCodeTip(10509);
			break
		}
	}
}
