class UH extends j_ {
	get dataSource() {
		return super.dataSource
	}
	set dataSource(e) {
		super.dataSource = e;
		if (!e)
			return;
		this._nowNum = e.nowNum;
		this._maxNum = e.maxNum;
		this.progress = this.getChildByName("progress");
		this.btnSub = this.getChildByName("btnSub");
		this.progressUp = this.getChildByName("progressUp");
		this.progressBack = this.getChildByName("progressBack");
		this.btnAdd = this.getChildByName("btnAdd");
		this.btnMax = this.getChildByName("btnMax");
		this.progress.on(Laya.Event.MOUSE_DOWN, this, this.progreeeIn);
		this.progress.on(Laya.Event.DRAG_MOVE, this, this.progreeeMove);
		this.progress.on(Laya.Event.DRAG_END, this, this.progreeeOut);
		this.btnSub.on(Laya.Event.CLICK, this, this.onclick);
		this.btnAdd.on(Laya.Event.CLICK, this, this.onclick);
		this.btnMax.on(Laya.Event.CLICK, this, this.onclick);
		if (this._maxNum <= 0) {
			this._nowNum = 0;
			this.progress.disabled = true;
			this.btnSub.disabled = true;
			this.btnAdd.disabled = true;
			this.btnMax.disabled = true
		} else {
			this.progress.disabled = false;
			this.btnSub.disabled = false;
			this.btnAdd.disabled = false;
			this.btnMax.disabled = false
		}
		this.updateInfo()
	}
	onclick(e) {
		switch (e.target) {
		case this.btnSub:
			this._nowNum--;
			if (this._nowNum < 0)
				this._nowNum = 0;
			this.updateInfo();
			break;
		case this.btnAdd:
			if (this._maxNum <= 0)
				return;
			this._nowNum++;
			if (this._nowNum > this._maxNum)
				this._nowNum = this._maxNum;
			this.updateInfo();
			break;
		case this.btnMax:
			if (this._maxNum <= 0)
				return;
			this._nowNum = this._maxNum;
			this.updateInfo();
			break
		}
	}
	get nowNum() {
		return this._nowNum
	}
	get maxNum() {
		return this._maxNum
	}
	progreeeIn() {
		this.progress.startDrag(new Laya.Rectangle(this.progressBack.x + this.progress.width * .5, this.progress.y, this.progressBack.width - this.progress.width * 1, 0));
		this.isStartDrag = true
	}
	progreeeMove() {
		if (!this.isStartDrag)
			return;
		this.progressScale = (this.progress.x - this.progress.width * .5 - this.progressBack.x) / (this.progressBack.width - this.progress.width * 1);
		this._nowNum = Math.round(this.progressScale * this._maxNum);
		this.updateInfo(false)
	}
	progreeeOut() {
		this.isStartDrag = false
	}
	updateInfo(e = true) {
		if (e) {
			if (this._maxNum == 0) {
				this.progressScale = 0
			} else {
				this.progressScale = this._nowNum / this._maxNum
			}
		}
		if (!this.progressScale) {
			this.progressUp.width = 0;
			this.progress.x = this.progressBack.x + this.progress.width * .5
		} else {
			this.progressUp.width = (this.progressBack.width - 6) * this.progressScale;
			this.progress.x = this.progressBack.x + this.progress.width * .5 + (this.progressBack.width - this.progress.width * 1) * this.progressScale
		}
		let t = this.dataSource;
		let i = t.callBack;
		i.call(t.caller, this._nowNum, this._maxNum)
	}
}
