class AG extends j_ {
	constructor() {
		super();
		this.checkPos = 50
	}
	start(e, t, i = 50) {
		this.preFun = e;
		this.nextFun = t;
		this.checkPos = i;
		this.on(Laya.Event.MOUSE_DOWN, this, this.onMouseBoxDownFun)
	}
	stop() {
		this.off(Laya.Event.MOUSE_DOWN, this, this.onMouseBoxDownFun);
		this.onMouseEventOutFun(null)
	}
	onMouseBoxDownFun(e) {
		if (!this.startClickPos)
			this.startClickPos = new Laya.Point;
		this.startClickPos.x = e.stageX;
		this.startClickPos.y = e.stageY;
		Laya.stage.on(Laya.Event.MOUSE_UP, this, this.onMouseEventUpFun);
		Laya.stage.on(Laya.Event.MOUSE_OUT, this, this.onMouseEventOutFun)
	}
	onMouseEventUpFun(e) {
		if (!this.endClickPos)
			this.endClickPos = new Laya.Point;
		this.endClickPos.x = e.stageX;
		this.endClickPos.y = e.stageY;
		Laya.stage.off(Laya.Event.MOUSE_UP, this, this.onMouseEventUpFun);
		Laya.stage.off(Laya.Event.MOUSE_OUT, this, this.onMouseEventOutFun);
		this.changePageFun()
	}
	onMouseEventOutFun(e) {
		Laya.stage.off(Laya.Event.MOUSE_UP, this, this.onMouseEventUpFun);
		Laya.stage.off(Laya.Event.MOUSE_OUT, this, this.onMouseEventOutFun)
	}
	changePageFun() {
		if (this.startClickPos && this.endClickPos && Math.abs(this.startClickPos.x - this.endClickPos.x) > this.checkPos) {
			if (this.startClickPos.x < this.endClickPos.x) {
				this.changeToPrev()
			} else {
				this.changeToNext()
			}
		}
	}
	changeToPrev() {
		if (this.preFun) {
			this.preFun.call(null)
		}
	}
	changeToNext() {
		if (this.nextFun) {
			this.nextFun.call(null)
		}
	}
}
