class OG extends j_ {
	constructor() {
		super(...arguments);
		this.isOpen = false
	}
	onAwake() {
		qM.regCmd(d.CHAMPION_PERIOD_CHANGE, this, this.exeCmd)
	}
	exeCmd(e, t) {
		if (!this.isOpen)
			return;
		switch (t) {
		case d.CHAMPION_PERIOD_CHANGE:
			this.refreshVSAndWin();
			break
		}
	}
	onEnable() {
		this.isOpen = true
	}
	onDisable() {
		this.isOpen = false;
		Laya.timer.clear(this, this.refreshVSAndWin)
	}
	showDatial(e) {
		this.showData = e;
		this.refreshVSAndWin();
		this.refreshPostion(e.A, 0);
		this.refreshPostion(e.B, 1)
	}
	refreshVSAndWin() {
		if (!this.showData)
			return;
		let e = false;
		let t = false;
		Laya.timer.clear(this, this.refreshVSAndWin);
		if (this.showData.round != gC.round) {
			e = true;
			t = true
		} else {
			if (gC.period >= gC.P3) {
				let i = b_.getTimeStamp();
				if (this.showData.replayIdHex && this.showData.endTime && i >= this.showData.endTime) {
					e = true;
					t = true
				} else {
					t = true;
					Laya.timer.once(this.showData.endTime - i + 10, this, this.refreshVSAndWin)
				}
			}
		}
		let i = this.getChildByName("winImg1");
		let s = this.getChildByName("winImg0");
		let a = this.getChildByName("VSImg");
		let r = this.getChildByName("btnWatch");
		a.visible = r.visible = i.visible = s.visible = false;
		if (e) {
			if (this.showData.winner == 1) {
				s.visible = true
			} else if (this.showData.winner == 2) {
				i.visible = true
			}
		}
		if (t && this.showData.B) {
			r.visible = true;
			r.on(Laya.Event.CLICK, this, this.onClickWatch)
		} else {
			a.visible = true
		}
	}
	refreshPostion(e, t) {
		let i = this.getChildByName("postionBox" + t);
		let s = i.getChildByName("playerHead");
		let a = i.getChildByName("playerName");
		let r = i.getChildByName("labCP");
		let l = i.getChildByName("playerLv");
		let h = i.getChildByName("imgForm");
		for (let n = 1; n < 10; n++) {
			Tb.removeGrid(i.getChildByName("imgPos" + n))
		}
		if (!e) {
			a.text = WM.getLanCodeTip(10147);
			UI.removeHead(s);
			l.text = WM.getLanCodeTip(20025, [0]);
			r.text = "0";
			return
		}
		h.skin = "img/zhandou/ZhenX_" + e.positionTid + ".png";
		UI.addPlayerHead(e.ms, s);
		a.text = e.ms.profile.name;
		l.text = WM.getLanCodeTip(20025, [e.ms.level]);
		r.text = e.ms.power;
		for (let n = 0; n < e.hs.length; n++) {
			e.hs[n].type = c.HERO;
			let t;
			for (let s = 0; s < e.grids.length; s++) {
				if (e.hs[n]._idHex == e.grids[s]._idHex) {
					t = i.getChildByName("imgPos" + e.grids[s].pos);
					break
				}
			}
			if (t) {
				Tb.addItemGrid(e.hs[n], t)
			}
		}
	}
	refrshSide(e) {
		if (!this.showData)
			return;
		if (e.ms._idHex == this.showData.A.ms._idHex) {
			this.refreshPostion(e, 0)
		} else if (e.ms._idHex == this.showData.B.ms._idHex) {
			this.refreshPostion(e, 1)
		}
	}
	onClickWatch() {
		FM.videoMan.getVideo(this.showData.replayIdHex)
	}
}
