class ZG extends g {
	constructor() {
		super("Collectgift2");
		this._propertyLists = []
	}
	static getIns() {
		if (!this._ins) {
			this._ins = new ZG
		}
		return this._ins
	}
	initUI() {
		this._ui = this.uiView;
		this.setLayer(1, 1, 1, 1)
	}
	propertyFilterSelect(e) {
		if (e < 0)
			return;
		this._selectedIndex = e;
		this.freshPropertyList()
	}
	onClick(e) {
		switch (e.target) {
		case this._ui.btnCancel:
			this.closeUI();
			break;
		case this._ui.btnSure:
			let t = this._ui.listProperty.getItem(this._selectedIndex);
			jT.getIns().callBackSelectPropertys(t.attr, this._type);
			this.closeUI();
			break
		}
	}
	show(e, t) {
		this._propertyLists = e;
		this._type = t;
		this._selectedIndex = 0;
		this.openUI()
	}
	afterOpen() {
		this.freshPropertyList()
	}
	freshPropertyList() {
		let e = [];
		for (let t = 0; t < this._propertyLists.length; t++) {
			e.push({
				attr: this._propertyLists[t],
				index: t,
				isSelect: this._selectedIndex == t
			})
		}
		this._ui.listProperty.array = e;
		this._ui.listProperty.selectedIndex = this._selectedIndex
	}
}
