class gU extends j_ {
	get dataSource() {
		return super.dataSource
	}
	set dataSource(e) {
		super.dataSource = e;
		if (!e)
			return;
		let t = this.getChildByName("labDesc");
		let i = this.getChildByName("labNum");
		let s = this.getChildByName("labNum1");
		let a = this.getChildByName("listRwd");
		let r = this.getChildByName("btnGet");
		let l = this.getChildByName("btnGo");
		let h = this.getChildByName("imgGot");
		let n = od.getTplInfo(nd.TASK_DATA, e.tpl.taskId);
		t.text = n.info;
		let o = cP.splitStr2Arr(n.prize);
		if (e.tpl.point) {
			o.push({
				type: c.PROP,
				tid: 200023,
				num: e.tpl.point
			})
		}
		a.array = o;
		let u = uP.getIns().task.getTaskItem(e.funcId, e.tpl.taskId);
		if (u) {
			if (i) {
				i.text = (u.value > n.target ? n.target : u.value) + "/" + n.target
			}
			if (s) {
				s.text = "(" + (u.value > n.target ? n.target : u.value) + "/" + n.target + ")"
			}
			if (u.done) {
				if (u.rewardGot) {
					l.visible = false;
					r.visible = false;
					h.visible = true
				} else {
					l.visible = false;
					r.visible = true;
					h.visible = false
				}
			} else {
				l.visible = true;
				r.visible = false;
				h.visible = false
			}
		} else {
			if (i) {
				i.text = "0/" + n.target
			}
			if (s) {
				s.text = "(0/" + n.target + ")"
			}
			l.visible = true;
			r.visible = false;
			h.visible = false
		}
		if (u && u.done) {
			r.on(Laya.Event.CLICK, this, this.getRwd, [e.funcId, e.tpl.taskId])
		} else {
			l.on(Laya.Event.CLICK, this, this.goto, [n.actionId])
		}
	}
	getRwd(e, t) {
		qM.sendMsg(zp.TASK_ONE_GET, {
			funcId: e,
			taskId: t
		})
	}
	goto(e) {
		FM.mainCityMan.openUI();
		qT.do(e)
	}
}
