class EU extends j_ {
	get dataSource() {
		return super.dataSource
	}
	set dataSource(e) {
		super.dataSource = e;
		if (!e)
			return;
		let t = this.getChildByName("prizeList");
		let i = this.getChildByName("hardLevelImg");
		let s = this.getChildByName("levelName");
		let a = this.getChildByName("recommendTag");
		let r = this.getChildByName("openTip");
		let n = this.getChildByName("btnFight");
		let o = this.getChildByName("btnNoOpen");
		let u = this.getChildByName("btnMopUp");
		let c = u.getChildByName("moneyLab");
		let d = u.getChildByName("moneyGrid");
		s.text = e.name;
		s.color = ud.getRewardTaskColor(e.hardType);
		s.strokeColor = ud.getRewardTaskStrokeColor(e.hardType);
		i.skin = h.getUrl(l.IMAGE, "daily/tab_" + (e.hardType - 1) + ".png");
		let p = Ex.getOneFBData(e.type);
		this.status = 0;
		if (p.combatNumPass >= e.level) {
			this.status = 1
		} else {
			if (p.combatNumOpen >= e.level) {
				this.status = 2
			} else {
				this.status = 0
			}
		}
		if (this.status > 0) {
			if (p.playTimes.freeTimes[1] && p.playTimes.freeTimes[1] >= od.getGlobalValue(8001, 0)) {
				this.status += 2
			}
		}
		n.visible = false;
		o.visible = false;
		u.visible = false;
		r.visible = false;
		let f;
		switch (this.status) {
		case 0:
			o.visible = true;
			o.gray = true;
			f = cP.splitStr2Arr(e.firstPrize);
			if (uP.getIns().master.level < e.openLevel) {
				o.label = WM.getLanCodeTip(20118, [this.dataSource.openLevel])
			} else {
				o.label = WM.getLanCodeTip(10125)
			}
			if (uP.getIns().master.cp < this.dataSource.openPower) {
				r.visible = true;
				r.text = WM.getLanCodeTip(20119, [this.dataSource.openPower])
			}
			o.on(Laya.Event.CLICK, this, this.onNoOpenClick);
			break;
		case 1:
			u.visible = true;
			f = cP.splitStr2Arr(e.mopUpPrize);
			u.on(Laya.Event.CLICK, this, this.onMopUpClick);
			c.text = WM.getLanCodeTip(10272);
			c.x = 31;
			d.visible = false;
			break;
		case 2:
			n.visible = true;
			f = cP.splitStr2Arr(e.firstPrize);
			n.on(Laya.Event.CLICK, this, this.onFightClick);
			break;
		case 3:
			u.visible = true;
			f = cP.splitStr2Arr(e.mopUpPrize);
			u.on(Laya.Event.CLICK, this, this.onMopUpClick);
			let t = cP.parseItemStr(e.mopUpPrice);
			c.text = WM.getLanCodeTip(20120, [t.num]);
			c.x = 53;
			d.visible = true;
			t.num = 0;
			Tb.addWealthGridByInfo(t, d);
			break;
		case 4:
			n.visible = true;
			f = cP.splitStr2Arr(e.firstPrize);
			n.on(Laya.Event.CLICK, this, this.onFightClick);
			break
		}
		t.array = f;
		let _ = p.combatNumOpen;
		if (_ > p.combatNumPass + 1) {
			_ = p.combatNumPass + 1
		}
		if (e.level == _ && !o.visible) {
			a.visible = true
		} else {
			a.visible = false
		}
	}
	onNoOpenClick() {
		if (uP.getIns().master.level < this.dataSource.openLevel) {
			FM.noticeMan.showNotice(WM.getLanCodeTip(20118, [this.dataSource.openLevel]))
		} else if (uP.getIns().master.cp < this.dataSource.openPower) {
			FM.noticeMan.showNotice(WM.getLanCodeTip(20119, [this.dataSource.openPower]))
		} else {
			FM.dailyFBMan.fightFB(this.dataSource.type, this.dataSource.level)
		}
	}
	onMopUpClick() {
		let e = Ex.getOneFBData(this.dataSource.type);
		if (Ex.isNoTimes(e)) {
			return
		}
		if (e.playTimes.freeTimes[1] && e.playTimes.freeTimes[1] >= od.getGlobalValue(8001, 0) && !KM.isEnough(KM.M1, od.getGlobalValue(8002))) {
			return
		}
		FM.dailyFBMan.mopUpFB(this.dataSource.type, this.dataSource.level)
	}
	onFightClick() {
		let e = Ex.getOneFBData(this.dataSource.type);
		if (this.dataSource.level > e.combatNumPass + 1) {
			FM.noticeMan.showNotice(WM.getLanCodeTip(10273))
		} else {
			FM.dailyFBMan.fightFB(this.dataSource.type, this.dataSource.level)
		}
	}
}
