class vU extends j_ {
	constructor() {
		super(...arguments);
		this._selected = true
	}
	get dataSource() {
		return super.dataSource
	}
	set dataSource(e) {
		super.dataSource = e;
		if (!e)
			return;
		let t = this.getChildByName("labNum");
		t.text = e.missionTpl.chapter + "-" + e.missionTpl.mission;
		this.selected = false;
		this.refreshStar();
		this.refreshActive()
	}
	refreshStar() {
		let e = this.dataSource.missionTpl;
		let t = e.challenge.split(":");
		let i = aL.getChallenge(e.chapter, e.id);
		for (let s = 0; s < t.length; s++) {
			let e = this.getChildByName("imgStar" + (s + 1));
			if (i[s]) {
				e.skin = "img/Destiny/star.png"
			} else {
				e.skin = "img/Destiny/star1.png"
			}
		}
	}
	refreshActive() {
		let e = this.getChildByName("imgIcon");
		let t = this.dataSource.missionTpl;
		if (t.mission == 10) {
			e.skin = "img/Destiny/" + this.dataSource.chapterTpl.icon + ".png";
			if (t.id <= aL.combatNumPass + 1) {
				this.gray = false
			} else {
				this.gray = true
			}
		} else {
			if (t.id <= aL.combatNumPass + 1) {
				e.skin = "img/Destiny/base.png"
			} else {
				e.skin = "img/Destiny/base1.png"
			}
		}
	}
	set selected(e) {
		if (this._selected == e)
			return;
		this._selected = e;
		if (e) {
			N_.addEffect("UI/xiaojian", this, true, 59, 69)
		} else {
			N_.removeEffect(this)
		}
	}
	get selected() {
		return this._selected
	}
}
