class KU extends j_ {
	get dataSource() {
		return super.dataSource
	}
	set dataSource(e) {
		super.dataSource = e;
		if (this.img3)
			this.img3.visible = false;
		if (this.touxiang)
			this.touxiang.visible = false;
		if (!e)
			return;
		let t = this.getChildByName("boxCtn");
		let i = this.getChildByName("imgNoUse");
		let s = this.getChildByName("imgLock");
		let a = this.getChildByName("imgAdd");
		let r = this.getChildByName("imgDot");
		let l = this.getChildByName("timeLabImage");
		let h = l.getChildByName("timeLab");
		r.visible = false;
		Tb.removeGrid(t);
		if (e == 1) {
			i.visible = true;
			s.visible = false;
			a.visible = false;
			l.visible = false;
			if (this.img3)
				this.img3.visible = false;
			if (this.touxiang)
				this.touxiang.visible = false;
			return
		}
		let o = e.type;
		if (o == 1) {
			i.visible = false;
			s.visible = false;
			a.visible = false;
			l.visible = false;
			let h = e.model;
			let n = h.leftTime - uP.getIns().serverTime;
			if (n > 0) {
				l.visible = true;
				vg.start(n, this, this.timerFun, 1, null)
			} else {
				if (h.hid != null && h.hid != "") {
					let e = FM.mingGeSharedMan.getMingGe(h.hid);
					Tb.addItemGrid(e, t).mouseEnabled = false
				} else {
					a.visible = true;
					if (e && e.msgBagId && FM.mingGeSharedMan.checkDotCanAddAndEmpty(e.msgBagId)) {
						r.visible = true
					}
				}
			}
		} else if (o == 2) {
			i.visible = false;
			s.visible = true;
			a.visible = false;
			l.visible = false
		}
		if (!this.touxiang)
			this.touxiang = new Laya.Image;
		this.touxiang.width = 36;
		this.touxiang.height = 36;
		this.touxiang.pos(130 - 36 - 5, 5);
		if (!this.touxiangMask)
			this.touxiangMask = new Laya.Image;
		this.touxiangMask.width = 36;
		this.touxiangMask.height = 36;
		if (!this.img3)
			this.img3 = new n;
		this.img3.width = 36;
		this.img3.height = 36;
		this.img3.pos(130 - 36 - 5, 5);
		this.addChild(this.img3);
		this.addChild(this.touxiang);
		this.img3.visible = false;
		this.touxiang.visible = false;
		if (o == 1) {
			let t = e.model;
			if (t.hid != null && t.hid != "") {
				let e = FM.mingGeSharedMan.getInHeroData(t.hid);
				if (e) {
					let t = od.getTplInfo(nd.HERO, null, {
							protoId: e.baseTpl.protoId
						});
					let i = t[t.length - 1];
					if (i) {
						this.touxiang.skin = "img/herocut/touxiang.png";
						this.touxiangMask.skin = "img/herocut/touxiangdi.png";
						this.img3.skin = "icon/head" + i.icon + ".png";
						this.img3.mask = this.touxiangMask;
						this.img3.visible = true;
						this.touxiang.visible = true
					}
				}
			}
		}
	}
	timerFun(e, t) {
		let i = this.getChildByName("boxCtn");
		let s = this.getChildByName("imgNoUse");
		let a = this.getChildByName("imgLock");
		let r = this.getChildByName("imgAdd");
		let l = this.getChildByName("timeLabImage");
		let h = l.getChildByName("timeLab");
		let n;
		if (e >= b_.ONEDAYMILLISECONDS) {
			n = b_.getDayHourStr(e)
		} else {
			n = b_.getCdTimeStrByMs(e)
		}
		h.text = n;
		if (t) {
			s.visible = false;
			a.visible = false;
			r.visible = false;
			l.visible = false;
			r.visible = true
		}
	}
}
