		super.dataSource = e;
		if (!e)
			return;
		let t = e;
		let i = this.getChildByName("sideAMark");
		let s = i.getChildByName("sideAWinMark");
		let a = i.getChildByName("sideAFailMark");
		let r = this.getChildByName("sideBMark");
		let l = r.getChildByName("sideBWinMark");
