class LF extends j_ {
	get dataSource() {
		return super.dataSource
	}
	set dataSource(e) {
		super.dataSource = e;
		if (!e)
			return;
		let t = this.getChildByName("boxCtn");
		let i = this.getChildByName("imgNoUse");
		let s = this.getChildByName("imgLock");
		let a = this.getChildByName("imgAdd");
		let r = this.getChildByName("timeLabImage");
		let l = r.getChildByName("timeLab");
		Tb.removeGrid(t);
		if (e == 1) {
			i.visible = true;
			s.visible = false;
			a.visible = false;
			r.visible = false;
			return
		}
		let h = e.type;
		if (h == 1) {
			i.visible = false;
			s.visible = false;
			a.visible = false;
			r.visible = false;
			let l = e.model;
			let h = l.leftTime - uP.getIns().serverTime;
			if (h > 0) {
				r.visible = true;
				vg.start(h, this, this.timerFun, 1, null)
			} else {
				if (l.hid != null && l.hid != "") {
					let e = FM.heroLevelShareMan.getShareHeroData(l.hid);
					if (e) {
						Tb.addItemGrid(e, t).mouseEnabled = false
					}
				} else {
					a.visible = true
				}
			}
		} else if (h == 2) {
			i.visible = false;
			s.visible = true;
			a.visible = false;
			r.visible = false
		}
	}
	timerFun(e, t) {
		let i = this.getChildByName("boxCtn");
		let s = this.getChildByName("imgNoUse");
		let a = this.getChildByName("imgLock");
		let r = this.getChildByName("imgAdd");
		let l = this.getChildByName("timeLabImage");
		let h = l.getChildByName("timeLab");
		let n;
		if (e >= b_.ONEDAYMILLISECONDS) {
			n = b_.getDayHourStr(e)
		} else {
			n = b_.getCdTimeStrByMs(e)
		}
		h.text = n;
		if (t) {
			s.visible = false;
			a.visible = false;
			r.visible = false;
			l.visible = false;
			r.visible = true
		}
	}
}
