class MF extends g {
	constructor() {
		super("ForgeRuneChose")
	}
	static getIns() {
		if (!this._ins) {
			this._ins = new MF
		}
		return this._ins
	}
	onClick(e) {
		switch (e.target) {
		case this._ui.btnSure:
			this.refreshList();
			FM.forgeMan.setShowList(this._list);
			this.closeUI();
			break
		}
	}
	initUI() {
		this._ui = this.uiView;
		this.setLayer(1, 1, 1, 1)
	}
	openList(e) {
		this._list = e;
		if (!this._list) {
			this._list = []
		}
		this.openUI()
	}
	refreshList() {
		let e = this._ui.propList.array;
		this._list.length = 0;
		for (let t = 0; t < e.length; t++) {
			if (e[t].selected) {
				this._list.push(e[t].runeData._idHex)
			}
		}
	}
	checkSelect(e) {
		let t = this._ui.propList.array;
		let i = e.tid;
		let s = 0;
		for (let a = 0; a < t.length; a++) {
			if (t[a].selected) {
				if (t[a].runeData.tid != i) {
					FM.noticeMan.showNotice(WM.getLanCodeTip(10299));
					return false
				}
				s++
			}
		}
		if (s >= od.getGlobalValue(704)) {
			FM.noticeMan.showNotice(WM.getLanCodeTip(10230));
			return false
		}
		s++;
		return true
	}
	refrshChooseNum() {
		let e = 0;
		let t = this._ui.propList.array;
		for (let i = 0; i < t.length; i++) {
			if (t[i].selected) {
				e++
			}
		}
		this._ui.chooseNumLab.text = WM.getLanCodeTip(20327, [e, od.getGlobalValue(704)])
	}
	afterOpen() {
		this.updateInfo()
	}
	updateInfo() {
		let e = this.data.bag.rune.list;
		let t = [];
		for (let i = 0; i < e.length; i++) {
			if (e[i].tid == 5) {
				continue
			}
			let s = {};
			s.runeData = e[i];
			s.selected = this._list.indexOf(e[i]._idHex) != -1;
			t.push(s)
		}
		this._ui.propList.array = t;
		this.refrshChooseNum()
	}
}
