class jF extends j_ {
	get dataSource() {
		return super.dataSource
	}
	set dataSource(e) {
		super.dataSource = e;
		if (!e)
			return;
		this.clearShake();
		this.clearEffect();
		this.boxShake = this.getChildByName("boxShake");
		this.grid = this.boxShake.getChildByName("grid");
		this.grid.scaleX = 1;
		this.back = this.boxShake.getChildByName("back");
		this.back.scaleX = 1;
		this.selectBox = this.boxShake.getChildByName("selectBox");
		this.boxCtn = this.grid.getChildByName("boxCtn");
		this.imgDiscount = this.boxShake.getChildByName("imgDiscount");
		this.labDiscount = this.imgDiscount.getChildByName("labDiscount");
		if (e.tpl) {
			this.back.visible = false;
			this.grid.visible = true;
			this.imgDiscount.visible = true;
			this.labDiscount.text = Math.floor(e.price / e.tpl.price * 10).toFixed(1) + "Gãy";
			this.itemGrid = Tb.addItemGrid(cP.parseItemStr(e.tpl.rwd), this.boxCtn);
			this.itemGrid.mouseEnabled = false;
			this.boxCtn.on(Laya.Event.CLICK, this, this.clickGrid);
			if (e.tpl.isTuChu) {
				N_.addEffect("hydt/HYDTSP", this.boxCtn)
			} else {
				N_.removeEffect(this.boxCtn)
			}
		} else {
			this.back.visible = true;
			this.grid.visible = false;
			this.imgDiscount.visible = false;
			N_.removeEffect(this.boxCtn);
			Tb.removeGrid(this.boxCtn);
			this.itemGrid = null
		}
		this.selected = e.selected
	}
	set selected(e) {
		if (!this.selectBox)
			return;
		this.selectBox.visible = e
	}
	clickGrid() {
		if (!this.itemGrid)
			return;
		this.itemGrid.clickThis()
	}
	startEffect(e) {
		if (!this.grid)
			return;
		this.dataSource = e;
		this.grid.visible = false;
		this.back.visible = true;
		this.imgDiscount.visible = false;
		Laya.timer.once(70, this, this.step0)
	}
	step0() {
		Laya.Tween.to(this.back, {
			scaleX: .03
		}, 110, null, Laya.Handler.create(this, this.step1))
	}
	step1() {
		this.back.visible = false;
		this.grid.visible = true;
		this.grid.scaleX = .03;
		Laya.Tween.to(this.grid, {
			scaleX: 1
		}, 90, null, Laya.Handler.create(this, this.step2))
	}
	step2() {
		this.imgDiscount.visible = true
	}
	clearEffect() {
		if (!this.grid || !this.back)
			return;
		Laya.timer.clearAll(this);
		Laya.Tween.clearAll(this.grid);
		this.grid.scaleX = 1;
		Laya.Tween.clearAll(this.back);
		this.back.scaleX = 1
	}
	shake() {
		if (!this.boxShake)
			return;
		Laya.Tween.to(this.boxShake, {
			rotation: 2
		}, 60, null, Laya.Handler.create(this, this.shake1))
	}
	shake1() {
		Laya.Tween.to(this.boxShake, {
			rotation: -2
		}, 120, null, Laya.Handler.create(this, this.shake2))
	}
	shake2() {
		Laya.Tween.to(this.boxShake, {
			rotation: 0
		}, 100, Laya.Ease.backOut, Laya.Handler.create(this, this.shake2))
	}
	clearShake() {
		if (!this.boxShake)
			return;
		Laya.Tween.clearAll(this.boxShake);
		this.boxShake.rotation = 0
	}
}
