class pV extends g {
	constructor() {
		super("GuildManage")
	}
	static getIns() {
		if (!this._ins) {
			this._ins = new pV
		}
		return this._ins
	}
	onClick(e) {
		switch (e.target) {
		case this._ui.btnFire:
			this.fireMem();
			this.closeUI();
			break;
		case this._ui.btnMaster:
			QM.show(WM.getLanCodeTip(20171, [this._memberData.it.profile.name]), Laya.Utils.bind(this.sureOperate, this));
			this.closeUI();
			break;
		case this._ui.btnMaster1:
			if (this._memberData.performance.position == 1) {
				FM.guildMan.fireMaster1(this._memberData.it._idHex)
			} else {
				FM.guildMan.appointMaster1(this._memberData.it._idHex)
			}
			this.closeUI();
			break;
		case this._ui.btnClose:
			this.closeUI();
			break
		}
	}
	fireMem() {
		if (od.getGlobalValue(9236) < 0 || b_.getTimeStamp() - this._memberData.performance.lastDonateTime > b_.ONEDAYMILLISECONDS) {
			FM.guildMan.fireMember(this._memberData.it._idHex)
		} else {
			dV.getIns().show(this._memberData)
		}
	}
	initUI() {
		this._ui = this.uiView;
		this.setLayer(1, 1, 1, 1)
	}
	operate(e) {
		this._memberData = e;
		this.openUI()
	}
	afterOpen() {
		this._ui.tipLab.text = WM.getLanCodeTip(20172, [this._memberData.it.profile.name]);
		if (E_.myPosition == 2) {
			this._ui.btnMaster.visible = true;
			this._ui.btnMaster1.visible = true;
			if (this._memberData.performance.position == 1) {
				this._ui.btnMaster1.label = WM.getLanCodeTip(10344)
			} else {
				this._ui.btnMaster1.label = WM.getLanCodeTip(10345)
			}
			this._ui.btnFire.y = this._ui.btnBox.height - this._ui.btnFire.height * .5
		} else {
			this._ui.btnMaster.visible = false;
			this._ui.btnMaster1.visible = false;
			this._ui.btnFire.y = this._ui.btnBox.height * .5
		}
	}
	sureOperate(e) {
		if (e) {
			FM.guildMan.appointMaster(this._memberData.it._idHex)
		}
	}
}
