class TV extends g {
	constructor() {
		super("GuildWarDfRecord")
	}
	static getIns() {
		if (!this._ins) {
			this._ins = new TV
		}
		return this._ins
	}
	getMsgs() {
		return [tp.GUILD_WARPTID_REC]
	}
	exeMsg(e, t) {
		switch (t) {
		case tp.GUILD_WARPTID_REC:
			this.warPtidRec(e);
			break
		}
	}
	getCmds() {
		return [d.VIDEO_PLAYSTART, d.VIDEO_PLAYOVER]
	}
	exeCmd(e, t) {
		switch (t) {
		case d.VIDEO_PLAYSTART:
			this.videoStart(e);
			break;
		case d.VIDEO_PLAYOVER:
			this.videoOver(e);
			break
		}
	}
	videoStart(e) {
		if (!this.isOpen)
			return;
		this.fightDetail = this._detail;
		this.closeUI();
		if (bV.getIns().isOpen) {
			bV.getIns().closeUI()
		}
		if (kT.getIns().isOpen) {
			kT.getIns().closeUI()
		}
	}
	videoOver(e) {
		if (this.isOpen)
			return;
		if (e.funcId == pd.GUILD_WAR) {
			this.showDetail(this.fightDetail);
			this.fightDetail = null
		}
	}
	onClick(e) {
		switch (e.target) {
		case this._ui.btnClose:
			this.closeUI();
			break
		}
	}
	initUI() {
		this._ui = this.uiView;
		this.setLayer(1, 1, 1, 1)
	}
	afterClose() {
		this._data = null;
		this._detail = null
	}
	show(e) {
		this._data = e;
		this.openUI();
		this.sendMsg(tp.GUILD_WARPTID_REQ, {
			team: PT.getIns().spaceTeam,
			ptId: e.ptId
		})
	}
	showDetail(e) {
		this._detail = e;
		this.openUI();
		this.updateInfo()
	}
	warPtidRec(e) {
		if (!this.isOpen)
			return;
		if (e.pt.ptId != this._data.ptId)
			return;
		this._detail = e.pt;
		this.updateInfo()
	}
	updateInfo() {
		if (!this.isOpen)
			return;
		this._ui.labCP.text = this._detail.ps.ms.power;
		let e = od.getTplInfo(nd.FORMATION, this._detail.ps.positionTid);
		if (!e)
			e = od.getTplInfo(nd.FORMATION, 1);
		this._ui.labPostion.text = e.name;
		this._ui.imgPostion.skin = "img/zhandou/ZhenX_" + e.id + ".png";
		let t = this._detail.ps.hs;
		let i = [];
		for (let a = 0; a < t.length; a++) {
			let e = new yg(t[a]);
			i.push(e)
		}
		this._ui.heroList.array = i;
		let s = this._detail.records;
		if (!s)
			s = [];
		s.sort(this.sortRecordListFun);
		this._ui.recordList.array = s
	}
	sortRecordListFun(e, t) {
		return t.recordTime - e.recordTime
	}
}
