class yV extends Laya.Box {
	constructor() {
		super(...arguments);
		this.poss = [[215, 390], [430, 640], [130, 805], [434, 933], [127, 1085], [428, 1212], [218, 1488], [457, 1753], [215, 2007], [430, 2257], [130, 2422], [434, 2550], [127, 2700], [428, 2830], [218, 3106], [457, 3370], [215, 3652], [430, 3902], [130, 4067], [434, 4305], [127, 4455], [428, 4585], [218, 4800], [430, 5100], [218, 5400], [430, 5700], [218, 6e3], [430, 6300], [218, 6700], [218, 7e3]];
		this.fighters = []
	}
	setShowList(e) {
		if (e.length > this.poss.length) {
			e.length = this.poss.length
		}
		for (let t = 0; t < e.length; t++) {
			if (!this.fighters[t]) {
				this.fighters[t] = new CV;
				this.fighters[t].x = this.poss[t][0];
				this.fighters[t].y = this.poss[t][1]
			}
			this.fighters[t].setData(e[t]);
			this.addChild(this.fighters[t])
		}
		for (let t = e.length; t < this.fighters.length; t++) {
			this.fighters[t].removeSelf()
		}
		if (e.length) {
			this.height = this.fighters[e.length - 1].y + 360
		} else {
			this.height = 100
		}
	}
}
