class nK extends j_ {
	get dataSource() {
		return super.dataSource
	}
	set dataSource(e) {
		super.dataSource = e;
		if (!e)
			return;
		let t = this.getChildByName("btnGo");
		let i = this.getChildByName("labName");
		let s = this.getChildByName("labLevel");
		i.text = this.getNameTxt(e);
		s.text = this.getLevelTxt(e);
		t.mouseEnabled = Boolean(e.go);
		t.on(Laya.Event.CLICK, this, this.onClick)
	}
	getNameTxt(e) {
		switch (e.funcId) {
		case pd.GUILD_SKILL:
			return WM.getLanCodeTip(20201, [T_.toName(e.job)]);
			break;
		case pd.GUILD_PVPSKILL:
			return "Tiên minh PVP Kỹ năng -" + e.name;
			break;
		case pd.TOTEM:
			return WM.getLanCodeTip(20202, [g_.getName(e.camp)]);
			break;
		case pd.MAZE:
			return WM.getLanCodeTip(20204, [T_.toName(e.job)]);
			break;
		case pd.JIBAN:
			return "Anh hùng ràng buộc -" + e.name
		}
		return ""
	}
	getLevelTxt(e) {
		switch (e.funcId) {
		case pd.GUILD_SKILL:
			return "Lv." + e.level + "(" + e.lightTime + ")";
			break;
		case pd.GUILD_PVPSKILL:
			if (e.lock) {
				return WM.getLanCodeTip(10385)
			} else {
				return "Lv." + e.level
			}
			break;
		case pd.TOTEM:
			if (e.lock) {
				return WM.getLanCodeTip(10385)
			} else {
				return WM.getLanCodeTip(20203, [e.level, e.grade])
			}
			break;
		case pd.MAZE:
			if (e.lock) {
				return WM.getLanCodeTip(10385)
			} else {
				return WM.getLanCodeTip(20203, [e.starType, e.starLevel])
			}
			break;
		case pd.JIBAN:
			if (e.lock) {
				return "Chưa kích hoạt"
			} else {
				return e.star + " sao"
			}
		}
		return ""
	}
	onClick() {
		if (!this.dataSource)
			return;
		switch (this.dataSource.funcId) {
		case pd.GUILD_SKILL:
			yT.getIns().openUI();
			break;
		case pd.GUILD_PVPSKILL:
			yT.getIns().openUI();
			break;
		case pd.TOTEM:
			FM.heroMan.openTotem();
			break;
		case pd.MAZE:
			if (FM.funcMan.checkFuncOpen(pd.MAZE, true)) {
				FM.palaceMan.openUI();
				FM.palaceStarMan.openUI();
				if (Wg.getIns().isOpen) {
					Wg.getIns().closeUI()
				}
			}
			break;
		case pd.JIBAN:
			FM.heroMan.openJB();
			break
		}
	}
}
