class _K extends g {
	constructor() {
		super("TalentLearn")
	}
	static getIns() {
		if (!this._ins) {
			this._ins = new _K
		}
		return this._ins
	}
	onClick(e) {
		switch (e.target) {
		case this._ui.btnClose:
			this.closeUI();
			break;
		case this._ui.btnLearn:
			this.learnClick();
			break
		}
	}
	initUI() {
		this._ui = this.uiView;
		this.setLayer(1, 1, 1, 1);
		this._ui.listSkill.selectHandler = Laya.Handler.create(this, this.onSelect, null, false);
		this._ui.labDesc.style.width = this._ui.labDesc.width;
		this._ui.labDesc.style.bold = true;
		this._ui.labDesc.style.wordWrap = true;
		this._ui.labDesc.style.leading = 5
	}
	show(e, t) {
		this.openUI();
		this._pos = e;
		this._heroIdHex = t.idHex;
		let i = od.getTplInfo(nd.HERO_TALENT, null, {
				level: 1
			});
		let s = [];
		for (let a = 0; a < i.length; a++) {
			let e = {};
			e.tpl = i[a];
			e.learnt = this.checkLearnt(e.tpl.id, t);
			e.canLearn = cP.checkEnough(e.tpl.learnCost) ? 1 : 0;
			e.recommand = this.checkRecommand(e.tpl, t.baseTpl.job);
			s.push(e)
		}
		s.sort(this.sortFun);
		this._ui.listSkill.array = s;
		this._ui.listSkill.selectedIndex = -1;
		this._ui.listSkill.selectedIndex = 0;
		this._ui.listSkill.scrollTo(0)
	}
	sortFun(e, t) {
		if (e.learnt != t.learnt) {
			return t.learnt - e.learnt
		} else {
			if (e.canLearn != t.canLearn) {
				return t.canLearn - e.canLearn
			} else {
				if (e.recommand != t.recommand) {
					return t.recommand - e.recommand
				} else {
					return e.tpl.id - t.tpl.id
				}
			}
		}
	}
	checkLearnt(e, t) {
		for (let i in t.talentDic) {
			let s = t.talentDic[i];
			if (s.tid == e) {
				return 1
			}
		}
		return 0
	}
	checkRecommand(e, t) {
		if (e.recJob.indexOf(t + "") != -1) {
			return 1
		}
		return 0
	}
	onSelect(e) {
		if (e < 0)
			return;
		let t = this._ui.listSkill.getItem(e);
		let i = {
			tid: t.tpl.id
		};
		Tb.addSkillGrid(i, this._ui.boxCtn);
		this._ui.labName.text = i.baseTpl.name;
		this._ui.labDesc.innerHTML = WM.str2Html(i.baseTpl.desc, 2468, 24, "398f00", false);
		this._ui.labDesc.height = this._ui.labDesc.contextHeight;
		this._ui.lanPanel.refresh();
		this._ui.lanPanel.scrollTo(0, 0);
		this._ui.listCost.array = t.tpl.learnCost.split("#")
	}
	learnClick() {
		this.sendMsg(Qp.LEARN_REQ, {
			heroIdHex: this._heroIdHex,
			talentTid: this._ui.listSkill.selectedItem.tpl.id,
			pos: this._pos
		});
		this.closeUI()
	}
}
