		for (let I = 0; I < u.length; I++) {
			const e = u[I];
			if (!e.isLock && e.heroData == null) {
				f = true;
				break
			}
		}
		l.on(Laya.Event.CLICK, this, this.onClick);
		l.gray = false;
		if (!f) {
			l.gray = true
		}
		let _ = 0;
