class OK extends j_ {
	get dataSource() {
		return super.dataSource
	}
	set dataSource(e) {
		super.dataSource = e;
		if (!e)
			return;
		let t = this.getChildByName("boxCtn");
		let i = this.getChildByName("lock");
		let s = e.heroData;
		let a = e.index;
		let r = e.isLock;
		let l = e.cfg;
		i.visible = false;
		Tb.removeGrid(t);
		if (s) {
			Tb.addItemGrid(s, t)
		}
		if (r) {
			i.visible = true
		}
		t.on(Laya.Event.CLICK, this, this.onClick2)
	}
	onClick2(e) {
		if (this.dataSource) {
			let e = this.dataSource.isLock;
			OK.index = 1;
			OK.cfg = this.dataSource.cfg;
			let t = this.getChildByName("boxCtn");
			if (!e) {
				let e = this.dataSource.heroData;
				if (e) {
					let i = new Laya.Point(t.width * .5, t.height * .5);
					i = this.localToGlobal(i, true);
					let s = this.getBounds();
					s.x = i.x;
					s.y = i.y;
					Pm.getIns().showJobFairy(s, e, 1, this.dataSource.cfg)
				} else {
					let e = OK.getCanSelectHero();
					e.sort(OK.heroSort);
					for (let t = 0; t < e.length; t++) {
						let i = {
							heroData: e[t]
						};
						i.selected = false;
						e[t] = i
					}
					Mm.getIns().show(e, Laya.Handler.create(this, OK.setSelectHero))
				}
			} else {
				let e = this.dataSource.index;
				let t = this.dataSource.cfg;
				let i = od.getTplInfo(nd.JOB_FAIRY, null, {
						protoId: t.baseTpl.protoId
					});
				i.sort(function (e, t) {
					return e.level - t.level
				});
				let s;
				for (let a = 0; a < i.length; a++) {
					const t = i[a];
					if (t.equipNum >= e) {
						s = t;
						break
					}
				}
				if (s) {
					FM.noticeMan.showNotice("Nghề nghiệp Tiên Khí" + s.level + "Cấp mở ra")
				}
			}
		}
	}
	static getCanSelectHero() {
		let e = [];
		for (let t = 0; t < uP.getIns().bag.hero.list.length; t++) {
			let i = uP.getIns().bag.hero.list[t];
			if (i) {
				if (OK.cfg.baseTpl.job == i.baseTpl.job) {
					if (!FM.bagMan.jobFairyHasHero(i.idHex)) {
						if (V_.checkLockStatus(i, false, true, true, true, true, false))
							continue;
						e.push(i)
					}
				}
			}
		}
		return e
	}
	static setSelectHero(e) {
		let t = null;
		if (e.length > 0) {
			t = e[0]
		}
		qM.sendMsg(rp.JOB_FAIRY_ON_REQ, {
			heroIdHex: t,
			protoId: OK.cfg.baseTpl.protoId,
			pos: OK.index
		})
	}
	static heroSort(e, t) { {
			if (e.baseTpl.star != t.baseTpl.star) {
				return t.baseTpl.star - e.baseTpl.star
			} else {
				if (t.level != e.level) {
					return t.level - e.level
				} else {
					if (e.baseTpl.camp != t.baseTpl.camp) {
						return t.baseTpl.camp - e.baseTpl.camp
					} else {
						if (e.baseTpl.job != t.baseTpl.job) {
							return e.baseTpl.job - t.baseTpl.job
						}
						return e.baseTpl.id - t.baseTpl.id
					}
				}
			}
		}
	}
}
