class WK extends g {
	constructor() {
		super("jierihuo5206")
	}
	static getIns() {
		if (!this._ins) {
			this._ins = new WK
		}
		return this._ins
	}
	onClick(e) {
		switch (e.target) {
		case this._ui.btnClose:
		case this._ui.btnCancel:
			this.closeUI();
			break;
		case this._ui.btnGive:
			this.btnGiveClick();
			break
		}
	}
	initUI() {
		this._ui = this.uiView;
		this.setLayer(1, 1, 1, 1);
		this._ui.htmlDesc.style.width = this._ui.htmlDesc.width;
		this._ui.htmlDesc.style.leading = 5;
		this.subAndAdd = this._ui.subAndAdd
	}
	afterOpen() {
		this._ui.labTitle.text = this.title;
		Tb.addItemGrid(this.giveItem, this._ui.propIcon);
		this._ui.labName.text = this.giveItem.baseTpl.name;
		this._ui.labName.color = ud.toColor(this.giveItem.baseTpl.quality);
		this._ui.htmlDesc.innerHTML = WM.str2Html(this.giveItem.baseTpl.desc, 2451, 22, "825632");
		let e = {};
		e.maxNum = this.haveNum;
		if (this.limitNum > 0) {
			e.maxNum = Math.min(e.maxNum, this.limitNum)
		}
		if (this.defNum > 0) {
			this._nowNum = Math.min(this.defNum, e.maxNum)
		} else {
			this._nowNum = 1
		}
		e.nowNum = this._nowNum;
		e.callBack = this.updateInfo;
		e.caller = this;
		this.subAndAdd.dataSource = e
	}
	show(e, t, i, s, a, r) {
		this.title = e;
		this.giveItem = t;
		this.limitNum = i;
		this.haveNum = s;
		this.defNum = a;
		this.giveHandler = r;
		this.openUI()
	}
	updateInfo() {
		this._nowNum = this.subAndAdd.nowNum;
		this._ui.labNum.text = String(this._nowNum)
	}
	btnGiveClick() {
		if (this._nowNum > 0) {
			this.giveHandler.runWith(this._nowNum)
		} else {
			FM.noticeMan.showNotice("Đưa tặng số lượng không thể vì 0")
		}
		this.closeUI()
	}
}
