class JK extends j_ {
	get dataSource() {
		return super.dataSource
	}
	set dataSource(e) {
		super.dataSource = e;
		if (!e)
			return;
		let t = this.getChildByName("labDesc");
		let i = this.getChildByName("listRwd");
		let s = this.getChildByName("imgDot");
		let a = this.getChildByName("imgBg");
		t.text = e.desc;
		i.array = cP.splitStr2Arr(e.rwd);
		a.skin = "common/" + e.pic + ".png";
		this.gray = false;
		switch (e.id) {
		case 1:
			this.regDotType(dd.SKYBATTLE_ENTER);
			this.funcGray(pd.SKYBATTLE);
			break;
		case 2:
			this.regDotType(dd.DONG_TIAN_FU_DI);
			this.funcGray(pd.DONG_TIAN_FU_DI);
			break;
		case 3:
			this.regDotType(dd.ARENA3V3_ENTER);
			this.funcGray(pd.ARENA3V3);
			break;
		case 4:
			s.visible = false;
			this.funcGray(pd.LING_XIAO);
			break;
		case 5:
			this.regDotType(dd.ARENA_LEVEL_ENTER);
			this.funcGray(pd.ARENA_LEVEL);
			break;
		case 6:
			this.regDotType(dd.COUNTRYWAR_ENTER);
			this.funcGray(pd.COUNTRY_WAR);
			break;
		case 7:
			this.regDotType(dd.CROSS_BOSS_ENTER);
			this.funcGray(pd.CROSS_BOSS);
			break;
		case 8:
			this.regDotType(dd.CROSS_PVP_ENTER);
			this.funcGray(pd.CROSS_PVP_TEAM);
			break;
		case 9:
			this.regDotType(dd.PEAK_PVP_ENTER);
			this.funcGray(pd.PEAK_PVP);
			break;
		case 10:
			this.regDotType(dd.RACE_PVP_ENTER);
			this.funcGray(pd.RACE_PVP);
			break
		}
	}
	regDotType(e) {
		if (this.lastRegDotType != e) {
			let t = this.getChildByName("imgDot");
			if (this.lastRegDotType)
				cd.unRegDot(this.lastRegDotType);
			cd.regDot(e, t);
			this.lastRegDotType = e
		}
	}
	funcGray(e) {
		if (e == pd.CROSS_BOSS) {
			this.gray = !FD.isSvrDayOpen || !FM.funcMan.checkFuncOpen(e, false)
		} else if (e == pd.CROSS_PVP_TEAM) {
			this.gray = !bI.isSvrDayOpen || !FM.funcMan.checkFuncOpen(e, false)
		} else if (e == pd.PEAK_PVP) {
			this.gray = !SC.checkSvrDay(false) || !FM.funcMan.checkFuncOpen(e, false) || !SC.checkActID(false)
		} else if (e == pd.ARENA_LEVEL) {
			this.gray = !FM.arenaLevelMan.checkOpen(false)
		} else if (e === pd.RACE_PVP) {
			this.gray = !HR.checkActID(false) || !FM.funcMan.checkFuncOpen(e, false) || !HR.checkSvrDay(false)
		} else {
			this.gray = !FM.funcMan.checkFuncOpen(e, false)
		}
	}
}
