class sY extends j_ {
	get dataSource() {
		return super.dataSource
	}
	set dataSource(e) {
		super.dataSource = e;
		if (!e)
			return;
		let t = this.getChildByName("sideAMark");
		let i = t.getChildByName("sideAWinMark");
		let s = t.getChildByName("sideAFailMark");
		let a = this.getChildByName("sideBMark");
		let r = a.getChildByName("sideBWinMark");
		let l = a.getChildByName("sideBFailMark");
		let h = e.replayInfo;
		if (h.winner == 1) {
			i.visible = true;
			s.visible = false;
			r.visible = false;
			l.visible = true
		} else {
			i.visible = false;
			s.visible = true;
			r.visible = true;
			l.visible = false
		}
		let n = this.getChildByName("sideARoleName");
		let o = this.getChildByName("sideBRoleName");
		n.text = e.nameA;
		o.text = e.nameB;
		let u = this.getChildByName("replayProfileRoundTxt");
		u.text = WM.getLanCodeTip(20097, [h.round, h.roundMax]);
		let c = this.getChildByName("replayProfileCreateTime");
		c.text = b_.getTimeStmapStr(h.createDate, "[YY]-[MM]-[DD] [hh]:[mm]");
		let d = this.getChildByName("sideAPwBox");
		let p = d.getChildByName("sideARolePower");
		p.text = String(h.A.ms.power);
		let f = this.getChildByName("sideBPwBox");
		let _ = f.getChildByName("sideBRolePower");
		_.text = String(h.B.ms.power);
		let g = this.getChildByName("sideARoleList");
		let m = g.getChildByName("heroList");
		let I = [];
		let T = 0;
		for (T = 0; T < 9; T++) {
			let e = {};
			I.push(e)
		}
		let b = h.A.grids;
		let C = h.A.hs;
		let y = {};
		if (h.A.bg) {
			let e = h.A.bg.heros;
			for (let t = 0; t < e.length; t++) {
				y[e[t].heroIdHex] = e[t]
			}
		}
		if (b) {
			for (T = 0; T < b.length; T++) {
				let e = b[T].pos;
				let t = this.getHsIndex(C, b[T]._idHex);
				let i = new yg(C[t]);
				I[this.getArrIndex(e, true)] = {
					heroData: i,
					heroBg: y[i.idHex]
				}
			}
		}
		m.array = I;
		let E = this.getChildByName("sideBRoleList");
		let S = E.getChildByName("heroList");
		let L = [];
		for (T = 0; T < 9; T++) {
			let e = {};
			L.push(e)
		}
		let A = h.B.grids;
		let D = h.B.hs;
		let R = {};
		if (h.B.bg) {
			let e = h.B.bg.heros;
			for (let t = 0; t < e.length; t++) {
				R[e[t].heroIdHex] = e[t]
			}
		}
		if (A) {
			for (T = 0; T < A.length; T++) {
				let e = A[T].pos;
				let t = this.getHsIndex(D, A[T]._idHex);
				let i = new yg(D[t]);
				L[this.getArrIndex(e, false)] = {
					heroData: i,
					heroBg: R[i.idHex]
				}
			}
		}
		S.array = L;
		let x = this.getChildByName("btnToReplay");
		x.on(Laya.Event.CLICK, this, this.btnToReplayFun);
		let k = this.getChildByName("btnDataShow");
		k.on(Laya.Event.CLICK, this, this.btnDataShowFun)
	}
	btnToReplayFun() {
		if (!this.dataSource)
			return;
		let e = this.dataSource.replayInfo.replayIdHex;
		if (this.dataSource.phase == TI.Knockout) {
			FM.videoMan.getVideo(e, pd.CROSS_PVP_KNOCK, 2)
		} else if (this.dataSource.phase == TI.Trials) {
			FM.videoMan.getVideo(e, pd.CROSS_PVP_TRIAL, 2)
		}
	}
	btnDataShowFun() {
		if (!this.dataSource)
			return;
		let e = this.dataSource.replayInfo.replayIdHex;
		if (this.dataSource.phase == TI.Knockout) {
			KI.getIns().getReport(e, pd.CROSS_PVP_KNOCK, 2)
		} else if (this.dataSource.phase == TI.Trials) {
			KI.getIns().getReport(e, pd.CROSS_PVP_TRIAL, 2)
		}
	}
	getHsIndex(e, t) {
		let i = 0;
		for (i = 0; i < e.length; i++) {
			if (e[i]._idHex == t) {
				return i
			}
		}
		return 0
	}
	getArrIndex(e, t) {
		let i = [7, 4, 1, 8, 5, 2, 9, 6, 3];
		let s = [1, 4, 7, 2, 5, 8, 3, 6, 9];
		if (t) {
			return i.indexOf(e)
		}
		return s.indexOf(e)
	}
}
