class nY extends j_ {
	get dataSource() {
		return super.dataSource
	}
	set dataSource(e) {
		super.dataSource = e;
		if (!e)
			return;
		let t = this.getChildByName("tileLabel");
		let i = this.getChildByName("campBox");
		let s = this.getChildByName("imgForm");
		let a = this.getChildByName("labName");
		let r = this.getChildByName("cpLab");
		let n = this.getChildByName("heroList");
		let o = this.getChildByName("boxArtifact");
		let u = "Đội viên";
		let c = "Tạm thời chưa có";
		if (e.player) {
			u = e.player.pos == 1 ? "Đội trưởng" : "Đội viên";
			c = jg.getZoneIndexName(e.player.srv.index) + e.player.name
		}
		t.changeText(u);
		s.visible = !!e.side;
		let d = null;
		if (s.visible) {
			d = od.getTplInfo(nd.FORMATION, e.side.positionTid);
			if (!d)
				d = od.getTplInfo(nd.FORMATION, 1);
			s.skin = h.getUrl(l.IMAGE_ICON, "form" + d.icon)
		}
		a.changeText(c);
		g_.handleMixCamp(i, e.camps);
		r.changeText(e.power);
		let p = [];
		if (e.player && d) {
			var f = d.pos;
			let t = e.side.grids;
			for (let s = 0; s < 5; s++) {
				let i = Number(f.charAt(s));
				let a = false;
				for (let s = 0; s < t.length; s++) {
					if (t[s].pos != i)
						continue;
					if (e.heroList[t[s]._idHex]) {
						p.push(e.heroList[t[s]._idHex]);
						a = true;
						break
					}
				}
				if (!a) {
					p.push({})
				}
			}
			let i = false;
			for (let s = 0; s < t.length; s++) {
				if (t[s].pos != f_.ZHIYUANPOS)
					continue;
				if (e.heroList[t[s]._idHex]) {
					p.push(e.heroList[t[s]._idHex]);
					i = true;
					break
				}
			}
			if (!i) {
				p.push({})
			}
		} else {
			for (let e = 0; e < 6; e++) {
				p.push({})
			}
		}
		n.array = p;
		if (e.side && e.side.artifact && e.side.artifact.tid) {
			Tb.addArtifactGrid({
				tid: e.side.artifact.tid
			}, o)
		} else {
			Tb.removeGrid(o)
		}
	}
}
