class dY extends j_ {
	get dataSource() {
		return super.dataSource
	}
	set dataSource(e) {
		super.dataSource = e;
		if (!e)
			return;
		let t = this.getChildByName("indexBox");
		let i = this.getChildByName("labTeamName");
		let s = this.getChildByName("labCP");
		let a = this.getChildByName("btnWatch");
		a.on(Laya.Event.CLICK, this, this.btnWatchClick);
		let r = this.getChildByName("heroList");
		let l = this.getChildByName("btnChall");
		l.on(Laya.Event.CLICK, this, this.btnChallClick);
		l.gray = e.myRank < 0 || e.index + 1 == e.myRank;
		let h = l.getChildByName("btnMoneyBox");
		h.dataSource = X_.getStrTypeData(od.getGlobalValue(64002, 1), false);
		h.mouseEnabled = false;
		t.dataSource = e.index + 1;
		i.changeText("Chiến đội:" + e.data.name);
		s.changeText(e.data.totalPower);
		r.array = e.memberList
	}
	btnWatchClick() {
		if (!this.dataSource)
			return;
		ox.getIns().show(this.dataSource.data.teamIdHex, this.dataSource.index + 1)
	}
	btnChallClick() {
		if (!this.dataSource)
			return;
		if (bI.phase != TI.Trials) {
			FM.noticeMan.showNotice(CI.TRIAL_OVER);
			return
		}
		if (this.dataSource.myRank < 0) {
			FM.noticeMan.showNotice(CI.TRIAL_NO_TEAM);
			return
		}
		if (this.dataSource.index + 1 == this.dataSource.myRank) {
			FM.noticeMan.showNotice(CI.TRIAL_SELF);
			return
		}
		if (this.dataSource.index + 1 > this.dataSource.myRank) {
			FM.noticeMan.showNotice(CI.TRIAL_LOW);
			return
		}
		let e = od.getGlobalValue(64002, 1);
		if (e && e != "") {
			let t = cP.parseItemCostStr(e);
			if (t.num == null)
				t.num = 0;
			if (uP.getIns().bag.prop.getNum(t.tid) < t.num) {
				FM.arena.buyFightProp();
				return
			}
		}
		zM.getIns().sendMsg(_f.TRIALS_CHALL_REQ, {
			teamIdHex: this.dataSource.data.teamIdHex
		})
	}
}
