class mY extends g {
	constructor() {
		super("LegionShopBuy")
	}
	static getIns() {
		if (!this._ins) {
			this._ins = new mY
		}
		return this._ins
	}
	onClick(e) {
		switch (e.target) {
		case this._ui.btnBuy:
			this.sureBuy();
			this.closeUI();
			break;
		case this._ui.btnCancel:
			this.closeUI();
			break;
		case this._ui.btnClose:
			this.closeUI();
			break
		}
	}
	initUI() {
		this._ui = this.uiView;
		this.setLayer(1, 1, 1, 1);
		this.subAndAdd = this._ui.subAndAdd
	}
	showBuyDetail(e, t = 1) {
		this._info = e;
		this._nowNum = t;
		this.openUI()
	}
	getMaxNumByObj(e) {
		let t = od.getTplInfo(nd.LEGION_GET, e.tid);
		let i = cP.splitStr2Arr(t.cost);
		let s = 1e6;
		for (let a = 0; a < i.length; a++) {
			let e = this.data.bag.prop.getNum(i[a].tid);
			e = Math.floor(e / i[a].num);
			if (s > e)
				s = e
		}
		if (t.limitNum && t.limitNum > 0) {
			return Math.min(s, t.limitNum - e.purchaseNum)
		}
		return s
	}
	afterOpen() {
		let e = {};
		e.nowNum = this._nowNum;
		e.maxNum = this.getMaxNumByObj(this._info);
		e.callBack = this.updateInfo;
		e.caller = this;
		this.subAndAdd.dataSource = e;
		let t = od.getTplInfo(nd.LEGION_GET, this._info.tid);
		let i = Tb.addItemGrid(cP.splitStr2Arr(t.rwd)[0], this._ui.propIcon);
		this._ui.propName.text = i.info.baseTpl.name;
		this._ui.propName.color = ud.toColor(i.info.baseTpl.quality);
		if (t.limitNum && t.limitNum > 0) {
			this._ui.propLimitInfo.visible = true;
			this._ui.propLimitInfo.text = WM.getLanCodeTip(20221, [t.limitNum - this._info.purchaseNum])
		} else {
			this._ui.propLimitInfo.visible = false
		}
	}
	updateInfo() {
		let e = od.getTplInfo(nd.LEGION_GET, this._info.tid);
		let t = cP.splitStr2Arr(e.cost);
		this._nowNum = this.subAndAdd.nowNum;
		this._ui.buyNumNum.text = String(this._nowNum);
		let i = [];
		for (let s = 0; s < t.length; s++) {
			t[s].num = t[s].num * this._nowNum;
			i[s] = X_.getTypeData(t[s])
		}
		this._ui.moneyList.array = i
	}
	sureBuy() {
		if (this._nowNum == 0)
			return;
		kN.getIns().exchange(this._info.tid, this._nowNum)
	}
}
