class yY extends j_ {
	get dataSource() {
		return super.dataSource
	}
	set dataSource(e) {
		super.dataSource = e;
		if (!e)
			return;
		let t = this.getChildByName("prizeList");
		let i = this.getChildByName("hardLevelImg");
		let s = this.getChildByName("levelName");
		let a = this.getChildByName("recommendTag");
		let r = this.getChildByName("btnFight");
		let n = this.getChildByName("btnNoOpen");
		let o = this.getChildByName("btnMopUp");
		let u = o.getChildByName("moneyLab");
		let c = o.getChildByName("moneyGrid");
		s.text = e.name;
		if (!e.hardType)
			e.hardType = 1;
		s.color = ud.getRewardTaskColor(e.hardType);
		s.strokeColor = ud.getRewardTaskStrokeColor(e.hardType);
		i.skin = h.getUrl(l.IMAGE, "daily/tab_" + (e.hardType - 1) + ".png");
		let d = GN.fbData;
		let p = GN.timesTpl;
		this.status = 0;
		if (this.dataSource.openLevel <= uP.getIns().master.level) {
			if (d.combatNumPass >= e.level) {
				this.status = 1
			} else {
				this.status = 2
			}
			if (d.playTimes.freeTimes[1] && d.playTimes.freeTimes[1] >= p.free) {
				this.status += 2
			}
		}
		r.visible = false;
		n.visible = false;
		o.visible = false;
		let f;
		switch (this.status) {
		case 0:
			n.visible = true;
			n.label = e.openLevel + "Cấp mở ra";
			f = cP.splitStr2Arr(e.rwd);
			n.gray = true;
			n.on(Laya.Event.CLICK, this, this.onNoOpenClick);
			break;
		case 1:
			o.visible = true;
			f = cP.splitStr2Arr(e.rwd);
			o.on(Laya.Event.CLICK, this, this.onMopUpClick);
			u.text = WM.getLanCodeTip(10272);
			u.x = 31;
			c.visible = false;
			break;
		case 2:
			r.visible = true;
			f = cP.splitStr2Arr(e.rwd);
			r.on(Laya.Event.CLICK, this, this.onFightClick);
			break;
		case 3:
			o.visible = true;
			f = cP.splitStr2Arr(e.rwd);
			o.on(Laya.Event.CLICK, this, this.onMopUpClick);
			let t = GN.getBuyMoney();
			u.text = WM.getLanCodeTip(20120, [t.num]);
			u.x = 53;
			c.visible = true;
			t.num = 0;
			Tb.addWealthGridByInfo(t, c);
			break;
		case 4:
			r.visible = true;
			f = cP.splitStr2Arr(e.rwd);
			r.on(Laya.Event.CLICK, this, this.onFightClick);
			break
		}
		t.array = f;
		let _ = d.combatNumOpen;
		if (_ > d.combatNumPass + 1) {
			_ = d.combatNumPass + 1
		}
		if (e.level == _ && !n.visible) {
			a.visible = true
		} else {
			a.visible = false
		}
	}
	onNoOpenClick() {
		if (this.dataSource.openLevel > uP.getIns().master.level) {
			FM.noticeMan.showNotice(this.dataSource.openLevel + "Cấp mở ra")
		}
	}
	onMopUpClick() {
		FM.lineHeroMan.fightFB(true, this.dataSource.level)
	}
	onFightClick() {
		if (this.dataSource.openLevel > uP.getIns().master.level) {
			FM.noticeMan.showNotice(this.dataSource.openLevel + "Cấp mở ra");
			return
		}
		let e = GN.fbData;
		if (this.dataSource.level > e.combatNumPass + 1) {
			FM.noticeMan.showNotice(WM.getLanCodeTip(10273))
		} else {
			FM.lineHeroMan.fightFBToBattle(this.dataSource.level)
		}
	}
}
