class DY extends j_ {
	get dataSource() {
		return super.dataSource
	}
	set dataSource(e) {
		super.dataSource = e;
		if (!e)
			return;
		let t = this.getChildByName("grid");
		let i = this.getChildByName("got");
		let s = this.getChildByName("maskImg");
		let a;
		if (e.type) {
			a = FM.limitEliteCall1Man.getCurCallTime()
		} else {
			a = FM.limitEliteCallMan.getCurCallTime()
		}
		Tb.addItemGrid(cP.splitStr2Arr(e.tpl.rwd)[0], t);
		this.off(Laya.Event.CLICK, this, this.onBtnGet);
		DY.stop(s);
		if (a >= e.tpl.times) {
			let a = false;
			if (e.type) {
				a = FM.limitEliteCall1Man.isGotPrize(e.tpl.id)
			} else {
				a = FM.limitEliteCallMan.isGotPrize(e.tpl.id)
			}
			if (a) {
				s.visible = false;
				i.visible = true;
				t.gray = true;
				t.mouseEnabled = true
			} else {
				s.visible = true;
				DY.start(s);
				i.visible = false;
				t.gray = false;
				t.mouseEnabled = false;
				this.on(Laya.Event.CLICK, this, this.onBtnGet)
			}
		} else {
			s.visible = false;
			i.visible = false;
			t.gray = false;
			t.mouseEnabled = true
		}
	}
	onBtnGet(e) {
		if (this.dataSource.type) {
			FM.limitEliteCall1Man.getCallTimePrize(this.dataSource.tpl.id)
		} else {
			FM.limitEliteCallMan.getCallTimePrize(this.dataSource.tpl.id)
		}
		e.stopPropagation()
	}
	static start(e, t = true) {
		if (!this.targetArr) {
			this.targetArr = [];
			this.alpha = 1;
			this.dir = -1;
			Laya.timer.loop(30, this, this.fadeInOut)
		}
		if (this.targetArr.indexOf(e) != -1)
			return;
		this.targetArr.push(e);
		if (t) {
			e.on(Laya.Event.UNDISPLAY, this, this.targetUndisplay, [e])
		}
	}
	static targetUndisplay(e) {
		this.stop(e)
	}
	static stop(e) {
		if (!this.targetArr)
			return;
		let t = this.targetArr.indexOf(e);
		if (t == -1)
			return;
		e.alpha = 1;
		e.off(Laya.Event.UNDISPLAY, this, this.targetUndisplay);
		this.targetArr.splice(t, 1);
		if (this.targetArr.length <= 0) {
			this.targetArr = null;
			Laya.timer.clear(this, this.fadeInOut)
		}
	}
	static fadeInOut() {
		if (this.alpha >= 1.1) {
			this.alpha = 1.1;
			this.dir = -1
		}
		if (this.alpha <= .5) {
			this.alpha = .5;
			this.dir = 1
		}
		for (let e = 0; e < this.targetArr.length; e++) {
			if (!this.targetArr[e].displayedInStage)
				continue;
			this.targetArr[e].alpha = this.alpha
		}
		this.alpha += .025 * this.dir
	}
}
