class NY extends Laya.Box {
	constructor() {
		super(...arguments);
		this._spaceY = 0;
		this._elasticEnabled = false;
		this.cellDic = {};
		this.cellPool = []
	}
	createChildren() {
		this._content = new Laya.Box;
		this.addChild(this._content);
		this.setContentSize(this.width, this.height)
	}
	_sizeChanged() {
		super._sizeChanged();
		this.setContentSize(this.width, this.height);
		if (this._scrollBar)
			this.callLater(this.onScrollBarChange)
	}
	setContentSize(e, t) {
		this._content.width = e;
		this._content.height = t;
		if (this._scrollBar) {
			let i = Laya.Rectangle.create();
			i.setTo(0, 0, e, t);
			this._content.scrollRect = i
		}
	}
	get itemRender() {
		return this._itemRender
	}
	set itemRender(e) {
		if (this._itemRender != e) {
			this._itemRender = e
		}
	}
	set spaceY(e) {
		if (this._spaceY == e)
			return;
		this._spaceY = e
	}
	get spaceY() {
		return this._spaceY
	}
	get elasticEnabled() {
		return this._elasticEnabled
	}
	set elasticEnabled(e) {
		this._elasticEnabled = e;
		if (this._scrollBar) {
			this._scrollBar.elasticDistance = e ? 200 : 0
		}
	}
	set array(e) {
		this._array = e || [];
		for (let t in this.cellDic) {
			let e = this.cellDic[t];
			e.removeSelf();
			e.dataSource = null;
			this.cellPool.push(e);
			delete this.cellDic[t]
		}
		this.refreshExpand()
	}
	get array() {
		return this._array
	}
	refreshExpand() {
		if (!this._array)
			return;
		if (this._scrollBar) {
			this._scrollBar.stopScroll();
			let e = 0;
			for (let i = 0; i < this._array.length; i++) {
				let t = this._array[i];
				e += t.size + this.spaceY
			}
			if (this.array.length) {
				e -= this.spaceY
			}
			let t = this._scrollBar.isVertical ? this._content.height : this._content.width;
			if (e > t) {
				this._scrollBar.setScroll(0, e - t, this._scrollBar.value);
				this._scrollBar.target = this._content
			} else {
				this._scrollBar.setScroll(0, 0, 0);
				this._scrollBar.target = this._content
			}
		}
		this.changeCells()
	}
	get vScrollBarSkin() {
		return this._scrollBar ? this._scrollBar.skin : null
	}
	set vScrollBarSkin(e) {
		this._removePreScrollBar();
		var t = new Laya.VScrollBar;
		t.right = 0;
		t.skin = e;
		t.elasticDistance = this._elasticEnabled ? 200 : 0;
		this.scrollBar = t;
		this.addChild(t)
	}
	_removePreScrollBar() {
		if (this.scrollBar) {
			this.scrollBar.destroy(true)
		}
	}
	get hScrollBarSkin() {
		return this._scrollBar ? this._scrollBar.skin : null
	}
	set hScrollBarSkin(e) {
		this._removePreScrollBar();
		var t = new Laya.HScrollBar;
		t.bottom = 0;
		t.skin = e;
		t.elasticDistance = this._elasticEnabled ? 200 : 0;
		this.scrollBar = t;
		this.addChild(t)
	}
	get scrollBar() {
		return this._scrollBar
	}
	set scrollBar(e) {
		if (this._scrollBar != e) {
			this._scrollBar = e;
			if (e) {
				this.addChild(this._scrollBar);
				this._scrollBar.on(Laya.Event.CHANGE, this, this.onScrollBarChange)
			}
		}
	}
	onScrollBarChange(e = null) {
		var t = this._content.scrollRect;
		if (!t) {
			this.setContentSize(this.width, this.height)
		}
		if (t) {
			var i = Math.round(this.scrollBar.value);
			this.scrollBar.isVertical ? t.y = i : t.x = i;
			this._content.scrollRect = t
		}
		this.changeCells()
	}
	changeCells() {
		if (!this.array)
			return;
		let e = [];
		let t = 0;
		for (let i = 0; i < this.array.length; i++) {
			let s = this.array[i];
			if (this.scrollBar.isVertical) {
				if (t + s.size > this._content.scrollRect.y && t < this._content.scrollRect.y + this._content.scrollRect.height) {
					let s = this.addCell(i);
					s.y = t;
					e[i] = s
				} else {
					this.removeCell(i)
				}
			} else {}
			t += s.size + this.spaceY
		}
		for (let i in this.cellDic) {
			if (!e[i]) {
				this.removeCell(parseInt(i))
			}
		}
	}
	getCell(e) {
		return this.cellDic[e]
	}
	addCell(e) {
		let t = this.cellDic[e];
		if (!t) {
			if (this.cellPool.length) {
				t = this.cellPool.pop()
			} else {
				t = Laya.SceneUtils.createComp(this._itemRender, null, null);
				t.on(Laya.Event.CLICK, this, this.onCellMouse)
			}
			this.cellDic[e] = t;
			t.dataSource = this.array[e]
		}
		this._content.addChild(t);
		return t
	}
	removeCell(e) {
		let t = this.cellDic[e];
		if (t) {
			t.removeSelf();
			delete this.cellDic[e];
			this.cellPool.push(t)
		}
	}
	onCellMouse(e) {
		let t = e.currentTarget;
		for (let i in this.cellDic) {
			if (t == this.cellDic[i]) {
				this.mouseHandler && this.mouseHandler.runWith([e, i])
			}
		}
	}
}
