class dW extends g {
	constructor() {
		super("MonthReward");
		this.showType = 1
	}
	static getIns() {
		if (!this._ins) {
			this._ins = new dW
		}
		return this._ins
	}
	onClick(e) {
		switch (e.target) {
		case this._ui.btnClose:
			this.closeUI();
			break
		}
	}
	initUI() {
		this._ui = this.uiView;
		this.setLayer(1, 1, 1, 1)
	}
	openByType(e) {
		this.showType = e;
		this.openUI()
	}
	afterOpen() {
		let e = od.getTplInfo(nd.MONTH_FUND_PRIZE, null, {
				type: this.showType
			});
		this._ui.prizeList.array = e;
		this._ui.prizeList.scrollTo(0)
	}
	isGotPrizeDay(e) {
		return Ev.isDayPrize(this.showType, e)
	}
}
