class XW extends j_ {
	constructor() {
		super(...arguments);
		this.maxGrids = 6
	}
	get dataSource() {
		return super.dataSource
	}
	set dataSource(e) {
		super.dataSource = e;
		if (!e)
			return;
		let t = this.getChildByName("tileLabel");
		let i = this.getChildByName("hideTipLab");
		let s = this.getChildByName("btnArtifact");
		s.on(Laya.Event.CLICK, this, this.selectArtifactClick);
		t.text = WM.getLanCodeTip(20071, [e.team]);
		if (!this.posGridList) {
			this.posGridList = [];
			for (let e = 0; e < 6; e++) {
				let t = new LI(this.getChildByName("imgPos" + e), e);
				t.takeOffHero = Laya.Utils.bind(this.takeOffHero, this);
				t.fillHero2Grid = Laya.Utils.bind(this.fillHero2Grid, this);
				t.checkFunIdHero = Laya.Utils.bind(this.checkFunIdHero, this);
				this.posGridList.push(t)
			}
		}
		let a = od.getTplInfo(nd.FORMATION, e.posData.tid);
		if (!a)
			a = od.getTplInfo(nd.FORMATION, 1);
		var r = a.pos;
		for (let h = 0; h < 5; h++) {
			this.posGridList[h].pos = Number(r.charAt(h));
			this.posGridList[h].funcId = e.posData.applyTo
		}
		this.posGridList[5].pos = f_.ZHIYUANPOS;
		this.posGridList[5].funcId = e.posData.applyTo;
		let l = od.getTplInfo(nd.BATTLE_BG, e.posData.applyTo);
		if (l && l.isZhiYuan && uP.getIns().master.level >= od.getGlobalValue(9300)) {
			this.maxGrids = 6;
			this.posGridList[5].dragable = true;
			this.getChildByName("imgPos5").visible = this.getChildByName("imgPosYuan").visible = true
		} else {
			this.maxGrids = 5;
			this.posGridList[5].dragable = false;
			this.getChildByName("imgPos5").visible = this.getChildByName("imgPosYuan").visible = false
		}
		i.visible = e.hide;
		if (e.hide) {
			i.text = WM.getLanCodeTip(20266, [e.team])
		}
		this.refreshGrids()
	}
	selectArtifactClick() {
		let e = -1;
		if (this.dataSource.posData.artifactTid) {
			e = this.dataSource.posData.artifactTid
		}
		DI.getIns().openData(this.dataSource.posData, this.dataSource.posData.applyTo, Laya.Utils.bind(this.artifactSelect, this), Laya.Utils.bind(this.beastSelect, this), Laya.Utils.bind(this.ShenLongSelect, this), 0)
	}
	ShenLongSelect(e) {
		this.dataSource.posData.loongMap = e
	}
	artifactSelect(e) {
		this.dataSource.posData.artifactTid = e;
		this.refreshGrids()
	}
	beastSelect(e) {
		this.dataSource.posData.beastMap = e;
		this.refreshGrids()
	}
	freshArtifact() {
		if (this.dataSource.posData.artifactTid && this.dataSource.posData.artifactTid > 0) {
			Tb.addArtifactGrid({
				tid: this.dataSource.posData.artifactTid
			}, this.getChildByName("btnArtifact"))
		} else {
			Tb.removeGrid(this.getChildByName("btnArtifact"))
		}
	}
	refreshGrids() {
		let e = this.getChildByName("imgForm");
		let t = this.getChildByName("campBox");
		let i = this.getChildByName("cpLab");
		let s = this.dataSource.posData;
		let a = od.getTplInfo(nd.FORMATION, s.tid);
		if (!a)
			a = od.getTplInfo(nd.FORMATION, 1);
		e.skin = h.getUrl(l.IMAGE_ICON, "form" + a.icon);
		g_.handleMixCamp(t, FM.positionMan.getCamps(s));
		let r = 0;
		let n = s.grids;
		let o = 0;
		let u = 0;
		let c = [];
		let d = 0;
		let p;
		for (let l = 0; l < n.length; l++) {
			if (n[l].pos == f_.ZHIYUANPOS) {
				p = FM.positionMan.getHeroData(n[l]._idHex);
				break
			}
		}
		for (let l = 0; l < this.posGridList.length; l++) {
			let e = this.posGridList[l];
			let t = null;
			for (let i = 0; i < n.length; i++) {
				if (n[i].pos == e.pos) {
					t = FM.positionMan.getHeroData(n[i]._idHex);
					break
				}
			}
			this.posGridList[l].updateInfo(t);
			if (t) {
				r += V_.getCP(t, null, s.artifactTid, null, false, a.id, s.beastMap, s.loongMap, p);
				if (t.godEquipDic[1] && this.posGridList[l].pos != f_.ZHIYUANPOS) {
					let e = t.godEquipDic[1];
					if (u !== 0 && u === e.baseTpl.suitType && c.indexOf(e.baseTpl.suitPos) < 0) {
						o++;
						c.push(e.baseTpl.suitPos);
						let t = e.baseTpl.suitAttr;
						let i = n_.splitStr2Arr(t);
						for (let e = 0; e < i.length; e++) {
							d += n_.toCP(i[0].type, i[0].value)
						}
					} else if (u === 0) {
						u = e.baseTpl.suitType;
						c = [e.baseTpl.suitPos];
						o++;
						let t = e.baseTpl.suitAttr;
						let i = n_.splitStr2Arr(t);
						for (let e = 0; e < i.length; e++) {
							d += n_.toCP(i[0].type, i[0].value)
						}
					}
				}
			}
		}
		if (o >= 5) {
			r = r + d
		}
		i.text = r + "";
		this.freshArtifact()
	}
	takeOffHero(e) {
		if (FM.positionMan.takingHero)
			return;
		for (s = 0; s < this.posGridList.length; s++) {
			if (!this.posGridList[s].heroData || this.posGridList[s].heroData.idHex != e.idHex)
				continue;
			FM.positionMan.takingHero = true;
			let i = Tb.getItemGrid(e);
			let a = this.posGridList[s].getPos();
			var t = FM.positionMan.getHeroListPos(e);
			i.pos(a.x, a.y);
			Laya.Tween.to(i, {
				x: t.x,
				y: t.y
			}, 250, null, Laya.Handler.create(this, this.takeOffFlyEnd, [i]));
			Laya.stage.addChild(i);
			break
		}
		var i = this.dataSource.posData.grids;
		var s;
		for (s = 0; s < i.length; s++) {
			if (i[s]._idHex == e.idHex) {
				i.splice(s, 1)
			}
		}
		FM.positionMan.freshPanel()
	}
	takeOffFlyEnd(e) {
		e.removeSelf();
		FM.positionMan.takingHero = false
	}
	takeOnHero(e, t) {
		if (FM.positionMan.takingHero)
			return;
		let i = this.dataSource.posData.grids;
		if (i.length >= this.maxGrids) {
			return false
		}
		for (let c = 0; c < i.length; c++) {
			let t = FM.positionMan.getHeroData(i[c]._idHex);
			if (t && t.baseTpl.protoId == e.baseTpl.protoId) {
				return false
			}
		}
		FM.positionMan.takingHero = true;
		var s = {};
		let a = od.getTplInfo(nd.FORMATION, this.dataSource.posData.tid);
		if (!a)
			a = od.getTplInfo(nd.FORMATION, 1);
		var r = a.pos;
		var l;
		for (l = 0; l < i.length; l++) {
			s[i[l].pos] = true
		}
		var h = f_.getPriorityPos(e.baseTpl.priority, s, r);
		let n = 0;
		if (h == 0 && this.maxGrids == 6) {
			this.dataSource.posData.grids.push({
				_idHex: e.idHex,
				pos: f_.ZHIYUANPOS
			});
			n = 5
		} else {
			this.dataSource.posData.grids.push({
				_idHex: e.idHex,
				pos: h
			});
			n = r.indexOf(h.toString())
		}
		var o = Tb.getItemGrid(e);
		Laya.stage.addChild(o);
		o.pos(t.x, t.y);
		var u = this.posGridList[n].getPos();
		Laya.Tween.to(o, {
			x: u.x,
			y: u.y
		}, 250, null, Laya.Handler.create(this, this.takeOnFlyEnd, [o]));
		return true
	}
	takeOnFlyEnd(e) {
		e.removeSelf();
		FM.positionMan.freshPanel();
		FM.positionMan.takingHero = false
	}
	fillHero2Grid(e, t, i = false, s = 0, a = 0) {
		var r = FM.positionMan.getTmpPosData(true, a).grids;
		var l = false;
		for (var h = 0; h < r.length; h++) {
			if (r[h].pos == t) {
				if (!e) {
					r.splice(h, 1)
				} else {
					r[h]._idHex = e
				}
				l = true;
				break
			}
		}
		if (!l) {
			if (r.length < this.maxGrids) {
				r.push({
					_idHex: e,
					pos: t
				})
			}
		}
		if (i) {
			FM.positionMan.freshPanel()
		}
	}
	checkFunIdHero(e, t, i, s) {
		if (t && s && t.baseTpl.protoId == s.baseTpl.protoId)
			return false;
		var a = FM.positionMan.getTmpPosData(true, e).grids;
		var r = FM.positionMan.getTmpPosData(true, i).grids;
		if (s && a) {
			for (var l = 0; l < a.length; l++) {
				let e = FM.positionMan.getHeroData(a[l]._idHex);
				if (e && e.baseTpl.protoId == s.baseTpl.protoId) {
					FM.noticeMan.showNotice(WM.getLanCodeTip(10496));
					return true
				}
			}
		}
		if (t && r) {
			for (var l = 0; l < r.length; l++) {
				let e = FM.positionMan.getHeroData(r[l]._idHex);
				if (e && e.baseTpl.protoId == t.baseTpl.protoId) {
					FM.noticeMan.showNotice(WM.getLanCodeTip(10496));
					return true
				}
			}
		}
		return false
	}
}
