class AQ extends j_ {
	get dataSource() {
		return super.dataSource
	}
	set dataSource(e) {
		super.dataSource = e;
		vg.stop(this, this.cdFun);
		if (!e)
			return;
		let t = this.getChildByName("lineImg");
		let i = this.getChildByName("taskName");
		let s = this.getChildByName("prizeList");
		let a = this.getChildByName("btnGet");
		let r = this.getChildByName("timeProBox");
		let l = r.getChildByName("cdTimeLab");
		let h = r.getChildByName("pro");
		let n = this.getChildByName("moneyBox");
		let o = this.getChildByName("btnMoneyGet");
		let u = o.getChildByName("getMoneyBox");
		let c = o.getChildByName("tipLab");
		let d = e.cfg;
		let p = d.quality - 1;
		if (p < 0)
			p = 0;
		t.skin = "img/maoxian/sign_" + p + ".png";
		i.text = d.name;
		s.array = cP.splitStr2Arr(d.prize);
		a.visible = false;
		o.visible = false;
		r.visible = false;
		n.visible = false;
		if (e.startTime == undefined) {
			n.visible = true;
			n.dataSource = X_.getWealthTypeData(KM.M2, d.m2, false);
			a.visible = true;
			a.on(Laya.Event.CLICK, this, this.getPrize);
			a.label = WM.getLanCodeTip(10520)
		} else {
			let t = b_.getTimeStamp();
			let i = e.startTime + d.time * 1e3 - t;
			if (i > 0) {
				o.visible = true;
				Tb.addWealthGrid(KM.M1, u);
				c.text = this.getMoneyByTime(i) + WM.getLanCodeTip(10521);
				o.on(Laya.Event.CLICK, this, this.getPrize);
				r.visible = true;
				vg.start(i, this, this.cdFun)
			} else {
				a.visible = true;
				a.label = WM.getLanCodeTip(10155);
				a.on(Laya.Event.CLICK, this, this.getPrize);
				r.visible = true;
				l.text = b_.getCdTimeStrBySec(0);
				h.value = 1
			}
		}
	}
	cdFun(e, t, i) {
		let s = this.getChildByName("timeProBox");
		let a = s.getChildByName("cdTimeLab");
		let r = s.getChildByName("pro");
		let l = this.dataSource.cfg.time * 1e3;
		a.text = i;
		r.value = (l - e) / l;
		if (t) {
			this.dataSource = this.dataSource
		}
	}
	getMoneyByTime(e) {
		return 10 + Math.floor(e / (3600 * 1e3)) * 5
	}
	getPrize() {
		if (this.dataSource._idHex) {
			FM.rewardTaskMan.getTaskPrize(this.dataSource._idHex)
		} else {
			bN.getIns().openByTaskId(this.dataSource.taskId)
		}
	}
	sureGet(e) {
		if (e) {
			FM.rewardTaskMan.getTaskPrize(this.dataSource._idHex)
		}
	}
}
