class HQ extends j_ {
	get dataSource() {
		return super.dataSource
	}
	set dataSource(e) {
		super.dataSource = e;
		if (!e)
			return;
		let t = this.getChildByName("grid");
		let s = this.getChildByName("nameLab");
		let a = this.getChildByName("desLab");
		let r = this.getChildByName("btnGet");
		let l = this.getChildByName("btnGoTo");
		let h = this.getChildByName("got");
		let n = od.getTplInfo(nd.TASK_DATA, e.id);
		s.text = n.name;
		h.visible = r.visible = l.visible = false;
		let o = cP.splitStr2Arr(n.prize)[0];
		if (sB.isCompleted(e.id)) {
			h.visible = true;
			a.text = n.info + "(" + n.target + "/" + n.target + ")"
		} else {
			if (sB.checkComplete(e.id)) {
				r.visible = true;
				r.label = WM.getLanCodeTip(10155);
				a.text = n.info + "(" + n.target + "/" + n.target + ")";
				r.on(Laya.Event.CLICK, this, this.onSend)
			} else {
				let t = sB.getTaskItem(e.id);
				if (!t) {
					i.reportError("normalError", "Không có nhiệm vụ số liệu" + e.id);
					a.text = n.info + "(0/" + n.target + ")"
				} else {
					a.text = n.info + "(" + t.value + "/" + n.target + ")"
				}
				l.visible = true;
				l.on(Laya.Event.CLICK, this, this.onGoTo)
			}
			if (sB.isMaxPoint) {
				o.type = c.WEALTH;
				o.tid = KM.M1;
				o.num = Math.round(o.num * parseFloat(od.getGlobalValue(38001, 2)))
			}
		}
		Tb.addItemGrid(o, t)
	}
	onGoTo() {
		let e = od.getTplInfo(nd.TASK_DATA, this.dataSource.id);
		if (e && e.actionId) {
			qT.do(e.actionId)
		}
	}
	onSend() {
		uP.getIns().task.compelet(pd.SCHOOL_NOTEPAD, this.dataSource.id)
	}
}
class GQ extends j_ {
	get dataSource() {
		return super.dataSource
	}
	set dataSource(e) {
		super.dataSource = e;
		if (!e)
			return;
		let t = this.getChildByName("baseGrid");
		let i = this.getChildByName("activeList");
		let s = this.getChildByName("btnGet");
		let a = this.getChildByName("got");
		let r = cP.splitStr2Arr(e.baseRwd)[0];
		let l = cP.splitStr2Arr(e.activeRwd);
		let h = !sB.activeAdvanced;
		let n = sB.point;
		s.visible = a.visible = false;
		s.disabled = false;
		if (n >= e.point) {
			t.dataSource = WH.getData(r, sB.isBaseGot(e.id), false);
			for (let t = 0; t < l.length; t++) {
				l[t] = WH.getData(l[t], sB.isAdvanceGot(e.id), h)
			}
			i.array = l;
			if (sB.isBaseGot(e.id)) {
				if (sB.isAdvanceGot(e.id)) {
					a.visible = true
				} else {
					s.label = WM.getLanCodeTip(10382);
					s.visible = true
				}
			} else {
				s.label = WM.getLanCodeTip(10155);
				s.visible = true
			}
		} else {
			t.dataSource = WH.getData(r, false, false);
			for (let e = 0; e < l.length; e++) {
				l[e] = WH.getData(l[e], false, h)
			}
			i.array = l;
			s.label = WM.getLanCodeTip(10155);
			s.disabled = true;
			s.visible = true
		}
		s.on(Laya.Event.CLICK, this, this.onGet)
	}
	onGet() {
		let e = this.dataSource;
		if (sB.isBaseGot(e.id)) {
			if (!sB.isAdvanceGot(e.id) && sB.activeAdvanced) {
				FM.schoolNotepadMan.getPrize(this.dataSource.id)
			} else {
				aB.getIns().show()
			}
		} else {
			FM.schoolNotepadMan.getPrize(this.dataSource.id)
		}
	}
}
