class qQ extends j_ {
	constructor() {
		super(...arguments);
		this._state = 0
	}
	get dataSource() {
		return super.dataSource
	}
	set dataSource(e) {
		super.dataSource = e;
		this.on(Laya.Event.UNDISPLAY, this, this.unDisplay);
		let t = this.getChildByName("iconImg");
		let i = this.getChildByName("bgImg");
		this.iconImg = t;
		if (!this._timeLab) {
			this._timeLab = i.getChildByName("timeLab");
			this.on(Laya.Event.CLICK, this, this.onClick)
		}
		if (!e.startTime) {
			vg.stop(this, this.timerFun);
			i.visible = false;
			t.skin = "img/Activity/jia.png";
			this._state = 0;
			this.stopRoll()
		} else {
			t.skin = "img/Activity/christmas" + e.level + ".png";
			let s = b_.ONEHOURMILLISECONDS * e.ripeTime - (b_.getTimeStamp() - e.startTime);
			if (s > 0) {
				i.visible = true;
				vg.start(s, this, this.timerFun, 1, "[mm]:[ss]");
				this._state = 1;
				this.stopRoll()
			} else {
				vg.stop(this, this.timerFun);
				i.visible = false;
				this._state = 2;
				this.startRoll()
			}
		}
	}
	timerFun(e, t, i) {
		if (!t) {
			this._timeLab.changeText("Tặng lễ thời gian:" + i)
		} else {
			this.dataSource = this.dataSource
		}
	}
	onClick(e) {
		switch (this._state) {
		case 0:
			FM.actChristmasShopMan.show(this.dataSource.tid);
			break;
		case 2:
			qM.sendMsg(mf.REWARD_REQ, {
				tid: this.dataSource.tid
			});
			break
		}
	}
	unDisplay() {
		this.stopRoll();
		vg.stop(this, this.timerFun)
	}
	startRoll() {
		this.stopRoll();
		Laya.timer.once(Math.random() * 1e3 + 1e3, this, this.step1)
	}
	step1() {
		Laya.Tween.to(this.iconImg, {
			rotation: -25
		}, 100, null, Laya.Handler.create(this, this.step2))
	}
	step2() {
		Laya.Tween.to(this.iconImg, {
			rotation: 25
		}, 200, null, Laya.Handler.create(this, this.step3))
	}
	step3() {
		Laya.Tween.to(this.iconImg, {
			rotation: -25
		}, 200, null, Laya.Handler.create(this, this.step4))
	}
	step4() {
		Laya.Tween.to(this.iconImg, {
			rotation: 25
		}, 200, null, Laya.Handler.create(this, this.step5))
	}
	step5() {
		Laya.Tween.to(this.iconImg, {
			rotation: 0
		}, 100, null, Laya.Handler.create(this, this.startRoll))
	}
	stopRoll() {
		Laya.timer.clearAll(this);
		Laya.Tween.clearAll(this)
	}
}
