class rz extends j_ {
	static getData(e, t, i) {
		return {
			gridData: e,
			got: t,
			lock: i
		}
	}
	get dataSource() {
		return super.dataSource
	}
	set dataSource(e) {
		super.dataSource = e;
		if (!e)
			return;
		let t = this.getChildByName("baseGrid");
		let i = this.getChildByName("primaryList");
		let s = this.getChildByName("seniorList");
		let a = this.getChildByName("btnGet");
		let r = this.getChildByName("got");
		let l = this.getChildByName("point");
		let h = cP.splitStr2Arr(e.baseRwd)[0];
		let n = cP.splitStr2Arr(e.primaryRwd);
		let o = cP.splitStr2Arr(e.seniorRwd);
		let u = !kx.activePrimary;
		let c = !kx.activeSenior;
		let d = kx.point;
		l.text = "Điểm" + d + "/" + e.point;
		l.visible = a.visible = r.visible = false;
		a.disabled = false;
		if (d >= e.point) {
			t.dataSource = rz.getData(h, kx.isBaseGot(e.id), false);
			for (let t = 0; t < n.length; t++) {
				n[t] = rz.getData(n[t], kx.isPrimaryGot(e.id), u)
			}
			i.array = n;
			for (let t = 0; t < o.length; t++) {
				o[t] = rz.getData(o[t], kx.isSeniorGot(e.id), c)
			}
			s.array = o;
			if (kx.isBaseGot(e.id)) {
				if (kx.isPrimaryGot(e.id) && kx.isSeniorGot(e.id)) {
					r.visible = true
				} else {
					a.label = WM.getLanCodeTip(10382);
					a.visible = true;
					l.visible = true
				}
			} else {
				a.label = WM.getLanCodeTip(10155);
				a.visible = true;
				l.visible = true
			}
		} else {
			t.dataSource = rz.getData(h, false, false);
			for (let t = 0; t < n.length; t++) {
				n[t] = rz.getData(n[t], kx.isPrimaryGot(e.id), u)
			}
			i.array = n;
			for (let t = 0; t < o.length; t++) {
				o[t] = rz.getData(o[t], kx.isSeniorGot(e.id), c)
			}
			s.array = o;
			a.label = WM.getLanCodeTip(10155);
			a.disabled = true;
			a.visible = true;
			l.visible = true
		}
		a.on(Laya.Event.CLICK, this, this.onGet)
	}
	onGet() {
		let e = this.dataSource;
		let t = false;
		let i = kx.activePrimary;
		let s = kx.activeSenior;
		let a = kx.isPrimaryGot(e.id);
		let r = kx.isSeniorGot(e.id);
		if (!kx.isBaseGot(e.id)) {
			t = true
		} else if (!a && i) {
			t = true
		} else if (!r && s) {
			t = true
		}
		if (t) {
			FM.dragonWarOrder.getPrize(e.id)
		} else if (!i || !s) {
			FM.noticeMan.showNotice("Mời trước giải tỏa khế ước!")
		}
	}
}
class lz extends j_ {
	get dataSource() {
		return super.dataSource
	}
	set dataSource(e) {
		super.dataSource = e;
		if (!e)
			return;
		let t = this.getChildByName("desLab");
		let i = this.getChildByName("nameLab");
		let s = this.getChildByName("btnGet");
		let a = this.getChildByName("btnGoTo");
		let r = this.getChildByName("got");
		let l = this.getChildByName("grid");
		let h = od.getTplInfo(nd.TASK_DATA, e.tpl.id);
		t.text = h.info;
		i.text = h.name;
		let n = cP.splitStr2Arr(h.prize)[0];
		Tb.addItemGrid(n, l);
		let o = uP.getIns().task.getTaskItem(e.funcId, e.tpl.id);
		if (o) {
			if (o.done) {
				if (o.rewardGot) {
					a.visible = false;
					s.visible = false;
					r.visible = true
				} else {
					a.visible = false;
					s.visible = true;
					r.visible = false
				}
			} else {
				a.visible = true;
				s.visible = false;
				r.visible = false
			}
		} else {
			a.visible = true;
			s.visible = false;
			r.visible = false
		}
		if (o && o.done) {
			s.on(Laya.Event.CLICK, this, this.getRwd, [e.funcId, e.tpl.id])
		} else {
			a.on(Laya.Event.CLICK, this, this.goto, [h.actionId])
		}
	}
	getRwd(e, t) {
		qM.sendMsg(zp.TASK_ONE_GET, {
			funcId: e,
			taskId: t
		})
	}
	goto(e) {
		FM.mainCityMan.openUI();
		qT.do(e)
	}
}
