class nz extends j_ {
	set dataSource(e) {
		this._dataSource = e;
		if (!e)
			return;
		let t = this.getChildByName("activated");
		let i = this.getChildByName("suitName");
		let s = this.getChildByName("attrList");
		let a = this.getChildByName("suitIcon");
		let r = this.getChildByName("highLightMask");
		let n = this.getChildByName("suitStatus");
		let o = this.getChildByName("skillCell");
		let u = e.suit;
		let c = u.length >= 5;
		t.visible = c;
		n.gray = !c;
		r.visible = c;
		let d = [];
		let p = "";
		let f = e.type;
		let _ = false;
		let g = od.getTplInfo(nd.GOD_EQUIP_SUIT, f);
		if (g) {
			a.skin = h.getUrl(l.IMAGE_ICON, "SZ" + g.icon)
		}
		for (let l = 1; l <= 8; l++) {
			let e = false;
			for (let t = 0; t < u.length; t++) {
				let i = u[t];
				if (i.pos === l) {
					e = true;
					let t = od.getTplInfo(nd.GOD_EQUIP_BASE, null, {
							protoId: i.protoId,
							level: i.level,
							suitType: f
						});
					d.push({
						name: t[0].name,
						attr: t[0].suitAttr,
						quality: t[0].quality,
						level: i.level,
						activated: c,
						equipped: e
					});
					p = t[0].suitName;
					if (t[0].quality === 5) {
						_ = true
					}
					break
				}
			}
			if (!e) {
				let t = od.getTplInfo(nd.GOD_EQUIP_BASE, null, {
						suitPos: l,
						quality: 5,
						level: 1,
						suitType: f
					});
				d.push({
					name: t[0].name,
					attr: t[0].suitAttr,
					quality: t[0].quality,
					level: 1,
					activated: false,
					equipped: e
				});
				p = t[0].suitName
			}
		}
		s.array = d;
		i.text = p;
		if (!c) {
			n.text = "( Chưa kích hoạt )";
			o.dataSource = {
				enabled: false,
				tid: g.skill1,
				color: 1
			}
		} else if (_) {
			n.text = "( Đã kích hoạt )";
			o.dataSource = {
				enabled: true,
				tid: this.getSkillId(u, g),
				color: 1
			}
		} else {
			n.text = "( Không thuộc tính có hiệu lực )";
			o.dataSource = {
				enabled: true,
				tid: g.skill1,
				color: 1
			}
		}
	}
	getSkillId(e, t) {
		if (!t)
			return "";
		let i = 5;
		for (let s = 0; s < e.length; s++) {
			let t = e[s];
			let a = od.getTplInfo(nd.GOD_EQUIP_BASE, null, {
					protoId: t.protoId,
					level: t.level
				});
			if (a[0] && a[0].quality < i) {
				i = a[0].quality
			}
		}
		return bg.getSkillId(t.id, i)
	}
}
