class Iz extends g {
	constructor() {
		super("shiliangift")
	}
	static getIns() {
		if (!this._ins) {
			this._ins = new Iz
		}
		return this._ins
	}
	getMsgs() {
		return [Ff.LEVEL_REC]
	}
	exeMsg(e, t) {
		switch (t) {
		case Ff.LEVEL_REC:
			this.updateInfo();
			break
		}
	}
	onClick(e) {
		switch (e.target) {
		case this._ui.btnClose:
			this.closeUI();
			break
		}
	}
	initUI() {
		this._ui = this.uiView;
		this.setLayer(1, 1, 1, 1)
	}
	showDetail() {
		this.openUI()
	}
	afterOpen() {
		this.updateInfo()
	}
	updateInfo() {
		if (!this.isOpen)
			return;
		let e = [];
		let t = od.getTplInfo(nd.SHILIAN_COMBAT);
		for (let i = 0; i < t.length; i++) {
			let s = {};
			if (!t[i].levelRwd)
				continue;
			s.tpl = t[i];
			e.push(s)
		}
		this._ui.listCell.array = e
	}
}
