	set dataSource(e) {
		super.dataSource = e;
		if (!e)
			return;
		let t = this.getChildByName("imgFirst");
		let i = this.getChildByName("labLevel");
		let s = this.getChildByName("listRwd");
		let a = this.getChildByName("labCP");
		let r = this.getChildByName("labNeed");
		let l = this.getChildByName("btnSweep");
		let h = this.getChildByName("btnBattle");
		let n = this.getChildByName("imgLock");
		i.text = e.tpl.level + "";
		a.text = e.tpl.recCP + "";
		if (e.tpl.needNum) {
			r.visible = true;
			r.text = WM.getLanCodeTip(20222, [e.tpl.needNum, g_.getName(e.tpl.needCamp)])
		} else {
			r.visible = false
		}
		if (e.tpl.level <= e.passLevel) {
			t.visible = false;
			l.visible = true;
			h.visible = false;
			n.visible = false;
			l.on(Laya.Event.CLICK, this, this.onSweep);
			s.array = cP.splitStr2Arr(e.tpl.rwd)
		} else {
			t.visible = true;
			l.visible = false;
			s.array = cP.splitStr2Arr(e.tpl.firstRwd);
			if (e.tpl.level == e.passLevel + 1) {
				h.visible = true;
				n.visible = false;
				h.on(Laya.Event.CLICK, this, this.onBattle)
			} else {
				h.visible = false;
				n.visible = true
			}
		}
	}
	onSweep() {
		if (oL.leftTimes) {
			this.sweepReq(this.dataSource.tpl.type, this.dataSource.tpl.level)
		} else {
			let e = oL.leftBuyTimes;
			if (e) {
				QM.show(WM.getLanCodeTip(20223, [oL.buyTimesCost, e]), Laya.Handler.create(this, this.sweepReq, [this.dataSource.tpl.type, this.dataSource.tpl.level]), undefined, undefined, undefined, undefined, "center")
			} else {
				FM.noticeMan.showNotice(WM.getLanCodeTip(10240))
			}
		}
	}
	sweepReq(e, t, i = true) {
		if (!i)
			return;
		qM.sendMsg(Jp.BATTLE_REQ, {
			roomId: e,
			combatNum: t,
			mop: true
		})
	}
	onBattle() {
		if (oL.leftTimes) {
			vB.getIns().showTotemFB(pd.TOTEM_FB + this.dataSource.tpl.type, Laya.Handler.create(this, this.positionCallBack, [this.dataSource.tpl.type, this.dataSource.tpl.level]), this.dataSource.tpl.needNum, this.dataSource.tpl.needCamp)
		} else {
			let e = oL.leftBuyTimes;
			if (e) {
				QM.show(WM.getLanCodeTip(20224, [oL.buyTimesCost, e]), Laya.Handler.create(this, this.buySure), undefined, undefined, undefined, undefined, "center")
			} else {
				FM.noticeMan.showNotice(WM.getLanCodeTip(10240))
			}
		}
	}
	positionCallBack(e, t) {
		qM.sendMsg(Jp.BATTLE_REQ, {
			roomId: e,
			combatNum: t,
			mop: false
		})
	}
	buySure(e) {
		if (!e)
			return;
		qM.sendMsg(vd.BUY_PLAY_TIMES_REQ, {
			funcId: pd.TOTEM_FB
		})
	}
