		s.visible = l;
		a.visible = !l;
		let h = e.tpl.level >= nL.lockLevel;
		a.label = !h ? "Khiêu chiến" : "Chưa giải khóa";
		a.gray = h;
		a.mouseEnabled = !h;
		a.on(Laya.Event.CLICK, this, this.btnChallengeClick);
