		let K = g.B.hs;
		let Y = {};
		if (g.B.bg) {
			let e = g.B.bg.heros;
			for (let t = 0; t < e.length; t++) {
				Y[e[t].heroIdHex] = e[t]
			}
		}
		if (V) {
			for (B = 0; B < V.length; B++) {
				let e = V[B].pos;
				let t = this.getHsIndex(K, V[B]._idHex);
				let i = new yg(K[t]);
				F[this.getArrIndex(e, false)] = {
					heroData: i,
					heroBg: Y[i.idHex]
				}
			}
		}
		U.array = F;
		let W = this.getChildByName("btnToReplay");
		W.on(Laya.Event.CLICK, this, this.btnToReplayFun);
		let Q = this.getChildByName("btnCollect");
		Q.on(Laya.Event.CLICK, this, this.btnCollectFun);
		let z = this.getChildByName("btnDataShow");
		z.on(Laya.Event.CLICK, this, this.btnDataShowFun);
		let q = this.getChildByName("btnShare");
		q.on(Laya.Event.CLICK, this, this.btnShareFun);
		let j = this.getChildByName("btnAdmired");
		let X = j.getChildByName("admireDot");
		j.on(Laya.Event.CLICK, this, this.btnAdmiredFun);
		Q.x = 380;
		z.x = 440;
		q.x = 500;
		j.x = 560;
		let Z = 8;
		j.visible = true;
