	btnToReplayFun() {
		let e = this.dataSource.group;
		let t = this.dataSource.data.replayProfile.replayIdHex;
		FM.videoMan.playVideoTimes(e, t);
		FM.videoMan.getVideo(t, pd.VIDEO)
	}
	btnCollectFun() {
		let e = this.dataSource.group;
		let t = this.dataSource.data.replayProfile.replayIdHex;
		let i = 0;
		if (this.dataSource.isCollect != null) {
			i = this.dataSource.isCollect
		}
		if (i == 0) {
			FM.videoMan.collectVideo(e, t)
		} else {
			FM.videoMan.uncollectVideo(e, t)
		}
	}
