	getHsIndex(e, t) {
		let i = 0;
		for (i = 0; i < e.length; i++) {
			if (e[i]._idHex == t) {
				return i
			}
		}
		return 0
	}
	getArrIndex(e, t) {
		let i = [7, 4, 1, 8, 5, 2, 9, 6, 3];
		let s = [1, 4, 7, 2, 5, 8, 3, 6, 9];
		if (t) {
			return i.indexOf(e)
		}
		return s.indexOf(e)
	}
