class Aq extends j_ {
	get dataSource() {
		return super.dataSource
	}
	set dataSource(e) {
		super.dataSource = e;
		if (!e)
			return;
		let t = e.tid;
		let i = od.getTplInfo(nd.VIP_SHOP_GOODS, t);
		let s = this.getChildByName("discount");
		let a = this.getChildByName("sellout");
		let r = this.getChildByName("propIcon");
		let l = this.getChildByName("propName");
		let h = this.getChildByName("propInfo");
		if (h) {
			h.style.color = "#683f12";
			h.style.fontSize = 24;
			h.style.bold = true
		}
		if (i.discount && i.discount != 10) {
			s.visible = true;
			let e = s.getChildByName("label");
			e.text = WM.getLanCodeTip(20017, [i.discount])
		} else {
			s.visible = false
		}
		let n = cP.splitStr2Arr(i.rwd);
		let o = Tb.addItemGrid(n[0], r);
		r.gray = false;
		l.text = o.info.baseTpl.name;
		if (a) {
			a.visible = false
		}
		if (i.limitTimes && i.limitTimes > 0 && h) {
			h.visible = true;
			let t = i.limitTime;
			h.innerHTML = this.getTimeName(t) + WM.getHtmlByColor(String(e.purchaseNum) + "/" + String(i.limitTimes), m.TIP_GREEN);
			h.x = 12 + (158 - h.contextWidth) * .5;
			if (e.purchaseNum == i.limitTimes) {
				if (a) {
					a.visible = true
				}
				r.gray = true
			}
		} else {
			if (h) {
				h.visible = false
			}
		}
		let u = this.getChildByName("btnBuy");
		let c;
		let d;
		if (u) {
			c = u.getChildByName("cellMoneyIcon");
			d = u.getChildByName("cellMoneyNum")
		}
		if (i.payItemId) {
			c.visible = false;
			d.text = WM.getLanCodeTip(20001, [i.price]);
			d.x = (u.width - d.width) * .5
		} else {
			let e = cP.splitStr2Arr(i.cost);
			d.x = 48;
			d.text = WM.num2Str(e[0].num);
			let t = Tb.addWealthGridByInfo(e[0], c);
			t.mouseEnabled = false;
			c.visible = true
		}
		u.on(Laya.Event.CLICK, this, this.onBuyClick);
		if (i.vip > uP.getIns().master.vip) {
			u.disabled = true
		} else {
			u.disabled = false
		}
	}
	onBuyClick() {
		FM.vipShopMan.onShopClick(this.dataSource)
	}
	getTimeName(e) {
		if (!e) {
			return WM.getLanCodeTip(10549)
		}
		let t = e.split(":");
		switch (parseInt(t[0])) {
		case b_.TIMETYPE_HOUR:
			return WM.getLanCodeTip(10547);
			break;
		case b_.TIMETYPE_DAY:
			return WM.getLanCodeTip(10548);
			break;
		case b_.TIMETYPE_WEEK:
			return WM.getLanCodeTip(10508);
			break;
		case b_.TIMETYPE_MONTH:
			return WM.getLanCodeTip(10509);
			break
		}
	}
}
