class Yq extends j_ {
	constructor() {
		super(...arguments);
		this._init = false
	}
	get dataSource() {
		return super.dataSource
	}
	set dataSource(e) {
		if (!this._init) {
			this.init()
		}
		this._match = !!e ? T.deepCopy(e) : null;
		super.dataSource = this._match;
		let t = SC.koPhase;
		if (t == CC.FinalMatch) {
			if (SC.koRoundPhase != EC.Rest) {
				this.showProgressing(this._match)
			} else {
				this.reset()
			}
		} else {
			if (!!this._match && !!this._match.lastPromote) {
				this.showNotice(this._match)
			} else {
				this.reset()
			}
		}
	}
	init() {
		this.imgShadowA = this.getChildByName("imgShadowA");
		this.imgShadowB = this.getChildByName("imgShadowB");
		this.btnArtifactA = this.getChildByName("btnArtifactA");
		this.btnArtifactB = this.getChildByName("btnArtifactB");
		this.imgKongA = this.getChildByName("imgKongA");
		this.imgKongB = this.getChildByName("imgKongB");
		this.boxNotice = this.getChildByName("boxNotice");
		this.labTime = this.boxNotice.getChildByName("labTime");
		this.boxGuess = this.getChildByName("boxGuess");
		this.btnWatch = this.getChildByName("btnWatch");
		this.labNameA = this.getChildByName("labNameA");
		this.labNameB = this.getChildByName("labNameB");
		let e = this.boxGuess.getChildByName("btnGuess");
		e.on(Laya.Event.CLICK, this, this.btnGuessClick);
		this.boxClickA = this.getChildByName("boxClickA");
		this.boxClickB = this.getChildByName("boxClickB");
		this.on(Laya.Event.UNDISPLAY, this, this.reset);
		this.btnWatch.on(Laya.Event.CLICK, this, this.btnWatchClick);
		this._init = true
	}
	showProgressing(e) {
		let t = !!e && !!e.a && !!e.a.masterIdHex;
		let i = !!e && !!e.b && !!e.b.masterIdHex;
		if (t) {
			this.showPlayer("A", e.a)
		} else {
			this.hidePlayer("A")
		}
		if (i) {
			this.showPlayer("B", e.b)
		} else {
			this.hidePlayer("B")
		}
		let s = !t || !i;
		this.boxGuess.visible = !s && SC.koRoundPhase < EC.Battle;
		this.btnWatch.visible = !s && SC.koRoundPhase == EC.Battle;
		this.boxNotice.visible = false;
		vg.stop(this, this.timerFun)
	}
	showNotice(e) {
		let t = !!e && !!e.a && !!e.a.masterIdHex;
		let i = !!e && !!e.b && !!e.b.masterIdHex;
		if (t) {
			this.showPlayer("A", e.a)
		} else {
			this.hidePlayer("A")
		}
		if (i) {
			this.showPlayer("B", e.b)
		} else {
			this.hidePlayer("B")
		}
		this.boxGuess.visible = this.btnWatch.visible = false;
		this.boxNotice.visible = true;
		this.refreshCdTime()
	}
	showPlayer(e, t) {
		let i = od.getTplInfo(nd.AVATAR, t.avatarId);
		if (!i) {
			this.hidePlayer(e);
			return
		}
		this["imgShadow" + e].visible = true;
		q_.addUIRole(i.model, this["btnArtifact" + e], i.star).scale(.7, .7);
		this["imgKong" + e].visible = false;
		this["labName" + e].text = jg.getZoneIndexName(t.srv.index) + t.name;
		this["boxClick" + e].on(Laya.Event.CLICK, this, this.playerClick, [t])
	}
	hidePlayer(e) {
		this["imgShadow" + e].visible = false;
		q_.removeUIRole(this["btnArtifact" + e]);
		this["imgKong" + e].visible = true;
		this["labName" + e].text = "";
		this["boxClick" + e].off(Laya.Event.CLICK, this, this.playerClick)
	}
	playerClick(e) {
		if (!e)
			return;
		Gq.getIns().show(2, e.masterIdHex)
	}
	btnGuessClick() {
		if (!this._match)
			return;
		Kq.getIns().show(1, this._match)
	}
	btnWatchClick() {
		if (!this._match)
			return;
		Kq.getIns().show(2, this._match)
	}
	refreshCdTime() {
		vg.stop(this, this.timerFun);
		if (!this._match || !this._match.lastPromote)
			return;
		let e = 0;
		let t = SC.getRoundData(this._match.lastRound);
		let i = SC.getRoundData(this._match.lastRound + 1);
		let s = b_.getTimeStamp();
		if (t.resetStart <= s && s < i.guessStart) {
			e = i.guessStart - s
		}
		if (e > 0) {
			vg.start(e, this, this.timerFun)
		} else {
			vg.stop(this, this.timerFun);
			this.labTime.text = "00:00:00"
		}
	}
	timerFun(e, t) {
		let i;
		if (e >= b_.ONEDAYMILLISECONDS) {
			i = b_.getDayHourStr(e)
		} else {
			i = b_.getCdTimeStrByMs(e)
		}
		this.labTime.text = i;
		if (t) {
			this.refreshCdTime()
		}
	}
	reset() {
		if (!this._init)
			return;
		this._match = null;
		this.hidePlayer("A");
		this.hidePlayer("B");
		this.boxGuess.visible = false;
		this.btnWatch.visible = false;
		this.boxNotice.visible = false;
		vg.stop(this, this.timerFun)
	}
}
