class zq extends j_ {
	get dataSource() {
		return super.dataSource
	}
	set dataSource(e) {
		super.dataSource = e;
		if (!e)
			return;
		let t = this.getChildByName("imgBg");
		let i = this.getChildByName("imgMask");
		let s = this.getChildByName("imgDes");
		if (!this._labState) {
			this._labState = this.getChildByName("labState")
		}
		let a = this.getChildByName("labTime");
		let r = 0;
		if (e.phase == SC.phase) {
			r = 1
		} else if (e.phase < SC.phase) {
			r = 2
		}
		this.mouseEnabled = r != 0;
		let l = r == 0 || r == 2;
		if (t) {
			t.gray = l
		}
		if (i) {
			i.visible = r == 0
		}
		if (s) {
			s.gray = l;
			if (r == 1) {
				s.on(Laya.Event.CLICK, this, this.imgDesClick)
			} else {
				s.off(Laya.Event.CLICK, this, this.imgDesClick)
			}
			let e = s.getChildByName("labBless");
			if (e) {
				e.underlineColor = l ? "#dddddd" : "#e7df09"
			}
		}
		let h = SC.getPhaseTime(e.phase);
		if (this._labState) {
			let e = zq.STATE[r];
			this._labState.color = e.color;
			this._timeHeaderStr = e.name;
			vg.stop(this, this.timerFun);
			if (r == 0) {
				this.refreshCdTime(h.start - b_.getTimeStamp())
			} else if (r == 1) {
				this.refreshCdTime(h.over - b_.getTimeStamp())
			} else if (r == 2) {
				this._labState.changeText(e.name)
			}
		}
		if (a) {
			a.gray = r == 2;
			let e = new Date(h.start);
			let t = new Date(h.over);
			a.text = this.analysisTime(e) + "-" + this.analysisTime(t)
		}
	}
	imgDesClick() {
		if (!this.dataSource)
			return;
		let e = this.dataSource;
		if (e.phase == IC.Knockout) {
			e.blessFunc.call(this)
		}
	}
	refreshCdTime(e) {
		if (!this.dataSource)
			return;
		if (e > 0) {
			vg.start(e, this, this.timerFun)
		} else {
			vg.stop(this, this.timerFun);
			this._labState.text = this._timeHeaderStr + "00:00:00"
		}
	}
	timerFun(e, t) {
		let i;
		if (e >= b_.ONEDAYMILLISECONDS) {
			i = b_.getDayHourStr(e)
		} else {
			i = b_.getCdTimeStrByMs(e)
		}
		this._labState.text = this._timeHeaderStr + i
	}
	clear() {
		vg.stop(this, this.timerFun)
	}
	analysisTime(e) {
		if (!e)
			return "";
		if (e.getMinutes() == 59 && e.getSeconds() == 59) {
			e.setTime(e.getTime() + 1e3)
		}
		return e.getMonth() + 1 + "m" + e.getDate() + "d" + e.getHours() + "h"
	}
}
