		this.imgLineB = this.getChildByName("imgLineB");
		this.imgHeadA = this.getChildByName("imgHeadA");
		this.imgHeadB = this.getChildByName("imgHeadB");
		this.imgHeadWin = this.getChildByName("imgHeadWin");
		this.boxHeadA = this.getChildByName("boxHeadA");
		this.boxHeadB = this.getChildByName("boxHeadB");
		this.boxHeadWin = this.getChildByName("boxHeadWin");
		this.labNameA = this.getChildByName("labNameA");
		this.labNameB = this.getChildByName("labNameB");
		this.labNameWin = this.getChildByName("labNameWin");
		this.imgGroupA = this.getChildByName("imgGroupA");
		this.imgGroupB = this.getChildByName("imgGroupB");
		this.imgGroupWin = this.getChildByName("imgGroupWin");
		this.btnGuess = this.getChildByName("btnGuess");
		this.btnWatch = this.getChildByName("btnWatch");
		this.btnLook = this.getChildByName("btnLook");
		this.on(Laya.Event.UNDISPLAY, this, this.reset);
