class Jq extends j_ {
	get dataSource() {
		return super.dataSource
	}
	set dataSource(e) {
		super.dataSource = e;
		if (!e)
			return;
		if (!this._imgClose) {
			this._imgClose = this.getChildByName("close");
			this.on(Laya.Event.UNDISPLAY, this, this.onUndisplay)
		}
		let t = this.getChildByName("got");
		this.stopAni();
		this._imgClose.gray = e.state == 2;
		t.visible = e.state == 2;
		if (e.state == 1) {
			this.startAni()
		}
		this.on(Laya.Event.CLICK, this, this.onClick)
	}
	onUndisplay() {
		this.stopAni()
	}
	startAni() {
		this.step0()
	}
	step0() {
		Laya.Tween.to(this._imgClose, {
			y: this.height - 12,
			scaleY: 1.15
		}, 250, null, Laya.Handler.create(this, this.step1))
	}
	step1() {
		Laya.Tween.to(this._imgClose, {
			y: this.height
		}, 150);
		Laya.Tween.to(this._imgClose, {
			scaleY: .85
		}, 250, null, Laya.Handler.create(this, this.step2))
	}
	step2() {
		Laya.Tween.to(this._imgClose, {
			scaleY: 1.1
		}, 200, null, Laya.Handler.create(this, this.step3))
	}
	step3() {
		Laya.Tween.to(this._imgClose, {
			scaleY: .95
		}, 150, null, Laya.Handler.create(this, this.step0))
	}
	stopAni() {
		Laya.Tween.clearAll(this._imgClose);
		this._imgClose.scaleY = 1;
		this._imgClose.pos(this.width / 2, this.height)
	}
	onClick() {
		if (!this.dataSource)
			return;
		let e = this.dataSource;
		if (e.state == 2)
			return;
		if (e.state == 0) {
			mR.getIns().show(e.awards)
		} else {
			qM.sendMsg(Of.ZONEBOSS_GETAWARDS_REQ, {
				tid: e.tpl.id
			})
		}
	}
}
