class ej extends j_ {
	get dataSource() {
		return super.dataSource
	}
	set dataSource(e) {
		super.dataSource = e;
		if (!this.labRound) {
			this.labRound = this.getChildByName("labRound")
		}
		if (!this.labGuess) {
			this.labGuess = this.getChildByName("labGuess")
		}
		if (!this.labBattle) {
			this.labBattle = this.getChildByName("labBattle")
		}
		if (!e) {
			this.reset();
			return
		}
		let t = SC.getRoundData(e.round);
		if (!t) {
			this.reset();
			return
		}
		this.labRound.text = e.name;
		let i = new Date(t.guessStart);
		let s = b_.getTimeStamp();
		let a = "Cạnh đoán giai đoạn" + this.analysisTime(i) + " " + b_.getTimeStmapStr(t.guessStart, "[hh]:[mm]") + "-" + b_.getTimeStmapStr(t.fightStart, "[hh]:[mm]");
		if (s < t.guessStart) {
			this.labGuess.color = "#f0f0f0"
		} else if (s < t.fightStart) {
			a += " ( Đang tiến hành )";
			this.labGuess.color = "#1dc724"
		} else {
			this.labGuess.color = "#999999"
		}
		this.labGuess.text = a;
		let r = "Chiến đấu giai đoạn" + this.analysisTime(i) + " " + b_.getTimeStmapStr(t.fightStart, "[hh]:[mm]") + "-" + b_.getTimeStmapStr(t.resetStart, "[hh]:[mm]");
		if (s < t.fightStart) {
			this.labBattle.color = "#f0f0f0"
		} else if (s < t.resetStart) {
			r += " ( Đang tiến hành )";
			this.labBattle.color = "#1dc724"
		} else {
			this.labBattle.color = "#999999"
		}
		this.labBattle.text = r
	}
	reset() {
		if (!!this.labRound)
			this.labRound.text = "";
		if (!!this.labGuess)
			this.labGuess.text = "";
		if (!!this.labBattle)
			this.labBattle.text = ""
	}
	analysisTime(e) {
		if (!e)
			return "";
		if (e.getMinutes() == 59 && e.getSeconds() == 59) {
			e.setTime(e.getTime() + 1e3)
		}
		return e.getMonth() + 1 + "m" + e.getDate() + "d"
	}
}
