class aj extends j_ {
	constructor() {
		super(...arguments);
		this._init = false;
		this._avatarId = 0;
		this._isMoving = false;
		this.index = 0;
		this._showPos = 0
	}
	get dataSource() {
		return super.dataSource
	}
	set dataSource(e) {
		if (!this._init) {
			this.init()
		}
		this._value = !!e ? T.deepCopy(e) : null;
		super.dataSource = this._value;
		this.imgGroup.skin = "img/WYCF/flag" + this._value.tpl.id + ".png";
		this.labGroup.text = this._value.tpl.name;
		if (this._value.hasOverlord) {
			this.showPlayer(this._value.data.championInfo)
		} else {
			this.hidePlayer()
		}
		this.labValue.text = this._value.data.admireNum
	}
	init() {
		this.imgTitle = this.getChildByName("imgTitle");
		this.imgValueBg = this.getChildByName("imgValueBg");
		this.imgShadow = this.getChildByName("imgShadow");
		this.btnArtifact = this.getChildByName("btnArtifact");
		this.imgKong = this.getChildByName("imgKong");
		this.imgGroup = this.getChildByName("imgGroup");
		this.labGroup = this.getChildByName("labGroup");
		this.labName = this.getChildByName("labName");
		this.boxValue = this.getChildByName("boxValue");
		this.labValue = this.boxValue.getChildByName("labValue");
		this.boxClick = this.getChildByName("boxClick");
		this.on(Laya.Event.UNDISPLAY, this, this.reset);
		this.boxClick.on(Laya.Event.CLICK, this, this.playerClick);
		this._init = true
	}
	showPlayer(e) {
		if (!e || this._avatarId == e.avatarId)
			return;
		this._avatarId = e.avatarId;
		let t = od.getTplInfo(nd.AVATAR, e.avatarId);
		if (!t) {
			this.hidePlayer();
			return
		}
		this.imgShadow.visible = true;
		q_.addUIRole(t.model, this.btnArtifact, t.star).scale(.7, .7);
		this.imgKong.visible = false;
		this.labName.text = jg.getZoneIndexName(e.srv.index) + e.name
	}
	hidePlayer() {
		this.imgShadow.visible = false;
		q_.removeUIRole(this.btnArtifact);
		this.imgKong.visible = true;
		this.labName.text = ""
	}
	playerClick() {
		if (!this._value || this._isMoving)
			return;
		if (this._showPos != 2) {
			if (!!this._value.onClick) {
				this._value.onClick.call(null, this._value.tpl.id)
			}
		} else if (this._value.hasOverlord) {
			Gq.getIns().show(3, this._value.data.championInfo.masterIdHex, 1)
		}
	}
	doMove(e, t) {
		if (!this._value)
			return;
		if (!aj.POS_TPLS[e] || this._isMoving)
			return;
		this._showPos = e;
		if (t) {
			this._isMoving = true;
			this.imgTitle.visible = false;
			let t = aj.POS_TPLS[e];
			Laya.Tween.to(this, t, 250, Laya.Ease.sineOut, Laya.Handler.create(this, this.onMoveEnd, [true]))
		} else {
			this.onMoveEnd(false)
		}
	}
	onMoveEnd(e) {
		if (!this._value)
			return;
		this._isMoving = false;
		let t = aj.POS_TPLS[this._showPos];
		this.x = t.x;
		this.y = t.y;
		this.scaleX = t.scaleX;
		this.scaleY = t.scaleY;
		this.imgTitle.visible = this._showPos == 2;
		if (e && !!this._value.onMoveEnd) {
			this._value.onMoveEnd.call(null, this._value)
		}
	}
	reset() {
		if (!this._init)
			return;
		this._value = null;
		this._avatarId = 0;
		this._isMoving = false;
		this.imgTitle.visible = false;
		this.imgValueBg.visible = true;
		this.hidePlayer();
		Laya.Tween.clearAll(this)
	}
}
aj.POS_TPLS = {
	1: {
		x: 14,
		y: 78,
		scaleX: .8,
		scaleY: .8
	},
	2: {
		x: 233,
		y: 74,
		scaleX: 1,
		scaleY: 1
	},
	3: {
		x: 510,
		y: 78,
		scaleX: .8,
		scaleY: .8
	}
};
