class Mj extends g {
	constructor() {
		super("LineHeroOver")
	}
	static getIns() {
		if (!this._ins) {
			this._ins = new Mj
		}
		return this._ins
	}
	onClick(e) {
		switch (e.target) {
		case this._ui.imgOk:
			this.closeUI();
			break
		}
	}
	initUI() {
		this._ui = this.uiView;
		this.setLayer(2, 1, 1, 2)
	}
	afterClose() {
		Pj.getIns().showEnd()
	}
}
class Pj extends g {
	constructor() {
		super(...arguments);
		this.showIndex = 0;
		this.showArr = []
	}
	static getIns() {
		if (!this._ins) {
			this._ins = new Pj
		}
		return this._ins
	}
	getCmds() {
		return [d.LINE_HERO_BATTLEOVER]
	}
	exeCmd(e, t) {
		switch (t) {
		case d.LINE_HERO_BATTLEOVER:
			if (e.type != 2)
				return;
			if (e.win) {
				this.showWin()
			} else {
				this.showFail()
			}
			break
		}
	}
	show() {
		this.showArr = od.getTplInfo(nd.LINEHERO_BATTLE, null, {
				type: 2
			});
		this.showNext()
	}
	showNext() {
		if (!this.showArr[this.showIndex]) {
			Mj.getIns().openUI();
			return
		}
		HN.getIns().show(this.showArr[this.showIndex].id, 2)
	}
	showWin() {
		this.showIndex++;
		this.showNext()
	}
	showFail() {
		this.showNext()
	}
	showEnd() {
		HN.getIns().closeUI();
		lL.getIns().openUI()
	}
}
class Hj {
	constructor() {
		this.ttttt = 0;
		if (Hj._instance) {
			throw new Error("PlayModule Là đơn lệ")
		}
	}
	static getIns() {
		if (!this._instance) {
			this._instance = new Hj
		}
		return this._instance
	}
	init() {
		s.log("PlayModule Ban đầu hóa");
		FM.init();
		_.initNotch(Laya.Utils.bind(this.startLogin, this))
	}
	startLogin() {
		qM.regCmd(d.PRE_LOAD, this, this.preLoad);
		qM.exeCmd(d.LOGIN)
	}
	preLoad() {
		FM.loadingMan.beginProg();
		FM.loadingMan.updateProg("Đang tải cấu hình giao diện...", 1 / 5);
		this.ttttt = Laya.Browser.now();
		this.loadUiJson()
	}
	loadUiKeys() {
		if (Laya.Browser.window.ydwxConfig.uiPath) {
			Laya.loader.load(Laya.Browser.window.ydwxConfig.uiPath, Laya.Handler.create(this, this.onUIConfigLoaded))
		} else {
			Laya.loader.load("ui/ui.keys", Laya.Handler.create(this, this.onUIKeysLoaded), undefined, Laya.Loader.BUFFER)
		}
	}
	onUIKeysLoaded(e) {
		if (!e) {
			this.loadUiJson();
			return
		}
		FM.loadingMan.updateProgQuick("Đang tải dữ liệu mẫu ...", 1 / 5);
		FM.loadingMan.updateProg("Đang tải dữ liệu mẫu ...", 2 / 5);
		let t = Laya.Browser.now();
		s.log("ui.keys Tăng thêm thời gian:" + (t - this.ttttt));
		let i = new Laya.Byte(e);
		i.endian = Laya.Byte.BIG_ENDIAN;
		while (i.bytesAvailable) {
			let e = i.readFloat64();
			let t = i.readUTFBytes(e);
			let s = i.readFloat64();
			let a = i.readArrayBuffer(s);
			Laya.Loader.loadedMap[Laya.URL.formatURL(t + ".json")] = a
		}
		s.log("ui.keys Phân tích thời gian:" + (Laya.Browser.now() - t));
		s.log("ui.keys Tăng thêm hoàn tất");
		s.log("ui.keys Phân tích tốn hao thời gian:" + (Laya.Browser.now() - t));
		this.loadGameTpls()
	}
	loadUiJson() {
		if (Laya.Browser.window.ydwxConfig.uiPath) {
			Laya.loader.load(Laya.Browser.window.ydwxConfig.uiPath, Laya.Handler.create(this, this.onUIConfigLoaded))
		} else {
			Laya.loader.load("version", Laya.Handler.create(this, this.onUIConfigLoaded))
		}
	}
	onUIConfigLoaded(e) {
		if (getStrUi) {
			this.loadUiBin();
			i.reportError("resLoadFail", "ui.json Tăng thêm thất bại");
			return
		}
		FM.loadingMan.updateProgQuick("Đang tải giao diện...", 1 / 5);
		FM.loadingMan.updateProg("Đang tải giao diện...", 2 / 5);
		let t = Laya.Browser.now();
		s.log("ui.json Tăng thêm thời gian:" + (t - this.ttttt));
		for (let i in getStrUi) {
			Laya.Loader.loadedMap[Laya.URL.formatURL(i + ".json")] = getStrUi[i]
		}
		s.log("ui.json Tăng thêm hoàn tất");
		s.log("ui.json Phân tích tốn hao thời gian:" + (Laya.Browser.now() - t));
		this.loadGameTpls()
	}
	loadUiBin() {
		Laya.loader.load("ui/ui.bin", Laya.Handler.create(this, this.onUIBinLoaded), undefined, Laya.Loader.BUFFER)
	}
	onUIBinLoaded(e) {
		if (!e) {
			FM.loadingMan.updateProg("Lỗi tải giao diện...", 1 / 5);
			vy.show("Đang tải cấu hình giao diện lỗi BIN, bấm OK để thử lại");
			i.reportError("resLoadFail", "ui.bin Tăng thêm thất bại");
			return
		}
		FM.loadingMan.updateProgQuick("Đang tải dữ liệu...", 1 / 5);
		FM.loadingMan.updateProg("Đang tải dữ liệu...", 2 / 5);
		let t = Laya.Browser.now();
		s.log("ui.bin Tăng thêm thời gian:" + (t - this.ttttt));
		let a = T.uncompress(e);
		let r = this.byteToString(a);
		s.log("ui.bin Phân tích thời gian:" + (Laya.Browser.now() - t));
		let l = JSON.parse(r);
		for (let i in l) {
			Laya.Loader.loadedMap[Laya.URL.formatURL(i + ".json")] = l[i]
		}
		s.log("ui.bin Tăng thêm hoàn tất");
		s.log("ui.bin Phân tích tốn hao thời gian:" + (Laya.Browser.now() - t));
		this.loadGameTpls()
	}
	byteToString(e) {
		let t = new I(e);
		return t.readUTFBytes()
	}
	loadGameTpls() {
		Laya.loader.load("template/perLoadTpls.json", Laya.Handler.create(this, this.onGameTpls))
	}
	onGameTpls(e) {
		if (e && e.can) {
			b.gameTpls = e.list;
			if (e.type) {
				b.gameTplType = e.type
			}
		}
		this.loadTemplates()
	}
	loadTemplates() {
		if (Laya.Browser.window.ydwxConfig.templatesPath) {
			Laya.loader.load(Laya.Browser.window.ydwxConfig.templatesPath, Laya.Handler.create(this, this.onTemplatesLoaded), undefined, Laya.Loader.BUFFER, undefined, false)
		} else {
			h.load(l.TEMP, "templates.bin", Laya.Handler.create(this, this.onTemplatesLoaded), undefined, undefined, false)
		}
	}
	onTemplatesLoaded(e) {
		if (!e) {
			FM.loadingMan.updateProg("Lỗi tải dữ liệu...", 2 / 5);
			vy.show("Lỗi khi tải dữ liệu mẫu, hãy nhấp vào OK để thử lại");
			i.reportError("resLoadFail", "templates Tăng thêm thất bại");
			return
		}
		s.log("templates Mô bản biểu ghi vào hoàn tất");
		if (i.isMiniGame) {
			FM.loadingMan.updateProgQuick("Đang phân tích dữ liệu...", 2 / 5);
			FM.loadingMan.updateProg("Đang phân tích dữ liệu...", 4 / 5, 12e3)
		}
		i.loginStatistic(i.CLIENTTEMPATE);
		qM.regCmd(d.TEMPLATES_PARSED, this, this.onTemplatesParsed);
		od.getIns().init(e)
	}
	onTemplatesParsed() {
		FM.loadingMan.updateProgQuick("Đang liên kết máy chủ...", 4 / 5);
		FM.loadingMan.updateProg("Đang liên kết máy chủ...", 5 / 5);
		qM.regMsg(fd.SERVER_CONNECTED_REC, this, this.serverConnected);
		qM.regMsg(mp.INIT_COMPLETE_REC, this, this.initCompleteRec);
		qM.regCmd(d.SOCKET_CONNECTED, this, this.socketConnected);
		zM.getIns().connect()
	}
	socketConnected() {
		FM.topBarMan.openUI();
		FM.bottomBarMan.openUI();
		FM.mainCityMan.openUI()
	}
	serverConnected(e) {
		if (e.code != 0) {
			vy.show(e.note);
			i.serverConnected = false;
			return
		} else {
			i.serverConnected = true
		}
		s.log("Server kết nối hoàn tất");
		i.masterCreated = e.masterCreated;
		uP.getIns().openSrvTimeBase = e.openTime;
		uP.getIns().combinedSrvTimeBase = e.mergeTime;
		uP.getIns().serverTime = e.timestamp;
		uP.getIns().masterCreated = e.masterCreated;
		if (!e.masterCreated) {
			if (i.gameId == "10274" || i.gameId == "10275") {
				Pj.getIns().show()
			} else {
				if (!i.isNative) {
					lL.getIns().openUI()
				} else {
					hL.getIns().openUI()
				}
			}
		}
		i.loginStatistic(i.GAMEWS);
		qM.sendCmd(d.SERVER_CONNECTED);
		i.checkClientVersionOutOfDate(Laya.Handler.create(this, this.checkVersionCallback))
	}
	checkVersionCallback(e) {
		if (e) {
			QM.show("Phiên bản hiện tại đã cũ, vui lòng nhấp OK để update và đăng nhập lại game", Laya.Handler.create(null, function () {
					i.reload()
				}))
		} else {
			qM.sendMsg(mp.INIT_INFO_REQ)
		}
	}
	initCompleteRec(e) {
		FM.loadingMan.endProg(null);
		i.loginStatistic(i.GAMEENTER);
		this.mainCityOkDo()
	}
	mainCityOkDo() {
		if (Laya.Browser.onBLMiniGame) {
			Laya.Browser.window.bl.onShow(function (e) {
				Hj.getIns().recoveryMusic()
			});
			Laya.Browser.window.bl.onAudioInterruptionEnd(function () {
				Hj.getIns().recoveryMusic()
			})
		}
		if (Laya.Browser.onMiniGame) {
			let e = this;
			Laya.Browser.window.wx.onShow(function (e) {
				console.log("Về sân khấu biểu hiện trò chơi");
				setTimeout(() => {
					_.showLayers()
				}, 250)
			});
			Laya.Browser.window.wx.onHide(function () {
				console.log("Về sân khấu ẩn tàng trò chơi");
				_.hideLayers()
			})
		}
	}
	showLayers() {
		_.showLayers()
	}
	recoveryMusic() {
		a_.stopMusic();
		Laya.timer.once(30, this, this.playMusic)
	}
	playMusic() {
		a_.playBGM()
	}
}
class Gj {
	constructor() {
		if (window["Laya3D"])
			Laya3D.init(Bj.width, Bj.height);
		else
			Laya.init(Bj.width, Bj.height, Laya["WebGL"]);
		Laya["Physics"] && Laya["Physics"].enable();
		Laya["DebugPanel"] && Laya["DebugPanel"].enable();
		Laya.stage.scaleMode = Laya.Stage.SCALE_SHOWALL;
		Laya.stage.bgColor = "#403a3a";
		Laya.stage.screenMode = Bj.screenMode;
		Laya.stage.alignH = Bj.alignH;
		Laya.stage.alignV = Bj.alignV;
		Laya.URL.exportSceneToJson = Bj.exportSceneToJson;
		if (Bj.debug || Laya.Utils.getQueryString("debug") == "true")
			Laya.enableDebugPanel();
		if (Bj.physicsDebug && Laya["PhysicsDebugDraw"])
			Laya["PhysicsDebugDraw"].enable();
		if (i.debug) {
			var t = 0;
			Laya.Browser.window.onerror = function (e, s, a, r, l) {
				if (t++ < 5 && l)
					this.alert("Phạm sai lầm rồi, xin đem này tin tức Screenshots cho nghiên cứu phát minh thương \n" + e + "\n" + l.stack);
				i.reportError("errorStack", l.stack)
			}
		} else {
			Laya.Browser.window.onerror = function (e, t, s, a, r) {
				if (r)
					i.reportError("errorStack", r.stack)
			}
		}
		if (i.basePath) {
			Laya.URL.basePath = i.basePath
		}
		Laya.ResourceVersion.enable("version?v=" + appVersion, Laya.Handler.create(this, this.onVersionLoaded), Laya.ResourceVersion.FILENAME_VERSION);
		if (Laya.Browser.window.conch) {
			Laya.Browser.window.conch.setScreenWakeLock(true);
			Laya.Browser.window.ydwxJSBridge = e;
			if (i.loginType == 2) {
				Laya.Browser.window.conch.setOnBackPressedFunction(function () {
					e.call("exit")
				})
			}
			e.initUUID();
			e.initGameId();
			e.initChannelId();
			e.call("hideSplash")
		}
		Laya.Browser.window.ydwxReportError = Laya.Utils.bind(i.reportError, i)
	}
	onVersionLoaded() {
		Laya.AtlasInfoManager.enable("5c597-36b84-cbdb1.json", Laya.Handler.create(this, this.onConfigLoaded))
	}
	onConfigLoaded() {
		Laya.Text.defaultFontSize = 24;
		if (Laya.Browser.onPC) {
			Laya.Text.defaultFont = "Arial"
		} else if (Laya.Browser.onQGMiniGame) {
			Laya.Text.defaultFont = "Arial"
		}
		this.moduleInit()
	}
	moduleInit() {
		h.getIns().init();
		qM.getIns().init();
		zM.getIns().init();
		Hj.getIns().init()
	}
}
